dialog.inviter-prompt {
  position: fixed;
  inset: 0;
  margin: auto;
  height: fit-content;
  border: 0;
  padding: 30px 0 0;
  background: transparent;
  color: #f3ead2;
  max-width: min(360px, calc(100vw - 32px));
  overflow: visible;
}
.inviter-prompt::backdrop { background: rgba(6, 10, 14, .55); backdrop-filter: blur(3px); }
.inviter-card {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 14px;
  padding: 34px 22px 20px;
  border-radius: 28px;
  border: 1px solid rgba(233, 215, 160, .28);
  background: radial-gradient(circle at 50% 0%, rgba(103, 210, 187, .18), transparent 60%),
    linear-gradient(160deg, #191f33 0%, #1a1230 55%, #0d1a16 100%);
  box-shadow: 0 18px 50px rgba(0, 0, 0, .5);
  animation: inviter-rise .35s ease-out;
}
.inviter-card h2 { margin: 0; font-size: 1.05rem; font-weight: 600; letter-spacing: .02em; }
.inviter-ufo {
  position: absolute;
  top: -26px;
  font-size: 2.6rem;
  filter: drop-shadow(0 6px 10px rgba(103, 210, 187, .45));
  animation: inviter-hover 3.2s ease-in-out infinite;
}
.inviter-prompt button { border-radius: 999px; font: inherit; cursor: pointer; }
.inviter-prompt .inviter-info {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 24px;
  height: 24px;
  min-height: 0;
  padding: 0;
  border: 1px solid rgba(233, 215, 160, .4);
  background: transparent;
  color: #e9d7a0;
  font-size: .75rem;
  font-style: italic;
}
.inviter-info-text { margin: -6px 0 0; font-size: .78rem; opacity: .75; text-align: center; }
.inviter-chips { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px 10px; max-height: 210px; overflow-y: auto; padding: 4px; }
.inviter-prompt .inviter-chip {
  display: grid;
  justify-items: center;
  gap: 4px;
  width: 74px;

  padding: 6px 2px;
  min-height: 0;
  border: 0;
  border-radius: 18px;
  background: transparent;
  color: inherit;
  transition: transform .15s ease, background .15s ease;
}
.inviter-prompt .inviter-chip:hover { transform: translateY(-2px); }
.inviter-prompt .inviter-chip[aria-checked="true"] { background: rgba(103, 210, 187, .16); }
.inviter-prompt .inviter-chip[aria-checked="true"] .inviter-avatar { box-shadow: 0 0 0 2px #67d2bb, 0 0 14px rgba(103, 210, 187, .6); }
.inviter-avatar {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  overflow: hidden;
  background: #0d1210;
  box-shadow: 0 0 0 1px rgba(233, 215, 160, .35);
  font-size: 1.45rem;
  transition: box-shadow .2s ease;
}
.inviter-avatar img { width: 100%; height: 100%; object-fit: cover; }
.inviter-chip-name { max-width: 72px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: .72rem; opacity: .85; }
.inviter-other {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  border-radius: 999px;
  border: 1px solid rgba(233, 215, 160, .25);
  background: rgba(0, 0, 0, .25);
}
.inviter-other input { width: 17ch; border: 0; background: transparent; color: inherit; font: inherit; font-size: .85rem; outline: none; }
.inviter-status { min-height: 1em; margin: 0; font-size: .78rem; color: #ffc35c; text-align: center; }
.inviter-actions { display: flex; gap: 10px; }
.inviter-prompt .inviter-skip { padding: 7px 16px; min-height: 0; border: 1px solid rgba(233, 215, 160, .25); background: transparent; color: #f3ead2; opacity: .75; }
.inviter-prompt .inviter-confirm { padding: 7px 18px; min-height: 0; border: 0; background: linear-gradient(135deg, #67d2bb, #e9d7a0); color: #0d1210; font-weight: 600; }

.inviter-prompt .inviter-confirm:disabled { opacity: .4; cursor: default; }
.inviter-prompt.is-welcomed .inviter-ufo { animation: inviter-beam .6s ease-in forwards; }
.inviter-prompt.is-leaving .inviter-card { animation: inviter-fade .2s ease-in .45s forwards; }
.inviter-prompt:not(.is-welcomed).is-leaving .inviter-card { animation-delay: 0s; }

.creator-profile-referred { position: absolute; right: 12px; bottom: 10px; z-index: 2; }
#creator-profile .referred-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 0;
  padding: 2px 9px 2px 3px;
  border: 0;
  border-radius: 999px;
  background: rgba(8, 12, 16, .42);
  backdrop-filter: blur(4px);
  color: rgba(243, 234, 210, .72);
  font-size: .7rem;
  letter-spacing: .02em;
  opacity: .78;
  transition: opacity .2s ease;
}
#creator-profile .referred-badge:hover, #creator-profile .referred-badge:focus-visible { opacity: 1; }
#creator-profile .referred-badge.is-ask { padding-left: 9px; font-style: italic; opacity: .55; }
.referred-badge-icon { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; overflow: hidden; font-size: .75rem; }
.referred-badge-icon img { width: 100%; height: 100%; object-fit: cover; }

@keyframes inviter-rise { from { opacity: 0; transform: translateY(14px) scale(.97); } }
@keyframes inviter-hover { 50% { transform: translateY(-6px) rotate(-4deg); } }
@keyframes inviter-beam { to { transform: translateY(-80px) scale(.4); opacity: 0; } }
@keyframes inviter-fade { to { opacity: 0; transform: scale(.96); } }
@media (prefers-reduced-motion: reduce) {
  .inviter-card, .inviter-ufo, .inviter-prompt.is-welcomed .inviter-ufo { animation: none; }
}

