.feedback-table { width: 100%; table-layout: fixed; border-collapse: collapse; font-size: .8rem; }
.feedback-table :is(th, td) {
  padding: .35rem .3rem;
  border-bottom: 1px solid #ffffff22;
  text-align: left;
  vertical-align: top;
  overflow-wrap: anywhere;
}
.feedback-table thead th { color: #c9c1b0; font-size: .74rem; }
.feedback-table tbody th { width: 28%; }
.feedback-last, .feedback-limited { color: #c9c1b0; }
.feedback-limited:not(:empty) { color: #ffd2a1; }

@media (max-width: 600px) {
  .live-feedback-status { min-height: 2.5em; }
  .live-feedback-panel { padding: .75rem; }
  .feedback-table { font-size: .72rem; }
