.inbox-alien { display: grid; place-items: center; width: 38px; height: 38px; margin-left: -6px; border-radius: 999px; background: conic-gradient(#7ee0b5 calc(var(--p, 0) * 1turn), #ffffff22 0); animation: inbox-pop .4s cubic-bezier(.3, 1.4, .5, 1) both; transition: transform .2s; }
