@keyframes inbox-burst { to { transform: rotate(var(--a)) translateY(-34px); opacity: 0; } }
@keyframes inbox-pop { from { transform: scale(.85); opacity: 0; } }
@keyframes inbox-rise { from { transform: translateY(8px); opacity: 0; } }
@keyframes inbox-pulse { 50% { transform: scale(1.08); } }
@keyframes inbox-float { 50% { transform: translateY(-3px); } }
@keyframes inbox-spin { to { transform: rotate(1turn); } }
@media (prefers-reduced-motion: reduce) {
  .profile-inbox, .inbox-referral, .inbox-referral::before, .inbox-badge, .inbox-alien, :is(#creator-profile, .profile-inbox) .inbox-action.is-done, .inbox-burst i { animation: none; }
