/* css/styles.css — DecentBusking */
/* Dark space theme with warm stage lighting for the busker zone */

/* ── Reset & Base ─────────────────────────────────────────────────────────── */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-space: #03010a;
  --bg-stage: rgba(10, 5, 25, 0.85);
  --gold: #f0c040;
  --gold-dim: #b8922a;
  --amber: #ffb347;
  --teal: #00d4aa;
  --purple: #7c3aed;
  --text-primary: #f0e6c8;
  --text-dim: #8a7a5a;
  --border-glow: rgba(240, 192, 64, 0.35);
  --panel-bg: rgba(5, 3, 18, 0.92);
  --panel-border: rgba(240, 192, 64, 0.2);
  --font-display: 'Bungee', 'Impact', sans-serif;
  --font-body: 'Segoe UI', system-ui, sans-serif;
  --stage-radius: 16px;
  --transition: 0.25s ease;
}

html, body {
  width: 100%;
  height: 100%;
  overflow-x: hidden;
}

body {
  background: var(--bg-space);
  color: var(--text-primary);
  font-family: var(--font-body);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

/* ── Three.js Canvas (background) ────────────────────────────────────────── */
#space-canvas {
  position: fixed;
  inset: 0;
  z-index: 0;
  /* pointer-events enabled so raycaster can detect clicks on 3-D NFT meshes.
     UI elements (z-index ≥ 10) capture their own clicks first. */
  pointer-events: auto;
  cursor: default;
}

/* ── Header ──────────────────────────────────────────────────────────────── */
decent-header {
  display: block;
  position: relative;
  z-index: 100;
}

@media (max-width: 600px) {
  #stage {
    z-index: 60;
    pointer-events: none;
  }

  decent-header {
    position: relative;
    z-index: 100;
    flex: 0 0 112px;
    height: 112px;
  }

  #stage {
    min-height: calc(100vh - 112px);
  }

  #busker-info {
    top: auto;
    bottom: 174px;
    left: 50%;
    z-index: 60;
    width: min(88vw, 320px);
    padding: 0.45rem 0.8rem;
    background: rgba(5, 3, 18, 0.9);
    border: 1px solid var(--panel-border);
    border-radius: 10px;
    backdrop-filter: blur(10px);
    box-shadow: 0 4px 18px rgba(0,0,0,.38);
  }
  #now-playing-title { font-size: 1.05rem; }
  #center-stage {
    top: auto;
    bottom: 112px;
    left: 50%;
    z-index: 60;
    pointer-events: auto;
    gap: 2rem;

  }
  #hat-btn, #guitar-case-btn { font-size: 3.25rem; }
  #timeline-nav {
    bottom: 48px;
    left: 50%;
    max-width: calc(100vw - 24px);
    transform: translateX(-50%);
    gap: 0.35rem;
    padding: 0.4rem 0.55rem;
  }
  #timeline-slider { width: 150px; }

  #mobile-discord-link {
    position: fixed;
    bottom: 8px;
    left: 50%;
    z-index: 55;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    min-height: 36px;
    padding: 0.35rem 0.85rem;
    color: var(--text-primary);
    background: rgba(5, 3, 18, .92);
    border: 1px solid var(--panel-border);
    border-radius: 22px;
    box-shadow: 0 3px 12px rgba(0,0,0,.35);
    font-size: 0.78rem;
    text-decoration: none;
    transform: translateX(-50%);
  }
}

@media (min-width: 601px) {
  #busker-info,
  #center-stage,
  #timeline-nav {
    left: 50%;
    transform: translateX(-50%);
  }
}

/* ── Main Stage ──────────────────────────────────────────────────────────── */
#stage {
  position: relative;
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  flex: 1;
  padding: 2rem 1rem 3rem;
  min-height: calc(100vh - 120px);
}

/* Now-playing banner */
#busker-info {
  position: fixed;
  top: auto;
  bottom: 225px;
  left: calc(50% - 115px);
  transform: translateX(-50%);
  z-index: 20;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  text-align: center;
  pointer-events: none;
}

#now-playing-label {
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold-dim);
}

#now-playing-title {
  font-family: var(--font-display);
  font-size: 1.4rem;
  color: var(--gold);
  text-shadow: 0 0 18px rgba(240, 192, 64, 0.6);
  min-height: 1.6rem;
}

#now-playing-artist {
  font-size: 0.875rem;
  color: var(--text-dim);
}

/* Now Playing — play button (shown when autoplay is blocked) */
#now-playing-play-btn {
  pointer-events: auto;
  background: linear-gradient(135deg, var(--teal), var(--purple));
  color: #fff;
  border: none;
  border-radius: 20px;
  padding: 0.35rem 1rem;
  font-size: 0.8rem;
  font-family: var(--font-display);
  cursor: pointer;
  margin-top: 0.25rem;
  transition: opacity var(--transition), transform var(--transition);
  animation: pulse-glow 1.8s ease-in-out infinite;
}

#now-playing-play-btn:hover {
  opacity: 0.88;
  transform: scale(1.05);
}

.now-playing-actions {
  display: flex;
  gap: 0.5rem;
  justify-content: center;
}

#now-playing-radio-btn {
  pointer-events: auto;
  background: rgba(5, 3, 18, 0.75);
  color: var(--gold);
  border: 1px solid var(--gold-dim);
  border-radius: 20px;
  padding: 0.35rem 1rem;
  font-size: 0.8rem;
  font-family: var(--font-display);
  cursor: pointer;
  margin-top: 0.25rem;
  transition: background var(--transition), transform var(--transition);
}

#now-playing-radio-btn:hover {
  background: rgba(240, 192, 64, 0.15);
  transform: scale(1.05);
}

#radio-activity {
