}

.nft-watchlist-status {
  min-height: 1.1em;
  margin: 0.4rem 0 0;
  font-size: 0.75rem;
  color: var(--text-dim);
}
/* ── NFT Parent / Remix section ──────────────────────────────────────────── */
.nft-parent-section {
  margin-bottom: 0.75rem;
}

.nft-parent-card {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  background: rgba(124, 58, 237, 0.1);
