.hype-stage .hype-spark { left: calc(5% + var(--i) * 10%); bottom: 3px; font-size: 14px; color: #ffe1a2; opacity: 0; animation: hype-float 4.8s linear infinite; animation-delay: calc(var(--i) * -.73s); }
.hype-equalizer { position: absolute; bottom: 0; left: 5%; right: 5%; height: 34px; display: flex; align-items: end; gap: 4px; }

