}

#dnft-list-items::-webkit-scrollbar { width: 4px; }
#dnft-list-items::-webkit-scrollbar-thumb { background: var(--gold-dim); border-radius: 2px; }

:root { --recording-editor-width: min(560px, calc(100vw - 44px)); }
#recording-edit-tab {
  position: fixed;
  right: 0;
  top: calc(var(--header-height, 112px) + 140px);
  z-index: 121;
  display: grid;
  justify-items: center;
  align-content: center;
  gap: 5px;
  width: 44px;
  min-height: 86px;
  padding: 6px 2px;
  border: 1px solid #a491c5;
  border-right: 0;
  border-radius: 7px 0 0 7px;
  background: #241e32;
  color: #eee3ff;
  cursor: pointer;
  transition: right var(--transition);
}
#recording-edit-tab[hidden] { display: none; }
#recording-edit-tab span:first-child { font-size: 17px; }
#recording-edit-tab span:last-child { font: 700 .66rem var(--font-body); }
body.recording-edit-open #recording-edit-tab { right: var(--recording-editor-width); }
#recording-edit-panel {
  position: fixed;
  right: 0;

  top: calc(var(--header-height, 112px) + 12px);
  bottom: calc(var(--radio-footer-height, 96px) + 12px);
  width: var(--recording-editor-width);
  z-index: 120;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: rgba(5, 3, 18, 0.96);
  border-left: 1px solid var(--panel-border);
  box-shadow: -16px 0 38px rgba(0, 0, 0, 0.42);
  backdrop-filter: blur(12px);
  transform: translateX(calc(100% + 12px));
  visibility: hidden;
  pointer-events: none;
  transition: transform var(--transition), visibility var(--transition);
}

#recording-edit-panel.is-open {
  transform: translateX(0);
  visibility: visible;
  pointer-events: auto;
}

.recording-edit-panel-heading {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-height: 48px;
  padding: 0.45rem 0.75rem;
  border-bottom: 1px solid var(--panel-border);
}

.recording-edit-panel-heading h2 {
  flex: 1;
  margin: 0;
  color: var(--gold);
  font: 600 0.78rem var(--font-display);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.recording-edit-panel-heading button {
  width: 30px;
  height: 30px;
  border: 1px solid rgba(240,192,64,.24);
  border-radius: 50%;
  color: var(--text-dim);
  background: transparent;
  cursor: pointer;
}

#recording-edit-panel iframe {
  flex: 1;
  width: 100%;
  min-height: 0;

  border: 0;
  background: #080612;
}
#recording-edit-panel [hidden] { display: none; }
.recording-edit-library { padding: .6rem .8rem; border-bottom: 1px solid var(--panel-border); }
.recording-edit-library label { display: block; color: var(--text-dim); font-size: .75rem; margin-bottom: .35rem; }
.recording-edit-library input {
  box-sizing: border-box; width: 100%; padding: .6rem; border: 1px solid #736086;
  border-radius: 6px; background: #151121; color: var(--text);
}
#recording-edit-library-status { margin: .4rem 0; color: var(--text-dim); font-size: .72rem; }
#recording-edit-library { list-style: none; padding: 0; margin: 0; max-height: 120px; overflow-y: auto; }
#recording-edit-library button, #recording-edit-more {
  width: 100%; padding: .5rem; border: 0; border-radius: 4px; background: #231b32;
  color: #e5dcf4; text-align: left; cursor: pointer; margin: 2px 0;
}
#recording-edit-library button:hover { background: #3a2c50; }
#recording-edit-panel:has(iframe:not([hidden])) #recording-edit-library { max-height: 72px; }
#recording-edit-opening { flex: 1; display: grid; place-content: center; padding: 1rem; text-align: center; color: #e0c9ff; }
#recording-edit-opening > span { font-size: 2rem; }
#recording-edit-panel button:focus-visible, #recording-edit-tab:focus-visible,
#recording-edit-panel input:focus-visible { outline: 2px solid #c5a5f2; outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) {
  #recording-edit-panel, #recording-edit-tab { transition: none; }
}

.dnft-list-item {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  padding: 0.55rem 0.85rem;
  cursor: pointer;
  border-bottom: 1px solid rgba(240, 192, 64, 0.07);
  transition: background var(--transition), border-left var(--transition);
  border-left: 2px solid transparent;
}

.dnft-list-item:hover {
  background: rgba(240, 192, 64, 0.06);
  border-left-color: var(--gold-dim);
}

.dnft-list-item.active {
  background: rgba(0, 212, 170, 0.08);
  border-left-color: var(--teal);
}

.dnft-list-item-title {
  font-size: 0.8rem;
  color: var(--text-primary);
  font-weight: bold;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dnft-list-item-meta {
  font-size: 0.68rem;
  color: var(--text-dim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dnft-list-empty {
  padding: 1rem 0.85rem;
  color: var(--text-dim);
  font-size: 0.78rem;
  font-style: italic;
}

/* ── DNFT list spinner ────────────────────────────────────────────────────── */
.dnft-list-spinner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0.75rem 0;
  list-style: none;
}

.dnft-spinner-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--gold);
  animation: dnftPulse 1.2s ease-in-out infinite;
}
.dnft-spinner-dot:nth-child(2) { animation-delay: 0.2s; }
.dnft-spinner-dot:nth-child(3) { animation-delay: 0.4s; }

@keyframes dnftPulse {

  0%, 80%, 100% { opacity: 0.2; transform: scale(0.7); }
  40%            { opacity: 1;   transform: scale(1);   }
}

/* ── "Show All Now" button ────────────────────────────────────────────────── */
.dnft-show-all-btn {
  display: block;
  width: 100%;
  padding: 0.5rem 0.85rem;
  background: transparent;
  border: none;
  border-top: 1px solid var(--panel-border);
  color: var(--teal);
  font-size: 0.72rem;
  font-family: var(--font-body);
  cursor: pointer;
  text-align: center;
  letter-spacing: 0.04em;
  transition: background var(--transition), color var(--transition);
  flex-shrink: 0;
}
.dnft-show-all-btn:hover {
  background: rgba(0, 212, 170, 0.07);
  color: #00d4aa;
}
.dnft-show-all-btn:disabled {
  color: var(--text-dim);
  cursor: default;
}

/* ── Timeline Navigation Controls ────────────────────────────────────────── */
#timeline-nav {
  position: fixed;
  bottom: 72px;
  /* Shift left by ~half the list-panel width (230px / 2 ≈ 115px) so the nav
     appears centred in the main viewport area, not under the right-side panel. */
  left: calc(50% - 115px);
  transform: translateX(-50%);
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  background: rgba(5, 3, 18, 0.88);
  border: 1px solid var(--panel-border);
  border-radius: 28px;
  padding: 0.45rem 0.9rem;
  backdrop-filter: blur(12px);
  box-shadow: 0 0 20px rgba(240, 192, 64, 0.08);
}

#timeline-nav button {
  background: none;
  border: none;
  color: var(--gold-dim);
  font-size: 1rem;
  line-height: 1;

  cursor: pointer;
  padding: 0.2rem 0.35rem;
  border-radius: 50%;
  transition: color var(--transition), background var(--transition);
}

#timeline-nav button:hover {
  color: var(--gold);
  background: rgba(240, 192, 64, 0.1);
}

#timeline-nav button:disabled {
  opacity: 0.3;
  cursor: default;
}

#timeline-slider-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.15rem;
}

#timeline-slider {
  width: 180px;
  accent-color: var(--gold);
  cursor: pointer;
}

#timeline-label {
  font-size: 0.65rem;
  color: var(--text-dim);
  text-align: center;
  min-width: 90px;
  letter-spacing: 0.03em;
}

/* Shrink stage right-padding when list panel is present */
@media (min-width: 600px) {
  #stage {
    padding-right: 240px;
  }
  /* Shift fixed Now Playing / controls left so they don't overlap the list panel */
  #busker-info,
  #center-stage {
    left: calc(50% - 115px);
  }
}

/* ── Mint Modal ──────────────────────────────────────────────────────────── */
#mint-modal {
  position: fixed;
  inset: 0;
  z-index: 300;
  display: flex;
  align-items: center;

  justify-content: center;
  background: rgba(3, 1, 10, 0.82);
  backdrop-filter: blur(6px);
  animation: fadeIn 0.2s ease;
}

#mint-modal-inner {
  box-sizing: border-box;
  background: radial-gradient(ellipse at 0 0, #24403e88, transparent 55%), linear-gradient(145deg, #192a2e, #0e191e 70%);
  border: 1px solid #91bdb75c;
  border-radius: 20px;
  padding: 28px;
  width: 90vw;
  max-width: 720px;
  max-height: 90vh;
  overflow-y: auto;
  box-shadow: inset 0 1px #d4fff52b, 0 24px 90px #000a, 0 0 45px #6ab8ad12;
}

#mint-modal-inner h2 {
  font-family: var(--font-body);
  color: #e4f7ef;
  margin-bottom: 0.5rem;
  font-size: 1.9rem;
}

#mint-modal-inner p {
  color: var(--text-dim);
  font-size: 0.875rem;
  margin-bottom: 1.25rem;
  line-height: 1.5;
}

.mint-modal-heading, .submission-policy-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.mint-modal-heading h2 { margin: 0; }
.mint-modal-heading { margin-bottom: 16px; }
.submission-policy-icon { flex: 0 0 36px; width: 36px; height: 36px; display: inline-flex; align-items: center; justify-content: center; padding: 0; border: 1px solid var(--panel-border); border-radius: 4px; color: var(--text-primary); background: transparent; cursor: pointer; }
.submission-policy-icon img { filter: invert(1); }
.submission-policy-icon:focus-visible { outline: 2px solid var(--teal); outline-offset: 3px; }
#submission-policy-dialog { box-sizing: border-box; margin: auto; width: min(480px, calc(100% - 24px)); max-height: 85vh; overflow-y: auto; padding: 20px; border: 1px solid var(--panel-border); border-radius: 6px; background: #10121a; color: var(--text-primary); }
#submission-policy-dialog::backdrop { background: rgba(0,0,0,.72); }

#submission-policy-dialog h2 { margin: 0; font-size: 1.05rem; }
#submission-policy-dialog p { margin: 12px 0 0; font-size: .85rem; line-height: 1.5; }
#submission-policy-dialog a { color: var(--teal); }
.submission-policy-note { color: var(--text-dim); }

#mint-form label {
  display: block;
  font-size: 0.8rem;
  text-transform: none;
  letter-spacing: .01em;
  color: #b5d3ce;
  margin-bottom: 0.3rem;
}

#mint-form label .hint {
  font-size: 0.75rem;
  text-transform: none;
  letter-spacing: 0;
  color: var(--text-dim);
}

#mint-form input[type="text"],
#mint-form input[type="number"],
#mint-form input[type="file"] {
  width: 100%;
  box-sizing: border-box;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid #9fc9c32e;
  border-radius: 6px;
  padding: 0.6rem 0.75rem;
  color: var(--text-primary);
  font-size: 0.9rem;
  margin-bottom: 1rem;
  outline: none;
  transition: border-color var(--transition);
}

#mint-form input:focus {
  border-color: var(--teal);
}

#mint-form input[type="file"] {
  cursor: pointer;
}

#mint-status {
  font-size: 0.85rem;
  min-height: 1.2rem;
  margin-bottom: 0.75rem;
  color: var(--teal);
}

#mint-status.error {
  color: #f87171;
}

.mint-form-actions {
  display: flex;
  gap: 0.75rem;
}

#mint-submit-btn {
  flex: 1;
  padding: 0.75rem;
  background: linear-gradient(160deg, #acd8ca, #5e9d90);
  color: #102824;
  box-shadow: inset 0 1px #e6fff4aa, 0 3px 12px #0004;
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 0.95rem;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: opacity var(--transition);
}

#mint-submit-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

#mint-cancel-btn {
  padding: 0.75rem 1.25rem;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: var(--text-dim);
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.9rem;
  transition: background var(--transition);
}

#mint-cancel-btn:hover {
  background: rgba(255, 255, 255, 0.1);
}
.mint-eyebrow { font-size: .65rem; letter-spacing: .19em; color: #93bcb5; }
.mint-flow { display: flex; justify-content: space-between; gap: 8px; padding: 12px 0 18px; margin: 0; list-style: none; color: #8fbab2; font-size: .74rem; border-bottom: 1px solid #b4d9cc1c; }
.mint-step { padding: 20px 0; border-bottom: 1px solid #b4d9cc1c; }
.mint-step h3 { margin: 0 0 14px; font-size: 1.04rem; color: #d3ebe1; font-weight: 600; }
.mint-step h3 > span { display: inline-grid; place-items: center; width: 30px; height: 30px; margin-right: 6px; border-radius: 9px; background: #93d3c219; color: #a4d8c7; }
.mint-two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }

#mint-form .mint-dropzone { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 9px; min-height: 165px; padding: 20px; border: 1px dashed #8fc6b875; border-radius: 14px; text-align: center; background: linear-gradient(150deg, #a1ddca0d, #51847f0b); cursor: pointer; transition: border-color .2s, background .2s; overflow: hidden; }
#mint-form .mint-dropzone:hover, #mint-form .mint-dropzone.is-dragover, #mint-form .mint-dropzone:focus-within { border-color: #b0e9d2; background: #a1ddca18; }
.mint-dropzone strong { color: #d4e9e1; font-size: 1rem; font-weight: 600; }
.mint-dropzone small { color: #8fa9a5; font-size: .7rem; line-height: 1.5; }
.mint-drop-icon { font-size: 2rem; }
#mint-form .mint-dropzone input[type="file"] { position: absolute; inset: 0; opacity: 0; margin: 0; padding: 0; width: 100%; height: 100%; cursor: pointer; }
#mint-form .mint-art-drop { min-height: 110px; }
#mint-art-preview { width: 94px; height: 94px; object-fit: cover; border-radius: 12px; box-shadow: 0 4px 16px #0006; }
#mint-modal-inner .mint-help { font-size: .76rem; color: #a2b9b5; margin: 8px 0 12px; }
#mint-modal-inner .mint-detected { font-size: .78rem; color: #a4d8c7; margin: 12px 0; overflow-wrap: anywhere; }
#mint-media-preview audio, #mint-media-preview video { display: block; width: 100%; max-height: 230px; margin-bottom: 14px; border-radius: 10px; }
#mint-form .mint-ad-choice { display: flex; align-items: flex-start; gap: 10px; margin: 16px 0 0; padding: 13px; background: #7ca79f10; border: 1px solid #bdd9d01f; border-radius: 10px; }
.mint-ad-choice small { display: block; margin-top: 5px; color: #a2b9b5; line-height: 1.5; }
.mint-ad-choice input { accent-color: #8fc6b8; flex: 0 0 auto; margin-top: 3px; }

.mint-extras { margin-top: 16px; }
.mint-extras summary { color: #a9cec5; font-size: .8rem; cursor: pointer; margin-bottom: 12px; }
.mint-split-row { display: grid; grid-template-columns: minmax(0, 1fr) 95px 30px; align-items: center; gap: 9px; }
#mint-form .mint-split-row input { margin: 5px 0 10px; font-size: .8rem; }
.mint-split-row button, .mint-split-tools button { color: #b4dace; border: 1px solid #8bada640; background: linear-gradient(#243c3b, #192c2b); border-radius: 7px; padding: 8px; cursor: pointer; font: inherit; font-size: .75rem; box-shadow: inset 0 1px #d8fff011; }
.mint-split-tools { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
#mint-split-total { margin-left: auto; color: #a9d5bf; font-size: .76rem; }
#mint-split-total.error { color: #f6b49d; }
#mint-modal-inner .mint-review-note { margin: 18px 0 12px; font-size: .77rem; }
#mint-status { overflow-wrap: anywhere; }
@media (max-width: 600px) {
  #mint-modal-inner { width: calc(100vw - 20px); padding: 20px 16px; max-height: 92dvh; border-radius: 15px; }
  .mint-two-col { grid-template-columns: 1fr; gap: 0; }
  .mint-flow { font-size: .66rem; gap: 4px; }
  .mint-split-row { grid-template-columns: minmax(0, 1fr) 76px 26px; gap: 6px; }
}

.mint-referral-section {
  margin: 0.85rem 0;
  padding: 0.85rem;
  border: 1px solid rgba(240, 192, 64, 0.24);
  border-radius: 10px;
  background: rgba(240, 192, 64, 0.06);
}

.mint-referral-section h4,
.mint-referral-section p {
  margin: 0 0 0.5rem;
}

.mint-referral-section small {
  display: block;
  color: var(--text-dim);
  line-height: 1.4;
}
@media (prefers-reduced-motion: reduce) {
  #mint-modal { animation: none; }
  #mint-form .mint-dropzone { transition: none; }
}

/* ── Mint Parent Preview ─────────────────────────────────────────────────── */
#mint-parent-preview {
  margin-bottom: 1rem;
}

#mint-parent-preview-inner {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  background: rgba(0, 212, 170, 0.07);
  border: 1px solid rgba(0, 212, 170, 0.25);
  border-radius: 8px;
  padding: 0.75rem 1rem;
}

#mint-parent-preview-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--teal);
}

#mint-parent-preview-title {
  font-family: var(--font-display);
  font-size: 0.95rem;
  color: var(--gold);
}

#mint-parent-preview-artist {
  font-size: 0.8rem;
  color: var(--text-dim);
}

#mint-parent-preview-audio {
  width: 100%;
  margin-top: 0.35rem;
  accent-color: var(--teal);
}

/* ── Tip Modal ───────────────────────────────────────────────────────────── */
#tip-modal {
  position: fixed;
  inset: 0;
  z-index: 300;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(3, 1, 10, 0.82);
  backdrop-filter: blur(6px);
  animation: fadeIn 0.2s ease;
}

#tip-modal-inner {
  background: var(--panel-bg);
  border: 1px solid var(--panel-border);
  border-radius: var(--stage-radius);

  padding: 2rem;
  width: 90vw;
  max-width: 520px;
  box-shadow: 0 0 60px rgba(240, 192, 64, 0.12);
}

#tip-modal-inner h2 {
  font-family: var(--font-display);
  color: var(--gold);
  margin-bottom: 0.5rem;
}

#tip-modal-inner p {
  color: var(--text-dim);
  font-size: 0.875rem;
  margin-bottom: 1.25rem;
}

.tip-track-picker {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.tip-track-picker button {
  width: 2.5rem;
  min-height: 2.5rem;
  padding: 0;
  border: 1px solid rgba(240, 192, 64, 0.2);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  color: var(--gold);
  font-size: 1.1rem;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), opacity var(--transition);
}

.tip-track-picker button:hover:not(:disabled) {
  background: rgba(240, 192, 64, 0.14);
  transform: translateY(-1px);
}

.tip-track-picker button:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
}

.tip-track-picker button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
  transform: none;
}

.tip-track-details {

  min-width: 0;
  text-align: center;
}

.tip-track-details p {
  margin-bottom: 0;
}

.tip-track-position {
  margin-bottom: 0.35rem !important;
  color: var(--gold-dim) !important;
  font-size: 0.74rem !important;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  min-height: 1em;
}

#tip-form label {
  display: block;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gold-dim);
  margin-bottom: 0.3rem;
}

.tip-wallet-address {
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  font-family: monospace;
}

.tip-wallet-address img {
  width: 20px;
  height: 20px;
  object-fit: contain;
}

#tip-form label .hint {
  font-size: 0.75rem;
  text-transform: none;
  letter-spacing: 0;
  color: var(--text-dim);
}

#tip-amount {
  width: 100%;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(240, 192, 64, 0.2);
  border-radius: 6px;
  padding: 0.6rem 0.75rem;
  color: var(--text-primary);
  font-size: 1.1rem;
  margin-bottom: 1rem;
  outline: none;

  transition: border-color var(--transition);
}

#tip-amount:focus {
  border-color: var(--gold);
}

.tip-usdc-estimate {
  margin: -0.75rem 0 1rem;
  color: var(--text-dim);
  font-size: 0.78rem;
}

.tip-asset-picker {
  display: flex;
  justify-content: center;
  gap: 0.6rem;
  margin-bottom: 1rem;
}

.tip-asset-picker button {
  width: 3rem;
  height: 3rem;
  border-radius: 50%;
  border: 1px solid rgba(240, 192, 64, 0.25);
  background: rgba(255, 255, 255, 0.04);
  color: var(--gold-dim);
  font-size: 1.35rem;
  cursor: pointer;
  transition: transform var(--transition), box-shadow var(--transition), color var(--transition);
}

.tip-asset-picker button:hover,
.tip-asset-picker button:focus-visible {
  transform: translateY(-2px);
  color: var(--gold);
}

.tip-asset-picker button[aria-checked="true"] {
  color: var(--gold);
  border-color: var(--gold);
  box-shadow: 0 0 0 3px rgba(240, 192, 64, 0.15), 0 0 18px rgba(240, 192, 64, 0.35);
}

.tip-gift-list {
  list-style: none;
  margin: 0 0 0.6rem;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}

.tip-gift-row {
  display: grid;
  grid-template-columns: minmax(0, 2.4fr) minmax(0, 1fr) 4rem minmax(0, 1.4fr) 2rem;
  gap: 0.35rem;

  align-items: center;
}

.tip-gift-row input,
.tip-gift-row select {
  min-width: 0;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(240, 192, 64, 0.2);
  border-radius: 6px;
  padding: 0.45rem 0.5rem;
  color: var(--text-primary);
  font: inherit;
  font-size: 0.85rem;
}

.tip-gift-row button,
.tip-gift-add {
  border: 1px dashed rgba(240, 192, 64, 0.35);
  border-radius: 999px;
  background: transparent;
  color: var(--gold);
  cursor: pointer;
  font: inherit;
}

.tip-gift-add {
  padding: 0.3rem 0.9rem;
  margin-bottom: 1rem;
}

@media (max-width: 560px) {
  .tip-gift-row { grid-template-columns: 1fr 1fr; }
  .tip-gift-row input[data-gift="collection"] { grid-column: 1 / -1; }
}

.tip-wallet-copy {
  margin-left: 0.55rem;
  padding: 0.28rem 0.5rem;
  border: 1px solid rgba(240, 192, 64, 0.3);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--gold);
  font: inherit;
  cursor: pointer;
}

.tip-wallet-copy:hover,
.tip-wallet-copy:focus-visible {
  background: rgba(240, 192, 64, 0.12);
}

#tip-status {
  font-size: 0.85rem;
  overflow-wrap: anywhere;
  min-height: 1.2rem;
  margin-bottom: 0.75rem;

  color: var(--teal);
}

#tip-status.error {
  color: #f87171;
}

.tip-form-actions {
  display: flex;
  gap: 0.75rem;
}

#tip-send-btn {
  flex: 1;
  padding: 0.75rem;
  background: linear-gradient(135deg, var(--gold), var(--amber));
  color: #111;
  font-family: var(--font-display);
  font-size: 0.95rem;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: opacity var(--transition);
}

#tip-send-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

#tip-cancel-btn {
  padding: 0.75rem 1.25rem;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: var(--text-dim);
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.9rem;
  transition: background var(--transition);
}

#tip-cancel-btn:hover {
  background: rgba(255, 255, 255, 0.1);
}

@media (max-width: 600px) {
  #tip-modal-inner {
    width: min(94vw, 520px);
    padding: 1.25rem;
  }

  .tip-track-picker {
    gap: 0.5rem;
  }

  .tip-track-picker button {

    width: 2.25rem;
    min-height: 2.25rem;
  }
}

/* ── Footer ──────────────────────────────────────────────────────────────── */
decent-foot {
  position: relative;
  z-index: 100;
}

/* ── Utility ──────────────────────────────────────────────────────────────── */
.hidden {
  display: none !important;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translate(-50%, calc(-50% + 10px)); }
  to   { opacity: 1; transform: translate(-50%, -50%); }
}

/* Non-translate fadeIn for modals */
#mint-modal,
#tip-modal {
  animation: overlayFadeIn 0.2s ease;
}

@keyframes overlayFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* ── Payroll Panel ────────────────────────────────────────────────────────── */

/* Payroll open button — anchored in center-stage next to hat/guitar buttons */
#payroll-open-btn {
  background: linear-gradient(135deg, rgba(0, 212, 170, 0.15), rgba(124, 58, 237, 0.15));
  border: 1px solid var(--teal);
  color: var(--teal);
  padding: 0.5rem 1.1rem;
  border-radius: 999px;
  cursor: pointer;
  font-size: 0.9rem;
  font-family: var(--font-body);
  transition: var(--transition);
  white-space: nowrap;
}
#payroll-open-btn:hover {
  background: rgba(0, 212, 170, 0.25);
  box-shadow: 0 0 12px rgba(0, 212, 170, 0.4);
}

/* Overlay backdrop */
#payroll-overlay {
  position: fixed;
  inset: 0;

  background: rgba(0, 0, 0, 0.72);
  z-index: 1100;
  backdrop-filter: blur(4px);
}

/* Modal container */
#payroll-modal {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 1200;
  width: min(92vw, 760px);
  max-height: 90vh;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--teal) transparent;
  animation: overlayFadeIn 0.22s ease;
}

#payroll-modal-inner {
  background: var(--panel-bg);
  border: 1px solid var(--teal);
  border-radius: var(--stage-radius);
  box-shadow: 0 0 40px rgba(0, 212, 170, 0.25), 0 0 80px rgba(124, 58, 237, 0.15);
  padding: 1.8rem 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
}

/* Header row */
#payroll-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(0, 212, 170, 0.2);
  padding-bottom: 0.8rem;
}
#payroll-modal-header h2 {
  font-family: var(--font-display);
  color: var(--teal);
  font-size: 1.4rem;
  letter-spacing: 0.03em;
}
#payroll-close-btn {
  background: none;
  border: none;
  color: var(--text-dim);
  font-size: 1.4rem;
  cursor: pointer;
  transition: var(--transition);
}
#payroll-close-btn:hover { color: var(--text-primary); }

/* Description */

.payroll-description {
  color: var(--text-dim);
  font-size: 0.9rem;
  line-height: 1.5;
}

/* Connect section */
#payroll-connect-row {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}
.payroll-addr {
  font-family: 'Courier New', monospace;
  font-size: 0.8rem;
  color: var(--text-dim);
  background: rgba(255,255,255,0.04);
  padding: 0.25rem 0.6rem;
  border-radius: 6px;
}

/* Owner warning */
.payroll-warning {
  background: rgba(255, 107, 107, 0.12);
  border: 1px solid rgba(255, 107, 107, 0.4);
  border-radius: 8px;
  padding: 0.6rem 1rem;
  color: #ff9999;
  font-size: 0.88rem;
}

/* Status text */
.payroll-status {
  font-size: 0.88rem;
  min-height: 1.2em;
  color: var(--teal);
}
.payroll-status a { color: var(--teal); }

/* Queue header */
#payroll-queue-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
#payroll-queue-header h3 {
  font-family: var(--font-display);
  color: var(--gold);
  font-size: 1rem;
  letter-spacing: 0.02em;
}

/* Empty message */
.payroll-empty {
  color: var(--teal);

  text-align: center;
  padding: 1rem;
  font-size: 0.95rem;
}

/* Table */
.payroll-table-wrap {
  min-width: 0;
  max-width: 100%;
  overflow-x: auto;
  border-radius: 8px;
  border: 1px solid var(--panel-border);
}

.payroll-section { padding: 16px 0; border-top: 1px solid var(--panel-border); }
.payroll-section h3 { margin: 0 0 10px; font-size: 1rem; }
.payroll-allocation { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px 16px; margin: 0; font-size: .85rem; }
.payroll-allocation dt { color: var(--text-dim); }
.payroll-allocation dd { margin: 0; }
.radio-payroll-controls { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; margin: 12px 0; }
.radio-payroll-controls label { display: grid; gap: 6px; font-size: .8rem; color: var(--text-dim); }
.payroll-fund-guide { margin: 10px 0; padding: 10px 12px; color: var(--text-dim); background: rgba(0,212,170,.06); border-left: 2px solid var(--teal); font-size: .78rem; line-height: 1.5; }
.payroll-field-hint { color: var(--text-dim); font-size: .7rem; line-height: 1.4; }
.radio-payroll-controls input, .radio-payroll-controls select, .radio-payroll-controls textarea { min-width: 0; width: 100%; min-height: 38px; padding: 8px; font: inherit; color: var(--text-primary); background: #10121a; border: 1px solid var(--panel-border); border-radius: 4px; }
.radio-payroll-controls textarea { resize: vertical; }
.radio-payroll-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.payroll-funding-band { padding: 12px 0; border-bottom: 1px solid var(--panel-border); }
.payroll-funding-band h4 { margin: 0 0 6px; font-size: .9rem; }
.payroll-funding-band meter { display: block; width: 100%; height: 16px; }

.payroll-funding-band p { margin: 6px 0 0; font-size: .8rem; line-height: 1.45; overflow-wrap: anywhere; }
.payroll-funding-warning { color: var(--gold); }
.radio-payroll-controls input[readonly] { opacity: .85; }
.settlement-router-section summary { cursor: pointer; font-weight: 700; margin-bottom: 16px; }
.settlement-router-section .payroll-allocation dd { min-width: 0; overflow-wrap: anywhere; max-width: 100%; }
.settlement-router-section .payroll-allocation { grid-template-columns: auto minmax(0, 1fr); }
.router-metadata-label { grid-column: 1 / -1; }
#router-custom-fund-label[hidden] { display: none; }
#router-custom-fund-form[hidden] { display: none; }
#router-save-metadata { display: inline-flex; align-items: center; gap: 8px; }
#router-save-metadata img { filter: invert(1); opacity: .8; }
#router-metadata-status { overflow-wrap: anywhere; }
.settlement-router-section .radio-payroll-controls { grid-template-columns: minmax(0, 1fr); }
.settlement-router-section select { width: 100%; min-width: 0; }
.settlement-router-section #router-fund-status { overflow-wrap: anywhere; }
.settlement-router-section .payroll-status { overflow-wrap: anywhere; }
.radio-payroll-artist { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; padding: 10px 0; border-bottom: 1px solid var(--panel-border); font-size: .8rem; overflow-wrap: anywhere; }
@media (max-width: 600px) { .radio-payroll-artist { grid-template-columns: minmax(0, 1fr); } }
.payroll-secondary-flow { margin: 12px 0; border-block: 1px solid var(--panel-border); }
.payroll-secondary-flow > summary { padding: 10px 0; cursor: pointer; font-weight: 600; }
.payroll-work-reference { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px 10px; align-items: center; padding: 8px 0 12px; }

.payroll-work-reference > span { color: var(--text-dim); font-size: .75rem; }
.payroll-work-reference > input { grid-column: 1; width: 100%; min-width: 0; font-size: .72rem; font-family: monospace; }
.payroll-copy-reference { grid-column: 2; grid-row: 1 / span 2; }
.payroll-legacy-warning { color: var(--gold); font-size: .85rem; }
.payroll-legacy-review { display: grid; min-width: 220px; gap: 8px; margin-top: 8px; }
.payroll-legacy-review input[type="text"], .payroll-tx-hash { min-width: 0; width: 100%; padding: 8px; border: 1px solid var(--panel-border); border-radius: 4px; background: #10121a; color: var(--text-primary); font: inherit; }
.payroll-legacy-review label { font-size: .75rem; white-space: normal; }
.payroll-verify-btn { padding: 6px 8px; border: 1px solid var(--panel-border); border-radius: 4px; color: var(--text-primary); background: #10121a; cursor: pointer; }
#payroll-connect-section, #payroll-queue-section { min-width: 0; max-width: 100%; }
#payroll-modal .payroll-addr { max-width: 100%; white-space: normal; overflow-wrap: anywhere; }
#payroll-settle-hint { min-width: 0; overflow-wrap: anywhere; }
#payroll-settle-hint code { word-break: break-all; }
@media (max-width: 600px) {
  #payroll-table thead { display: none; }
  #payroll-table, #payroll-table tbody { display: block; width: 100%; }
  #payroll-table .payroll-row { display: grid; grid-template-columns: minmax(0, 1fr) auto; border-bottom: 1px solid var(--panel-border); }
  #payroll-table .payroll-td { display: block; min-width: 0; border: 0; }
  #payroll-table .payroll-td:nth-child(2), #payroll-table .payroll-td:nth-child(4), #payroll-table .payroll-td:nth-child(5) { grid-column: 1 / -1; }
  #payroll-table .payroll-td:nth-child(3) { grid-column: 2; grid-row: 1; }

  #payroll-table .payroll-legacy-review { min-width: 0; }
}
.payroll-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.87rem;
}
.payroll-table thead th {
  background: rgba(0, 212, 170, 0.08);
  color: var(--teal);
  padding: 0.55rem 0.8rem;
  text-align: left;
  font-weight: 600;
  white-space: nowrap;
}
.payroll-table tbody tr {
  border-top: 1px solid rgba(255,255,255,0.06);
  transition: background var(--transition);
}
.payroll-table tbody tr:hover { background: rgba(255,255,255,0.03); }
.payroll-table tbody tr.payroll-row-paid {
  opacity: 0.5;
  text-decoration: line-through;
}
.payroll-td {
  padding: 0.55rem 0.8rem;
  color: var(--text-primary);
  vertical-align: middle;
}
.payroll-loading {
  text-align: center;
  padding: 1rem;
  color: var(--text-dim);
}
.payroll-error { color: #ff6b6b !important; }

/* Table links */
.payroll-addr-link,
.payroll-github-link,
.payroll-issue-link,
.payroll-link {
  color: var(--teal);
  text-decoration: none;
  transition: var(--transition);
}
.payroll-addr-link:hover,
.payroll-github-link:hover,
.payroll-issue-link:hover,
.payroll-link:hover { text-decoration: underline; }

.payroll-avatar {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  vertical-align: middle;
  margin-right: 0.35rem;

}
.payroll-amount { font-family: 'Courier New', monospace; color: var(--gold); }
.payroll-no-wallet { color: #ff9999; font-size: 0.82rem; }

/* Pay buttons */
.payroll-pay-btn {
  background: rgba(0, 212, 170, 0.12);
  border: 1px solid var(--teal);
  color: var(--teal);
  padding: 0.28rem 0.7rem;
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.82rem;
  transition: var(--transition);
}
.payroll-pay-btn:hover { background: rgba(0, 212, 170, 0.25); }
.payroll-pay-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.payroll-pay-disabled { color: var(--text-dim); font-size: 0.82rem; }

/* Settle All row */
#payroll-settle-all-row {
  display: flex;
  justify-content: flex-end;
  padding-top: 0.5rem;
}

/* Hint block */
.payroll-hint {
  background: rgba(0, 212, 170, 0.07);
  border: 1px solid rgba(0, 212, 170, 0.2);
  border-radius: 8px;
  padding: 0.6rem 1rem;
  font-size: 0.85rem;
  color: var(--text-dim);
  line-height: 1.5;
}
.payroll-hint a { color: var(--teal); }
.payroll-hint code {
  font-family: 'Courier New', monospace;
  font-size: 0.78rem;
  background: rgba(255,255,255,0.07);
  padding: 0.1rem 0.35rem;
  border-radius: 4px;
}

/* Buttons */
.payroll-btn {
  border: none;
  padding: 0.55rem 1.1rem;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.9rem;
  font-family: var(--font-body);

  transition: var(--transition);
}
.payroll-btn-primary {
  background: linear-gradient(135deg, var(--teal), var(--purple));
  color: #fff;
  font-weight: 600;
}
.payroll-btn-primary:hover { filter: brightness(1.1); }
.payroll-btn-primary:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  filter: none;
}
.payroll-btn-secondary {
  background: rgba(255,255,255,0.06);
  color: var(--text-dim);
  border: 1px solid rgba(255,255,255,0.1);
}
.payroll-btn-secondary:hover { background: rgba(255,255,255,0.1); color: var(--text-primary); }

/* Supporter tokens owed */
.supporter-payroll { margin-top: 1.1rem; padding: 0.8rem 0.9rem; border-radius: 18px;
  background: radial-gradient(circle at 12% 0%, rgba(255, 200, 80, 0.1), transparent 60%), rgba(255,255,255,0.03);
  border: 1px solid rgba(255, 200, 80, 0.18); transition: box-shadow 0.4s ease; }
.supporter-payroll.is-celebrating { box-shadow: 0 0 22px rgba(255, 200, 80, 0.45); }
.supporter-payroll-head { display: flex; align-items: center; gap: 0.5rem; }
.supporter-payroll-head h4 { margin: 0; font-family: var(--font-display); color: var(--gold); font-size: 0.95rem; }
.supporter-payroll-count { font-size: 0.8rem; color: var(--text-dim); padding: 0.1rem 0.55rem; border-radius: 999px; background: rgba(255,255,255,0.06); }
.supporter-payroll-info { margin-left: auto; cursor: help; color: var(--teal); }
.supporter-payroll-list { list-style: none; margin: 0.6rem 0 0; padding: 0; display: grid; gap: 0.4rem; }
.supporter-payroll-row { display: flex; flex-wrap: wrap; align-items: center; gap: 0.4rem 0.8rem; padding: 0.45rem 0.7rem;
  border-radius: 999px; background: rgba(255,255,255,0.04); }
.supporter-payroll-row.is-transfer-pending { animation: supporter-pending 1.6s ease-in-out infinite; }

.supporter-payroll-who { font-weight: 600; }
.supporter-payroll-what { font-size: 0.85rem; color: var(--text-dim); }
.supporter-payroll-actions { margin-left: auto; display: flex; gap: 0.35rem; }
.supporter-payroll-btn { border-radius: 999px; padding: 0.3rem 0.8rem; font-size: 0.82rem; }
.supporter-payroll-btn:disabled { opacity: 0.45; cursor: not-allowed; }
.supporter-payroll-status { margin: 0.45rem 0 0; }
.supporter-payroll-status.is-error { color: #ff9999; }
@keyframes supporter-pending { 50% { background: rgba(255, 200, 80, 0.1); } }
@media (prefers-reduced-motion: reduce) { .supporter-payroll-row.is-transfer-pending { animation: none; } }

/* Responsive */
@media (max-width: 600px) {
  #payroll-modal-inner { padding: 1.2rem 1rem; }
  .payroll-table { font-size: 0.78rem; }
  .payroll-td { padding: 0.4rem 0.5rem; }
}

/* ── Admin Role-Grant Modal ────────────────────────────────────────────────── */
#admin-modal {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 1200;
  width: min(94vw, 820px);
  max-height: 90vh;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--teal) transparent;
  animation: overlayFadeIn 0.22s ease;
}

#admin-modal-inner {
  background: #090d18;
  border: 1px solid #a0e0ff;
  border-radius: var(--stage-radius);
  box-shadow: 0 0 40px rgba(160, 224, 255, 0.2), 0 0 80px rgba(124, 58, 237, 0.12);
  padding: 1.8rem 2rem;
  display: flex;
  flex-direction: column;
