.artwork-editor-close svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; }
.artwork-editor-previews { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 10px; margin-bottom: 16px; }
.artwork-editor-frame { position: relative; display: grid; place-items: center; margin: 0; aspect-ratio: 1; border: 2px solid rgba(233, 215, 160, .3); border-radius: 18px; background: #0d1210; overflow: hidden; transition: border-color .25s ease, box-shadow .25s ease; }
.artwork-editor-frame img { width: 100%; height: 100%; object-fit: cover; }
