.artwork-editor-frame.is-new { border-style: dashed; }
.artwork-editor-frame.is-new.has-image { border-style: solid; border-color: #e9d7a0; box-shadow: 0 0 0 4px rgba(233, 215, 160, .14); }
.artwork-editor-frame.has-image img { animation: artwork-pop .35s ease both; }
@keyframes artwork-pop { from { opacity: 0; transform: scale(.9); } to { opacity: 1; transform: none; } }
.artwork-editor-placeholder { font-size: 2rem; opacity: .45; }
