.artwork-editor-arrow { color: #e9d7a0; font-size: 1.2rem; opacity: .7; }
.artwork-editor-frame.has-image ~ .artwork-editor-arrow, .artwork-editor-previews:has(.has-image) .artwork-editor-arrow { animation: artwork-arrow 1.2s ease-in-out infinite; }
@keyframes artwork-arrow { 0%, 100% { transform: translateX(0); opacity: .6; } 50% { transform: translateX(4px); opacity: 1; } }
.artwork-editor-picker { position: relative; display: flex; align-items: center; gap: 10px; padding: 6px 6px 6px 6px; margin-bottom: 12px; border: 1px dashed rgba(233, 215, 160, .45); border-radius: 999px; background: rgba(233, 215, 160, .05); cursor: pointer; transition: background .2s ease, border-color .2s ease; }
.artwork-editor-picker:hover, .artwork-editor-picker:focus-within { background: rgba(233, 215, 160, .12); border-color: #e9d7a0; }
.artwork-editor-picker input { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; cursor: pointer; }

.artwork-editor-picker-label { flex: none; padding: 7px 14px; border-radius: 999px; background: #e9d7a0; color: #15221c; font-size: .78rem; font-weight: 700; }
.artwork-editor-picker-name { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-dim); font-size: .74rem; }
.artwork-editor-save { width: 100%; min-height: 44px; padding: 10px 18px; border: 0; border-radius: 999px; background: linear-gradient(135deg, #f5cf66, #e9d7a0 55%, #c9a94f); color: #15221c; font: inherit; font-size: .88rem; font-weight: 800; cursor: pointer; box-shadow: 0 6px 18px rgba(245, 207, 102, .25); transition: transform .15s ease, box-shadow .2s ease, filter .2s ease; }
.artwork-editor-save:hover:not(:disabled), .artwork-editor-save:focus-visible { transform: translateY(-2px); box-shadow: 0 10px 24px rgba(245, 207, 102, .35); outline: none; }
.artwork-editor-save:disabled { opacity: .45; cursor: not-allowed; box-shadow: none; filter: grayscale(.4); }
#nft-artwork-editor.is-busy .artwork-editor-save { background-size: 200% 100%; background-image: linear-gradient(90deg, #c9a94f, #f5cf66, #c9a94f); animation: artwork-busy 1.2s linear infinite; opacity: .9; }
@keyframes artwork-busy { from { background-position: 0 0; } to { background-position: -200% 0; } }
.artwork-editor-status { min-height: 1.2em; margin: 12px 0 0; color: var(--text-dim); font-size: .76rem; text-align: center; }
