import { id, isAddress } from 'ethers';
import { currentPayrollPeriod, payrollPeriodFromKey } from '../js/payroll-week.mjs';

export const ADVERT_COMPETITION_POLICY = 'net-positive-ny-monday-wallet-uri-consecutive-v1';

export function advertIdentity(campaign) {
  if (!campaign || !isAddress(campaign.advertiser) || /^0x0{40}$/i.test(campaign.advertiser) ||
    typeof campaign.audioURI !== 'string' || !/^ipfs:\/\/[^\s?#]+$/.test(campaign.audioURI)) return null;
  return id(JSON.stringify([campaign.advertiser.toLowerCase(), campaign.audioURI]));
}

function followingWeek(week) {
  return currentPayrollPeriod(Date.parse(payrollPeriodFromKey(week).endAt)).week;
}

function tally(receipts, catalog) {
  const lifetime = new Map();
  const weekly = new Map();
  const unresolved = new Map();
  for (const receipt of receipts) {
    const week = currentPayrollPeriod(Date.parse(receipt.recordedAt)).week;
    const campaign = catalog.get(receipt.campaignId);
    if (!campaign) {
      unresolved.set(`${week}:${receipt.campaignId}`, { week, campaignId: receipt.campaignId,
        reason: 'Campaign identity unavailable; recover verified campaign metadata and retry' });
      continue;
    }
    const advertId = advertIdentity(campaign);
    for (const [rows, key, initial] of [[lifetime, advertId, { advertId }],
      [weekly, `${week}:${advertId}`, { advertId, week }]]) {
      if (!rows.has(key)) rows.set(key, { ...initial, up: 0, down: 0, net: 0 });
      const row = rows.get(key);
      if (receipt.vote === 1) row.up++;
      else row.down++;
      row.net += receipt.vote;
    }
  }
  return { lifetimeTotals: [...lifetime.values()], weeklyTotals: [...weekly.values()], unresolved: [...unresolved.values()] };
}

export function validateAdvertCompetition(state) {

if (!state || state.schemaVersion !== 1 || state.policy !== ADVERT_COMPETITION_POLICY ||
  !Array.isArray(state.catalog) || !Array.isArray(state.closedWeeks) || !Array.isArray(state.grants) ||
  !Array.isArray(state.plays) || !Array.isArray(state.weeklyTotals) || !Array.isArray(state.lifetimeTotals) ||
  !Array.isArray(state.unresolved)) throw new Error('Invalid advert competition journal');
payrollPeriodFromKey(state.nextWeek);
const catalogIds = new Set();
for (const campaign of state.catalog) {
  if (!advertIdentity(campaign) || !/^\d+$/.test(campaign.campaignId) || catalogIds.has(campaign.campaignId)) {
    throw new Error('Invalid advert competition catalog');
  }
  catalogIds.add(campaign.campaignId);
}
const advertIds = new Set(state.catalog.map(advertIdentity));
for (const rows of [state.lifetimeTotals, state.weeklyTotals]) {
  const keys = new Set();
  for (const row of rows) {
    const key = `${row.week || ''}:${row.advertId}`;
    if (!advertIds.has(row.advertId) || keys.has(key) || !Number.isSafeInteger(row.up) || row.up < 0 ||
      !Number.isSafeInteger(row.down) || row.down < 0 || row.net !== row.up - row.down) {
      throw new Error('Invalid advert competition totals');
    }
    if (rows === state.weeklyTotals) payrollPeriodFromKey(row.week);
    keys.add(key);
  }
}
const weeks = new Set();
for (const closed of state.closedWeeks) {
  if (weeks.has(closed.week) || !Array.isArray(closed.ranking) || !Array.isArray(closed.winners) ||
    !Number.isFinite(Date.parse(closed.closedAt))) throw new Error('Invalid closed advert competition week');
  payrollPeriodFromKey(closed.week);
  const expectedRanking = state.weeklyTotals.filter(row => row.week === closed.week)

    .sort((a, b) => b.net - a.net || a.advertId.localeCompare(b.advertId));
  const period = payrollPeriodFromKey(closed.week);
  if (JSON.stringify(closed.ranking) !== JSON.stringify(expectedRanking) ||
    closed.startAt !== period.startAt || closed.endAt !== period.endAt || closed.week >= state.nextWeek) {
    throw new Error('Invalid frozen advert competition ranking');
  }
  const winners = closed.ranking.length && closed.ranking[0].net > 0
    ? closed.ranking.filter(row => row.net === closed.ranking[0].net).map(row => row.advertId) : [];
  if (JSON.stringify(winners) !== JSON.stringify(closed.winners)) throw new Error('Invalid advert competition winners');
  weeks.add(closed.week);
}
const grantKeys = new Set();
for (const grant of state.grants) {
  const period = payrollPeriodFromKey(followingWeek(grant.sourceWeek));
  const key = `${grant.sourceWeek}:${grant.advertId}`;
  if (grantKeys.has(key) || grant.rewardWeek !== period.week || grant.startAt !== period.startAt || grant.endAt !== period.endAt ||
    !state.closedWeeks.some(week => week.week === grant.sourceWeek && week.winners.includes(grant.advertId))) {
    throw new Error('Invalid advert competition reward grant');
  }
  grantKeys.add(key);
}
for (const closed of state.closedWeeks) {
  if (closed.winners.some(advertId => !grantKeys.has(`${closed.week}:${advertId}`))) {
    throw new Error('Missing advert competition reward grant');
  }
}
const playKeys = new Set();
for (const play of state.plays) {
  const key = `${play.mainRadio}:${play.radioPlayId}`;
  if (playKeys.has(key) || typeof play.mainRadio !== 'boolean' || typeof play.radioPlayId !== 'string' || !play.radioPlayId ||

      !Number.isFinite(Date.parse(play.recordedAt)) || !Number.isFinite(Date.parse(play.startedAt)) ||
      !grantKeys.has(`${play.sourceWeek}:${play.advertId}`) ||
      !competitionGrant(state, { ...play, rewardWeek: followingWeek(play.sourceWeek) }, Date.parse(play.startedAt)) ||
      !state.catalog.some(campaign => campaign.campaignId === play.campaignId && advertIdentity(campaign) === play.advertId)) {
      throw new Error('Invalid free advert play receipt');
    }
    playKeys.add(key);
  }
}

export async function reconcileAdvertCompetition({ state, receipts, snapshot, readCampaign, now }) {
  if (snapshot.chainId !== 8453 || !Array.isArray(snapshot.campaigns)) throw new Error('Advert competition campaign snapshot unavailable');
  const catalog = new Map((state?.catalog || []).map(campaign => [campaign.campaignId, campaign]));
  for (const campaign of snapshot.campaigns) {
    if (advertIdentity(campaign)) {
      const previous = catalog.get(String(campaign.campaignId));
      if (previous && advertIdentity(previous) !== advertIdentity(campaign)) throw new Error('Advert campaign identity changed');
      catalog.set(String(campaign.campaignId), { ...campaign, campaignId: String(campaign.campaignId) });
    }
  }
  for (const campaignId of new Set(receipts.map(receipt => receipt.campaignId))) {
    if (catalog.has(campaignId) || !readCampaign) continue;
    const campaign = await readCampaign(campaignId, snapshot);
    if (campaign && String(campaign.campaignId) === campaignId && advertIdentity(campaign)) {
      catalog.set(campaignId, { ...campaign, campaignId });
    }
  }
  const current = currentPayrollPeriod(now);
  const totals = tally(receipts, catalog);

  const firstAt = receipts.reduce((earliest, receipt) => Math.min(earliest, Date.parse(receipt.recordedAt)), now);
  const next = { schemaVersion: 1, policy: ADVERT_COMPETITION_POLICY, catalog: [...catalog.values()],
    nextWeek: state?.nextWeek || currentPayrollPeriod(firstAt).week,
    closedWeeks: structuredClone(state?.closedWeeks || []), grants: structuredClone(state?.grants || []),
    plays: structuredClone(state?.plays || []), ...totals };
  // Bound a recovery pass; the persisted cursor resumes automatically on the next timer tick.
  for (let recovered = 0; next.nextWeek < current.week && recovered < 100; recovered++) {
    const week = next.nextWeek;
    if (next.unresolved.some(row => row.week === week)) break;
    if (!next.closedWeeks.some(row => row.week === week)) {
      const ranking = next.weeklyTotals.filter(row => row.week === week)
        .sort((a, b) => b.net - a.net || a.advertId.localeCompare(b.advertId));
      const winners = ranking.length && ranking[0].net > 0 ? ranking.filter(row => row.net === ranking[0].net).map(row => row.advertId) : [];
      next.closedWeeks.push({ week, ...payrollPeriodFromKey(week), closedAt: new Date(now).toISOString(), ranking, winners });
      const reward = payrollPeriodFromKey(followingWeek(week));
      for (const advertId of winners) next.grants.push({ advertId, sourceWeek: week, rewardWeek: reward.week,
        startAt: reward.startAt, endAt: reward.endAt });
    }
    next.nextWeek = followingWeek(week);
  }
  validateAdvertCompetition(next);
  return next;
}

export function competitionGrant(state, marker, at) {
  return state?.grants.find(grant => grant.advertId === marker?.advertId && grant.sourceWeek === marker?.sourceWeek &&

    grant.rewardWeek === marker?.rewardWeek && Date.parse(grant.startAt) <= at && at < Date.parse(grant.endAt));
}

export function competitionCandidates({ state, snapshot, now, isCampaignRemoved, resolveCampaignMedia }) {
  if (!state || snapshot.paused || snapshot.chainId !== 8453) return [];
  const campaigns = new Map(state.catalog.map(campaign => [campaign.campaignId, campaign]));
  for (const campaign of snapshot.campaigns) campaigns.set(String(campaign.campaignId), campaign);
  const candidates = [];
  for (const grant of state.grants) {
    if (!competitionGrant(state, grant, now)) continue;
    const matching = [...campaigns.values()].filter(campaign => advertIdentity(campaign) === grant.advertId);
    if (matching.some(campaign => campaign.removed || campaign.moderationBlocked || isCampaignRemoved(campaign.campaignId, campaign) ||
      snapshot.contentBlockedMedia?.includes(campaign.audioURI))) continue;
    const campaign = matching.reverse().find(campaign => typeof campaign.title === 'string' && campaign.title &&
      resolveCampaignMedia(campaign, campaign.audioURI.slice(7)));
    if (!campaign) continue;
    const plays = state.plays.filter(play => play.advertId === grant.advertId && play.sourceWeek === grant.sourceWeek);
    candidates.push({ campaign, grant, playCount: plays.length, lastPlayedAt: plays.at(-1)?.recordedAt || '' });
  }
  return candidates.sort((a, b) => a.playCount - b.playCount || a.lastPlayedAt.localeCompare(b.lastPlayedAt) ||
    a.grant.advertId.localeCompare(b.grant.advertId));
}

import { load } from 'cheerio';
import { parse } from 'acorn';
import { CID } from 'multiformats/cid';
import { createHash } from 'node:crypto';
import { createReadStream } from 'node:fs';
import { readdir, stat } from 'node:fs/promises';
import { join, relative } from 'node:path';
import { importer } from 'ipfs-unixfs-importer';
import { fixedSize } from 'ipfs-unixfs-importer/chunker';
import { create as createDigest } from 'multiformats/hashes/digest';

const AUDIO_EXTENSION = /\.(mp3|wav|ogg|aac|m4a|flac|opus|mp4)(?:[?#]|$)/i;

export async function reconstructLocalAlbumDirectory(directory, { rawLeaves = false, includeFinderMetadata = false } = {}) {
  const sources = [];
  async function walk(path) {
    const entries = (await readdir(path, { withFileTypes: true })).sort((first, second) => first.name.localeCompare(second.name));
    for (const entry of entries) {
      if (!includeFinderMetadata && entry.name === '.DS_Store') continue;
      const source = join(path, entry.name);
      if (entry.isSymbolicLink()) throw new Error('Album directory contains a symlink; manual review required');
      if (entry.isDirectory()) await walk(source);
      else if (entry.isFile()) sources.push({ path: relative(directory, source), source, before: await stat(source) });
    }
  }
  await walk(directory);
  if (!sources.length) throw new Error('Album directory is empty');
  const results = [];
  for await (const entry of importer(sources.map(file => ({ path: file.path, content: createReadStream(file.source) })),
    { put: async () => {} }, { cidVersion: 1, rawLeaves, chunker: fixedSize({ chunkSize: 262144 }), wrapWithDirectory: true })) {
    results.push({ path: entry.path || '', cid: entry.cid.toV1().toString(), dagBytes: String(entry.size) });
  }

  for (const file of sources) {
    const after = await stat(file.source);
    if (after.size !== file.before.size || after.mtimeMs !== file.before.mtimeMs) throw new Error('Album changed during directory verification');
  }
  const root = results.find(entry => entry.path === '');
  if (!root) throw new Error('Reconstructed album root is unavailable');
  return { rootCid: root.cid, rawLeaves, includeFinderMetadata, files: results.filter(entry => entry.path),
    sourceBytes: sources.reduce((sum, file) => sum + file.before.size, 0) };
}

export async function inventoryLocalAlbumFiles(root) {
  const files = [];
  async function walk(directory) {
    const entries = (await readdir(directory, { withFileTypes: true })).sort((first, second) => first.name.localeCompare(second.name));
    for (const entry of entries) {
      const path = join(directory, entry.name);
      if (entry.isDirectory()) await walk(path);
      else if (entry.isFile() && AUDIO_EXTENSION.test(entry.name)) {
        const before = await stat(path);
        const hash = createHash('sha256');
        for await (const chunk of createReadStream(path)) hash.update(chunk);
        const digest = hash.digest();
        const cidCandidates = [CID.createV1(0x55, createDigest(0x12, digest)).toString()];
        for (const rawLeaves of [false, true]) {
          for await (const result of importer([{ content: createReadStream(path) }], { put: async () => {} }, {
            cidVersion: 1, rawLeaves, chunker: fixedSize({ chunkSize: 262144 }),
          })) cidCandidates.push(result.cid.toV1().toString());
        }
        const after = await stat(path);
        if (before.size !== after.size || before.mtimeMs !== after.mtimeMs) throw new Error(`Source file changed during audit: ${entry.name}`);

        const sourcePath = relative(root, path);
        files.push({ sourcePath, album: sourcePath.split('/')[0], filename: entry.name,
          size: before.size, sha256: digest.toString('hex'), cidCandidates: [...new Set(cidCandidates)] });
      }
    }
  }
  await walk(root);
  return files;
}

export async function listPublicPinataFiles({ pinataJwt, fetchImpl = fetch, maxPages = 100 }) {
  if (!pinataJwt) throw new Error('Pinata listing credentials are required');
  const files = [];
  const cursors = new Set();
  let cursor;
  for (let page = 0; page < maxPages; page++) {
    const url = new URL('https://api.pinata.cloud/v3/files/public');
    url.searchParams.set('limit', '1000');
    url.searchParams.set('order', 'DESC');
    if (cursor) url.searchParams.set('pageToken', cursor);
    const response = await fetchImpl(url, { headers: { authorization: `Bearer ${pinataJwt}` }, signal: AbortSignal.timeout(20000) });
    if (!response.ok) throw new Error(`Pinata read-only listing failed (${response.status}); stop and retry later`);
    const result = await response.json();
    if (!Array.isArray(result.data?.files)) throw new Error('Invalid Pinata inventory response');
    files.push(...result.data.files.map(({ id, cid, name, size, mime_type, number_of_files }) =>
      ({ id, cid, name, size, mimeType: mime_type, fileCount: number_of_files })));
    cursor = result.data.next_page_token;
    if (!cursor) return files;
    if (cursors.has(cursor)) throw new Error('Pinata inventory pagination repeated; coverage incomplete');
    cursors.add(cursor);
  }
  throw new Error('Pinata inventory exceeded page limit; coverage incomplete');
}

export function compareLocalPinataInventory(localFiles, pinataFiles, playlist = []) {
  const pins = new Map();

for (const file of pinataFiles) {
  const key = canonicalAudioKey(`ipfs://${file.cid}`);
  if (!key) continue;
  const matches = pins.get(key) || [];
  matches.push(file);
  pins.set(key, matches);
}
const recordings = new Map();
for (const file of localFiles) {
  if (recordings.has(file.sha256)) {
    recordings.get(file.sha256).sources.push(file.sourcePath);
    continue;
  }
  const exactPins = file.cidCandidates.flatMap(cid => pins.get(cid) || []);
  const pinataCandidates = exactPins.length ? [] : pinataFiles.filter(pin => pin.name === file.filename && pin.size === file.size);
  const playlistMatches = playlist.filter(track => file.cidCandidates.includes(canonicalAudioKey(`ipfs://${track.ipfsCid || ''}`)));
  recordings.set(file.sha256, { ...file, sources: [file.sourcePath], exactPins,
    pinataCandidates, playlistMatches: playlistMatches.map(({ trackId, tokenId, mintStatus }) => ({ trackId, tokenId, mintStatus })),
    disposition: exactPins.length ? 'reuse-pinata' : pinataCandidates.length ? 'verify-existing-candidate' : 'not-found-in-file-inventory' });
}
const unique = [...recordings.values()];
return { schemaVersion: 1, readOnly: true, dualPinRequired: true, uploadsPerformed: 0,
  fileCount: localFiles.length, uniqueRecordings: unique.length, duplicateLocalCopies: localFiles.length - unique.length,
  localMediaBytes: localFiles.reduce((sum, file) => sum + file.size, 0),
  uniqueMediaBytes: unique.reduce((sum, file) => sum + file.size, 0),
  exactReusableRecordings: unique.filter(file => file.exactPins.length).length,
  exactReusableBytes: unique.filter(file => file.exactPins.length).reduce((sum, file) => sum + file.size, 0),

    unmatchedBytesUpperBound: unique.filter(file => !file.exactPins.length).reduce((sum, file) => sum + file.size, 0),
    recordings: unique,
    note: 'Public file inventory only. Unmatched files may exist inside pinned directories, legacy pins, or other import layouts. Do not upload from this report without resolving those cases and checking plan capacity.' };
}

export function normalizeAlbumSongTitle(value) {
  return String(value || '').normalize('NFKC').trim().toLowerCase().replace(/\.(mp3|m4a|mp4|wav|ogg|aac|flac|opus)$/i, '')
    .replace(/[_\s]+/g, ' ').trim();
}

export function buildReviewedAlbumImportPlan(manifest) {
  if (manifest?.duplicateMode !== 'title' || !manifest.playlistVerified || !Array.isArray(manifest.recordings)) {
    throw new Error('Verified title-review manifest required');
  }
  const tracks = [];
  const titleKeys = new Set();
  const audioKeys = new Set();
  for (const recording of manifest.recordings) {
    if (recording.action !== 'review-new-radio-entry') continue;
    if (!Array.isArray(recording.blockers) || recording.blockers.length || !recording.dualPinVerified ||
      !canonicalAudioKey(`ipfs://${recording.audioCid || ''}`)) throw new Error('Import candidate has unresolved safety blockers');
    const title = String(recording.filename).replace(/\.(mp3|m4a|mp4|wav|ogg|aac|flac|opus)$/i, '').replace(/_/g, ' ').trim();
    const key = normalizeAlbumSongTitle(title);
    if (!key || titleKeys.has(key) || audioKeys.has(recording.audioCid)) throw new Error('Import plan contains a duplicate title or audio reference');
    titleKeys.add(key);
    audioKeys.add(recording.audioCid);
    tracks.push({ title, filename: recording.filename, ipfsCid: recording.audioCid, sha256: recording.sha256,

      albums: recording.albums, sources: recording.sources, dualPinVerified: true });
  }
  return { schemaVersion: 1, applyEnabled: false, sourceGeneratedAt: manifest.generatedAt,
    duplicateMode: 'title', uploadsRequired: 0, nftVerification: 'not-performed-by-user-request', tracks,
    requirements: ['recheck-current-playlist-titles-before-apply', 'confirm-artist-attribution',
      'persist-radio-and-album-state-without-changing-existing-history'] };
}

export function buildAlbumImportManifest({ localFiles, verifiedDirectories, pinataFiles, playlist, nfts = [],
  duplicateMode = 'content', nftScanComplete = false, playlistVerified = false, localPinnedRoots = [], generatedAt = new Date().toISOString() }) {
  if (!['content', 'title'].includes(duplicateMode)) throw new Error('Invalid album duplicate mode');
  const roots = new Set(localPinnedRoots.map(cid => canonicalAudioKey(`ipfs://${cid}`)));
  const children = [];
  for (const album of verifiedDirectories.filter(album => album.matched)) {
    for (const file of album.files || []) {
      if (!AUDIO_EXTENSION.test(file.path)) continue;
      children.push({ cid: file.cid, name: file.path, parentCid: album.cid, parentName: album.name });
    }
  }
  const report = compareLocalPinataInventory(localFiles, [...pinataFiles, ...children], playlist);
  const references = entry => canonicalAudioKey(entry.audioUrl || entry.animation_url ||
    (entry.ipfsCid ? `ipfs://${entry.ipfsCid}` : ''));
  const titleKey = normalizeAlbumSongTitle;
  const directoriesByFolder = new Map(verifiedDirectories.map(album => [album.localFolder, album]));
  const recordings = report.recordings.map(recording => {
    const candidates = new Set(recording.cidCandidates);
    for (const pin of recording.exactPins) {

  candidates.add(canonicalAudioKey(`ipfs://${pin.cid}`));
  if (pin.parentCid) candidates.add(canonicalAudioKey(`ipfs://${pin.parentCid}/${pin.name}`));
}
const playlistMatches = playlist.filter(track => candidates.has(references(track)));
const nftMatches = nfts.filter(nft => candidates.has(references(nft)));
const aliases = localFiles.filter(file => file.sha256 === recording.sha256);
const titles = new Set(aliases.map(file => titleKey(file.filename)));
const titleMatches = playlist.filter(entry => [entry.title, entry.name, entry.filename].some(value =>
  value && titles.has(titleKey(value))));
const localTitleMatches = localFiles.filter(file => file.sha256 !== recording.sha256 && titles.has(titleKey(file.filename)));
const possibleDuplicates = [...playlist, ...nfts].filter(entry => !candidates.has(references(entry)) &&
  titles.has(titleKey(entry.title || entry.name || entry.filename))).map(entry => ({
    trackId: entry.trackId || null, tokenId: entry.tokenId ?? null, title: entry.title || entry.name || entry.filename,
  }));
const pinned = recording.exactPins.find(pin => roots.has(canonicalAudioKey(`ipfs://${pin.parentCid || pin.cid}`)));
const albums = [...new Set(aliases.map(file => file.album))];
const blockers = [];
if (!playlistVerified) blockers.push('live-playlist-not-verified');
if (!nftScanComplete && duplicateMode !== 'title') blockers.push('nft-scan-incomplete');
if (!pinned) blockers.push('dual-pin-not-verified');
if (duplicateMode === 'title' && titleMatches.length) blockers.push('existing-song-title-match');
if (duplicateMode === 'title' && localTitleMatches.length) blockers.push('local-song-title-collision');

  if (possibleDuplicates.length && duplicateMode !== 'title') blockers.push('possible-alternate-encoding');
  if (albums.some(album => directoriesByFolder.has(album) && !directoriesByFolder.get(album).matched)) blockers.push('album-directory-mismatch');
  if (!albums.some(album => directoriesByFolder.get(album)?.matched)) blockers.push('outside-verified-ens-albums');
  if (playlistMatches.length > 1) blockers.push('multiple-existing-playlist-identities');
  return { sha256: recording.sha256, filename: recording.filename, bytes: recording.size,
    sources: recording.sources, albums, audioCid: pinned ? canonicalAudioKey(`ipfs://${pinned.cid}`) : null,
    dualPinVerified: !!pinned,
    playlistMatches: playlistMatches.map(track => ({ trackId: track.trackId, tokenId: track.tokenId ?? null, mintStatus: track.mintStatus })),
    nftMatches: nftMatches.map(nft => ({ chainId: nft.chainId, contractAddress: nft.contractAddress, tokenId: nft.tokenId })),
    titleMatches: titleMatches.map(track => ({ trackId: track.trackId, title: track.title, filename: track.filename })),
    localTitleMatches: localTitleMatches.map(file => file.sourcePath),
    possibleDuplicates, blockers,
    action: duplicateMode === 'title' && titleMatches.length ? 'hold-existing-title-match' :
      playlistMatches.length ? 'reuse-existing-song-and-attach-albums' :
      nftMatches.length ? 'reuse-existing-nft-review-radio-entry' : blockers.length ? 'blocked-review' : 'review-new-radio-entry' };
});
return { schemaVersion: 1, generatedAt, importEnabled: false, duplicateMode, nftScanComplete, playlistVerified,
  fileCount: localFiles.length, uniqueRecordings: recordings.length, duplicateLocalCopies: report.duplicateLocalCopies,

    verifiedAlbums: verifiedDirectories.filter(album => album.matched).map(album => ({ album: album.name, cid: album.cid,
      localRecursivePinned: roots.has(canonicalAudioKey(`ipfs://${album.cid}`)) })),
    directoryMismatches: verifiedDirectories.filter(album => !album.matched).map(album => album.name),
    counts: {
      reuseExistingSongs: recordings.filter(recording => recording.playlistMatches.length).length,
      existingNfts: recordings.filter(recording => recording.nftMatches.length).length,
      dualPinnedRecordings: recordings.filter(recording => recording.dualPinVerified).length,
      newRadioCandidates: recordings.filter(recording => recording.action === 'review-new-radio-entry').length,
      blockedRecordings: recordings.filter(recording => recording.blockers.length).length,
      heldExistingTitles: recordings.filter(recording => recording.titleMatches.length).length,
      localTitleCollisions: recordings.filter(recording => recording.localTitleMatches.length).length,
    }, recordings };
}

export function canonicalAudioKey(uri) {
  if (typeof uri !== 'string') return null;
  let path;
  if (uri.startsWith('ipfs://')) path = uri.replace(/^ipfs:\/\/(?:ipfs\/)?/, '');
  else {
    try {
      const url = new URL(uri);
      path = url.pathname.startsWith('/ipfs/') ? url.pathname.slice(6) :
        url.hostname.includes('.ipfs.') ? `${url.hostname.split('.ipfs.')[0]}${url.pathname}` : null;
    } catch { return null; }
  }
  if (!path) return null;
  const [root, ...segments] = path.split(/[?#]/)[0].split('/');
  try {
    const cid = CID.parse(root).toV1().toString();
    return `${cid}${segments.length ? `/${segments.join('/')}` : ''}`;
  } catch { return null; }
}

export function extractCatalogAlbums(html, baseUrl) {

  const document = load(html);
  const albums = [];
  document('a.album-card[href]').each((_index, element) => {
    const link = document(element);
    const url = new URL(link.attr('href'), baseUrl).href;
    if (!canonicalAudioKey(url)) throw new Error('Catalog album is not an IPFS player');
    albums.push({ title: link.find('h3').text().trim() || link.text().trim(), url });
  });
  if (!albums.length) throw new Error('No album cards found in the current catalog');
  return albums;
}

function literal(node) {
  if (node?.type === 'Literal') return node.value;
  if (node?.type === 'ArrayExpression') return node.elements.map(literal);
  if (node?.type === 'ObjectExpression') return Object.fromEntries(node.properties.map(property => {
    if (property.type !== 'Property' || property.computed || property.kind !== 'init') throw new Error('Nonliteral track manifest');
    return [property.key.name || property.key.value, literal(property.value)];
  }));
  throw new Error('Nonliteral track manifest');
}

export function extractAlbumTracks(html, albumUrl) {
  const document = load(html);
  const tracks = new Map();
  const baseUrl = albumUrl.endsWith('/') ? albumUrl : `${albumUrl}/`;
  const add = (value, title = '') => {
    if (typeof value !== 'string' || !value.trim()) return;
    let url;
    try { url = new URL(value, baseUrl).href; } catch { return; }
    const audioKey = canonicalAudioKey(url);
    if (!audioKey) return;
    if (!tracks.has(audioKey)) tracks.set(audioKey, { audioKey, url,
      title: title || decodeURIComponent(new URL(url).pathname.split('/').pop() || 'Untitled recording') });
  };
  const addManifest = entries => {
    if (!Array.isArray(entries)) return;
    for (const entry of entries) {
      if (typeof entry === 'string') add(entry);

      else if (entry && typeof entry === 'object') {
        add(entry.audioUrl || entry.audio || entry.url || entry.src || entry.file || entry.path,
          typeof entry.title === 'string' ? entry.title : typeof entry.name === 'string' ? entry.name : '');
      }
    }
  };
  document('audio[src], audio source[src]').each((_index, element) => add(document(element).attr('src')));
  document('a[href]').each((_index, element) => {
    const link = document(element);
    if (AUDIO_EXTENSION.test(link.attr('href') || '')) add(link.attr('href'), link.text().trim());
  });
  document('script:not([src])').each((_index, element) => {
    const source = document(element).html() || '';
    if (document(element).attr('type') === 'application/json') {
      try { const manifest = JSON.parse(source); addManifest(Array.isArray(manifest) ? manifest : manifest.tracks || manifest.songs || manifest.playlist); } catch {}
      return;
    }
    let ast;
    try { ast = parse(source, { ecmaVersion: 'latest', sourceType: 'module' }); } catch { return; }
    for (const statement of ast.body) {
      if (statement.type !== 'VariableDeclaration') continue;
      for (const declaration of statement.declarations) {
        if (!['tracks', 'songs', 'playlist', 'audioFiles'].includes(declaration.id.name)) continue;
        try { addManifest(literal(declaration.init)); } catch {}
      }
    }
  });
  return [...tracks.values()];
}

export function auditAlbumTracks(albums, { playlist = [], nfts = [] } = {}) {
  const known = new Map();
  for (const entry of [...playlist, ...nfts]) {
    const audioKey = canonicalAudioKey(entry.audioUrl || entry.animation_url || (entry.ipfsCid ? `ipfs://${entry.ipfsCid}` : ''));
    if (audioKey) {
      const matches = known.get(audioKey) || [];

      matches.push({ trackId: entry.trackId || null, contractAddress: entry.contractAddress || null, tokenId: entry.tokenId ?? null });
      known.set(audioKey, matches);
    }
  }
  const imported = new Map();
  const recordings = [];
  for (const album of albums) for (const track of album.tracks || []) {
    if (imported.has(track.audioKey)) {
      imported.get(track.audioKey).albums.push(album.title);
      continue;
    }
    const titleKey = track.title.toLowerCase().replace(/\.[a-z0-9]+$/i, '').trim();
    const possibleReencodedMatch = [...playlist, ...nfts].some(entry =>
      String(entry.title || entry.name || '').toLowerCase().replace(/\.[a-z0-9]+$/i, '').trim() === titleKey);
    const recording = { ...track, albums: [album.title], matches: known.get(track.audioKey) || [],
      disposition: known.has(track.audioKey) ? 'reuse-existing' : possibleReencodedMatch ? 'review-possible-reencoding' : 'review-new-recording' };
    imported.set(track.audioKey, recording);
    recordings.push(recording);
  }
  return { schemaVersion: 1, importEnabled: false, albums, recordings,
    blockedAlbums: albums.filter(album => album.error || !album.tracks?.length).map(album => album.title),
    note: 'CID/path matches are exact references, not perceptual audio matches. Review rights and alternate encodings before importing.' };
}

export async function auditLiveAlbumCatalog({ catalogUrl = 'https://decentbusking.thejollylama.eth.limo/',
  playlist = [], nfts = [], fetchImpl = fetch } = {}) {
  const getHtml = async url => {
    const response = await fetchImpl(url, { signal: AbortSignal.timeout(20000) });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const html = await response.text();

    if (html.length > 5 * 1024 * 1024) throw new Error('Album HTML exceeds audit limit');
    return html;
  };
  const albums = extractCatalogAlbums(await getHtml(catalogUrl), catalogUrl);
  for (const album of albums) {
    try {
      album.tracks = extractAlbumTracks(await getHtml(album.url), album.url);
      if (!album.tracks.length) album.error = 'No supported literal audio manifest found; external manifests need review';
    } catch (error) { album.tracks = []; album.error = error.message; }
  }
  return auditAlbumTracks(albums, { playlist, nfts });
}

import { normalizeAlbumSongTitle } from './album-audit.js';
import { normalizeMediaCid, mediaTypeFor } from './media.js';

export function prepareAlbumPlaylistImport({ playlist, plan, artist, now = new Date().toISOString(), queueForMint = false }) {
  if (!Array.isArray(playlist) || plan?.duplicateMode !== 'title' || !Array.isArray(plan.tracks) || plan.uploadsRequired !== 0) {
    throw new Error('Reviewed title-based album plan and restored playlist are required');
  }
  if (!artist?.name || !artist.uploaderId || !/^0x[0-9a-fA-F]{40}$/.test(artist.wallet || '')) throw new Error('Verified album artist attribution is required');
  const next = structuredClone(playlist);
  const titleKeys = new Set(next.flatMap(track => [track.title, track.filename, track.name].filter(Boolean).map(normalizeAlbumSongTitle)));
  const existingCids = new Set(next.filter(track => track.ipfsCid).map(track => track.ipfsCid));
  const existingIds = new Set(next.map(track => track.trackId));
  const skipped = [];
  const added = [];
  const queued = [];
  for (const candidate of plan.tracks) {
    if (!candidate.dualPinVerified || !candidate.title || !candidate.sha256 || !Array.isArray(candidate.albums) || !candidate.albums.length) {
      throw new Error('Album candidate is not verified');
    }
    const cid = normalizeMediaCid(candidate.ipfsCid);
    const titleKey = normalizeAlbumSongTitle(candidate.title);
    const filenameKey = normalizeAlbumSongTitle(candidate.filename);
    const trackId = `album:${artist.wallet.toLowerCase()}:${cid}`;
    const existingTrack = next.find(track => track.trackId === trackId);
    if (existingTrack) {
      if (queueForMint && existingTrack.source === 'album' && existingTrack.ipfsCid === cid &&

        normalizeAlbumSongTitle(existingTrack.title) === titleKey && existingTrack.mintRecipient?.toLowerCase() === artist.wallet.toLowerCase() &&
        existingTrack.mintStatus === 'unminted') {
      existingTrack.mintStatus = 'requested';
      existingTrack.mintRequestedAt = new Date(Date.parse(now) + queued.length * 1000).toISOString();
      queued.push(trackId);
    }
    skipped.push({ title: candidate.title, reason: 'already-present-title-or-audio' });
    continue;
  }
  if (titleKeys.has(titleKey) || titleKeys.has(filenameKey) || existingCids.has(cid) || existingIds.has(trackId)) {
    skipped.push({ title: candidate.title, reason: 'already-present-title-or-audio' });
    continue;
  }
  const mediaType = mediaTypeFor(candidate.filename);
  if (!mediaType) throw new Error('Unsupported album media type');
  const track = { trackId, attachmentId: trackId, source: 'album', title: candidate.title,
    filename: candidate.filename, mediaType, ipfsCid: cid, pinStatus: 'pinned',
    pinVerification: { pinata: true, local: true, verifiedAt: plan.sourceGeneratedAt },
    albums: [...new Set(candidate.albums)], contentSha256: candidate.sha256,
    uploader: artist.name, uploaderId: artist.uploaderId, mintRecipient: artist.wallet, tipWallet: artist.wallet,
    mintStatus: queueForMint ? 'requested' : 'unminted',
    ...(queueForMint ? { mintRequestedAt: new Date(Date.parse(now) + queued.length * 1000).toISOString() } : {}),
    likes: 0, dislikes: 0, plays: 0, addedAt: now, payrollTrackingStartedAt: now };
  next.push(track);
  added.push(trackId);
  if (queueForMint) queued.push(trackId);
  titleKeys.add(titleKey);
  titleKeys.add(filenameKey);
  existingCids.add(cid);
  existingIds.add(trackId);
}

  return { playlist: next, added, queued, skipped };
}

export function resolveAlbumArtist(playlist, { name, wallet }) {
  if (!/^0x[0-9a-fA-F]{40}$/.test(wallet || '')) throw new Error('Verified album artist wallet is required');
  const matches = playlist.filter(track => track.uploader === name);
  const ids = new Set(matches.map(track => track.uploaderId).filter(Boolean));
  if (ids.size !== 1) throw new Error('Album artist attribution is missing or ambiguous in restored playlist');
  if (matches.some(track => track.mintRecipient && track.mintRecipient.toLowerCase() !== wallet.toLowerCase())) {
    throw new Error('Album artist has conflicting wallet attribution in restored playlist');
  }
  return { name, wallet, uploaderId: [...ids][0] };
}

export async function checkpointReviewedAlbumImport({ playlist, plan, artist, save, mirrorCheckpoint, verifyMirrorAvailable,
  mirrorBeforePublication = false, queueForMint = false }) {
  const result = prepareAlbumPlaylistImport({ playlist, plan, artist, queueForMint });
  if (!result.added.length && !result.queued.length) return { ...result, checkpointUri: null };
  if (typeof save !== 'function') throw new Error('Durable album checkpoint writer required');
  if ((!mirrorBeforePublication && typeof mirrorCheckpoint !== 'function') || typeof verifyMirrorAvailable !== 'function') throw new Error('Local checkpoint mirror required');
  await verifyMirrorAvailable();
  const checkpointUri = await save(structuredClone(result.playlist));
  if (typeof checkpointUri !== 'string' || !checkpointUri.startsWith('ipfs://')) throw new Error('Album checkpoint did not confirm');
  try { if (!mirrorBeforePublication) await mirrorCheckpoint(checkpointUri); }

  catch (error) { throw new Error(`Album checkpoint ${checkpointUri} exists on Pinata but local mirror is pending; no state adopted. ${error.message}`); }
  return { ...result, checkpointUri };
}

import { createHmac, timingSafeEqual } from 'node:crypto';

export const MAX_WEBHOOK_BODY_BYTES = 512 * 1024;

export function verifyAlchemySignature(rawBody, signature, signingKey) {
  if (!signingKey || typeof signature !== 'string' || !/^[0-9a-f]{64}$/i.test(signature)) return false;
  const expected = createHmac('sha256', signingKey).update(rawBody).digest();
  return timingSafeEqual(expected, Buffer.from(signature, 'hex'));
}

// Collects every emitting contract address from a custom (GraphQL) or Address Activity payload.
export function webhookAddresses(payload) {
  const found = new Set();
  const add = value => { if (typeof value === 'string' && /^0x[0-9a-fA-F]{40}$/.test(value)) found.add(value.toLowerCase()); };
  const event = payload?.event || {};
  for (const log of event.data?.block?.logs || []) {
    add(log?.account?.address);
    for (const inner of log?.transaction?.logs || []) add(inner?.account?.address);
  }
  for (const activity of event.activity || []) {
    add(activity?.rawContract?.address);
    add(activity?.log?.address);
    add(activity?.toAddress);
    add(activity?.fromAddress);
  }
  return found;
}

/**
 * Alchemy webhooks are treated purely as a nudge: a verified delivery schedules the matching
 * refreshers, which then read the chain themselves. Payload contents are never trusted as data.
 */
export function createAlchemyWebhook({ signingKey, routes = [], debounceMs = 3_000, now = () => Date.now(),
  setTimer = setTimeout, clearTimer = clearTimeout, log = console } = {}) {
  const byAddress = new Map();
  for (const { addresses = [], refresh = [], label = 'contract' } of routes) {
    for (const address of addresses) {
      if (!address) continue;
      const key = address.toLowerCase();

    const entry = byAddress.get(key) || { labels: new Set(), refresh: new Set() };
    entry.labels.add(label);
    for (const task of refresh) if (typeof task === 'function') entry.refresh.add(task);
    byAddress.set(key, entry);
  }
}
const pending = new Set();
let timer = null;
const stats = { received: 0, verified: 0, rejected: 0, triggered: 0, lastVerifiedAt: null, lastEventAt: null, lastLabels: [] };

function flush() {
  timer = null;
  const tasks = [...pending];
  pending.clear();
  for (const task of tasks) {
    try {
      Promise.resolve(task()).catch(error => log.warn?.('[alchemy-webhook] refresh failed:', error?.message || error));
    } catch (error) {
      log.warn?.('[alchemy-webhook] refresh failed:', error?.message || error);
    }
  }
}

function handle(rawBody, signature) {
  stats.received += 1;
  if (!signingKey) return { status: 404, body: { error: 'Alchemy webhooks are not configured' } };
  if (!verifyAlchemySignature(rawBody, signature, signingKey)) {
    stats.rejected += 1;
    return { status: 401, body: { error: 'Invalid webhook signature' } };
  }
  let payload;
  try { payload = JSON.parse(Buffer.from(rawBody).toString('utf8')); } catch {
    stats.rejected += 1;
    return { status: 400, body: { error: 'Webhook body is not JSON' } };
  }
  stats.verified += 1;
  stats.lastVerifiedAt = new Date(now()).toISOString();
  const labels = new Set();
  for (const address of webhookAddresses(payload)) {
    const entry = byAddress.get(address);
    if (!entry) continue;
    for (const label of entry.labels) labels.add(label);
    for (const task of entry.refresh) pending.add(task);
  }
  if (labels.size) {
    stats.triggered += 1;

      stats.lastEventAt = stats.lastVerifiedAt;
      stats.lastLabels = [...labels];
      if (!timer) {
        timer = setTimer(flush, debounceMs);
        timer?.unref?.();
      }
    }
    return { status: 200, body: { ok: true, matched: [...labels] } };
  }

  return {
    handle,
    flush() { if (timer) clearTimer(timer); flush(); },
    configured: () => Boolean(signingKey),
    health: () => ({ configured: Boolean(signingKey), watching: byAddress.size, ...stats }),
  };
}

export async function readRawBody(request, limit = MAX_WEBHOOK_BODY_BYTES) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > limit) throw new Error('Request body is too large');
    chunks.push(chunk);
  }
  return Buffer.concat(chunks);
}

export function createArtworkUpdateQueue({ restore = async () => [], save = async () => {} } = {}) {
  let requests = [];

  const normalize = (request) => ({
    ...request,
    requestId: request.requestId || crypto.randomUUID(),
    tokenId: String(request.tokenId),
    contractAddress: String(request.contractAddress || '').toLowerCase(),
    status: request.status || 'pending',
    requestedAt: request.requestedAt || new Date().toISOString(),
  });

  const sortRequests = () => [...requests].sort((a, b) => Date.parse(a.requestedAt || 0) - Date.parse(b.requestedAt || 0));

  const persist = async () => save(structuredClone(requests));

  return {
    async initialize() {
      const restored = await restore();
      requests = Array.isArray(restored) ? restored.map(normalize) : [];
      return sortRequests();
    },
    getRequests() {
      return sortRequests();
    },
    getPendingRequests() {
      return sortRequests().filter(request => request.status === 'pending');
    },
    getPendingCount() {
      return requests.filter(request => request.status === 'pending').length;
    },
    getRequest({ requestId, tokenId, contractAddress }) {
      return sortRequests().find(request =>
        (requestId && request.requestId === requestId) ||
        (tokenId !== undefined && String(request.tokenId) === String(tokenId) &&
          (!contractAddress || request.contractAddress === String(contractAddress).toLowerCase())));
    },
    async queueRequest(request) {
      const normalized = normalize(request);
      const existingIndex = requests.findIndex(entry =>
        entry.status === 'pending' && String(entry.tokenId) === normalized.tokenId &&
        entry.contractAddress === normalized.contractAddress);
      if (existingIndex >= 0) {

        const existing = requests[existingIndex];
        existing.status = 'superseded';
        existing.supersededAt = normalized.requestedAt;
        existing.supersededBy = normalized.requestId;
      }
      requests.unshift(normalized);
      await persist();
      return normalized;
    },
    async completeRequest(requestId, update = {}) {
      const request = requests.find(entry => entry.requestId === requestId);
      if (!request) return null;
      request.status = 'completed';
      request.completedAt = new Date().toISOString();
      if (update.txHash) request.txHash = update.txHash;
      if (update.metadataUri) request.metadataUri = update.metadataUri;
      await persist();
      return request;
    },
    async rejectRequest(requestId, reason = 'rejected') {
      const request = requests.find(entry => entry.requestId === requestId);
      if (!request) return null;
      request.status = 'rejected';
      request.rejectedAt = new Date().toISOString();
      request.rejectionReason = reason;
      await persist();
      return request;
    },
  };
}

import { Contract, Interface, Transaction, getAddress, keccak256, id } from 'ethers';
import { SPONSORED_WORKER_MIN_BALANCE_WEI } from '../js/worker-gas.mjs';

export const CALENDAR_REWARD_ABI = [
  'function VERSION() view returns(string)', 'function LIMIT() view returns(uint256)',
  'function appointments() view returns(address)', 'function nft() view returns(address)', 'function tokenId() view returns(uint256)',
  'function enabled() view returns(bool)', 'function startAppointmentId() view returns(uint256)',
  'function awarded() view returns(uint256)', 'function rewardedAppointment(address) view returns(uint256)',
  'function eligible(uint256) view returns(address)', 'function award(uint256)',
];
const REGISTRY = '0xa61869FD9C4376fF1DA9E7dF48b5Ba746d4bD048';
const NFT = '0xe63EC9f8228720bAAC2fD528C0A6d06B3Dc5439B';
const ZERO = '0x'+'0'.repeat(40);
const TOTAL_CAP = 1_000_000_000_000_000n;
// Setup includes deployment, sale-stock cutover and activation.
const SETUP_RESERVE = 300_000_000_000_000n;
const WORKER_CAP = TOTAL_CAP - SETUP_RESERVE;
const PER_SEND_CAP = 100_000_000_000_000n;
const L1_RESERVE = 10_000_000_000_000n;

export function validateCalendarRewardCheckpoint(snapshot) {
  if (snapshot?.schema !== 1 || getAddress(snapshot.address) !== snapshot.address ||
      getAddress(snapshot.worker) !== snapshot.worker || !/^\d+$/.test(snapshot.cursor) ||
      !Array.isArray(snapshot.entries) || snapshot.entries.filter(entry => entry.status === 'pending').length > 1) {
    throw new Error('Invalid reward checkpoint.');
  }
  const abi = new Interface(CALENDAR_REWARD_ABI);
  for (const entry of snapshot.entries) {
    const tx = Transaction.from(entry.rawTransaction);
    const decoded = abi.parseTransaction({ data: tx.data });

    if (!['pending','confirmed','failed'].includes(entry.status) || tx.chainId !== 8453n ||
        tx.from?.toLowerCase() !== snapshot.worker.toLowerCase() || tx.to !== snapshot.address || tx.value !== 0n ||
        decoded?.name !== 'award' || String(decoded.args[0]) !== entry.appointmentId ||
        entry.hash !== tx.hash || !/^[1-9]\d*$/.test(entry.appointmentId) ||
        BigInt(entry.feeCapWei) !== tx.gasLimit * (tx.maxFeePerGas ?? tx.gasPrice) + L1_RESERVE ||
        BigInt(entry.feeCapWei) > PER_SEND_CAP) throw new Error('Invalid reward journal transaction; manual reconciliation required.');
  }
  if (new Set(snapshot.entries.map(entry => entry.hash)).size !== snapshot.entries.length ||
      snapshot.entries.reduce((sum, entry) => sum + BigInt(entry.feeCapWei), 0n) > WORKER_CAP) {
    throw new Error('Reward journal exceeds gas cap or repeats transactions.');
  }
}

export function createCalendarRewardWorker({ provider, signer, coordinator, address, runtimeCodeHash, restore, save,
  minimumReserveWei = SPONSORED_WORKER_MIN_BALANCE_WEI,
  contract = new Contract(address, CALENDAR_REWARD_ABI, provider),
  registry = new Contract(REGISTRY, ['function nextAppointmentId() view returns(uint256)'], provider),
  log = console, now = () => Date.now() }) {
  address = getAddress(address);
  if (!/^0x[0-9a-fA-F]{64}$/.test(runtimeCodeHash || '') || !signer || !coordinator ||
      typeof restore !== 'function' || typeof save !== 'function') throw new Error('Pinned rewards, existing DJuke signer and durable journal are required.');
  if (typeof minimumReserveWei !== 'bigint' || minimumReserveWei < SPONSORED_WORKER_MIN_BALANCE_WEI) throw new Error('Retain at least the sponsored DJuke worker gas minimum.');

let state, running, verifiedAt = 0, lastChecked = 0, lastError = 'Promotion worker has not reconciled';
const commit = async value => {
  const uri = await save(value);
  if (!/^ipfs:\/\//.test(uri || '')) throw new Error('Reward checkpoint did not confirm; nothing newly broadcast.');
  state = value;
};
async function verify() {
  if (state && now()-verifiedAt < 300000) return;
  if (BigInt(await provider.send('eth_chainId', [])) !== 8453n ||
      keccak256(await provider.getCode(address)) !== runtimeCodeHash) throw new Error('Reward network/runtime mismatch.');
  const [version,limit,registryAddress,nft,token] = await Promise.all([
    contract.VERSION(),contract.LIMIT(),contract.appointments(),contract.nft(),contract.tokenId(),
  ]);
  if (version !== 'dcal-first-booking-rewards-1' || limit !== 10n ||
      getAddress(registryAddress) !== REGISTRY || getAddress(nft) !== NFT || token !== 77n) throw new Error('Reward policy differs from approved ten-copy promotion.');
  if (!state) {
    const loaded = await restore();
    const initial = loaded ?? {schema:1,address,worker:signer.address,cursor:'0',entries:[]};
    if (initial.address !== address || initial.worker !== signer.address) throw new Error('Invalid reward checkpoint.');
    validateCalendarRewardCheckpoint(initial);
    state = initial;
    const pending = state.entries.find(entry=>entry.status==='pending');
    if (pending) coordinator.block(signer,pending.hash);
  }
  verifiedAt = now();
}
async function reconcile(entry) {
  const receipt = await provider.getTransactionReceipt(entry.hash);
  if (receipt) {
    if (await receipt.confirmations() < 2) return {pending:entry.hash};

    const rawReceipt = await provider.send('eth_getTransactionReceipt',[entry.hash]);
    if (rawReceipt?.l1Fee == null) throw new Error('Base L1 receipt fee unavailable; keep reward nonce held for reconciliation.');
    const actualFeeWei = receipt.gasUsed*receipt.gasPrice+BigInt(rawReceipt.l1Fee);
    await commit({...state,entries:state.entries.map(item=>item.hash===entry.hash
      ? {...item,status:receipt.status===1?'confirmed':'failed',actualFeeWei:String(actualFeeWei)} : item)});
    coordinator.unblock(signer,entry.hash);
    if (receipt.status !== 1) throw new Error(`Calendar reward reverted: ${entry.hash}; booking remains confirmed.`);
    return {confirmed:entry.hash};
  }
  // Only rebroadcast the identical, journaled transaction; never invent a replacement nonce.
  if (!await provider.getTransaction(entry.hash)) {
    try {
      const tx = await provider.broadcastTransaction(entry.rawTransaction);
      if (tx.hash !== entry.hash) throw new Error('Reward rebroadcast hash mismatch.');
    } catch (error) {
      if (error.error?.message !== 'already known' && error.code !== 'NONCE_EXPIRED') throw error;
      log.error('[calendar-rewards] RPC reports known/used nonce; exact reward receipt remains unconfirmed:',entry.hash);
    }
  }
  return {pending:entry.hash};
}
async function tick() {
  await verify();
  const pending = state.entries.find(entry=>entry.status==='pending');
  if (pending) return reconcile(pending);
  if (!await contract.enabled()) return {ready:false,reason:'Promotion is not activated or is paused'};
  if (await contract.awarded() >= 10n) return {ready:false,reason:'All ten gifts have been awarded'};
  const start = await contract.startAppointmentId();

let cursor = BigInt(state.cursor) > start ? BigInt(state.cursor) : start;
if (cursor === 0n) throw new Error('Activated promotion has no starting appointment ID.');
const through = await registry.nextAppointmentId();
for (let checked=0;cursor < through && checked<100;checked++,cursor++) {
  const recipient = await contract.eligible(cursor);
  if (recipient === ZERO) continue;
  return coordinator.exclusive(signer,async () => {
    if (await contract.eligible(cursor) === ZERO) { await commit({...state,cursor:String(cursor+1n)}); return {skipped:String(cursor)}; }
    let gas;
    try { gas = await contract.award.estimateGas(cursor,{from:signer.address}); }
    catch (error) {
      const receiverRejected = error.reason === 'ERC1155: transfer to non-ERC1155Receiver implementer' ||
        error.reason === 'ERC1155: ERC1155Receiver rejected tokens' ||
        typeof error.data === 'string' && error.data.startsWith(id('ERC1155InvalidReceiver(address)').slice(0,10));
      // Unknown reverts may be a paused NFT or transient stock issue; preserve this booking for retry.
      if (error.code !== 'CALL_EXCEPTION' || !receiverRejected) throw error;
      log.error('[calendar-rewards] Booking reward simulation rejected; booking is unchanged:',String(cursor),error.shortMessage || error.message);
      await commit({...state,cursor:String(cursor+1n)});
      return {rejected:String(cursor)};
    }
    const fees = await provider.getFeeData();
    const maxFeePerGas = fees.maxFeePerGas ?? fees.gasPrice;
    if (!maxFeePerGas || maxFeePerGas <= 0n) throw new Error('Reward fee quote unavailable.');
    const gasLimit = (gas*120n+99n)/100n;

    const feeCap = gasLimit*maxFeePerGas+L1_RESERVE;
    const used = state.entries.reduce((sum,entry)=>sum+(BigInt(entry.actualFeeWei || '0') > BigInt(entry.feeCapWei)
      ? BigInt(entry.actualFeeWei) : BigInt(entry.feeCapWei)),0n);
    if (feeCap > PER_SEND_CAP || used+feeCap > WORKER_CAP) throw new Error('Calendar promotion gas cap reached; no new transfer signed.');
    if (await provider.getBalance(signer.address) < minimumReserveWei+feeCap) throw new Error('Calendar rewards paused to retain DJuke minimum gas balance.');
    const nonce = Number(BigInt(await provider.send('eth_getTransactionCount',[signer.address,'pending'])));
    const transaction = await signer.populateTransaction({to:address,data:contract.interface.encodeFunctionData('award',[cursor]),
      value:0n,chainId:8453,nonce,gasLimit,maxFeePerGas,maxPriorityFeePerGas:fees.maxPriorityFeePerGas ?? 0n});
    const rawTransaction = await signer.signTransaction(transaction);
    const entry = {appointmentId:String(cursor),rawTransaction,hash:keccak256(rawTransaction),feeCapWei:String(feeCap),status:'pending'};
    validateCalendarRewardCheckpoint({...state,entries:[...state.entries,entry]});
    await commit({...state,cursor:String(cursor+1n),entries:[...state.entries,entry]});
    coordinator.block(signer,entry.hash);
    const tx = await provider.broadcastTransaction(rawTransaction);
    if (tx.hash !== entry.hash) throw new Error('Reward broadcast hash mismatch; reconcile journal.');
    log.info('[calendar-rewards] Transfer submitted',entry.hash,'recipient',recipient);
    // Reconciliation releases the signing lane only after two confirmations.
    return {pending:entry.hash};
  });
}

    if (state.cursor!==String(cursor)) await commit({...state,cursor:String(cursor)});
    return {ready:true,cursor:String(cursor)};
  }
  return {
    initialize:verify,
    check() {
      if (!running) running = tick().then(result=>{
        lastChecked=now(); lastError=result.reason || ''; return result;
      }).catch(error=>{lastError=error.shortMessage || error.message; throw error;}).finally(()=>{running=null;});
      return running;
    },
    status:()=>({ready:!lastError && now()-lastChecked<120000,reason:lastError || (now()-lastChecked>=120000?'Promotion worker status is stale':''),
      pendingHash:state?.entries.find(entry=>entry.status==='pending')?.hash || null}),
  };
}

