    let attempted = 0;
    let registered = 0;
    for (let scanned = 0; scanned < entries.length && attempted < batchSize; scanned++) {
      cursor %= entries.length;
      const entry = entries[cursor++];
      const { videoId, mediaHash, creator } = entry;
      const maxLanes = entry.radioTrack ? 3 : 1;
      const key = `${videoId}:${mediaHash}:${creator.toLowerCase()}:${maxLanes}`;
      if (confirmed.get(key) > now() || deferred.get(key) > now()) continue;
      attempted++;
      try {
        if (!isAddress(creator) || creator === ZeroAddress) throw new Error('No verified creator wallet');
        const current = await contract.videos(videoId);
        const lanes = Number(current.lanes);
        const exists = current.creator !== ZeroAddress;
        if (exists && current.mediaHash !== mediaHash) throw new Error('Existing media differs; admin review required');
        const moved = exists && current.creator.toLowerCase() !== creator.toLowerCase();
        // A configured but disabled entry may have been intentionally disabled by an admin.
        if ((exists && !lanes) || (!moved && (lanes & maxLanes) === maxLanes)) {
          confirmed.set(key, now() + 300_000);
          continue;
        }
        // Payees are re-verified on-chain (NFT creator or DJuke song split) before any write, including a move.
        if ((await getCreator(entry.nft)).toLowerCase() !== creator.toLowerCase()) {

            throw new Error('Archive wallet does not match the NFT payee');
          }
          let next = lanes;
          if ((lanes & maxLanes) !== maxLanes) {
            const url = await resolveMediaUrl(entry.ipfsCid);
            if (!url) throw new Error('IPFS media not available');
            const media = await probe(url);
            if (!media.video) throw new Error('No playable video stream');
            next = lanes | (media.radio ? maxLanes : 1);
          }
          if (next !== lanes || moved) {
            await preparePayee(entry.nft, creator);
            const tx = await contract.configureVideo(videoId, mediaHash, creator, next);
            if ((await tx.wait(2))?.status !== 1) throw new Error('Catalog registration not confirmed');
            log.log(`[dmtv-catalog] ${moved ? `Moved payout to ${creator} for` : 'Registered'} ${entry.nftId}, lanes ${next}: ${tx.hash}`);
            registered++;
          }
          confirmed.set(key, now() + 300_000);
        } catch (error) {
          deferred.set(key, now() + 900_000);
          log.warn(`[dmtv-catalog] ${entry.nftId} deferred: ${error.shortMessage || (error.code ? error.code : error.message)}`);
        }
      }
      return registered;
    })().finally(() => { task = null; });
    return task;
  };
}

import { id, ZeroHash } from 'ethers';

export function validDmtvEvidence(snapshot) {
  return snapshot?.dmtvEscrowEvidence === 1 && Array.isArray(snapshot.entries) &&
    snapshot.entries.every(entry => entry && (entry.lane === 0 || entry.lane === 1) &&
      /^\d{1,78}$/.test(entry.requestId) && /^0x[0-9a-f]{64}$/i.test(entry.proof));
}

export function createDmtvEscrowRuntime({ reader, writer, provider, store, resolveTrack, onSettled }) {
  let evidence;
  let serial = Promise.resolve();
  const held = new Map();
  const pendingWrite = new Map();
  const run = fn => {
    const pending = serial.then(fn);
    serial = pending.catch(() => {});
    return pending;
  };
  async function restore() {
    if (evidence) return;
    const snapshot = await store.restore();
    if (snapshot != null && !validDmtvEvidence(snapshot)) throw new Error('Invalid DMTv settlement checkpoint.');
    evidence = snapshot?.entries || [];
  }
  async function persist(entries) {
    if (!await store.save({ dmtvEscrowEvidence: 1, entries })) throw new Error('Could not save DMTv playback evidence.');
    evidence = entries;
  }
  async function settle(entry) {
    const { lane, requestId, proof } = entry;
    const request = await reader.requests(lane, requestId);
    const refund = proof === ZeroHash;
    if (Number(request.status) === 1 && (refund || Number(request.refundAt) > (await provider.getBlock('latest')).timestamp)) {
      const tx = await (refund ? writer.cancelAndRefund(lane, requestId) : writer.fulfill(lane, requestId, proof));
      if ((await tx.wait(2))?.status !== 1) throw new Error(`DMTv ${refund ? 'refund' : 'settlement'} not confirmed for ${requestId}.`);
      if (!refund) onSettled?.({ lane, requestId, txHash: tx.hash, creator: request.creator });
    }

  await persist(evidence.filter(item => item !== entry));
}
function forLane(lane) {
  async function flushOutcome() {
    const entry = pendingWrite.get(lane);
    if (entry) {
      await persist([...evidence, entry]);
      pendingWrite.delete(lane);
    }
    const prior = evidence.find(item => item.lane === lane);
    if (prior) await settle(prior);
  }

  async function recordCompletion(record, playId) {
    // Zero is forbidden as a fulfillment proof and journals a refund instead.
    pendingWrite.set(lane, { lane, requestId: record.requestId,
      proof: playId ? id(`dmtv:${lane}:${record.requestId}:${playId}`) : ZeroHash });
    await flushOutcome();
  }
  return {
    nextPaid: ({ acceptNew = true } = {}) => run(async () => {
      await restore();
      await flushOutcome();
      if (!acceptNew || held.has(lane) || await reader.paused()) return null;
      const latest = await provider.getBlockNumber();
      if (latest < 2) throw new Error('DMTv requires confirmed blocks.');
      const blockTag = latest - 1;
      const block = await provider.getBlock(blockTag);
      const bounds = { blockTag };
      const [head, tail] = await Promise.all([reader.head(lane, bounds), reader.tail(lane, bounds)]);
      for (let cursor = head; cursor < tail && cursor - head < 128n; cursor++) {
        const request = await reader.requests(lane, cursor, bounds);
        if (Number(request.status) !== 1 || Number(request.refundAt) <= block.timestamp) continue;
        const track = await resolveTrack(request.videoId, lane);
        const configured = await reader.videos(request.videoId, bounds);
        if (!track || id(track.videoUrl) !== request.mediaHash ||

        track.creator.toLowerCase() !== request.creator.toLowerCase() ||
        configured.mediaHash !== request.mediaHash ||
        configured.creator.toLowerCase() !== request.creator.toLowerCase() ||
        !(Number(configured.lanes) & (1 << lane))) {
      await recordCompletion({ requestId: String(cursor) }, null);
      return null;
    }
    const record = { kind: 'dmtv', requestId: String(cursor), lane, trackId: track.trackId };
    held.set(lane, record);
    return { record, track };
  }
  return null;
}),
complete: (record, play) => run(async () => {
  if (held.get(lane) !== record) return;
  held.delete(lane);
  if (!play?.finished || play.trackId !== record.trackId || !play.playId ||
      !(play.expectedMs > 0) || !(play.audibleMs >= play.expectedMs * 0.95)) {
    await recordCompletion(record, null);
    return;
  }
  await recordCompletion(record, play.playId);
}),
completePublished: (record, playId) => run(async () => {
  if (lane !== 0 || held.get(lane) !== record || !playId) throw new Error('Invalid DMTv station completion.');
  held.delete(lane);
  await recordCompletion(record, playId);
}),
completeVerifiedRadio: (record, playId) => run(async () => {
  if (lane !== 1 || held.get(lane) !== record || !playId) throw new Error('Invalid DMTv radio verification.');
  held.delete(lane);
  await recordCompletion(record, playId);
}),
release: record => run(() => { if (held.get(lane) === record) held.delete(lane); }),
fail: record => run(async () => {
  if (held.get(lane) !== record) return;
  held.delete(lane);

        await recordCompletion(record, null);
      }),
      hasPendingSelection: () => held.has(lane),
    };
  }
  return { forLane, checkStorage: () => run(restore) };
}

import { createHmac, randomUUID, timingSafeEqual } from 'node:crypto';
import { Interface, id, verifyMessage } from 'ethers';
import { SETTLEMENT_ROUTER_ADDRESS as ROUTER } from '../js/fund-contribution.mjs';
import { BASE_USDC_ADDRESS as USDC } from '../js/settlement-funds.mjs';
import { DMTV_FUND_SLUG, DMTV_MAIN_RADIO_CREATOR_UNITS, DMTV_MAIN_RADIO_FUND_UNITS } from '../js/dmtv.mjs';
import { dmtvRadioAuthorization } from '../js/dmtv-radio.mjs';

const hashPattern = /^0x[0-9a-f]{64}$/i;
const addressPattern = /^0x[0-9a-f]{40}$/i;
const same = (a, b) => typeof a === 'string' && a.toLowerCase() === b.toLowerCase();
export function isDmtvRadioCheckpoint(snapshot) {
  return snapshot?.version === 1 && Array.isArray(snapshot.requests) && snapshot.requests.every(record =>
    record?.kind === 'dmtv' && /^dmtv:[a-f0-9-]{36}$/i.test(record.requestId) &&
    ['pending', 'reserved', 'played'].includes(record.state) &&
    hashPattern.test(record.creatorTx) && hashPattern.test(record.fundTx) &&
    !same(record.creatorTx, record.fundTx) && addressPattern.test(record.track?.creator) &&
    typeof record.track.nftId === 'string' && !!record.track.nftId &&
    typeof record.track.ipfsCid === 'string' && !!record.track.ipfsCid);
}
const fundId = id(DMTV_FUND_SLUG);
const abi = new Interface([
  'event Transfer(address indexed from,address indexed to,uint256 value)',
  'event FundFunded(bytes32 indexed fundId,address indexed asset,address indexed funder,uint256 amount)',
]);

export function verifyDmtvRadioReceipts(quote, creator, fund) {
  const { payer, track, block } = quote;
  for (const [receipt, to] of [[creator, USDC], [fund, ROUTER]]) {
    if (receipt?.status !== 1 || receipt.blockNumber <= block ||
        !same(receipt.from, payer) || !same(receipt.to, to)) {

      throw new Error('DMTv requires two successful Base payments made after checkout opened.');
    }
  }
  const has = (receipt, address, name, matches) => receipt.logs.some(log => {
    if (!same(log.address, address)) return false;
    const event = abi.parseLog(log);
    return event?.name === name && matches(event.args);
  });
  if (!has(creator, USDC, 'Transfer', a => same(a.from, payer) && same(a.to, track.creator) &&
      a.value === DMTV_MAIN_RADIO_CREATOR_UNITS) ||
      !has(fund, USDC, 'Transfer', a => same(a.from, payer) && same(a.to, ROUTER) && a.value === DMTV_MAIN_RADIO_FUND_UNITS) ||
      !has(fund, ROUTER, 'FundFunded', a => a.fundId === fundId && same(a.asset, USDC) &&
      same(a.funder, payer) && a.amount === DMTV_MAIN_RADIO_FUND_UNITS)) {
    throw new Error('The receipts do not prove the $1 creator share and $2 weekly Playback deposit.');
  }
}

export function createDmtvRadioQueue({ provider, store, secret, findTrack, enabled }) {
  let state;
  let serial = Promise.resolve();
  const run = fn => {
    const result = serial.then(fn);
    serial = result.catch(() => {});
    return result;
  };
  async function restore() {
    if (state) return;
    const saved = await store.restore();
    if (saved != null && !isDmtvRadioCheckpoint(saved)) {
      throw new Error('Invalid DMTv radio checkpoint.');
    }
    state = (saved?.requests || []).map(record => record.state === 'reserved'
      ? { ...record, state: 'pending' } : record);
  }
  async function save(requests) {
    if (!await store.save({ version: 1, requests })) throw new Error('DMTv radio checkpoint did not persist.');
    state = requests;
  }
  const sign = payload => createHmac('sha256', secret).update(`dmtv-radio/v1:${payload}`).digest();
  function decode(ticket) {

  if (typeof ticket !== 'string' || ticket.length > 5000 || !/^[\w-]+\.[\w-]+$/.test(ticket)) {
    throw new Error('Invalid DMTv checkout.');
  }
  const [payload, signature] = ticket.split('.');
  const bytes = Buffer.from(signature, 'base64url');
  if (bytes.length !== 32 || !timingSafeEqual(bytes, sign(payload))) throw new Error('Invalid DMTv checkout.');
  return JSON.parse(Buffer.from(payload, 'base64url').toString());
}
function update(requestId, fields) {
  return save(state.map(request => request.requestId === requestId ? { ...request, ...fields } : request));
}
return {
  async status() {
    if (!enabled()) return { enabled: false };
    await run(restore);
    return { enabled: true };
  },
  async quote({ payer, nftId }) {
    if (!enabled()) throw new Error('DMTv main-radio checkout is unavailable.');
    if (!addressPattern.test(payer || '') || typeof nftId !== 'string' || nftId.length > 128) {
      throw new Error('Select an archive video and connect your Base wallet.');
    }
    await run(restore);
    const track = await findTrack(nftId);
    if (!track || !addressPattern.test(track.creator) || same(track.creator, payer)) {
      throw new Error('This archive video is not eligible for a paid main-radio spot.');
    }
    const block = await provider.getBlockNumber();
    const payload = Buffer.from(JSON.stringify({ quoteId: randomUUID(), payer, nftId, track, block })).toString('base64url');
    return { ticket: `${payload}.${sign(payload).toString('base64url')}`, creator: track.creator };
  },
  async submit({ ticket, creatorTx, fundTx, signature }) {
    const quote = decode(ticket);

  if (!hashPattern.test(creatorTx || '') || !hashPattern.test(fundTx || '') || same(creatorTx, fundTx) ||
      !same(verifyMessage(dmtvRadioAuthorization(ticket, creatorTx, fundTx), signature), quote.payer)) {
    throw new Error('DMTv radio submission must be signed by the paying wallet.');
  }
  const requestId = `dmtv:${quote.quoteId}`;
  const result = record => ({ requestId, state: record.state, title: record.track.title });
  return run(async () => {
    await restore();
    const existing = state.find(record => record.requestId === requestId);
    if (existing && same(existing.creatorTx, creatorTx) && same(existing.fundTx, fundTx)) return result(existing);
    if (existing || state.some(record => [record.creatorTx, record.fundTx].some(hash =>
      same(hash, creatorTx) || same(hash, fundTx)))) throw new Error('A DMTv payment is already assigned to a request.');
    const [creator, fund, block] = await Promise.all([
      provider.getTransactionReceipt(creatorTx), provider.getTransactionReceipt(fundTx), provider.getBlockNumber(),
    ]);
    if (!creator || !fund || block - Math.max(creator.blockNumber, fund.blockNumber) < 1) {
      throw new Error('Wait for two Base confirmations, then resume this purchase.');
    }
    verifyDmtvRadioReceipts(quote, creator, fund);
    const record = { requestId, creatorTx, fundTx, track: quote.track, kind: 'dmtv', state: 'pending' };
    await save([...state, record]);
    return result(record);
  });
},
nextPaid() {
  return run(async () => {
    await restore();
    const entry = state.find(record => record.state === 'pending' && (record.retryAfter || 0) <= Date.now());
    if (!entry) return null;

        const eligibility = await findTrack(entry.track.nftId);
        if (!eligibility || eligibility.ipfsCid !== entry.track.ipfsCid) {
          await update(entry.requestId, { retryAfter: Date.now() + 60_000 });
          throw new Error(`DMTv request ${entry.requestId} is awaiting archive media verification.`);
        }
        await update(entry.requestId, { state: 'reserved' });
        return { record: { requestId: entry.requestId, kind: entry.kind }, track: entry.track };
      });
    },
    complete(record, play) {
      return run(async () => {
        await restore();
        if (!state.some(entry => entry.requestId === record.requestId && entry.state === 'reserved')) return;
        await update(record.requestId, play?.finished && play.audibleMs > 0
          ? { state: 'played', playId: play.playId }
          : { state: 'pending', retryAfter: Date.now() + 60_000 });
      });
    },
    fail(record, error) {
      return run(async () => {
        await restore();
        if (!state.some(entry => entry.requestId === record.requestId && entry.state === 'reserved')) return;
        await update(record.requestId, { state: 'pending', retryAfter: Date.now() + 60_000, lastError: String(error.message).slice(0, 250) });
      });
    },
    release(record) {
      return run(async () => {
        await restore();
        if (!state.some(entry => entry.requestId === record.requestId && entry.state === 'reserved')) return;
        await update(record.requestId, { state: 'pending' });
      });
    },
  };
}

import { randomUUID } from 'node:crypto';

export function createDmtvRadioVerification({ now = Date.now, log = console } = {}) {
  let lastReady = -Infinity;
  let active;
  const ready = () => now() - lastReady < 12_000;

  function finish(ok, reason) {
    if (!active) return;
    const job = active;
    active = undefined;
    clearTimeout(job.timer);
    if (!ok) log.warn(`[dmtv] Radio video verification failed: ${reason}`);
    job.resolve(ok);
  }

  return {
    ready,
    start({ playId, ipfsCid, expectedMs }) {
      if (active || !ready() || !playId || !/^[a-z0-9]{20,120}$/i.test(ipfsCid) ||
          !Number.isFinite(expectedMs) || expectedMs <= 0 || expectedMs > 7_200_000) {
        log.warn('[dmtv] Radio video verification could not start');
        return Promise.resolve(false);
      }
      const deadline = now() + expectedMs + 45_000;
      return new Promise(resolve => {
        active = { data: { id: randomUUID(), playId, ipfsCid, expectedMs, deadline }, startedAt: now(), resolve };
        active.timer = setTimeout(() => finish(false, 'timed out'), expectedMs + 45_000);
        active.timer.unref?.();
      });
    },
    exchange(message) {
      if (message?.version !== 1 || typeof message.ready !== 'boolean') {
        throw new Error('Invalid DMTv verifier message');
      }
      if (message.ready) lastReady = now();
      else lastReady = -Infinity;
      const { result } = message;
      if (result && active?.data.id === result.id) {
        const { expectedMs, deadline } = active.data;
        const ok = now() <= deadline && now() - active.startedAt >= expectedMs / 2 && Number.isFinite(result.syncedMs) &&
          result.syncedMs >= expectedMs / 2 && result.syncedMs <= expectedMs;
        finish(ok, 'less than half was verified');
      }

      return { job: active?.data ?? null };
    },
  };
}

export function attachDmtvRadioVerification(queue, verifier, log = console) {
  const outcomes = new WeakMap();
  return {
    ...queue,
    startPlayback(record, program) {
      if (outcomes.has(record)) return;
      const outcome = verifier.start(program).then(ok => ok
        ? queue.completeVerifiedRadio(record, program.playId)
        : queue.fail(record));
      outcomes.set(record, outcome);
      void outcome.catch(error => log.warn(`[dmtv] Radio outcome deferred: ${error.code || 'checkpoint or RPC unavailable'}`));
    },
    complete(record) { return outcomes.get(record) || queue.fail(record); },
    fail(record) { return outcomes.get(record) || queue.fail(record); },
    release(record) { return outcomes.get(record) || queue.release(record); },
  };
}

import 'dotenv/config';
import { readFile } from 'node:fs/promises';
import { setTimeout as sleep } from 'node:timers/promises';
import { pathToFileURL } from 'node:url';
import { chromium } from 'playwright-core';

const probeOrigin = 'http://127.0.0.1:46931';

export async function createRadioProofBrowser(executablePath, libraryPath = process.env.DMTV_CHROME_LIBRARY_PATH) {
  const browser = await chromium.launch({ executablePath, timeout: 15_000,
    args: ['--autoplay-policy=no-user-gesture-required', '--disable-dev-shm-usage'],
    env: { ...Object.fromEntries(['HOME', 'PATH', 'TMPDIR', 'LANG', 'DISPLAY']
      .filter(name => process.env[name] != null).map(name => [name, process.env[name]])),
    ...(libraryPath ? { LD_LIBRARY_PATH: libraryPath } : {}) } });
  try {
    const page = await browser.newPage({ viewport: { width: 640, height: 360 } });
    page.on('console', message => {
      if (message.text().startsWith('[dmtv-proof]')) console.log(`${new Date().toISOString()} ${message.text()}`);
    });
    await page.route(`${probeOrigin}/**`, async route => {
      const { pathname } = new URL(route.request().url());
      if (pathname === '/') {
        await route.fulfill({ contentType: 'text/html', body: '<!doctype html><meta charset="utf-8"><title>DMTv verifier</title>' });
      } else if (/^\/[a-z][a-z0-9-]*\.mjs$/.test(pathname)) {
        await route.fulfill({ contentType: 'application/javascript', body: await readFile(new URL(`../js${pathname}`, import.meta.url)) });
      } else {
        await route.abort();
      }
    });
    await page.goto(probeOrigin);
    if (!await page.evaluate(() => typeof HTMLVideoElement.prototype.requestVideoFrameCallback === 'function' &&
        globalThis.MediaSource?.isTypeSupported('audio/mp4; codecs="mp4a.40.2"') &&

        document.createElement('video').canPlayType('video/mp4; codecs="avc1.42E01E"'))) {
      throw new Error('DMTv verifier needs Chrome with AAC, H.264 and video frame callbacks');
    }
    return {
      page,
      ready: () => browser.isConnected(),
      verify: (job, serviceUrl) => page.evaluate(async ({ job, serviceUrl }) =>
        (await import('/dmtv-radio-proof.mjs')).verifyRadioPlayback(job, serviceUrl), { job, serviceUrl }),
      close: () => browser.close(),
    };
  } catch (error) {
    await browser.close();
    throw error;
  }
}

async function main() {
  const base = new URL(process.env.PUBLIC_WORKER_URL);
  if (base.protocol !== 'https:' || base.username || base.password || base.origin !== base.href.replace(/\/$/, '')) {
    throw new Error('DMTv verifier requires the public HTTPS worker origin');
  }
  const secret = process.env.DMTV_VERIFIER_SECRET || process.env.CHECKPOINT_MIRROR_SECRET;
  if (!secret || Buffer.byteLength(secret) < 32) throw new Error('DMTv verifier requires DMTV_VERIFIER_SECRET');
  const executablePath = process.env.DMTV_CHROME_EXECUTABLE;
  if (!executablePath) throw new Error('Set DMTV_CHROME_EXECUTABLE to the installed Chrome executable');
  let stopping = false;
  for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, () => { stopping = true; });
  const player = await createRadioProofBrowser(executablePath);
  let active, result;
  try {
    while (!stopping) {
      if (!player.ready()) throw new Error('DMTv verifier browser disconnected');
      try {
        const response = await fetch(new URL('/api/dmtv/radio-verification', base), { method: 'POST',
          headers: { authorization: `Bearer ${secret}`, 'content-type': 'application/json' },

          body: JSON.stringify({ version: 1, ready: true, result }), redirect: 'error', signal: AbortSignal.timeout(6000) });
        if (!response.ok) throw new Error(`DMTv verifier exchange returned ${response.status}`);
        const { job } = await response.json();
        if (result && job?.id !== result.id) result = undefined;
        if (!active && !result && job?.id && job.deadline > Date.now()) {
          active = player.verify(job, base.origin)
            .then(syncedMs => { result = { id: job.id, syncedMs }; })
            .catch(error => {
              console.error(`${new Date().toISOString()} [dmtv-verifier] Playback check failed: ${error.name}`);
              result = { id: job.id, syncedMs: 0 };
            }).finally(() => { active = undefined; });
        }
      } catch (error) { console.error(`[dmtv-verifier] ${error.message}`); }
      await sleep(2000);
    }
  } finally { await player.close(); }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch(error => { console.error(`[dmtv-verifier] ${error.message}`); process.exitCode = 1; });
}

import { spawn } from 'node:child_process';
