}

const archiveWeeks = archiveGroupId ? createWeeklyHistory({ name, tags, timeZone: CHECKPOINT_TIME_ZONE,
  readBytes: readHistory,
  readVerifiedBytes: cid => readHistory(cid, { verifiedBytes: true }),
