function checksumAddress(address) {
  try { return getAddress(address); } catch { return address; }
}

function normalizeSponsor(sponsor) {
  if (!sponsor) return null;
  if (sponsor.kind === 'djuke') {
    return {
      kind: 'djuke',
      wallet: checksumAddress(sponsor.wallet),
      amountUnits: String(sponsor.amountUnits),
      requestId: sponsor.requestId,
    };
  }
  if (sponsor.kind === 'devert') {
    return {
      kind: 'devert',

      wallet: checksumAddress(sponsor.wallet),
      campaignId: String(sponsor.campaignId),
    };
  }
  return null;
}

function shortAddress(address) {
  const value = String(address || '');
  return value.length > 10 ? `${value.slice(0, 6)}…${value.slice(-4)}` : value;
}

function formatUsdcUnits(units) {
  const value = BigInt(units || '0');
  const fraction = (value % 1_000_000n).toString().padStart(6, '0').replace(/0+$/, '');
  return `${value / 1_000_000n}${fraction ? `.${fraction}` : ''}`;
}

function normalizeMainRadioAd(ad) {
  if (!ad || typeof ad !== 'object') return null;
  if (!/^\d+$/.test(String(ad.campaignId)) || typeof ad.mainRadio !== 'boolean' || !ad.track || typeof ad.track.trackId !== 'string') {
    throw new Error('Invalid DeVert main-radio ad journal entry');
  }
  return {
    campaignId: String(ad.campaignId),
    mainRadio: ad.mainRadio === true,
    ...(ad.competitionReward ? { competitionReward: structuredClone(ad.competitionReward) } : {}),
    track: structuredClone(ad.track),
  };
}

function validateMainRadioAdState(value) {
  if (!value || value.schemaVersion !== MAIN_RADIO_STATE_SCHEMA_VERSION ||
    !Number.isSafeInteger(value.musicSinceAd) || value.musicSinceAd < 0 ||
    !Number.isSafeInteger(value.musicPlayCount) || value.musicPlayCount < 0 ||
    !Array.isArray(value.pendingDevertAds) || !Array.isArray(value.failedDevertCampaigns)) {
    throw new Error('Invalid DeVert main-radio ad journal');
  }
  return structuredClone({
    schemaVersion: MAIN_RADIO_STATE_SCHEMA_VERSION,
    musicSinceAd: value.musicSinceAd,
    musicPlayCount: value.musicPlayCount,
    preparedDevertAd: value.preparedDevertAd ? normalizeMainRadioAd(value.preparedDevertAd) : null,
    pendingDevertAds: value.pendingDevertAds.map(normalizeMainRadioAd),

    breakAwaitingUnlock: value.breakAwaitingUnlock === true,
    unbookedLiveOccurrenceId: typeof value.unbookedLiveOccurrenceId === 'string' ? value.unbookedLiveOccurrenceId : null,
    failedDevertCampaigns: value.failedDevertCampaigns.map(entry => {
      if (!entry || !/^\d+$/.test(String(entry.campaignId)) ||
        !Number.isSafeInteger(entry.failedAt) || entry.failedAt < 0 ||
        !Number.isSafeInteger(entry.musicPlayCount) || entry.musicPlayCount < 0) {
        throw new Error('Invalid DeVert main-radio failure journal entry');
      }
      return {
        campaignId: String(entry.campaignId),
        failedAt: entry.failedAt,
        musicPlayCount: entry.musicPlayCount,
      };
    }),
    lastSkip: value.lastSkip && typeof value.lastSkip === 'object'
      ? {
          reason: typeof value.lastSkip.reason === 'string' ? value.lastSkip.reason : '',
          campaignId: value.lastSkip.campaignId ? String(value.lastSkip.campaignId) : null,
          at: Number.isSafeInteger(value.lastSkip.at) && value.lastSkip.at >= 0 ? value.lastSkip.at : 0,
        }
      : null,
  });
}

/** Build a gateway URL for a raw IPFS CID. */
export function buildIpfsGatewayUrl(gateway, cid) {
  const [rawBase, query = ''] = gateway.split('?');
  const base = rawBase.replace(/\/$/, '');
  return `${base}${base.endsWith('/ipfs') ? '' : '/ipfs'}/${cid}${query ? `?${query}` : ''}`;
}

const FALLBACK_IPFS_GATEWAY = 'https://gateway.pinata.cloud';
const GATEWAY_PROBE_TIMEOUT_MS = 15_000;

/** True when the URL serves audio bytes; public gateways often answer 429 or redirect to dead hosts. */
export async function isUrlStreamable(url, fetchImpl = fetch) {
  try {
    const response = await fetchImpl(url, {
      headers: { range: 'bytes=0-0' },

      signal: AbortSignal.timeout(GATEWAY_PROBE_TIMEOUT_MS),
    });
    await response.body?.cancel().catch(() => {});
    return response.status === 200 || response.status === 206;
  } catch {
    return false;
  }
}

// The account's dedicated Pinata gateway; public gateways rate-limit shared hosting IPs.
let dedicatedIpfsGateways = [];
export function setDedicatedIpfsGateways(gateways) {
  dedicatedIpfsGateways = (Array.isArray(gateways) ? gateways : [gateways]).filter(value => typeof value === 'string' && value);
}

/** First gateway URL (configured, public Pinata, then dedicated Pinata) that can actually stream the CID, or null. */
export async function resolveStreamableIpfsUrl(gateway, cid, fetchImpl = fetch, extraGateways = dedicatedIpfsGateways) {
  const gateways = [...new Set([gateway, FALLBACK_IPFS_GATEWAY, ...extraGateways].filter(Boolean))];
  for (const candidate of gateways) {
    const url = buildIpfsGatewayUrl(candidate, cid);
    if (await isUrlStreamable(url, fetchImpl)) return url;
  }
  return null;
}

/** Public radio snapshot; positionMs lets browsers sync without trusting their own clocks. */
export function buildRadioState({ nowPlaying, upNext = null, playlist, now = Date.now(), recentLimit = 10, mainRadioAdCountdown = null, playback = null,
  activeShow = null, topTenHype = null, playlistShow = null, adVotes = null }) {
  const mediaTypeForTrack = (track) => (track.videoUrl || track.mediaType === 'video/mp4')
    ? 'video/mp4'
    : mediaTypeFor(track.filename, track.mediaType) || '';
  const recent = playlist.filter(track => !track.isDevertAd && (track.source !== 'site' || track.mintStatus === 'minted'))
    .sort((first, second) => Date.parse(second.addedAt) - Date.parse(first.addedAt))
    .slice(0, recentLimit)
    .map((track) => ({

    trackId: track.trackId,
    title: track.title,
    uploader: track.uploader,
    filename: track.filename || null,
    mediaType: mediaTypeForTrack(track),
    ipfsCid: track.ipfsCid || null,
    addedAt: track.addedAt,
  }));
return {
  serverTime: now,
  recordingDurations: playlist.filter(track => !track.isDevertAd).reduce((counts, track) => {
    const seconds = verifiedRecordingDuration(track);
    counts[seconds === null ? 'unresolved' : seconds > 600 ? 'longForm' : 'ordinary']++;
    if (seconds === null && track.durationProbe?.status === 'failed') counts.failed++;
    return counts;
  }, { ordinary: 0, longForm: 0, unresolved: 0, failed: 0 }),
  playback,
  activeShow,
  topTenHype,
  playlistShow,
  nowPlaying: nowPlaying && nowPlaying.audible !== false
    ? (() => {
        const videoUrl = nowPlaying.videoUrl || (mediaTypeFor(nowPlaying.filename, nowPlaying.mediaType) === 'video/mp4'
          ? `ipfs://${nowPlaying.ipfsCid}`
          : '');
        const sponsor = normalizeSponsor(nowPlaying.sponsor);
        return {
          playId: nowPlaying.playId || `${nowPlaying.trackId}:${nowPlaying.startedAt}`,
          trackId: nowPlaying.trackId,
          title: nowPlaying.title,
          uploader: nowPlaying.uploader,
          filename: nowPlaying.filename || null,
          mediaType: mediaTypeForTrack(nowPlaying),
          ...(videoUrl ? { videoUrl } : {}),
          ipfsCid: nowPlaying.ipfsCid || null,
          isDevert: nowPlaying.isDevert === true,
          ...(nowPlaying.isDevert ? { adVotes } : {}),
          ...(nowPlaying.playlistShow ? { playlistShow: { ...nowPlaying.playlistShow } } : {}),
          ...(nowPlaying.hype ? { hype: { ...nowPlaying.hype } } : {}),

            ...(nowPlaying.djukePlaylist ? { djukePlaylist: { ...nowPlaying.djukePlaylist } } : {}),
            ...(sponsor ? { sponsor } : {}),
            startedAt: nowPlaying.startedAt,
            positionMs: Math.max(0, now - nowPlaying.startedAt),
          };
        })()
      : null,
    // The already-prepared next item, so browsers can preload it before the changeover.
    upNext: upNext?.trackId
      ? (() => {
          const mediaType = mediaTypeForTrack(upNext);
          const videoUrl = upNext.videoUrl || (mediaType === 'video/mp4' && upNext.ipfsCid ? `ipfs://${upNext.ipfsCid}` : '');
          return {
            trackId: upNext.trackId,
            title: upNext.title,
            uploader: upNext.uploader,
            filename: upNext.filename || null,
            mediaType,
            ...(videoUrl ? { videoUrl } : {}),
            ipfsCid: upNext.ipfsCid || null,
            isDevert: upNext.isDevert === true,
            ...(upNext.djukePlaylist ? { djukePlaylist: { ...upNext.djukePlaylist } } : {}),
            ...(Number.isFinite(upNext.startsAt)
              ? { startsAt: upNext.startsAt, startsInMs: Math.max(0, upNext.startsAt - now) }
              : {}),
          };
        })()
      : null,
    recent,
    mainRadioAdCountdown: mainRadioAdCountdown ? { ...mainRadioAdCountdown } : null,
  };
}

export async function buildMainRadioAdCountdown({ session, now = Date.now(), songsPerMainAd = DEVERT_SONGS_PER_MAIN_AD, paidQueue = null } = {}) {
  if (!session) {
    return { status: 'unavailable', reason: 'radio session unavailable', updatedAt: now, includesCurrentSong: false };
  }

  const activeShow = applyLiveAudioShow(resolveActiveShow({
    now, schedule: session.schedule, livePerformanceEvents: session.livePerformanceEvents,

}), session.liveAudioPolicy);
const summary = {
  updatedAt: now,
  activeShow: {
    type: activeShow.type,
    label: activeShow.label || '',
    window: activeShow.window || '',
  },
  includesCurrentSong: false,
  ...(paidQueue ? { paidQueue: paidQueue.unavailable ? { unavailable: true, reason: paidQueue.reason } : {
    pendingCount: paidQueue.pendingCount,
    immediateCount: paidQueue.requests.filter(request => request.tier === 1).length,
    playbackReady: !paidQueue.paused && paidQueue.playbackReady,
    reason: paidQueue.paused ? 'Priority queue paused' : paidQueue.playbackReason,
  } } : {}),
  ...(session._lastMainRadioAdSkip ? { lastSkip: { ...session._lastMainRadioAdSkip } } : {}),
};
// Skips recorded during this call must be reported, not the snapshot taken above.
const latestSkip = () => (session._lastMainRadioAdSkip ? { lastSkip: { ...session._lastMainRadioAdSkip } } : {});

if (session._currentDevertAd) {
  const audible = session._nowPlaying?.audible === true;
  return {
    ...summary,
    status: audible ? 'playing' : 'up_next',
    campaignId: String(session._currentDevertAd.campaignId),
    title: session._currentDevertAd.track?.title || 'Main radio advert',
    mainRadio: true,
    remainingSongs: 0,
    includesCurrentSong: false,
  };
}

const queuedAd = session._preparedDevertAd || session._pendingDevertAds?.[0] || null;
if (queuedAd) {
  return {
    ...summary,
    status: 'up_next',
    campaignId: String(queuedAd.campaignId),
    title: queuedAd.track?.title || 'Main radio advert',
    mainRadio: true,
    remainingSongs: 0,
    includesCurrentSong: false,
  };
}

if (!session.devertPlayback) {

  return { ...summary, status: 'unavailable', reason: 'main-radio scheduler unavailable' };
}

try {
  const gas = session.devertPlayback.getWorkerGasState ? await session.devertPlayback.getWorkerGasState() : null;
  if (gas?.lowBalance) {
    return {
      ...summary,
      status: 'unavailable',
      reason: 'worker gas low',
      workerAddress: gas.workerAddress || '',
      balanceWei: gas.balanceWei ?? null,
      thresholdWei: gas.thresholdWei ?? null,
      runwayDays: gas.runwayDays ?? null,
    };
  }
} catch (error) {
  console.warn('[devert] Worker gas status unavailable:', error.message);
  return { ...summary, status: 'unavailable', reason: 'worker gas check unavailable' };
}

if (activeShow.type === 'live_performance' || activeShow.type === 'weekly_top10') {
  return {
    ...summary,
    status: 'paused',
    reason: activeShow.label || activeShow.type,
  };
}

const songsSinceAd = Number.isSafeInteger(session._musicSinceAd) ? session._musicSinceAd : 0;
const remainingSongs = Math.max(0, songsPerMainAd - songsSinceAd);
if (remainingSongs > 0) {
  return {
    ...summary,
    status: 'countdown',
    remainingSongs,
    mainRadio: true,
  };
}

let nextAd = null;
try {
  nextAd = await session.devertPlayback.nextMainRadioAd({
    excludeCampaignIds: session._getActiveFailedDevertCampaignIds ? session._getActiveFailedDevertCampaignIds() : [],
    count: 1,
  });
} catch (error) {
  const lowGas = error?.code === 'INSUFFICIENT_FUNDS' || /insufficient funds/i.test(error?.shortMessage || error?.message || '');
  if (!lowGas) console.warn('[devert] Main radio ad lookup failed:', error?.message || error);

    if (session._setMainRadioAdSkip) session._setMainRadioAdSkip(lowGas ? 'worker gas low' : 'main-radio scheduler unavailable', null);
    return {
      ...summary,
      ...latestSkip(),
      status: 'unavailable',
      reason: lowGas ? 'worker gas low' : 'main-radio scheduler unavailable',
    };
  }

  const campaign = Array.isArray(nextAd) ? nextAd[0] : nextAd;
  if (!campaign) {
    if (session._lastMainRadioAdSkip?.reason === 'selection deferred') {
      return {
        ...summary,
        status: 'unavailable',
        reason: 'main-radio scheduler unavailable',
      };
    }
    if (session._setMainRadioAdSkip) session._setMainRadioAdSkip('no eligible campaign available', null);
    return {
      ...summary,
      ...latestSkip(),
      status: 'none',
      reason: 'no eligible campaign available',
      remainingSongs: 0,
      mainRadio: true,
    };
  }

  return {
    ...summary,
    status: 'up_next',
    campaignId: String(campaign.campaignId),
    title: campaign.track?.title || 'Main radio advert',
    remainingSongs: 0,
    mainRadio: true,
  };
}

export function buildSiteVotingLink() {
  const siteUrl = (process.env.SITE_URL || 'https://thejollylama.github.io/DecentBusking').replace(/\/$/, '');
  return `[Listen and vote on DecentBusking](${siteUrl}/)`;
}

export function buildNowPlayingMessage(track, { queueIndex, totalTracks, url, votingOpen = true, playId, paid = false, sponsor = null, hype = null, playlistShow = null }) {
  const listenLink = track.ipfsCid && /\/ipfs\//.test(url || '') ? `\n[Open IPFS audio](${url})` : '';
  const idLine = `\nTrack \`${track.trackId}\`` + (playId ? ` · Play \`${playId}\`` : '');
  const votingLine = votingOpen
    ? `Vote for this song on the site: ${buildSiteVotingLink()}`

    : `This play has finished. Vote for the current song on the site: ${buildSiteVotingLink()}`;
  const sponsorLine = sponsor?.kind === 'djuke'
    ? `💸 **DJuke paid request** · bumped by \`${shortAddress(sponsor.wallet)}\` · ${formatUsdcUnits(sponsor.amountUnits)} USDC\n`
    : sponsor?.kind === 'devert'
      ? `📣 **DeVert ad** · sponsored by \`${shortAddress(sponsor.wallet)}\`\n`
      : '';
  return (
    `🎵 Now playing: **${track.title}** by *${track.uploader}* ` +
    `(${queueIndex}/${totalTracks})\n` +
    (hype ? `🎉 **Friday Top10 Hype${hype.encore ? ' · Encore' : ''}** · Opening chart #${hype.openingRank}${hype.openingRank === 1 && !hype.encore ? ' · 🏆 Opening-chart headliner!' : ''}\nLive votes can change the current chart; this play order is fixed.\n` : '') +
    (playlistShow ? `📻 **${playlistShow.title}** · Vote up OR down — help these songs find their place in the rotation.\n` : '') +
    (paid ? sponsorLine || '💸 **DJuke paid request**\n' : '') +
    `**All-time:** 👍 ${track.likes ?? 0} · 👎 ${track.dislikes ?? 0} · ▶️ ${track.plays ?? 0}\n` +
    `${idLine}\n` +
    `${votingLine}${listenLink}`
  );
}

export function parseNowPlayingMessage(content) {
  const match = content.match(/^🎵 Now playing: \*\*(.+?)\*\* by \*(.+?)\*/);
  if (!match) return null;
  const trackId = content.match(/Track(?: ID)?:? (?:\|\||`)(.+?)(?:\|\||`)/)?.[1] || null;
  const playId = content.match(/Play(?: ID)?:? (?:\|\||`)(.+?)(?:\|\||`)/)?.[1];
  return { title: match[1], uploader: match[2], trackId, ...(playId ? { playId } : {}) };
}

function reactionCount(message, emoji) {
  return [...message.reactions.cache.values()]
    .filter(entry => entry.emoji.name?.startsWith(emoji))

    .reduce((total, reaction) => total + Math.max(0, (reaction.count || 0) - (reaction.me ? 1 : 0)), 0);
}

export function synchronizeDiscordRating(message, botUserId, { change, emoji, now = Date.now(), store = { getPlaylist, applyRating } } = {}) {
  const playlist = store.getPlaylist();
  const parsed = message.author?.id === botUserId ? parseNowPlayingMessage(message.content || '') : null;
  const uploads = message.author?.bot ? [] : playlist.filter(entry => entry.messageId === message.id && entry.uploaderId === message.author?.id);
  const track = parsed?.trackId ? playlist.find(entry => entry.trackId === parsed.trackId)
    : uploads.length === 1 ? uploads[0] : null;
  if (!track) return null;
  const likes = reactionCount(message, '👍');
  const dislikes = reactionCount(message, '👎');
  const initialCounts = change ? {
    likes: Math.max(0, likes - (emoji === '👍' ? change : 0)),
    dislikes: Math.max(0, dislikes - (emoji === '👎' ? change : 0)),
  } : undefined;
  return store.applyRating(track.trackId, likes, dislikes, message.id, { initialCounts, now });
}

/** Recover announcements that were abandoned by a restart before normal collection. */
export async function reconcileJukeLoopHistory(textChannel, botUserId, maxMessages = 500) {
  const playlist = getPlaylist();
  const events = [];
  let before;
  let scanned = 0;

  while (scanned < maxMessages) {
    const limit = Math.min(100, maxMessages - scanned);
    const batch = await textChannel.messages.fetch({ limit, ...(before ? { before } : {}) }).catch(() => null);
    if (!batch?.size) break;
    for (const message of batch.values()) {
      if (message.author.id !== botUserId) continue;
      const parsed = parseNowPlayingMessage(message.content);
      if (!parsed) continue;

      let track = parsed.trackId ? playlist.find((entry) => entry.trackId === parsed.trackId) : null;
      if (!track) {
        const matches = playlist.filter((entry) => entry.title === parsed.title && entry.uploader === parsed.uploader);
        if (matches.length === 1) [track] = matches;
      }
      if (!track) continue;
      events.push({
        trackId: track.trackId,
        messageId: message.id,
        likes: reactionCount(message, '👍'),
        dislikes: reactionCount(message, '👎'),
        playId: parsed.playId,
        legacyTotals: !parsed.playId ? (() => {
          const totals = message.content.match(/\*\*All-time:\*\* 👍 (\d+) · 👎 (\d+) · ▶️ (\d+)/);
          return totals ? { likes: Number(totals[1]), dislikes: Number(totals[2]), plays: Number(totals[3]) } : undefined;
        })() : undefined,
      });
    }
    scanned += batch.size;
    before = batch.last()?.id;
    if (batch.size < limit) break;
  }

  return reconcileRatings(events);
}

// ── Per-guild session registry ────────────────────────────────────────────────

/** @type {Map<string, JukeLoopSession>} guildId → active session */
const _sessions = new Map();

/**
 * Return the active JukeLoopSession for a guild, or null.
 * @param {string} guildId
 * @returns {JukeLoopSession|null}
 */
export function getJukeLoopSession(guildId) {
  return _sessions.get(guildId) ?? null;
}

export async function submitJukeLoopVote({ playId, voterId, vote }, saveVote = applySiteVote,
  publicBroadcast = null) {
  if (typeof playId !== 'string' || playId.length > 160 ||
      typeof voterId !== 'string' || !/^[a-zA-Z0-9_-]{16,128}$/.test(voterId) ||

    (vote !== 1 && vote !== -1)) throw new Error('Invalid radio vote');
const sessions = [..._sessions.values()].filter(entry => !entry._destroyed);
const current = sessions.find(entry => entry._nowPlaying?.audible && entry._nowPlaying.playId === playId);
const recentProgram = publicBroadcast?.selected !== false &&
  publicBroadcast?.programHistory?.find(entry => entry.playId === playId && entry.live === false &&
    entry.isDevert === false && entry.trackId);
const session = current ? current : recentProgram ? sessions.find(entry => entry.websitePlayback) : null;
if (!session) throw new Error('This radio play has ended or is not audible yet');
session._siteVoteHistory ||= new Map();
let voters = session._siteVoteHistory.get(playId);
if (!voters) {
  voters = new Map();
  session._siteVoteHistory.set(playId, voters);
  while (session._siteVoteHistory.size > 24) {
    session._siteVoteHistory.delete(session._siteVoteHistory.keys().next().value);
  }
}
if (!current && (!Number.isFinite(recentProgram.at) ||
    Date.now() - recentProgram.at > 120000 || recentProgram.at > Date.now())) {
  throw new Error('This buffered radio play has ended');
}
const trackId = current ? session._nowPlaying.trackId : recentProgram.trackId;
const previous = voters.get(voterId);
if (previous !== undefined) return { playId, vote: previous, duplicate: true };
if (voters.size >= 5000) throw new Error('Voting capacity reached for this play');
let acceptedVote = vote;
let duplicate = false;
if (current && session._nowPlaying.isDevert) {
  if (!session.devertPlayback?.recordMainRadioAdVote || !session._currentDevertAd) throw new Error('DeVert ad voting is not configured');

    const result = await session.devertPlayback.recordMainRadioAdVote({ campaignId: session._currentDevertAd.campaignId,
      radioPlayId: playId, voterId, vote });
    duplicate = result?.duplicate === true;
    if (duplicate) acceptedVote = result.vote;
  } else saveVote(trackId, vote);
  voters.set(voterId, acceptedVote);
  return { playId, vote: acceptedVote, duplicate };
}

/** The track currently audible in any JukeLoop voice session, or null. */
export function getJukeLoopNowPlaying({ websiteOnly = false } = {}) {
  for (const session of _sessions.values()) {
    if (websiteOnly && !session.websitePlayback) continue;
    if (session._nowPlaying) return { ...session._nowPlaying };
  }
  return null;
}

/** The prepared next item in any JukeLoop voice session, or null. */
export function getJukeLoopUpNext() {
  for (const session of _sessions.values()) {
    const upNext = session.getUpNext();
    if (upNext) return upNext;
  }
  return null;
}

export function getActiveJukeLoopSession() {
  return _sessions.values().next().value ?? null;
}

export function updateJukeLoopRadioSchedule({ events, schedule }) {
  for (const session of _sessions.values()) {
    if (Array.isArray(events)) session.setLivePerformanceEvents(events);
    if (Array.isArray(schedule)) session.setSchedule(schedule);
  }
}

/**
 * Create (or replace) the JukeLoopSession for a guild.
 *
 * @param {string} guildId
 * @param {object} opts
 * @param {import('discord.js').VoiceBasedChannel}  opts.voiceChannel
 * @param {import('discord.js').TextBasedChannel}   opts.textChannel
 * @param {import('discord.js').Client}             opts.client
 * @returns {JukeLoopSession}
 */
export function createJukeLoopSession(guildId, opts) {
  const existing = _sessions.get(guildId);

  if (existing) existing.destroy();
  const session = new JukeLoopSession(opts);
  session._sessionKey = guildId;
  _sessions.set(guildId, session);
  return session;
}

// ── FFmpeg helper ─────────────────────────────────────────────────────────────

/**
 * Spawn FFmpeg to transcode an HTTP(S) audio URL to raw 16-bit LE PCM at
 * 48 kHz stereo — the format expected by @discordjs/voice's StreamType.Raw.
 *
 * @param {string} url
 * @returns {{ stream: import('stream').Readable, ffmpegProcess: import('child_process').ChildProcess }}
 */
export function createFFmpegStream(url, { ad = false } = {}) {
  const args = [
    '-nostdin', '-hide_banner', '-loglevel', 'warning', '-xerror',
    ...(/^https?:\/\//.test(url) ? [
    '-reconnect',           '1',
    '-reconnect_streamed',  '1',
    '-reconnect_delay_max', '5',
    ] : []),
    '-i',                   url,
    ...(ad ? ['-t', String(DEVERT_MAX_AD_SECONDS)] : []),
    '-analyzeduration',     '0',
    '-vn',
    // Ease each song in from silence so tracks never pop in at full volume.
    '-af', `afade=t=in:st=0:d=${FADE_IN_SECONDS}:curve=qsin`,
    '-f',  's16le',
    '-ar', '48000',
    '-ac', '2',
    'pipe:1',
  ];
  const ffmpegProcess = spawn(FFMPEG_BIN, args, { stdio: ['ignore', 'pipe', 'pipe'] });
  ffmpegProcess.on('error', (err) =>
    console.error('[jukeloop] FFmpeg spawn error:', err.message),
  );
  return { stream: ffmpegProcess.stdout, ffmpegProcess };
}

export function monitorAudioCompletion(input, process) {
  let decodedBytes = 0, sourceEnded = false, streamError = false, interrupted = null;
  let exitCode = process.exitCode ?? null, signal = process.signalCode ?? null;

let stderrBytes = 0;
const warnings = new Set();
let notifyExit;
const exited = new Promise(resolve => { notifyExit = resolve; });
const stream = new Transform({
  transform(chunk, encoding, callback) {
    decodedBytes += chunk.length;
    callback(null, chunk);
  },
});
const failed = () => { streamError = true; notifyExit(); };
input.on('error', error => { failed(); stream.destroy(error); });
stream.on('error', failed);
stream.once('close', () => { if (!input.destroyed) input.destroy(); });
stream.once('end', () => { sourceEnded = true; });
process.once?.('error', failed);
process.once?.('exit', (code, exitSignal) => {
  exitCode = code;
  signal = exitSignal;
  notifyExit();
});
// Keep only bounded categories, never media URLs, gateway tokens or raw stderr.
process.stderr?.on('data', chunk => {
  stderrBytes = Math.min(1_000_000, stderrBytes + chunk.length);
  const text = String(chunk).slice(0, 4096);
  if (/HTTP|connection|timed out|network/i.test(text)) warnings.add('network');
  if (/invalid|corrupt|truncat|error|failed/i.test(text)) warnings.add('decode');
  if (/timestamp|duration|estimating/i.test(text)) warnings.add('timing');
});
input.pipe(stream);
return {
  stream,
  interrupt(reason) { interrupted = reason; notifyExit(); },
  async finish(resource, timeoutMs = 1000) {
    let timer;
    if (sourceEnded && exitCode === null && !signal && !streamError && !interrupted) {
      try {
        await Promise.race([exited, new Promise(resolve => { timer = setTimeout(resolve, timeoutMs); })]);
      } finally { clearTimeout(timer); }
    }
    const decodedMs = decodedBytes / (48000 * 2 * 2) * 1000;
    const playedMs = resource.playbackDuration;

      const cappedAdvert = interrupted === 'advert_time_limit' && !streamError &&
        decodedMs >= DEVERT_MAX_AD_SECONDS * 1000 - 20 && playedMs >= DEVERT_MAX_AD_SECONDS * 1000 - 20;
      const reason = interrupted || (streamError ? 'audio_stream_error'
        : !sourceEnded ? 'audio_stream_incomplete'
          : signal ? 'decoder_signaled'
            : exitCode === null ? 'decoder_exit_timeout'
              : exitCode !== 0 ? 'decoder_failed'
                : decodedBytes === 0 ? 'no_decoded_audio'
                  : !(playedMs > 0) || playedMs + 20 < decodedMs ? 'decoded_audio_not_fully_played' : 'clean_eof');
      if (reason !== 'clean_eof') process.kill?.();
      return { finished: cappedAdvert || reason === 'clean_eof', reason, interrupted, pid: process.pid || null, exitCode, signal,
        sourceEnded, streamError, decodedBytes, decodedMs: Math.round(decodedMs),
        playedMs, stderrBytes, warnings: [...warnings] };
    },
  };
}

export function waitForAudioReady(stream, ffmpegProcess, timeoutMs = NEXT_TRACK_READY_TIMEOUT_MS) {
  if (stream.readableLength > 0) return Promise.resolve();
  return new Promise((resolve, reject) => {
    let timer;
    const cleanup = () => {
      clearTimeout(timer);
      stream.off('readable', ready);
      stream.off('error', failed);
      stream.off('end', ended);
      ffmpegProcess?.off?.('error', failed);
      ffmpegProcess?.off?.('exit', exited);
    };
    const ready = () => {
      if (stream.readableLength === 0) return;
      cleanup();
      resolve();
    };
    const failed = error => {
      cleanup();
      stream.destroy();
      ffmpegProcess?.kill?.();
      reject(error);
    };
    const ended = () => failed(new Error('FFmpeg ended before producing audio'));

    const exited = (code, signal) => {
      if (code !== 0 || signal) failed(new Error(`FFmpeg exited before audio was ready (${code ?? signal ?? 'unknown'})`));
    };
    stream.once('readable', ready);
    stream.once('error', failed);
    stream.once('end', ended);
    ffmpegProcess?.once?.('error', failed);
    ffmpegProcess?.once?.('exit', exited);
    timer = setTimeout(() => failed(new Error('Timed out preparing the next track')), timeoutMs);
    timer.unref?.();
  });
}

// ── JukeLoopSession ───────────────────────────────────────────────────────────

export class JukeLoopSession {
  /**
   * @param {object} opts
   * @param {import('discord.js').VoiceBasedChannel} opts.voiceChannel  - JukeLoop voice channel
   * @param {import('discord.js').TextBasedChannel}  opts.textChannel   - JukeLoop text channel
   * @param {import('discord.js').Client}            opts.client        - Discord client (for re-fetching CDN URLs)
    * @param {() => void} [opts.onTerminalDisconnect] - Called after Discord voice recovery fails
   */
    constructor({ voiceChannel, textChannel, client, ipfsGateway, onTerminalDisconnect, djuke, devertPlayback,
      schedule, livePerformanceEvents, audioPlayer, createStream, mainRadioAdStateStore, restoreMainRadioAdState, saveMainRadioAdState,
      topTenHype, topTenHypeStore, playlistShow, playlistShowStore, isContentAllowed = () => true,
      audioReadyTimeoutMs = NEXT_TRACK_READY_TIMEOUT_MS, websitePlayback = false, durationBackfill, publicBroadcast }) {
    this.websitePlayback = websitePlayback;
    this.publicBroadcast = publicBroadcast;
    this.isContentAllowed = isContentAllowed;

this._discordOutputsAttached = false;
this._discordOutputsBlocked = false;
this.voiceChannel = voiceChannel;
this.textChannel  = textChannel;
this.client       = client;
this.ipfsGateway  = ipfsGateway;
this.onTerminalDisconnect = onTerminalDisconnect;
this._audioReadyTimeoutMs = audioReadyTimeoutMs;
this._playbackIdleSince = null;
this.djuke        = djuke || null;
this.devertPlayback = devertPlayback || null;
this._topTenHype = topTenHype || createTopTenHype({ store: topTenHypeStore });
this._hypeNotice = null;
this._playlistShow = playlistShow || createPlaylistShow({ store: playlistShowStore });
this._durationBackfill = durationBackfill || createDurationBackfill({
  getTracks: getPlaylist, resolveUrl: track => this._getFreshUrl(track), save: updateTrackDuration,
});
this._currentLongFormSelection = null;
this._longFormCompletionTask = null;
this._pendingLongFormCompletion = null;
this._mainRadioAdStateStore = mainRadioAdStateStore || null;
this._restoreMainRadioAdState = restoreMainRadioAdState || this._mainRadioAdStateStore?.restore || null;
this._saveMainRadioAdState = saveMainRadioAdState || this._mainRadioAdStateStore?.save || null;
this._mainRadioAdStateReady = !this._restoreMainRadioAdState;
this._mainRadioAdStateLoadTask = null;
this._mainRadioAdStateSaveTask = Promise.resolve();
this._musicSinceAd = 0;
this._musicPlayCount = 0;
this._currentDevertAd = null;
this._adCutoffTimer = null;
this._preparedDevertAd = null;
this._pendingDevertAds = [];
this._failedDevertCampaigns = new Map();
this._lastMainRadioAdSkip = null;
this.schedule     = Array.isArray(schedule) ? schedule : defaultRadioSchedule();

this.livePerformanceEvents = Array.isArray(livePerformanceEvents) ? livePerformanceEvents : [];
this._liveEventId = null;
this._unbookedLiveOccurrenceId = null;
this._unbookedLiveFallbackTask = null;
this._activeShowKey = null;
this._scheduleWatcher = null;
this._started = false;
this._currentPaid = null;
this._djukeCooldownUntil = 0;
this._paidFetchNotices = new Set();
this._mediaAbort = new AbortController();
this._createStream = createStream || (async (url, options) => {
  if (!options.playlist) return createFFmpegStream(url, options);
  const media = await bufferRadioMedia(url, { signal: this._mediaAbort.signal });
  if (this._destroyed) {
    await media.dispose();
    throw new Error('Radio stopped during media download');
  }
  const source = createFFmpegStream(media.path, options);
  const cleanup = () => media.dispose()
    .catch(error => console.error('[jukeloop] Paid media cleanup failed:', error.message));
  source.ffmpegProcess.once('close', cleanup);
  return source;
});

this._destroyed   = false;
this._ffmpeg      = null;
this._activeAudio = null;
this._endingAudio = null;
this._audioCompletionTask = null;
this._preparedNext = null;
this._priorityMintTrack = null;
this._prepareTask = null;
this._paidPollTimer = null;
this._primeRetryTimer = null;
this._primeRetryMs = 0;
this._transitionTask = null;
this._preparationEpoch = 0;
/** Earliest time the next item may start, and the item waiting out that changeover gap. */
this._changeoverAt = 0;
this._changeoverPrepared = null;
this._changeoverGapIndex = 0;
this._changeoverGapPlaying = false;

/** True while the queued advert break was picked early and still needs the current song to count. */
this._breakAwaitingUnlock = false;
this.connection   = null;
this._voiceConnection = null;
this.player       = audioPlayer || createAudioPlayer(websitePlayback
  ? { behaviors: { noSubscriber: NoSubscriberBehavior.Play } }
  : {});

/** Shuffled queue for the current loop pass */
this._queue      = [];
this._queueIndex = 0;

/** The "Now Playing" announcement message for the track *currently* playing */
this._announcementMsg = null;
this._announcementContext = null;
/** The track entry currently playing (so we can store ratings when it ends) */
this._currentTrack    = null;
this._completedPlay   = null;
/** Audible track and start time, published to the DecentBusking site. */
this._nowPlaying      = null;

this.player.on('stateChange', (oldState, newState) => {
  if (
    newState.status === AudioPlayerStatus.Playing &&
    this._nowPlaying && !this._nowPlaying.audible
  ) {
    this._nowPlaying.startedAt = Date.now();
    this._nowPlaying.audible = true;
    if (this.websitePlayback && this._currentTrack?.liveRecording) {
      void startLiveRecordingReplay(this._currentTrack.trackId, { ...this._nowPlaying })
        .catch(error => console.warn('[live-recording] Radio start checkpoint deferred:', error.message));
    }
    if (this._currentDevertAd) {
      const playId = this._nowPlaying.playId;
      this._adCutoffTimer = setTimeout(() => this._finishAdvertAtLimit(playId), DEVERT_MAX_AD_SECONDS * 1000);
      this._adCutoffTimer.unref?.();
    }
    this._primeNext();
  }
});

this.player.on(AudioPlayerStatus.Idle, oldState => {
  clearTimeout(this._adCutoffTimer);
  this._adCutoffTimer = null;
  if (this._changeoverGapPlaying) {
    this._changeoverGapPlaying = false;
    if (!this._destroyed) {
      this._playNext().catch(error =>
        console.error('[jukeloop] Unhandled error in _playNext:', error),
      );
    }
    return;
  }
  if (this._nowPlaying?.audible) {
    const audio = this._activeAudio;
    if (audio && oldState?.resource && oldState.resource !== audio.resource) {
      audio.completion.interrupt('audio_resource_mismatch');
    }
    this._activeAudio = null;
    this._endingAudio = audio;
    this._audioCompletionTask = audio?.completion.finish(audio.resource) || null;
    const endedAt = Date.now();
    this._changeoverAt = endedAt + (this._currentPaid?.playlistBatchId !== undefined ? 0 : CHANGEOVER_GAP_MS);
    this._completedPlay = {
      playId: this._nowPlaying.playId,
      trackId: this._nowPlaying.trackId,
      startedAt: this._nowPlaying.startedAt,
      endedAt,
      audibleMs: Math.max(0, endedAt - this._nowPlaying.startedAt),
      finished: false,
      completion: this._audioCompletionTask,
      countAdOnCompletion: !!this._currentDevertAd?.paidRequest && this._currentPaid?.tier === 0 && !!this._audioCompletionTask,
      firstWeekBonus: this._nowPlaying.firstWeekBonus,
      announcementId: this._announcementMsg?.id,
    };
    Object.assign(this._completedPlay, radioCompletionDiagnostics(
      this._completedPlay.audibleMs, this._nowPlaying.expectedMs));
    if (this._currentDevertAd && (!this._currentDevertAd.paidRequest ||

    (this._currentPaid?.tier === 0 && this._completedPlay.finished))) {
  this._musicSinceAd = 0;
  this._musicPlayCount++;
  this._persistMainRadioAdState();
} else if (!this._currentDevertAd && this._completedPlay.audibleMs >= 30_000) {
  this._musicSinceAd++;
  this._musicPlayCount++;
  this._persistMainRadioAdState();
}
if (this.devertPlayback && this._currentPaid?.kind !== 'devert') {
  const durableRecord = this._currentDevertAd?.competitionReward
    ? this.devertPlayback.recordCompetitionAdvertPlay({ campaignId: this._currentDevertAd.campaignId,
        competitionReward: this._currentDevertAd.competitionReward, startedAt: this._completedPlay.startedAt,
        radioPlayId: this._nowPlaying.playId, mainRadio: this._currentDevertAd.mainRadio,
        audibleMs: this._completedPlay.audibleMs, expectedMs: this._completedPlay.expectedMs })
    : this._currentDevertAd ? this.devertPlayback.recordCampaignImpression({ campaignId: this._currentDevertAd.campaignId,
        radioPlayId: this._nowPlaying.playId, mainRadio: this._currentDevertAd.mainRadio,
        audibleMs: this._completedPlay.audibleMs, expectedMs: this._completedPlay.expectedMs })
    : this.devertPlayback.recordCompletedMusicPlay({ playId: this._nowPlaying.playId,
        audibleMs: this._completedPlay.audibleMs });
  Promise.resolve(durableRecord)
    .catch(error => console.warn('[devert] Durable play record deferred:', error.message));
} else if (this.devertPlayback?.recordPaidAdvertPlay && this._currentDevertAd) {

      Promise.resolve(this.devertPlayback.recordPaidAdvertPlay({ campaignId: this._currentDevertAd.campaignId,
        radioPlayId: this._nowPlaying.playId, audibleMs: this._completedPlay.audibleMs,
        expectedMs: this._completedPlay.expectedMs }))
        .catch(error => console.warn('[devert] Paid advert play tally deferred:', error.message));
    }
  }
  const hadPaid = !!this._currentPaid;
  const bookkeeping = this._collectReactions()
    .catch(error => console.warn('[jukeloop] Previous-track bookkeeping deferred:', error.message))
    .finally(() => { if (this._paidBookkeepingTask === bookkeeping) this._paidBookkeepingTask = null; });
  if (hadPaid) this._paidBookkeepingTask = bookkeeping;
  const gapAllowed = !this._currentDevertAd &&
    (!hadPaid || this._currentPaid?.playlistBatchId === undefined);
  this._currentDevertAd = null;
  this._nowPlaying = null;
  const activeShow = this._resolveShow();
  if (!this._destroyed && activeShow.type !== 'live_performance') {
    if (!gapAllowed || !this._startChangeoverGap()) {
      this._playNext().catch((err) =>
        console.error('[jukeloop] Unhandled error in _playNext:', err),
      );
    }
  }
});

this.player.on('error', (err) => {
  clearTimeout(this._adCutoffTimer);
  this._adCutoffTimer = null;
  console.error('[jukeloop] Audio player error:', err.message);
  const paidAdvert = this._currentPaid?.kind === 'devert';
  if (this._nowPlaying?.playlistShow && !this._nowPlaying.playlistShow.fallback && !this._nowPlaying.isDevert) {
    this._playlistShow.recordSkip({ ...this._nowPlaying.playlistShow, trackId: this._nowPlaying.trackId }, `Audio playback failed: ${err.message}`)

        .catch(error => console.warn('[playlist-show] Failure checkpoint unavailable:', error.message));
    }
    if (this._nowPlaying?.hype) {
      this._topTenHype.recordFailure(this._nowPlaying.trackId, `Audio playback failed: ${err.message}`)
        .catch(error => console.error('[top10-hype] Failed to checkpoint audio failure:', error.message));
    }
    if (this._currentDevertAd) {
      if (!paidAdvert) this._recordMainRadioAdFailure(this._currentDevertAd.campaignId, 'audio player error');
      this._currentDevertAd = null;
      this._nowPlaying = null;
      this._completedPlay = null;
      this._currentTrack = null;
      this._announcementMsg = null;
      this._announcementContext = null;
    }
    if (!paidAdvert) {
      this._pendingDevertAds = [];
      this._preparedDevertAd = null;
      this._persistMainRadioAdState();
    }
    if (this._ffmpeg) {
      try { this._ffmpeg.kill(); } catch {}
      this._ffmpeg = null;
    }
    if (!this._destroyed) {
      this._collectReactions().catch(() => {});
      this._nowPlaying = null;
      this._playNext().catch(() => {});
    }
  });
}

// ── Connection ──────────────────────────────────────────────────────────────

/** Join the JukeLoop voice channel and subscribe the audio player to it. */
async connect() {
  this._voiceConnection = createVoiceConnectionSupervisor({
    name: 'jukeloop',
    voiceChannel: this.voiceChannel,
    player: this.player,
    joinVoiceChannel,
    entersState,
    VoiceConnectionStatus,
    subscribe: connection => connection.subscribe(this.player),

    onReady: async connection => { this.connection = connection; },
    log: console,
  });
  await this._voiceConnection.connect();
  this.connection = this._voiceConnection.connection;
}

// ── Playback ────────────────────────────────────────────────────────────────

/** Begin the infinite JukeLoop. */
async start() {
  if (this._destroyed) return;
  this._started = true;
  await this._ensureMainRadioAdState();
  this._syncScheduledShow({ requestPlayback: false });
  this._scheduleWatcher = setInterval(() => {
    this._syncScheduledShow();
    this._checkPlaybackHealth();
    this._durationBackfill.run().catch(error => console.error('[radio-duration] Backfill unavailable:', error.message));
  }, 1_000);
  this._scheduleWatcher.unref?.();
  this._refreshQueue();
  await this._playNext();
}

getPlaybackStatus(now = Date.now()) {
  const show = this.getShowState().activeShow;
  if (show.type === 'live_performance') return { status: 'paused', ready: false, reason: show.label || 'Live performance' };
  if (show.type === 'live_audio_ads' && !this._nowPlaying?.audible) {
    return { status: 'paused', ready: false, reason: `${show.label}: waiting for an eligible advert; no delivery is being claimed` };
  }
  const voice = this._voiceConnection?.getState();
  if (this._destroyed || (!this.websitePlayback && voice?.voiceConnected === false)) {
    return { status: 'recovering', ready: false, reason: 'Radio voice connection is recovering' };
  }
  if (this._nowPlaying?.audible && this.player.state.status === AudioPlayerStatus.Playing) {

    return { status: 'playing', ready: true, reason: null };
  }
  const idleMs = this._playbackIdleSince === null ? 0 : Math.max(0, now - this._playbackIdleSince);
  if (show.type === 'normal_rotation' && this.djuke?.hasPendingPlaylist?.()) {
    return { status: idleMs >= PLAYBACK_RECOVERY_TIMEOUT_MS ? 'recovering' : 'preparing', ready: false, idleMs,
      reason: this._playlistRetryReason || 'Preparing the next paid playlist song; your existing payment stays queued' };
  }
  if (!this._queue.length && !this._prepareTask && !this._transitionTask && !this._preparedNext &&
      !this._nowPlaying && !this._currentPaid && !this._currentDevertAd) {
    return { status: 'empty', ready: false, reason: 'No playable recordings are available' };
  }
  return { status: idleMs >= PLAYBACK_RECOVERY_TIMEOUT_MS ? 'recovering' : 'preparing',
    ready: false, reason: 'Radio is preparing the next recording', idleMs };
}

_checkPlaybackHealth(now = Date.now()) {
  if (this._destroyed || !this._started) return;
  const playback = this.getPlaybackStatus(now);
  if (playback.ready || playback.status === 'paused' || playback.status === 'empty') {
    this._playbackIdleSince = null;
    return;
  }
  this._playbackIdleSince ??= now;
  if (now - this._playbackIdleSince < PLAYBACK_RECOVERY_TIMEOUT_MS) return;
  console.error(`[jukeloop] Playback stalled for ${PLAYBACK_RECOVERY_TIMEOUT_MS / 1000}s; restarting the radio session.`);
  this.destroy();
  Promise.resolve(this.onTerminalDisconnect?.())
    .catch(error => console.error('[jukeloop] Playback recovery failed:', error.message));
}

_sendPlaybackNotice(content) {
  if (!this.textChannel || this.client?.isReady?.() === false) return;

  this.textChannel.send({ content, flags: MessageFlags.SuppressNotifications, allowedMentions: { parse: [] } })
    .catch(error => this._reportDiscordOutputFailure(error));
}

_reportDiscordOutputFailure(error) {
  if (error.status === 403 || [50001, 50013].includes(error.code)) {
    this._discordOutputsBlocked = true;
    this._discordOutputsAttached = false;
    this.textChannel = null;
    console.error('[jukeloop] Discord text output paused: missing access/permissions. Website broadcast continues; fix permissions and restart JukeLoop.');
  } else {
    console.warn('[jukeloop] Discord text delivery failed; inspect Discord REST diagnostics.');
  }
}

setLivePerformanceEvents(events) {
  this.livePerformanceEvents = Array.isArray(events) ? events : [];
  this._syncScheduledShow();
}

setLiveAudioPolicy(policy) {
  const previous = this.liveAudioPolicy;
  const previousShow = this._resolveShow();
  const key = policy ? `${policy.bookingId}:${policy.mode}` : '';
  this.liveAudioPolicy = policy;
  if (key === this._liveAudioPolicyKey) return;
  this._liveAudioPolicyKey = key;
  const nextShow = this._resolveShow();
  if (policy?.controlled && previousShow.type === nextShow.type && previousShow.id === nextShow.id &&
      nextShow.type !== 'live_performance') {
    this._syncScheduledShow();
    return;
  }
  if (previousShow.event?.id && previousShow.event.id === nextShow.event?.id &&
      previousShow.event.id !== policy?.eventId) {
    this._syncScheduledShow();
    return;
  }
  if (previous?.mode === 'radio' && !policy && previousShow.type === 'normal_rotation' &&
      this._resolveShow().type === 'normal_rotation') return;
  this._preparationEpoch++;

  this._disposePrepared(this._preparedNext, 'Live audio policy changed');
  this._preparedNext = null;
  this._activeAudio?.completion.interrupt('scheduled_handoff');
  if (this.player.state.status !== AudioPlayerStatus.Idle) this.player.stop(true);
  if (policy?.mode === 'fault') this._sendPlaybackNotice(`📴 ${policy.reason}`);
  if (policy?.mode === 'adverts') {
    this._musicSinceAd = Math.max(this._musicSinceAd, DEVERT_SONGS_PER_MAIN_AD);
    this._breakAwaitingUnlock = false;
  }
  this._syncScheduledShow({ requestPlayback: false });
  if (this._started && !['live', 'fault'].includes(policy?.mode)) {
    void this._playNext().catch(error => console.warn('[live-audio] Radio handoff deferred:', error.message));
  }
}

_resolveShow(now = Date.now()) {
  return applyLiveAudioShow(resolveActiveShow({ now, schedule: this.schedule,
    livePerformanceEvents: this.livePerformanceEvents }), this.liveAudioPolicy);
}

setSchedule(schedule) {
  this.schedule = Array.isArray(schedule) ? schedule : defaultRadioSchedule();
  this._syncScheduledShow();
}

queueMintedNext(track) {
  if (!track || track.mintStatus !== 'minted' || !track.ipfsCid || this._destroyed ||
      this._currentTrack?.trackId === track.trackId) return false;
  const show = this._resolveShow();
  if (show.type !== 'normal_rotation' || this._priorityMintTrack?.trackId === track.trackId ||
      this._preparedNext?.track?.trackId === track.trackId) return false;
  this._priorityMintTrack = track;
  const prepared = this._preparedNext;
  if (prepared && !prepared.paid && !prepared.devertAd && !prepared.hype &&
      !prepared.playlistShow && !prepared.liveReplay) {
    this._preparedNext = null;

    this._disposePrepared(prepared, 'Freshly minted song takes the next ordinary music slot');
    this._preparationEpoch++;
  } else if (!prepared && this._prepareTask) {
    this._preparationEpoch++;
    this._prepareTask.finally(() => {
      if (this._priorityMintTrack && !this._destroyed &&
          this.player.state.status === AudioPlayerStatus.Playing) this._primeNext();
    });
  }
  if (this.player.state.status === AudioPlayerStatus.Playing) this._primeNext();
  else if (this._started && this.player.state.status === AudioPlayerStatus.Idle) {
    void this._playNext().catch(error => console.warn('[jukeloop] Fresh mint playback deferred:', error.message));
  }
  return true;
}

_syncScheduledShow({ requestPlayback = true } = {}) {
  if (this._destroyed) return;
  const show = this._resolveShow();
  const event = show.type === 'live_performance' ? show.event : null;
  const eventId = event?.id || null;
  const previousEventId = this._liveEventId;
  const showKey = `${show.type}:${show.id || ''}${show.unbookedLiveOccurrenceId ? `:${show.unbookedLiveOccurrenceId}` : ''}`;

  if (eventId !== previousEventId) {
    this._liveEventId = eventId;
    if (event) {
      if (this.player.state.status !== AudioPlayerStatus.Idle) {
        this._activeAudio?.completion.interrupt('scheduled_handoff');
        this.player.stop(true);
      }
      if (this.liveAudioPolicy?.mode !== 'fault' ||
          event.id !== `${this.liveAudioPolicy.eventId || this.liveAudioPolicy.bookingId}:fault`) {
        this._sendPlaybackNotice(`🔴 **Live performance block: ${event.title}** starts now.`);
      }
    } else if (previousEventId && !this.liveAudioPolicy?.cancelledAt) {

    this._sendPlaybackNotice('📻 **Live performance block ended.** JukeLoop is resuming.');
  }
}

if (showKey !== this._activeShowKey) {
  this._preparationEpoch++;
  this._disposePrepared(this._preparedNext, 'Scheduled radio mode changed');
  this._preparedNext = null;
  const previousShowKey = this._activeShowKey;
  this._activeShowKey = showKey;
  if (show.type === 'normal_rotation' && show.cancelledOccurrenceId) {
    this._musicSinceAd = Math.max(this._musicSinceAd, DEVERT_SONGS_PER_MAIN_AD);
  }
  if (previousShowKey === 'weekly_top10:friday-top10-hype' && show.id !== 'friday-top10-hype') {
    if (show.type === 'normal_rotation') this._musicSinceAd = Math.max(this._musicSinceAd, DEVERT_SONGS_PER_MAIN_AD);
    this._sendPlaybackNotice('🎉 **Friday Top 10 hype hour has ended at the scheduled handoff.** Any remaining opening-chart songs will not overrun the next show.');
  }
  if (show.type === 'playlist_show') {
    this._playlistShow.ensure(show, getPlaylist()).catch(error => console.warn('[playlist-show]', error.message));
    this._sendPlaybackNotice(`📻 **${show.label}** · Vote up OR down! The opening pool is shuffled; voted songs are dropped before their turn.`);
  }
  if (show.instanceId && show.id === 'friday-top10-hype') {
    this._ensureTopTenHype(show).catch(error => console.error('[top10-hype] Opening chart blocked:', error.message));
  }
  if (show.type === 'weekly_top10' && !previousShowKey?.startsWith('weekly_top10:')) {
    const message = show.window === 'final-payroll-hour'
      ? `📊 **${show.label}** is live. Vote through the New York payroll cutoff at midnight for this week's chart: ${buildSiteVotingLink()}`

        : `📊 **${show.label}** is live. Vote for songs on the site: ${buildSiteVotingLink()}`;
      this._sendPlaybackNotice(message);
    } else if (previousShowKey?.startsWith('weekly_top10:') && previousShowKey !== 'weekly_top10:friday-top10-hype' && show.type === 'normal_rotation') {
      const finalListenEnded = previousShowKey === 'weekly_top10:weekly-top10-final-listen';
      const message = finalListenEnded
        ? '📊 The weekly Top 10 final listen has ended at the payroll cutoff. Normal rotation resumes.'
        : '📊 The Top 10 hype hour has ended. Normal rotation resumes.';
      this._sendPlaybackNotice(message);
    }
    const enteringOrLeavingTopTen = previousShowKey &&
      (previousShowKey.startsWith('weekly_top10:') || show.type === 'weekly_top10');
    if (this._started && enteringOrLeavingTopTen && !this._currentLongFormSelection &&
        this.player.state.status !== AudioPlayerStatus.Idle) {
      this._activeAudio?.completion.interrupt('scheduled_handoff');
      this.player.stop(true);
    }
    if (this._started && show.type !== 'live_performance') this._refreshQueue();
    if (requestPlayback && !previousEventId && this._started && show.id === 'friday-top10-hype' &&
      this.player.state.status === AudioPlayerStatus.Idle) {
      this._playNext().catch(error => console.error('[jukeloop] Scheduled playback blocked:', error.message));
    }
  }

  if (!event && previousEventId && requestPlayback && this._started) {
    this._playNext().catch(error => console.error('[jukeloop] Could not resume after live event:', error.message));
  }
}

/** (Re)build the active queue for the current show slot. */
_refreshQueue() {
  const activeShow = this._resolveShow();

  if (activeShow.type === 'weekly_top10') {
    if (activeShow.instanceId && activeShow.id === 'friday-top10-hype') {
      this._queue = [];
      this._queueIndex = 0;
      return;
    }
    const weeklyReport = getWeeklyPlayHistory({ weeks: 1, calendar: 'new-york' }).find(report => report.current);
    const topTenPool = rankWeeklyTopTenTracks(getPlaylist(), weeklyReport);
    this._queue = topTenPool.length > 0 ? topTenPool : getWeightedShuffledPlaylist();
  } else if (activeShow.type === 'live_performance') {
    this._queue = [];
  } else {
    this._queue = getWeightedShuffledPlaylist();
  }

  this._queue = this._queue.filter(track => !recordingDurationReason(track));
  this._queueIndex = 0;
}

_durationAdmissionReason(track, { longForm = false } = {}) {
  const current = getPlaylist().find(entry => entry.trackId === track?.trackId) || track;
  if (recordingMediaIdentity(current) !== recordingMediaIdentity(track)) return 'Recording media changed after preparation';
  const reason = recordingDurationReason(current, { longForm });
  if (reason) return reason;
  if (longForm) {
    const start = nextProtectedLiveStart({ schedule: this.schedule, livePerformanceEvents: this.livePerformanceEvents });
    if (start !== null && Date.now() + verifiedRecordingDuration(current) * 1000 + CHANGEOVER_GAP_MS > start) {
      return 'Full recording will not fit before the next protected live event';
    }
  }
  return null;
}

_ensureTopTenHype(show) {
  return this._topTenHype.ensure({ show, playlist: getPlaylist(),
    report: getWeeklyPlayHistory({ weeks: 1, calendar: 'new-york' }).find(report => report.current) });
}

getShowState(now = Date.now()) {
  const activeShow = this._resolveShow(now);

  return { activeShow, topTenHype: this._topTenHype.publicState(activeShow), playlistShow: this._playlistShow.publicState(activeShow) };
}

async _skipHype(selection, reason, options) {
  await this._topTenHype.advance(selection, reason);
  this._sendPlaybackNotice(`⚠️ Friday Top10 opening #${selection.openingRank}: **${selection.title}** skipped — ${reason}`);
  return this._prepareNextPlayback(null, { ...options, hypeAttempts: (options.hypeAttempts || 0) + 1 });
}

/**
 * Fetch a fresh (non-expired) attachment URL for a track entry.
 * Returns null if the message or attachment can no longer be found.
 *
 * @param {import('./playlist-store.js').TrackEntry} track
 * @returns {Promise<string|null>}
 */
async _getFreshUrl(track) {
  if (track.ipfsCid) {
    const ipfsUrl = await resolveStreamableIpfsUrl(this.ipfsGateway, track.ipfsCid);
    if (ipfsUrl) return ipfsUrl;
    console.warn(`[jukeloop] No IPFS gateway could stream "${track.title}"; using the Discord upload.`);
  }
  if (!track.channelId || !track.messageId || this.client?.isReady?.() === false) return null;

  try {
    const channel = await this.client.channels.fetch(track.channelId).catch(() => null);
    if (!channel) return null;
    const msg = await channel.messages.fetch(track.messageId).catch(() => null);
    if (!msg) return null;
    const attachment = msg.attachments.get(track.attachmentId)
      ?? msg.attachments.find((a) => a.name === track.filename);
    return attachment?.url ?? null;
  } catch {
    return null;
  }
}

async _ensureUnbookedLiveFallback(show) {
  if (this._unbookedLiveFallbackTask) return this._unbookedLiveFallbackTask;
  const occurrenceId = show.unbookedLiveOccurrenceId;

if (!occurrenceId || this._unbookedLiveOccurrenceId === occurrenceId) return false;
this._unbookedLiveOccurrenceId = occurrenceId;
this._unbookedLiveFallbackTask = (async () => {
  const existing = [this._preparedDevertAd, ...this._pendingDevertAds].filter(Boolean);
  const excluded = new Set([
    ...this._getActiveFailedDevertCampaignIds(),
    ...existing.map(ad => String(ad.campaignId)),
    ...(this._currentDevertAd ? [String(this._currentDevertAd.campaignId)] : []),
  ]);
  let selected = [];
  if (this.devertPlayback && existing.length < 4) {
    let selectionTimer;
    try {
      const ads = await Promise.race([
        this.devertPlayback.nextMainRadioAd({ excludeCampaignIds: [...excluded], count: 4 - existing.length }),
        new Promise((_, reject) => {
          selectionTimer = setTimeout(() => reject(new Error('Unbooked live-slot ad selection timed out')), 10000);
        }),
      ]);
      selected = Array.isArray(ads) ? ads : ads ? [ads] : [];
    } catch (error) {
      console.warn('[jukeloop] Unbooked live-slot adverts unavailable; resuming radio:', error.message);
      this._setMainRadioAdSkip('unbooked live-slot ad selection unavailable', null);
    } finally {
      clearTimeout(selectionTimer);
    }
  }
  if (this._destroyed) return false;
  const seen = new Set(this._currentDevertAd ? [String(this._currentDevertAd.campaignId)] : []);
  const ads = [...existing, ...selected].filter(ad => {
    const id = String(ad.campaignId);
    if (seen.has(id) || this.devertPlayback?.isCampaignRemoved?.(id)) return false;
    seen.add(id);
    return true;
  }).slice(0, 4);

    [this._preparedDevertAd, ...this._pendingDevertAds] = ads;
    this._preparedDevertAd ||= null;
    this._breakAwaitingUnlock = false;
    this._musicSinceAd = 0;
    await this._persistMainRadioAdState();
    this._sendPlaybackNotice(`📻 **No live performance is booked.** ${ads.length ? `Playing ${ads.length} available advert${ads.length === 1 ? '' : 's'} once, then returning to music.` : 'No adverts are available; returning directly to music.'}`);
    return true;
  })().finally(() => { this._unbookedLiveFallbackTask = null; });
  return this._unbookedLiveFallbackTask;
}

/**
 * @param {object|null} [forcedPaid]
 * @param {{ projectedMusicSinceAd?: number|null, allowAds?: boolean }} [options]
 *   projectedMusicSinceAd selects a due advert while the song that unlocks it is still playing;
 *   allowAds=false prepares music only and leaves any selected advert queued.
 */
async _prepareNextPlayback(forcedPaid = null, options = {}) {
  const { projectedMusicSinceAd = null } = options;
  const playlistOwnsRadio = this.djuke?.hasActivePlaylist?.() === true;
  const allowAds = options.allowAds !== false && !playlistOwnsRadio;
  if (this._destroyed || this._broadcastHandoff) return null;
  await this._ensureMainRadioAdState();
  this._pendingDevertAds = this._pendingDevertAds.filter(ad => !this.devertPlayback?.isCampaignRemoved?.(ad.campaignId));
  if (this._preparedDevertAd && this.devertPlayback?.isCampaignRemoved?.(this._preparedDevertAd.campaignId)) {
    this._preparedDevertAd = null;
  }
  const activeShow = this._resolveShow();
  if (activeShow.type === 'live_performance') return;
  const cancellationAds = activeShow.type === 'live_audio_ads';

if (cancellationAds && forcedPaid?.record.kind !== 'devert' && forcedPaid) {
  await this.djuke.release(forcedPaid.record, new Error('DJuke songs deferred during live cancellation recovery'));
  forcedPaid = null;
}
const initializedLiveFallback = allowAds ? await this._ensureUnbookedLiveFallback(activeShow) : false;
const fallbackBreak = !!activeShow.unbookedLiveOccurrenceId &&
  !!(this._preparedDevertAd || this._pendingDevertAds.length);
if (fallbackBreak && forcedPaid && this.djuke) {
  await this.djuke.release(forcedPaid.record, new Error('Unbooked live-slot advert break takes priority'));
  forcedPaid = null;
}
if (activeShow.type === 'playlist_show' && forcedPaid && this.djuke) {
  await this.djuke.release(forcedPaid.record, new Error('Paid request deferred during playlist show'));
  forcedPaid = null;
}
const isHype = !!activeShow.instanceId && activeShow.id === 'friday-top10-hype';
let hypeSelection = null;
if (isHype) {
  await this._ensureTopTenHype(activeShow);
  const state = this._topTenHype.publicState(activeShow);
  if (!state.tracks.length || (options.hypeAttempts || 0) >= state.tracks.length) {
    const notice = !state.tracks.length ? 'The opening Top10 chart is empty. No countdown is available; waiting until the scheduled handoff.'
      : 'No opening-chart recording could be played. The countdown will retry; skipped places are shown in the live panel.';
    if (this._hypeNotice !== notice) {
      this._hypeNotice = notice;
      this._sendPlaybackNotice(`📊 ${notice}`);
    }
    return null;
  }
  hypeSelection = this._topTenHype.next(getPlaylist());

  if (!hypeSelection.track) return this._skipHype(hypeSelection, 'Recording is no longer eligible or available.', options);
}

const musicSinceAd = cancellationAds ? DEVERT_SONGS_PER_MAIN_AD : initializedLiveFallback ? 0 : Number.isFinite(projectedMusicSinceAd) ? projectedMusicSinceAd : this._musicSinceAd;
const normalSlotDue = allowAds && (musicSinceAd >= DEVERT_SONGS_PER_MAIN_AD ||
  (!!(this._preparedDevertAd || this._pendingDevertAds.length) && !this._breakAwaitingUnlock));
// Only immediate adverts and DJuke songs buy an extra break between ordinary slots.
let paid = isHype || activeShow.type === 'playlist_show' ? null : forcedPaid;
if (!paid && !fallbackBreak && this.djuke && ((!this._deploymentDraining() && !(this._broadcastRequestedUntil > Date.now())) || playlistOwnsRadio) &&
    activeShow.type !== 'playlist_show' && activeShow.type !== 'weekly_top10' && Date.now() >= this._djukeCooldownUntil) {
  paid = await this.djuke.nextPaid({ allowBump: normalSlotDue,
    ...(cancellationAds ? { includeSongs: false } : {}),
    ...(normalSlotDue ? { includeVideos: false } : {}) });
  if (paid && !this._paidStartAllowed(paid.record)) {
    await this.djuke.release(paid.record, new Error('Deployment drain holds new paid starts'));
    paid = null;
  }
  if (this._destroyed && paid) {
    await this.djuke.release(paid.record, new Error('Radio stopped')).catch(() => {});
    return null;
  }
}

let devertAd = paid?.record.kind === 'devert'
  ? { campaignId: paid.track.campaignId, mainRadio: paid.record.tier === 0, paidRequest: true, track: paid.track } : null;
let selectionDeferred = false;

if (devertAd?.mainRadio && !this._preparedDevertAd && !this._pendingDevertAds.length && this.devertPlayback) {
  // Reserve the normal break so the bump replaces its first slot, not an additional break.
  const ads = await this.devertPlayback.nextMainRadioAd({
    excludeCampaignIds: this._getActiveFailedDevertCampaignIds(), count: 2,
  }).catch(error => {
    console.warn('[devert] Ordinary break companions deferred:', error.message);
    return [];
  });
  const selectedAds = Array.isArray(ads) ? ads : ads ? [ads] : [];
  [this._preparedDevertAd, ...this._pendingDevertAds] = selectedAds;
  this._preparedDevertAd ||= null;
  this._breakAwaitingUnlock = !cancellationAds && this._musicSinceAd < DEVERT_SONGS_PER_MAIN_AD;
  await this._persistMainRadioAdState();
}
if (!allowAds || isHype) {
  // Music only: keep any selected advert queued for its real slot.
} else if (!paid && this._preparedDevertAd) {
  devertAd = this._preparedDevertAd;
} else if (!paid && this._pendingDevertAds.length) {
  this._preparedDevertAd = this._pendingDevertAds.shift();
  devertAd = this._preparedDevertAd;
  this._persistMainRadioAdState();
} else if (!paid && this.devertPlayback && musicSinceAd >= DEVERT_SONGS_PER_MAIN_AD && activeShow.type !== 'weekly_top10') {
  const ads = await this.devertPlayback.nextMainRadioAd({
    excludeCampaignIds: this._getActiveFailedDevertCampaignIds(),
    count: 2,
  }).catch(error => {
    selectionDeferred = true;
    this._setMainRadioAdSkip('selection deferred', null);
    console.warn('[devert] Main-radio ad selection deferred:', error.message);
    return null;
  });

  const selectedAds = Array.isArray(ads) ? ads : ads ? [ads] : [];
  if (selectedAds.length) {
    [this._preparedDevertAd, ...this._pendingDevertAds] = selectedAds;
    devertAd = this._preparedDevertAd;
    this._breakAwaitingUnlock = !cancellationAds && this._musicSinceAd < DEVERT_SONGS_PER_MAIN_AD;
    this._persistMainRadioAdState();
  } else {
    this._setMainRadioAdSkip('no eligible campaign available', null);
  }
}

if (cancellationAds && !paid && !devertAd) return null;
let playlistSelection = null;
if (activeShow.type === 'playlist_show' && !paid && !devertAd) {
  try {
    playlistSelection = await this._playlistShow.next(activeShow, getPlaylist());
  } catch (error) {
    console.warn('[playlist-show] Normal rotation fallback:', error.message);
  }
}

// Refill + reshuffle if we've exhausted the current pass
if (!isHype && !playlistSelection && !paid && !devertAd && this._queueIndex >= this._queue.length) {
  this._refreshQueue();
}

if (!isHype && activeShow.type === 'normal_rotation' && !paid && !devertAd &&
    (!this._deploymentDraining() || playlistOwnsRadio) && this.djuke?.hasPendingPlaylist?.()) {
  return null;
}

const priorityMint = activeShow.type === 'normal_rotation' && !paid && !devertAd &&
  !playlistOwnsRadio && this._priorityMintTrack;
const replayCandidate = activeShow.type === 'normal_rotation' && !paid && !devertAd && !playlistOwnsRadio && !priorityMint && !options.skipLiveReplay
  ? pendingLiveRecordingReplay() : null;
const liveReplay = replayCandidate?.trackId !== this._currentTrack?.trackId ? replayCandidate : null;
// Nothing to play → wait and retry

if (!isHype && !playlistSelection && !paid && !devertAd && !liveReplay && !priorityMint && this._queue.length === 0) {
  this._sendPlaybackNotice('📭 The JukeLoop playlist is empty.\n' +
    (this.textChannel ? 'Post audio files (MP3, M4A, etc.) in <#' + this.textChannel.id + '> to add tracks!' : 'Waiting for playable recordings.'));
  return null;
}

const track = hypeSelection ? hypeSelection.track : playlistSelection ? playlistSelection.track : paid ? paid.track
  : devertAd ? devertAd.track : priorityMint || liveReplay || this._queue[this._queueIndex];
const queueIndex = !hypeSelection && !playlistSelection && !paid && !devertAd && !priorityMint && !liveReplay
  ? this._queueIndex : null;
const longForm = !!playlistSelection &&
  radioPlaylistDefinition(playlistSelection.playlistId, playlistSelection.playlistDefinition).selector === 'long-form';
const durationReason = !devertAd && paid?.record.kind !== 'devert'
  ? this._durationAdmissionReason(track, { longForm }) : null;
if (durationReason) {
  console.warn('[radio-duration] Playback deferred:', track?.trackId, durationReason);
  if (paid) {
    await this.djuke.release(paid.record, new Error(durationReason));
    this._djukeCooldownUntil = Date.now() + PAID_FETCH_RETRY_MS;
    this._playlistRetryReason = durationReason;
    return null;
  }
  if (hypeSelection) return this._skipHype(hypeSelection, durationReason, options);
  if (playlistSelection) await this._playlistShow.advance(playlistSelection, durationReason);
  else if (liveReplay) return this._prepareNextPlayback(null, { ...options, skipLiveReplay: true });
  else this._queueIndex++;

  if (priorityMint?.trackId === track?.trackId) this._priorityMintTrack = null;
  return this._prepareNextPlayback(null, options);
}
if (!this.isContentAllowed(track, !!devertAd || paid?.record.kind === 'devert')) {
  if (liveReplay) return this._prepareNextPlayback(null, { ...options, skipLiveReplay: true });
  if (paid) {
    await this.djuke.release(paid.record, new Error('Recording blocked by content review; payment remains unresolved'));
    this._djukeCooldownUntil = Date.now() + PAID_FETCH_RETRY_MS;
    return null;
  }
  if (devertAd) {
    this._preparedDevertAd = null;
    await this._persistMainRadioAdState();
  } else if (playlistSelection) {
    await this._playlistShow.advance(playlistSelection, 'Recording excluded by content review');
  } else if (hypeSelection) {
    return this._skipHype(hypeSelection, 'Recording excluded by content review', options);
  } else this._queueIndex++;
  if (priorityMint?.trackId === track?.trackId) this._priorityMintTrack = null;
  return this._prepareNextPlayback(null, options);
}

let url;
try { url = await this._getFreshUrl(track); }
catch (error) {
  if (longForm) {
    console.warn('[radio-duration] Long-form media lookup deferred:', error.message);
    await this._playlistShow.defer(playlistSelection, 'Long-form recording media temporarily unavailable');
    return this._prepareNextPlayback(null, options);
  }
  if (liveReplay) {
    console.warn('[live-recording] Replay media deferred:', error.message);
    return this._prepareNextPlayback(null, { ...options, skipLiveReplay: true });
  }
  if (paid?.record.playlistBatchId !== undefined) {

    await this._retryPlaylistMedia(paid.record, error);
    return null;
  }
  if (!devertAd || devertAd.paidRequest) throw error;
  console.warn('[devert] Advert media lookup failed; skipping:', error.message);
  url = null;
}
if (this._destroyed) {
  if (paid && this.djuke) await this.djuke.release(paid.record, new Error('Radio stopped during media lookup'));
  return null;
}
if (!url) {
  if (liveReplay) {
    console.warn('[live-recording] Replay media unavailable; keeping replay pending');
    return this._prepareNextPlayback(null, { ...options, skipLiveReplay: true });
  }
  console.warn(`[jukeloop] Could not fetch URL for "${track.title}" (${track.messageId}), skipping.`);
  if (hypeSelection) return this._skipHype(hypeSelection, 'The recording could not be fetched.', options);
  if (playlistSelection) {
    if (longForm) await this._playlistShow.defer(playlistSelection, 'Long-form recording could not be fetched; retry pending');
    else await this._playlistShow.advance(playlistSelection, 'The recording could not be fetched');
    return this._prepareNextPlayback(null, options);
  }
  if (devertAd && !devertAd.paidRequest) {
    this._recordMainRadioAdFailure(devertAd.campaignId, 'ad file could not be fetched');
    this._preparedDevertAd = null;
    this._persistMainRadioAdState();
  }
  const skipNoticeKey = paid ? `paid:${paid.record.requestId}` : null;
  if (!skipNoticeKey || !this._paidFetchNotices.has(skipNoticeKey)) {
    if (skipNoticeKey) this._paidFetchNotices.add(skipNoticeKey);
    this._sendPlaybackNotice(paid
        ? `⏳ Paid request **${track.title}** can't be fetched right now — it stays queued for retry.`

        : `⚠️ Skipping **${track.title}** — the original upload could not be found.`);
  }
  if (paid && this.djuke) {
    if (paid.record.playlistBatchId !== undefined) {
      await this._retryPlaylistMedia(paid.record, new Error('Paid recording could not be fetched'));
      return null;
    }
    // Keep the request queued, but let free rotation play instead of leaving the radio silent.
    this._djukeCooldownUntil = Date.now() + PAID_FETCH_RETRY_MS;
    await this.djuke.fail(paid.record, new Error('Paid recording could not be fetched')).catch(() => {});
    return this._prepareNextPlayback(null, options);
  }
  if (priorityMint?.trackId === track.trackId) this._priorityMintTrack = null;
  if (queueIndex !== null) this._queueIndex++;
  return this._prepareNextPlayback(null, options);
}

const showAfterMediaLookup = this._resolveShow();
if (showAfterMediaLookup.type === 'live_performance') {
  if (paid && this.djuke) await this.djuke.release(paid.record, new Error('Live performance block began before playback')).catch(() => {});
  return null;
}

try {
  const source = await this._createStream(url, { ad: !!devertAd,
    playlist: paid?.record.playlistBatchId !== undefined });
  const { ffmpegProcess } = source;
  const completion = monitorAudioCompletion(source.stream, ffmpegProcess);
  const { stream } = completion;
  await waitForAudioReady(stream, ffmpegProcess, this._audioReadyTimeoutMs);
  if (this._destroyed) {
    try { ffmpegProcess.kill(); } catch {}
    if (paid && this.djuke) await this.djuke.release(paid.record, new Error('Radio stopped')).catch(() => {});
    return null;
  }

  const resource = createAudioResource(stream, { inputType: StreamType.Raw });
  return { track, paid, devertAd, queueIndex, url, resource, ffmpegProcess, completion, liveReplay: !!liveReplay, hype: hypeSelection, playlistShow: playlistSelection,
    priorityMint: priorityMint?.trackId || null, longForm,
    playlistShowContext: activeShow.type === 'playlist_show'
      ? { title: activeShow.label, instanceId: activeShow.instanceId, fallback: !playlistSelection && !devertAd } : null };
} catch (err) {
  console.error('[jukeloop] Failed to prepare track:', err.message);
  if (liveReplay) return this._prepareNextPlayback(null, { ...options, skipLiveReplay: true });
  if (hypeSelection) return this._skipHype(hypeSelection, err.message, options);
  if (playlistSelection) {
    if (longForm) await this._playlistShow.defer(playlistSelection, 'Long-form recording audio preparation failed; retry pending');
    else await this._playlistShow.advance(playlistSelection, err.message);
    return this._prepareNextPlayback(null, options);
  }
  if (devertAd && !devertAd.paidRequest) {
    this._recordMainRadioAdFailure(devertAd.campaignId, err.message || 'ad playback failed');
    this._preparedDevertAd = null;
    this._persistMainRadioAdState();
  }
  if (paid && this.djuke) {
    if (this._destroyed) {
      await this.djuke.release(paid.record, new Error('Radio stopped during media preparation'));
      return null;
    }
    if (paid.record.playlistBatchId !== undefined) {
      await this._retryPlaylistMedia(paid.record, err);
      return null;
    }
    this._sendPlaybackNotice(`⚠️ Skipping **${track.title}**: ${err.message}`);

      await this.djuke.fail(paid.record, err).catch(() => {});
      throw err;
    }
    this._sendPlaybackNotice(`⚠️ Skipping **${track.title}**: ${err.message}`);
    if (priorityMint?.trackId === track.trackId) this._priorityMintTrack = null;
    if (queueIndex !== null) this._queueIndex++;
    return this._prepareNextPlayback(null, options);
  }
}

_disposePrepared(prepared, reason = 'Prepared playback discarded') {
  if (!prepared) return;
  try { prepared.ffmpegProcess?.kill(); } catch {}
  if (prepared.paid?.record && this.djuke) {
    this.djuke.release(prepared.paid.record, new Error(reason))
      .catch(error => console.warn('[jukeloop] Could not release prepared DJuke request:', error.message));
  }

}

async _retryPlaylistMedia(record, error) {
  const result = await this.djuke.retryMedia(record, error);
  this._setPlaylistMediaRetry(result);
}

_setPlaylistMediaRetry(result) {
  if (result.retrying) {
    this._djukeCooldownUntil = Date.now() + 5000 * 2 ** (result.retryNumber - 1);
    this._playlistRetryReason = `Paid playlist media retry ${result.retryNumber}/${result.maxRetries}; payment stays queued. No new payment required.`;
    this._sendPlaybackNotice(`⏳ ${this._playlistRetryReason}`);
  } else {
    this._playlistRetryReason = '';
  }
}

_schedulePaidPriorityCheck() {
  clearTimeout(this._paidPollTimer);
  this._paidPollTimer = null;
  const playlistRecord = this._preparedNext?.paid?.record;
  if (!this._destroyed && playlistRecord?.playlistBatchId !== undefined &&
      this.djuke?.hasActivePlaylist?.() && this.player.state.status === AudioPlayerStatus.Playing) {
    this._paidPollTimer = setTimeout(() => {
      this._paidPollTimer = null;

      Promise.resolve(this.djuke.refreshPlaybackState?.(playlistRecord))
        .catch(error => console.warn('[djuke] Playlist playback verification deferred:', error.message))
        .finally(() => {
          if (this._preparedNext?.paid?.record === playlistRecord) this._schedulePaidPriorityCheck();
        });
    }, 1000);
    this._paidPollTimer.unref?.();
    return;
  }
  const activeShow = this._resolveShow();
  if (!this.djuke || this._deploymentDraining() || this.djuke.hasActivePlaylist?.() ||
    !this._preparedNext || (this._preparedNext.paid && this._preparedNext.paid.record.tier !== 0) ||
    (activeShow.unbookedLiveOccurrenceId && (this._preparedDevertAd || this._pendingDevertAds.length)) ||
    activeShow.type === 'playlist_show' || activeShow.type === 'weekly_top10' || activeShow.type === 'live_performance' ||
    this.player.state.status !== AudioPlayerStatus.Playing) return;
  this._paidPollTimer = setTimeout(() => {
    this._paidPollTimer = null;
    this._checkPreparedPaidPriority();
  }, Math.max(DJUKE_PREFETCH_POLL_MS, this._djukeCooldownUntil - Date.now()));
  this._paidPollTimer.unref?.();
}

_checkPreparedPaidPriority() {
  if (this._destroyed || this._prepareTask || !this._preparedNext ||
      (this._preparedNext.paid && this._preparedNext.paid.record.tier !== 0)) return;
  const epoch = this._preparationEpoch;
  const task = (async () => {
    if (Date.now() < this._djukeCooldownUntil) {
      this._schedulePaidPriorityCheck();
      return this._preparedNext;
    }
    const preparedBump = this._preparedNext.paid?.record.kind === 'devert' && this._preparedNext.paid.record.tier === 0;
    const normalSlotDue = !!this._preparedNext.devertAd;

  const paid = await this.djuke.nextPaid({ allowBump: normalSlotDue && !preparedBump,
    includeSongs: !preparedBump && this._resolveShow().type !== 'live_audio_ads',
    ...(normalSlotDue ? { includeVideos: false } : {}) });
  if (!paid) {
    this._schedulePaidPriorityCheck();
    return this._preparedNext;
  }
  if (this._destroyed || epoch !== this._preparationEpoch || !this._preparedNext) {
    await this.djuke.release(paid.record, new Error('Radio mode changed during priority selection'));
    return null;
  }
  const regular = this._preparedNext;
  if (regular.paid) {
    try {
      await this.djuke.release(regular.paid.record, new Error('Immediate advert took priority before playback'));
    } catch (error) {
      await this.djuke.release(paid.record, error)
        .catch(releaseError => console.warn('[jukeloop] Could not release immediate advert after failed preemption:', releaseError.message));
      throw error;
    }
  }
  this._preparedNext = null;
  this._disposePrepared(regular.paid ? { ...regular, paid: null } : regular);
  const prepared = await this._prepareNextPlayback(paid);
  if (epoch !== this._preparationEpoch) {
    this._disposePrepared(prepared, 'Scheduled radio mode changed');
    return null;
  }
  this._preparedNext = prepared;
  if (prepared && (!prepared.paid || prepared.paid.record.tier === 0)) this._schedulePaidPriorityCheck();
  return prepared;
})().catch(error => {
  console.warn('[jukeloop] DJuke priority check deferred:', error.message);
  this._schedulePaidPriorityCheck();
  return this._preparedNext;
}).finally(() => {
  if (this._prepareTask === task) this._prepareTask = null;

  });
  this._prepareTask = task;
}

/** Keep looking for the next paid playlist song while the current one plays, so it is ready before this one ends. */
_schedulePrimeRetry() {
  clearTimeout(this._primeRetryTimer);
  this._primeRetryTimer = null;
  if (this._destroyed || this.player.state.status !== AudioPlayerStatus.Playing) return;
  this._primeRetryMs = Math.min(5_000, Math.max(1_000, this._primeRetryMs * 2));
  this._primeRetryTimer = setTimeout(() => {
    this._primeRetryTimer = null;
    this._primeNext();
  }, this._primeRetryMs);
  this._primeRetryTimer.unref?.();
}

_primeNext() {
  if (this._currentLongFormSelection || this._longFormCompletionTask || this._pendingLongFormCompletion) return;
  if (this._destroyed || this._preparedNext || this._prepareTask) return;
  clearTimeout(this._primeRetryTimer);
  this._primeRetryTimer = null;
  const epoch = this._preparationEpoch;
  // If the playing song is music, it should count toward the advert cadence when it ends.
  const projectedMusicSinceAd = this._currentDevertAd
    ? this._currentDevertAd.paidRequest && this._currentPaid?.tier !== 0 ? this._musicSinceAd : 0
    : this._musicSinceAd + 1;
  const task = this._prepareNextPlayback(null, { projectedMusicSinceAd })
    .then(prepared => {
      if (this._destroyed || epoch !== this._preparationEpoch) {
        this._disposePrepared(prepared, this._destroyed ? 'Radio stopped' : 'Scheduled radio mode changed');
        return null;
      }
      this._preparedNext = prepared;
      if (prepared) {
        this._primeRetryMs = 0;
        this._schedulePaidPriorityCheck();
      } else if (this.djuke?.hasPendingPlaylist?.()) {

        // A timed-out paid selection returns null while its durable reservation continues; collect it before this song ends.
        this._schedulePrimeRetry();
      }
      return prepared;
    })
    .catch(error => {
      console.warn('[jukeloop] Next track preparation deferred:', error.message);
      this._schedulePrimeRetry();
      return null;
    })
    .finally(() => {
      if (this._prepareTask === task) this._prepareTask = null;
    });
  this._prepareTask = task;
}

async _announcePrepared(prepared, playId) {
  if (!this.textChannel || this.client?.isReady?.() === false) return;
  const { track, devertAd, url } = prepared;
  const announcementContext = {
    playId,
    queueIndex: prepared.playlistShow ? prepared.playlistShow.cursor + 1 : prepared.hype ? prepared.hype.cursor % prepared.hype.totalTracks + 1 : this._queueIndex,
    totalTracks: prepared.playlistShow ? prepared.playlistShow.totalTracks : prepared.hype ? prepared.hype.totalTracks : this._queue.length,
    hype: prepared.hype,
    playlistShow: prepared.playlistShow || prepared.playlistShowContext,
    url,
    paid: !!prepared.paid,
    sponsor: this._nowPlaying?.sponsor || null,
  };
  const message = devertAd
    ? `${prepared.playlistShowContext ? `📻 **${prepared.playlistShowContext.title}** · Vote up OR down on the songs!\n` : ''}📢 **Sponsored campaign:** ${track.title} · campaign #${devertAd.campaignId}\n${buildSiteVotingLink()}`
    : buildNowPlayingMessage(track, announcementContext);
  const msg = await this.textChannel
    .send({ content: message, flags: MessageFlags.SuppressNotifications, allowedMentions: { parse: [] } })
    .catch(error => {
      this._reportDiscordOutputFailure(error);

      return null;
    });
  if (!msg || devertAd || this._nowPlaying?.playId !== playId) return;
  if (this._nowPlaying?.playId === playId) {
    this._announcementMsg = msg;
    this._announcementContext = announcementContext;
  }
}

_finishAdvertAtLimit(playId) {
  if (this._destroyed || !this._currentDevertAd || !this._nowPlaying?.audible ||
      this._nowPlaying.playId !== playId) return;
  this._activeAudio?.completion.interrupt('advert_time_limit');
  this._ffmpeg?.kill();
  this.player.stop(true);
}

_startPrepared(prepared) {
  if (!prepared || this._destroyed) return false;
  if (prepared.devertAd && this.devertPlayback?.isCampaignRemoved?.(prepared.devertAd.campaignId)) {
    this._disposePrepared(prepared, 'Advert removed from playback');
    return false;
  }
  const show = this.getShowState().activeShow;
  if (prepared.priorityMint && show.type !== 'normal_rotation') {
    this._disposePrepared(prepared, 'Fresh-mint priority waits for normal rotation');
    return false;
  }
  if (!prepared.devertAd && prepared.paid?.record.kind !== 'devert') {
    const designated = show.type === 'playlist_show' && prepared.playlistShow?.instanceId === show.instanceId &&
      radioPlaylistDefinition(show.playlistId, show.playlistDefinition).selector === 'long-form';
    const reason = this._durationAdmissionReason(prepared.track, { longForm: !!prepared.longForm && designated });
    if (reason || prepared.longForm && !designated) {
      console.warn('[radio-duration] Prepared playback rejected:', reason || 'Long-form programming changed');
      this._disposePrepared(prepared, reason || 'Long-form programming changed');
      return false;
    }
  }

if (prepared.liveReplay && (show.type !== 'normal_rotation' || this.djuke?.hasActivePlaylist?.() ||
    this.djuke?.hasPendingPlaylist?.())) {
  this._disposePrepared(prepared, 'Recording replay waits for a safe normal-radio boundary');
  return false;
}
if (show.type === 'live_performance' || (show.type === 'live_audio_ads' && !prepared.devertAd)) {
  this._disposePrepared(prepared, 'Live audio handoff excludes this prepared recording');
  return false;
}
if (this.isContentAllowed && !this.isContentAllowed(prepared.track, !!prepared.devertAd || prepared.paid?.record.kind === 'devert')) {
  this._disposePrepared(prepared, 'Recording excluded by content review');
  return false;
}
if (prepared.paid?.record.kind === 'devert' &&
    ['weekly_top10', 'live_performance'].includes(this.getShowState().activeShow.type)) {
  this._disposePrepared(prepared, 'Protected show began before paid advert playback');
  return false;
}
if (show.type !== 'live_audio_ads' && prepared.paid?.record.kind === 'devert' && prepared.paid.record.tier === 0 &&
    this._musicSinceAd < DEVERT_SONGS_PER_MAIN_AD && (this._breakAwaitingUnlock ||
    !(this._preparedDevertAd || this._pendingDevertAds.length))) {
  this._disposePrepared(prepared, 'Normal advert slot was not reached');
  return false;
}
if (this._ffmpeg && this._ffmpeg !== prepared.ffmpegProcess) {
  try { this._ffmpeg.kill(); } catch {}
}
this._ffmpeg = prepared.ffmpegProcess;
this._activeAudio = prepared.completion ? { completion: prepared.completion, resource: prepared.resource } : null;
this._currentPaid = prepared.paid?.record || null;
if (this._currentPaid) this._playlistRetryReason = '';

this._currentDevertAd = prepared.devertAd;
if (prepared.devertAd && !prepared.devertAd.paidRequest) this._breakAwaitingUnlock = false;
this._currentTrack = prepared.track;
if (prepared.priorityMint && this._priorityMintTrack?.trackId === prepared.priorityMint) {
  this._priorityMintTrack = null;
}
this._currentLongFormSelection = prepared.longForm ? prepared.playlistShow : null;
this._announcementMsg = null;
this._announcementContext = null;
if (prepared.queueIndex !== null && prepared.queueIndex === this._queueIndex) this._queueIndex++;
const playId = `${prepared.track.trackId}:${Date.now()}`;
const videoUrl = prepared.track.videoUrl || (mediaTypeFor(prepared.track.filename, prepared.track.mediaType) === 'video/mp4'
  ? `ipfs://${prepared.track.ipfsCid}`
  : '');
this._nowPlaying = {
  playId,
  trackId: prepared.track.trackId,
  expectedMs: expectedRecordingMs(prepared.track),
  title: prepared.track.title,
  uploader: prepared.track.uploader,
  filename: prepared.track.filename || null,
  mediaType: prepared.track.videoUrl || mediaTypeFor(prepared.track.filename, prepared.track.mediaType) === 'video/mp4'
    ? 'video/mp4'
    : mediaTypeFor(prepared.track.filename, prepared.track.mediaType) || '',
  ...(videoUrl ? { videoUrl } : {}),
  ipfsCid: prepared.track.ipfsCid || null,
  isDevert: !!prepared.devertAd,
  ...(prepared.devertAd?.campaignId != null ? { campaignId: String(prepared.devertAd.campaignId) } : {}),
  ...(prepared.paid?.record.playlist ? { djukePlaylist: { ...prepared.paid.record.playlist } } : {}),
  ...((prepared.playlistShow || prepared.playlistShowContext) ? { playlistShow: {

    title: (prepared.playlistShow || prepared.playlistShowContext).title,
    instanceId: (prepared.playlistShow || prepared.playlistShowContext).instanceId,
    fallback: prepared.playlistShowContext?.fallback === true } } : {}),
  ...(prepared.hype ? { hype: { openingRank: prepared.hype.openingRank, encore: prepared.hype.encore } } : {}),
  ...(prepared.paid ? {
    sponsor: {
      kind: prepared.paid.record.kind === 'devert' ? 'devert' : 'djuke',
      wallet: checksumAddress(prepared.paid.record.payer),
      amountUnits: prepared.paid.record.amountUnits,
      requestId: prepared.paid.record.requestId,
      ...(prepared.devertAd ? { campaignId: prepared.devertAd.campaignId } : {}),
    },
  } : prepared.devertAd ? {
    sponsor: {
      kind: 'devert',
      wallet: checksumAddress(prepared.devertAd.track.advertiser),
      campaignId: prepared.devertAd.campaignId,
    },
  } : {}),
  firstWeekBonus: prepared.track.firstWeekBonus === true,
  startedAt: Date.now(),
  audible: false,
};
if (prepared.devertAd?.paidRequest && prepared.paid.record.tier === 0) {
  if (this._preparedDevertAd) this._preparedDevertAd = null;
  else this._pendingDevertAds.shift();
  this._breakAwaitingUnlock = false;
  this._persistMainRadioAdState();
} else if (prepared.devertAd && !prepared.devertAd.paidRequest) {
  this._preparedDevertAd = null;
  this._persistMainRadioAdState();
}
if (this.websitePlayback && this.publicBroadcast?.enabled && typeof prepared.resource.read === 'function') {
  const read = prepared.resource.read.bind(prepared.resource);
  const program = { ...this._nowPlaying,

      protected: !!prepared.paid || !!prepared.devertAd };
    prepared.resource.read = () => {
      const packet = read();
      if (packet && !this._destroyed && this._nowPlaying?.playId === playId) {
        this.publicBroadcast.radioPacket(packet, program);
      }
      return packet;
    };
  }
  this.player.play(prepared.resource);
  if (this._currentPaid?.kind === 'dmtv') this.djuke?.startPlayback?.(this._currentPaid, this._nowPlaying);
  this._announcePrepared(prepared, playId)
    .catch(error => console.warn('[jukeloop] Now-playing announcement deferred:', error.message));
  console.log(`[jukeloop] Now playing: "${prepared.track.title}" by ${prepared.track.uploader}`);
  return true;
}

_sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

_startChangeoverGap() {
  if (!this._discordOutputsAttached && !this.publicBroadcast?.enabled) return false;
  let source;
  try {
    source = createFFmpegStream(gongGapAssetPath(this._changeoverGapIndex++), {});
  } catch (error) {
    console.warn('[jukeloop] Inter-song gap asset unavailable:', error.message);
    return false;
  }
  const index = (this._changeoverGapIndex - 1) % GONG_GAP_ASSET_COUNT;
  const resource = createAudioResource(source.stream, { inputType: StreamType.Raw });
  const playId = `gap:${Date.now()}:${index + 1}`;
  const program = { playId, title: 'Gentle inter-song gong', artist: '', isDevert: false };
  if (this.websitePlayback && this.publicBroadcast?.enabled && typeof resource.read === 'function') {
    const read = resource.read.bind(resource);
    resource.read = () => {
      const packet = read();
      if (packet && !this._destroyed) this.publicBroadcast.radioPacket(packet, program);

      return packet;
    };
  }
  this._changeoverGapPlaying = true;
  this.player.play(resource);
  return true;
}

/** Hold the prepared item until the changeover gap ends; null if the radio mode changed meanwhile. */
async _waitForChangeover(prepared) {
  const waitMs = this._changeoverAt - Date.now();
  if (!(waitMs > 0)) return prepared;
  const epoch = this._preparationEpoch;
  this._changeoverPrepared = prepared;
  try {
    await this._sleep(waitMs);
  } finally {
    if (this._changeoverPrepared === prepared) this._changeoverPrepared = null;
  }
  if (this._destroyed || epoch !== this._preparationEpoch) {
    this._disposePrepared(prepared, this._destroyed ? 'Radio stopped' : 'Scheduled radio mode changed');
    return null;
  }
  return prepared;
}

/** Public metadata for the prepared next item, with its start time while the changeover gap runs. */
getUpNext() {
  if (this._destroyed) return null;
  const waiting = this._changeoverPrepared;
  const prepared = waiting || this._preparedNext;
  const track = prepared?.track;
  if (!track?.trackId) return null;
  return {
    trackId: track.trackId,
    title: track.title,
    uploader: track.uploader,
    filename: track.filename || null,
    mediaType: track.mediaType || '',
    ...(track.videoUrl ? { videoUrl: track.videoUrl } : {}),
    ipfsCid: track.ipfsCid || null,
    isDevert: !!prepared.devertAd,
    ...(prepared.paid?.record.playlist ? { djukePlaylist: { ...prepared.paid.record.playlist } } : {}),
    ...(waiting ? { startsAt: this._changeoverAt } : {}),
  };
}

_deploymentDraining() { return (this._deploymentDrainUntil || 0) > Date.now(); }

_paidStartAllowed(record) {

  const active = this.djuke?.getActivePlaylistBatchId?.() ?? null;
  if (active !== null) return record.playlistBatchId === active;
  return !this._deploymentDraining() && !this._broadcastHandoff && !(this._broadcastRequestedUntil > Date.now());
}

async withBroadcastHandoff(apply, { protectAd = false } = {}) {
  const busy = () => this._currentPaid || protectAd && this._currentDevertAd || this.djuke?.hasActivePlaylist?.() ||
    this.djuke?.getActivePlaylistBatchId?.() != null || this._prepareTask || this._transitionTask ||
    this._paidCompletionTask || this._paidBookkeepingTask || this.djuke?.hasPendingSelection?.() ||
    this._changeoverPrepared?.paid;
  if (this._destroyed || this._broadcastHandoff || this._deploymentDraining()) {
    throw new Error('Broadcast handoff waits for the active paid item and in-flight selection, not queued purchases');
  }
  this._broadcastRequestedUntil = Date.now() + 60000;
  if (busy()) throw new Error('Finish the current paid item; new paid starts are held for sixty seconds while the producer retries');
  this._broadcastHandoff = true;
  clearTimeout(this._paidPollTimer); this._paidPollTimer = null;
  try {
    const prepared = this._preparedNext;
    if (prepared?.paid) {
      this._preparedNext = null;
      this._disposePrepared({ ...prepared, paid: null });
      let timer;
      try {
        await Promise.race([
          this.djuke.release(prepared.paid.record, new Error('Producer broadcast handoff retains this paid request')),
          new Promise((_, reject) => { timer = setTimeout(() => reject(new Error('Paid handoff verification timed out')), 5000); }),
        ]);
      } finally { clearTimeout(timer); }
    }

    if (busy()) throw new Error('Paid playback changed during broadcast handoff');
    return await apply();
  } finally {
    this._broadcastHandoff = false;
    this._broadcastRequestedUntil = 0;
    if (this._preparedNext) this._schedulePaidPriorityCheck();
    if (this._started && this.player.state.status === AudioPlayerStatus.Idle &&
        this._resolveShow().type !== 'live_performance') {
      void this._playNext().catch(() => {});
    }
  }
}

async drainForDeployment(until) {
  this._deploymentDrainUntil = until;
  clearTimeout(this._paidPollTimer);
  this._paidPollTimer = null;
  if (!this._deploymentDraining()) {
    if (this._preparedNext) this._schedulePaidPriorityCheck();
    return { draining: false, ready: false };
  }
  await this.djuke?.prepareForDeployment?.();
  const prepared = this._preparedNext;
  if (prepared?.paid && !this._paidStartAllowed(prepared.paid.record)) {
    await this.djuke.release(prepared.paid.record, new Error('Deployment drain holds new paid starts'));
    this._preparedNext = null;
    this._disposePrepared({ ...prepared, paid: null });
  }
  const activeBatch = this.djuke?.getActivePlaylistBatchId?.() ?? null;
  return { ready: !this._currentPaid && activeBatch === null && !this._prepareTask && !this._transitionTask &&
    !this._paidCompletionTask && !this._paidBookkeepingTask &&
    !this.djuke?.hasPendingSelection?.() && !this._changeoverPrepared?.paid,
  activePlaylistBatchId: activeBatch, currentPaidRequestId: this._currentPaid?.requestId || null,
  draining: this._deploymentDraining(), expiresAt: until };
}

async _playNext() {
  if (this._destroyed) return;
  if (this._transitionTask) return this._transitionTask;

const transition = (async () => {
  clearTimeout(this._paidPollTimer);
  this._paidPollTimer = null;
  let retryDelay = EMPTY_PLAYLIST_RETRY_MS;
  let prepared = null;
  const epoch = this._preparationEpoch;
  try {
    if (this._audioCompletionTask) await this._audioCompletionTask;
    if (this._longFormCompletionTask) await this._longFormCompletionTask;
    await this._completePendingLongForm();
    if (this._paidCompletionTask) await this._paidCompletionTask;
    if (this._prepareTask) await this._prepareTask;
    prepared = this._preparedNext;
    this._preparedNext = null;
    if (prepared && !prepared.paid && !prepared.devertAd && !prepared.hype &&
        this.getShowState().activeShow.type === 'normal_rotation' &&
        (!this._deploymentDraining() || this.djuke?.hasActivePlaylist?.()) && this.djuke?.hasPendingPlaylist?.()) {
      this._disposePrepared(prepared, 'Paid playlist continues');
      prepared = null;
    }
    // Prefetch may have run before the last song unlocked the next advert slot.
    if (prepared && !prepared.hype && !prepared.paid && !prepared.devertAd && this.devertPlayback &&
      this._musicSinceAd >= DEVERT_SONGS_PER_MAIN_AD) {
      try {
        const refreshed = await this._prepareNextPlayback();
        if (refreshed) {
          this._disposePrepared(prepared);
          prepared = refreshed;
        }
      } catch (error) {
        console.warn('[devert] Transition-time ad selection deferred; keeping prepared music:', error.message);
      }
    }
    if (!prepared) prepared = await this._prepareNextPlayback();
    if (!prepared && this.djuke?.hasPendingPlaylist?.()) retryDelay = 1_000;

if (prepared?.paid?.record.kind === 'devert' && prepared.paid.record.tier === 0 &&
    this._breakAwaitingUnlock && this._musicSinceAd < DEVERT_SONGS_PER_MAIN_AD) {
  await this.djuke.release(prepared.paid.record, new Error('Normal advert slot not reached yet'));
  this._disposePrepared({ ...prepared, paid: null });
  prepared = await this._prepareNextPlayback(null, { allowAds: false });
}
// An advert picked early stays queued if the song that should have unlocked it did not count.
if (prepared?.devertAd && !prepared.paid && this._breakAwaitingUnlock &&
  this._musicSinceAd < DEVERT_SONGS_PER_MAIN_AD) {
  this._disposePrepared(prepared, 'Advert slot not reached yet');
  prepared = await this._prepareNextPlayback(null, { allowAds: false });
}
if (prepared?.devertAd && !prepared.devertAd.paidRequest && this.devertPlayback?.canPlayCampaign &&
  !await this.devertPlayback.canPlayCampaign(prepared.devertAd.campaignId, {
    competitionReward: prepared.devertAd.competitionReward,
  })) {
  this._disposePrepared(prepared, 'Campaign expired or removed before playback');
  this._preparedDevertAd = null;
  await this._persistMainRadioAdState();
  prepared = null;
  retryDelay = 1_000;
}
if (prepared) {
  if (epoch !== this._preparationEpoch) {
    this._disposePrepared(prepared, 'Scheduled radio mode changed');
    prepared = null;
    retryDelay = 1_000;
  }
}
if (prepared) {
  prepared = await this._waitForChangeover(prepared);
  if (this._destroyed) return;
  if (!prepared) retryDelay = 1_000;
}

if (prepared) {
  const show = this.getShowState().activeShow;
  if ((prepared.playlistShowContext && ['live_performance', 'weekly_top10'].includes(show.type)) ||
    (prepared.playlistShow && show.instanceId !== prepared.playlistShow.instanceId) ||
    (show.type === 'playlist_show' && !prepared.playlistShow && !prepared.paid && !prepared.devertAd &&
      this._playlistShow.publicState(show)?.status === 'ready') ||
    show.type === 'live_performance' || (show.type === 'live_audio_ads' && !prepared.devertAd) ||
    (prepared.paid && ['weekly_top10', 'playlist_show'].includes(show.type)) || (prepared.hype
    ? show.instanceId !== prepared.hype.instanceId
    : show.id === 'friday-top10-hype')) {
    this._disposePrepared(prepared, 'Scheduled handoff reached');
    prepared = null;
    retryDelay = 1_000;
  }
}
const authorizationStarted = Date.now();
if (prepared?.paid && (!this._paidStartAllowed(prepared.paid.record) || this.djuke?.canPlay &&
    !await this.djuke.canPlay(prepared.paid.record))) {
  this._disposePrepared(prepared, 'Paid request changed or lost priority before playback');
  prepared = null;
  retryDelay = 1_000;
}
if (prepared?.paid && Date.now() - authorizationStarted >= 1_000) {
  console.log(`[jukeloop] Paid playback authorization took ${Date.now() - authorizationStarted}ms`);
}
if (prepared) {
  if (prepared.paid) await this.djuke?.start?.(prepared.paid.record);
  if (prepared.hype) {
    await this._topTenHype.advance(prepared.hype);
    if (this._destroyed || epoch !== this._preparationEpoch ||

        this.getShowState().activeShow.instanceId !== prepared.hype.instanceId) {
        this._disposePrepared(prepared, 'Friday Top10 ended during checkpoint');
        prepared = null;
        retryDelay = 1_000;
      }
    }
    if (prepared?.playlistShow) {
      const selection = prepared.playlistShow;
      const definition = radioPlaylistDefinition(selection.playlistId, selection.playlistDefinition);
      const reason = () => playlistTrackReason(getPlaylist().find(track => track.trackId === selection.trackId),
        definition, Date.parse(selection.capturedAt));
      const skipReason = reason();
      if (!prepared.longForm || skipReason) await this._playlistShow.advance(selection, skipReason);
      const afterCheckpoint = reason() || (this._destroyed || epoch !== this._preparationEpoch ||
        this.getShowState().activeShow.instanceId !== selection.instanceId ? 'Scheduled handoff reached before audio started' : null);
      if (skipReason || afterCheckpoint) {
        if (!skipReason) await this._playlistShow.recordSkip(selection, afterCheckpoint);
        this._disposePrepared(prepared, skipReason || afterCheckpoint);
        prepared = null;
        retryDelay = 1_000;
      }
    }
    if (prepared && this._startPrepared(prepared)) return;
    retryDelay = 1_000;
  }
} catch (error) {
  this._disposePrepared(prepared, 'Playback checkpoint failed');
  retryDelay = 1_000;
  console.warn('[jukeloop] Next playback blocked:', error.message);
}
if (!this._destroyed) {
  const retry = setTimeout(() => this._playNext().catch(() => {}), retryDelay);

      retry.unref?.();
    }
  })().finally(() => {
    if (this._transitionTask === transition) this._transitionTask = null;
  });
  this._transitionTask = transition;
  return transition;
}

async _completePendingLongForm() {
  const pending = this._pendingLongFormCompletion;
  if (!pending) return;
  await this._playlistShow.complete(pending.selection, pending.playId);
  if (this._pendingLongFormCompletion === pending) this._pendingLongFormCompletion = null;
}

/**
 * Read 👍 / 👎 counts from the last "Now Playing" message and persist them.
 * Called automatically when the next track is about to start.
 */
async _collectReactions() {
  const trackRef = this._currentTrack;
  const completedPlay = this._completedPlay;
  this._completedPlay = null;
  const paidRecord = this._currentPaid;
  const longFormSelection = this._currentLongFormSelection;
  this._currentLongFormSelection = null;
  this._currentPaid = null;
  const msgRef   = this._announcementMsg;
  const announcementContext = this._announcementContext;

  // Clear refs first so any re-entrant call is a no-op
  this._announcementMsg = null;
  this._currentTrack    = null;
  this._announcementContext = null;

  const finish = async () => {
    if (completedPlay?.completion) {
      const media = await completedPlay.completion;
      delete completedPlay.completion;
      completedPlay.finished = media.finished;
      completedPlay.media = media;
      if (media.finished && completedPlay.countAdOnCompletion) {
        this._musicSinceAd = 0;
        this._musicPlayCount++;
        this._persistMainRadioAdState();
      }
    }
    if (completedPlay) {

    Object.assign(completedPlay, radioCompletionDiagnostics(completedPlay.audibleMs,
      completedPlay.expectedMs === undefined ? expectedRecordingMs(trackRef) : completedPlay.expectedMs));
    console.log('[jukeloop] Audio completion:', JSON.stringify({
      playId: completedPlay.playId, trackId: completedPlay.trackId,
      requestId: paidRecord?.requestId || null, attempt: paidRecord?.attempts || null,
      audibleMs: completedPlay.audibleMs,
      ...radioCompletionDiagnostics(completedPlay.audibleMs, completedPlay.expectedMs),
      finished: completedPlay.finished, ...completedPlay.media,
    }));
  }
  if (longFormSelection && trackRef && completedPlay?.trackId === trackRef.trackId) {
    const seconds = verifiedRecordingDuration(trackRef);
    if (seconds !== null && completedPlay.finished === true && completedPlay.audibleMs >= seconds * 1000 - 2000) {
      this._pendingLongFormCompletion = { selection: longFormSelection, playId: completedPlay.playId };
      await this._completePendingLongForm();
    }
  }
};
if (longFormSelection) {
  const task = finish().catch(error => console.warn('[radio-duration] Completion checkpoint deferred:', error.message));
  this._longFormCompletionTask = task;
  try { await task; }
  finally { if (this._longFormCompletionTask === task) this._longFormCompletionTask = null; }
} else if (completedPlay) {
  await finish();
}

if (paidRecord?.kind === 'devert' && this.djuke) {
  if (['scheduled_handoff', 'radio_stopped'].includes(completedPlay?.media?.interrupted)) {
    await this.djuke.release(paidRecord, new Error(completedPlay.media.reason));
    return;
  }

  await this.djuke.complete(paidRecord, completedPlay?.trackId === trackRef?.trackId ? completedPlay : null);
  return;
}
if (completedPlay?.trackId?.startsWith('devert:')) return;

if (trackRef && completedPlay?.trackId === trackRef.trackId) {
  await completeLiveRecordingReplay(trackRef.trackId, completedPlay);
  const recorded = recordAudiblePlay(trackRef.trackId, completedPlay);
  if (recorded.counted) {
    console.log(`[jukeloop] Counted weekly play for "${trackRef.title}" (${recorded.week}, ${Math.round(completedPlay.audibleMs / 1000)}s audible).`,
      JSON.stringify({ playId: completedPlay.playId, audibleMs: completedPlay.audibleMs,
        ...radioCompletionDiagnostics(completedPlay.audibleMs, completedPlay.expectedMs) }));
  }
}
if (paidRecord?.kind === 'dmtv' && this.djuke) {
  // Public HLS is buffered; the verifier may still be playing this recording after ingest ends.
  void this.djuke.complete(paidRecord, completedPlay).catch(() => {
    console.warn('[dmtv] Radio outcome could not be finalized; escrow journal will retry');
  });
} else if (paidRecord && this.djuke) {
  const play = trackRef && completedPlay?.trackId === trackRef.trackId ? completedPlay : null;
  if (['scheduled_handoff', 'radio_stopped'].includes(play?.media?.interrupted)) {
    await this.djuke.release(paidRecord, new Error(play.media.reason));
  } else {
    const completion = this.djuke.complete(paidRecord, play);
    // Clean evidence lets the next lane start while this checkpoint finishes; retries/failures still block it.
    if (paidRecord.playlistBatchId !== undefined && !this.djuke.hasPlaybackEvidence?.(paidRecord)) {
      this._paidCompletionTask = completion;

      }
      const recovery = await completion
        .finally(() => {
          if (this._paidCompletionTask === completion) this._paidCompletionTask = null;
        })
        .catch((err) => console.warn('[jukeloop] DJuke completion pending:', err.message));
      if (paidRecord.playlistBatchId !== undefined && recovery) this._setPlaylistMediaRetry(recovery);
    }
  }
  if (!msgRef || !trackRef) return;

  try {
    const fresh = await msgRef.fetch().catch(() => null);
    if (!fresh) return;

    const likes = reactionCount(fresh, '👍');
    const dislikes = reactionCount(fresh, '👎');

    const updatedTrack = applyRating(trackRef.trackId, likes, dislikes, fresh.id);
    if (updatedTrack && announcementContext) {
      await fresh.edit(buildNowPlayingMessage(updatedTrack, {
        ...announcementContext,
        votingOpen: false,
      })).catch(() => {});
    }

    if (likes > 0 || dislikes > 0) {
      console.log(
        `[jukeloop] Ratings for "${trackRef.title}": +${likes} 👍 / -${dislikes} 👎`,
      );
    }
  } catch (err) {
    console.error('[jukeloop] Error collecting reactions:', err.message);
  }
}

/** Return an unplayed paid request to the queue and pause paid picks briefly. */
async _releasePaid(reason) {
  const record = this._currentPaid;
  this._currentPaid = null;
  if (!record || !this.djuke) return;
  this._djukeCooldownUntil = Date.now() + 60_000;
  await this.djuke.fail(record, new Error(reason))
    .catch((err) => console.warn('[jukeloop] DJuke release failed:', err.message));
}

async getMainRadioAdCountdown(now = Date.now(), paidQueue = null) {
  await this._ensureMainRadioAdState();

  return buildMainRadioAdCountdown({ session: this, now, paidQueue });
}

async removeDevertCampaign(campaignId) {
  const matches = ad => ad && String(ad.campaignId) === String(campaignId);
  this._pendingDevertAds = this._pendingDevertAds.filter(ad => !matches(ad));
  if (matches(this._preparedDevertAd)) this._preparedDevertAd = null;
  if (matches(this._preparedNext?.devertAd)) {
    this._disposePrepared(this._preparedNext, 'Advert removed from playback');
    this._preparedNext = null;
  }
  await this._persistMainRadioAdState();
  if (matches(this._currentDevertAd)) this.player.stop(true);
}

async refreshContentReview({ stopNow = false } = {}) {
  this._preparationEpoch++;
  this._disposePrepared(this._preparedNext, 'Content review changed');
  this._preparedNext = null;
  this._refreshQueue();
  if (stopNow && this._currentTrack && !this.isContentAllowed(this._currentTrack,
    !!this._currentDevertAd || this._currentPaid?.kind === 'devert')) {
    const paid = this._currentPaid;
    this._currentPaid = null;
    if (this._currentDevertAd) this._currentDevertAd = null;
    this._activeAudio?.completion.interrupt('content_review');
    this._activeAudio = null;
    this._completedPlay = null;
    this._currentTrack = null;
    this._announcementMsg = null;
    this._announcementContext = null;
    this._nowPlaying = null;
    this.player.stop(true);
    if (paid) await this.djuke.fail(paid, new Error('Recording excluded by content review; interrupted payment remains queued'));
  }
  if (this.player.state.status === AudioPlayerStatus.Playing) this._primeNext();
  else await this._playNext();
}

_ensureMainRadioAdState() {
  if (this._mainRadioAdStateReady) return Promise.resolve();

  if (!this._mainRadioAdStateLoadTask) {
    this._mainRadioAdStateLoadTask = (async () => {
      if (!this._restoreMainRadioAdState) {
        this._mainRadioAdStateReady = true;
        return;
      }
      try {
        const restored = await this._restoreMainRadioAdState();
        if (restored) this._applyMainRadioAdState(validateMainRadioAdState(restored));
      } catch (error) {
        console.warn('[devert] Main-radio ad state restore failed:', error.message);
      } finally {
        this._mainRadioAdStateReady = true;
      }
    })();
  }
  return this._mainRadioAdStateLoadTask;
}

_applyMainRadioAdState(state) {
  this._musicSinceAd = Number.isSafeInteger(state.musicSinceAd) ? state.musicSinceAd : 0;
  this._musicPlayCount = Number.isSafeInteger(state.musicPlayCount) ? state.musicPlayCount : 0;
  this._preparedDevertAd = state.preparedDevertAd;
  this._pendingDevertAds = Array.isArray(state.pendingDevertAds) ? state.pendingDevertAds : [];
  this._breakAwaitingUnlock = state.breakAwaitingUnlock === true && Boolean(this._preparedDevertAd || this._pendingDevertAds.length);
  this._failedDevertCampaigns = new Map((state.failedDevertCampaigns || []).map(entry => [String(entry.campaignId), {
    failedAt: entry.failedAt,
    musicPlayCount: entry.musicPlayCount,
  }]));
  this._lastMainRadioAdSkip = state.lastSkip || null;
  this._unbookedLiveOccurrenceId = state.unbookedLiveOccurrenceId;
  this._pruneExpiredFailedDevertCampaigns();
}

_snapshotMainRadioAdState() {
  return validateMainRadioAdState({
    schemaVersion: MAIN_RADIO_STATE_SCHEMA_VERSION,
    musicSinceAd: this._musicSinceAd,
    musicPlayCount: this._musicPlayCount,
    preparedDevertAd: this._preparedDevertAd,

    pendingDevertAds: this._pendingDevertAds,
    breakAwaitingUnlock: this._breakAwaitingUnlock,
    unbookedLiveOccurrenceId: this._unbookedLiveOccurrenceId,
    failedDevertCampaigns: [...this._failedDevertCampaigns.entries()].map(([campaignId, entry]) => ({
      campaignId,
      failedAt: entry.failedAt,
      musicPlayCount: entry.musicPlayCount,
    })),
    lastSkip: this._lastMainRadioAdSkip,
  });
}

_persistMainRadioAdState() {
  if (!this._saveMainRadioAdState || this._destroyed) return Promise.resolve(null);
  this._pruneExpiredFailedDevertCampaigns();
  const snapshot = this._snapshotMainRadioAdState();
  const next = async () => {
    const uri = await this._saveMainRadioAdState(structuredClone(snapshot));
    if (typeof uri !== 'string' || !uri.startsWith('ipfs://')) {
      throw new Error('Main-radio ad state was not durably checkpointed');
    }
    return uri;
  };
  this._mainRadioAdStateSaveTask = this._mainRadioAdStateSaveTask.then(next, next)
    .catch(error => {
      console.warn('[devert] Main-radio ad state save failed:', error.message);
    });
  return this._mainRadioAdStateSaveTask;
}

_setMainRadioAdSkip(reason, campaignId) {
  this._lastMainRadioAdSkip = {
    reason,
    campaignId: campaignId ? String(campaignId) : null,
    at: Date.now(),
  };
  console.warn(`[devert] main-radio ad skipped: ${reason}${campaignId ? ` (campaign ${campaignId})` : ''}`);
  void this._persistMainRadioAdState();
}

_recordMainRadioAdFailure(campaignId, reason) {
  const key = String(campaignId);
  this._failedDevertCampaigns.set(key, { failedAt: Date.now(), musicPlayCount: this._musicPlayCount });
  this._setMainRadioAdSkip(reason, key);
}

_pruneExpiredFailedDevertCampaigns() {
  const now = Date.now();
  let changed = false;
  for (const [campaignId, entry] of this._failedDevertCampaigns.entries()) {
    if (now - entry.failedAt >= MAIN_RADIO_FAILED_CAMPAIGN_MS ||
      this._musicPlayCount - entry.musicPlayCount >= MAIN_RADIO_FAILED_CAMPAIGN_SONGS) {
      this._failedDevertCampaigns.delete(campaignId);
      changed = true;
    }
  }
  return changed;
}

_getActiveFailedDevertCampaignIds() {
  this._pruneExpiredFailedDevertCampaigns();
  return [...this._failedDevertCampaigns.keys()];
}

/** Stop all playback and disconnect from the voice channel. */
destroy() {
  this._destroyed = true;
  this._durationBackfill.close();
  clearTimeout(this._adCutoffTimer);
  this._adCutoffTimer = null;
  this._mediaAbort.abort();
  this._activeAudio?.completion.interrupt('radio_stopped');
  this._endingAudio?.completion.interrupt('radio_stopped');
  clearTimeout(this._paidPollTimer);
  this._paidPollTimer = null;
  clearTimeout(this._primeRetryTimer);
  this._primeRetryTimer = null;
  this._disposePrepared(this._preparedNext, 'Radio stopped');
  this._preparedNext = null;
  this._pendingDevertAds = [];
  this._preparedDevertAd = null;
  if (this._scheduleWatcher) {
    clearInterval(this._scheduleWatcher);
    this._scheduleWatcher = null;
  }
  this._nowPlaying = null;
  if (this._currentPaid && this.djuke) {
    this.djuke.release(this._currentPaid, new Error('Radio stopped')).catch(() => {});
    this._currentPaid = null;
  }
  const sessionKey = this._sessionKey ?? this.voiceChannel?.guild.id;
  if (_sessions.get(sessionKey) === this) _sessions.delete(sessionKey);
  if (this._ffmpeg) {

      try { this._ffmpeg.kill(); } catch {}
      this._ffmpeg = null;
    }
    this._voiceConnection?.stop();
    this.connection = null;
    try { this.player.stop(true); } catch {}
  }
}

// ── Channel backfill ──────────────────────────────────────────────────────────

/**
 * Scan the DecentJukebox text channel for historic audio uploads and register
 * any that are not already in the playlist store.
 *
 * Fetches messages in reverse-chronological batches (100 per request, the
 * Discord API maximum) until all messages have been seen.  Only messages
 * posted by non-bot users that contain audio attachments are considered.
 *
 * @param {import('discord.js').TextBasedChannel} jukeboxChannel
 * @returns {Promise<number>} Number of new tracks added to the store
 */
export async function backfillFromChannel(jukeboxChannel, store = { addTrack, restoreTrackTitles }) {
  let added   = 0;
  let lastId  = undefined;
  const titles = [];

  console.log(`[jukeloop] Backfilling historic uploads from #${jukeboxChannel.name ?? jukeboxChannel.id}…`);

  // eslint-disable-next-line no-constant-condition
  while (true) {
    /** @type {import('discord.js').Collection<string, import('discord.js').Message>} */
    const batch = await jukeboxChannel.messages
      .fetch(lastId ? { limit: 100, before: lastId } : { limit: 100 })
      .catch(() => null);

    if (!batch || batch.size === 0) break;

    for (const msg of batch.values()) {
      if (msg.author.bot) continue;

      for (const attachment of msg.attachments.values()) {
        if (!AUDIO_EXTENSIONS_RE.test(attachment.name ?? '')) continue;

        if (!isDiscordAttachmentWithinLimit(attachment)) continue;

        const filename = attachment.name;
        const title    = getAttachmentTitle(attachment);
        titles.push({ trackId: attachment.id, legacyTrackId: `${msg.id}:${filename}`, title });

        const wasAdded = store.addTrack({
          attachmentId: attachment.id,
          messageId:  msg.id,
          channelId:  jukeboxChannel.id,
          filename,
          title,
          uploader:   msg.author.tag ?? msg.author.username ?? 'Unknown',
          uploaderId: msg.author.id,
          pinStatus:  'untracked',
        });

        if (wasAdded) added++;
      }
    }

    lastId = batch.last()?.id;
    if (batch.size < 100) break;
  }

  const retitled = store.restoreTrackTitles(titles);
  if (retitled) console.log(`[jukeloop] Restored ${retitled} original track title(s) with emoji/accents.`);
  console.log(`[jukeloop] Backfill complete — added ${added} new track(s).`);
  return added;
}

import { createRequire } from 'node:module';
import { readFile } from 'node:fs/promises';
import { LiveAudioError } from './live-audio-errors.js';
import { LiveDirectionError } from './live-direction.js';

let clientScript;
async function body(request) {
  let text = '';
  for await (const chunk of request) {
    text += chunk;
    if (Buffer.byteLength(text) > 32 * 1024) throw new Error('Room request is too large');
  }
  return JSON.parse(text || '{}');
}

export async function handleLiveAudioRequest(request, response, { service, allowedOrigins = [] }) {
  const url = new URL(request.url, 'http://localhost');
  if (!url.pathname.startsWith('/api/live-audio/')) return false;
  const origin = String(request.headers.origin || '');
  const allowed = allowedOrigins.includes(origin);
  const headers = { 'content-type': 'application/json', 'cache-control': 'no-store',
    ...(allowed ? { 'access-control-allow-origin': origin, vary: 'origin' } : {}) };
  const send = (status, data) => { response.writeHead(status, headers); response.end(JSON.stringify(data)); };
  if (request.method === 'OPTIONS') {
    response.writeHead(allowed ? 204 : 403, { ...headers,
      'access-control-allow-methods': 'GET, POST, OPTIONS', 'access-control-allow-headers': 'content-type, authorization' });
    response.end(); return true;
  }
  try {
    if (request.method === 'GET' && url.pathname === '/api/live-audio/client.js') {
      clientScript ||= await readFile(createRequire(import.meta.url).resolve('livekit-client'));
      response.writeHead(200, { 'content-type': 'application/javascript', 'cache-control': 'public, max-age=3600',
        'access-control-allow-origin': '*', 'x-content-type-options': 'nosniff' });
      response.end(clientScript); return true;
    }

  if (!service?.configured) { send(503, { error: 'Live audio is not configured', status: 'OFF-AIR' }); return true; }
  if (request.method === 'GET' && url.pathname === '/api/live-audio/state') {
    send(200, await service.state(url.searchParams.get('bookingId'))); return true;
  }
  if (!allowed) { send(403, { error: 'Room origin is not allowed' }); return true; }
  if (request.method !== 'POST') { send(405, { error: 'Room action requires POST' }); return true; }
  const input = await body(request);
  if (url.pathname === '/api/live-audio/recording-preview') send(200, await service.previewRecording(input, origin));
  else if (url.pathname === '/api/live-audio/recording-publish') send(200, await service.publishRecording(input, origin));
  else if (url.pathname === '/api/live-audio/challenge') send(200, await service.challenge(input, origin));
  else if (url.pathname === '/api/live-audio/session') send(200, await service.authorize(input, origin));
  else if (url.pathname === '/api/live-audio/control') {
    const token = String(request.headers.authorization || '').replace(/^Bearer /, '');
    send(200, await service.command(token, input, origin));
  } else if (url.pathname === '/api/live-audio/listen') send(200, await service.listener(input.bookingId, input.telemetryPageId, input.transport));
  else send(404, { error: 'Unknown room route' });
} catch (error) {
  // Never return provider errors: they can contain stream keys, tokens or signed URLs.
  if (!(error instanceof LiveAudioError)) console.warn('[live-audio] Request failed:', {
    route: ['/api/live-audio/recording-preview', '/api/live-audio/recording-publish',

        '/api/live-audio/session', '/api/live-audio/challenge', '/api/live-audio/control'].includes(url.pathname) ? url.pathname : 'other',
      kind: ['Error', 'TypeError', 'RangeError', 'SyntaxError', 'AbortError', 'TimeoutError'].includes(error.name) ? error.name : 'Error',
      code: ['ECONNRESET', 'ECONNREFUSED', 'ENOTFOUND', 'EAI_AGAIN', 'ETIMEDOUT', 'ENOENT', 'EACCES',
        'EPIPE', 'UND_ERR_CONNECT_TIMEOUT', 'UND_ERR_HEADERS_TIMEOUT', 'UND_ERR_SOCKET'].includes(error.code) ? error.code : undefined,
    });
    send(error instanceof LiveDirectionError ? error.status : 400,
      { error: error instanceof LiveAudioError ? error.message : 'Live audio request unavailable; retry or contact the operator',
        ...(error instanceof LiveDirectionError ? { code: error.code } : {}) });
  }
  return true;
}

import { createCipheriv, createDecipheriv, randomBytes } from 'node:crypto';
import { createPinataStateStore } from './ipfs-state.js';
import { validateLiveAllocation } from '../js/live-broadcast.mjs';
import { validateLiveRecovery } from '../js/live-recovery.mjs';

export const LIVE_AUDIO_STATE_NAME = 'decentbusking-live-audio-encrypted.json';
export const LIVE_AUDIO_STATE_TAGS = Object.freeze({ app: 'decentbusking', kind: 'live-audio-encrypted', schema: '1' });
const SCHEMA = 'encrypted-live-audio-v1';
const AAD = Buffer.from('dbusk-live-audio-state-v1');
const ROOM_KEYS = new Set(['bookingId', 'armed', 'checks', 'lastVerifiedAt', 'lossSince', 'cancelledAt', 'reason', 'cancelNoticePending', 'allocation', 'broadcastCommands', 'recovery']);
const CHECK_KEYS = new Set(['t60', 't15']);
const MAX_ROOMS = 500;

const time = value => value === undefined || (Number.isSafeInteger(value) && value >= 0);

// Allowlist only lifecycle facts so grants, session tokens or ingress endpoints can never be checkpointed.
export function validateLiveAudioState(state) {
  if (!state || typeof state !== 'object' || Array.isArray(state) || Object.keys(state).some(key => !['version', 'rooms'].includes(key)) ||
      state.version !== 1 || !Array.isArray(state.rooms) || state.rooms.length > MAX_ROOMS) {
    throw new Error('Invalid live audio checkpoint');
  }
  const seen = new Set();
  for (const room of state.rooms) {
    if (!room || typeof room !== 'object' || Array.isArray(room) || Object.keys(room).some(key => !ROOM_KEYS.has(key)) ||
        typeof room.bookingId !== 'string' || !room.bookingId || room.bookingId.length > 200 || seen.has(room.bookingId) ||
        typeof room.armed !== 'boolean' || !room.checks || typeof room.checks !== 'object' || Array.isArray(room.checks) ||

        Object.entries(room.checks).some(([key, value]) => !CHECK_KEYS.has(key) || typeof value !== 'string' || !Number.isFinite(Date.parse(value))) ||
        ![room.lastVerifiedAt, room.lossSince, room.cancelledAt].every(time) ||
        (room.reason !== undefined && (typeof room.reason !== 'string' || room.reason.length > 500)) ||
        (room.cancelledAt && !room.reason) ||
        (room.cancelNoticePending !== undefined && typeof room.cancelNoticePending !== 'boolean')) {
      throw new Error('Invalid live audio checkpoint');
    }
    if (room.allocation !== undefined) validateLiveAllocation(room.allocation);
    if (room.recovery !== undefined) validateLiveRecovery(room.recovery, room);
    if (room.broadcastCommands !== undefined && (!Array.isArray(room.broadcastCommands) || room.broadcastCommands.length > 128 ||
        room.broadcastCommands.some(c => !c || Object.keys(c).some(k => !['id', 'hash'].includes(k)) ||
          !/^[a-zA-Z0-9:_-]{8,100}$/.test(c.id || '') || !/^[a-f0-9]{64}$/.test(c.hash || '')) ||
        new Set(room.broadcastCommands.map(c => c.id)).size !== room.broadcastCommands.length)) {
      throw new Error('Invalid live broadcast command receipts');
    }
    seen.add(room.bookingId);
  }
  if (state.rooms.filter(r => r.allocation?.startedAt && !r.allocation.endedAt && !r.cancelledAt).length > 1) {
    throw new Error('Multiple active broadcast allocations');
  }
  return state;
}

export function liveAudioStateCodec(keyHex, { distinctFrom = [] } = {}) {
  if (!/^[0-9a-f]{64}$/i.test(keyHex || '')) throw new Error('LIVE_AUDIO_STORAGE_KEY must be 32 random bytes in hex, privately backed up');
  if (distinctFrom.some(other => typeof other === 'string' && other.toLowerCase() === keyHex.toLowerCase())) {

    throw new Error('LIVE_AUDIO_STORAGE_KEY must be dedicated, not reused from another store');
  }
  const key = Buffer.from(keyHex, 'hex');
  return {
    serialize(value) {
      const iv = randomBytes(12);
      const cipher = createCipheriv('aes-256-gcm', key, iv);
      cipher.setAAD(AAD);
      const data = Buffer.concat([cipher.update(JSON.stringify(validateLiveAudioState(value))), cipher.final()]);
      return { schema: SCHEMA, iv: iv.toString('hex'), tag: cipher.getAuthTag().toString('hex'), data: data.toString('base64') };
    },
    deserialize(value) {
      if (value?.schema !== SCHEMA || !/^[0-9a-f]{24}$/.test(value.iv || '') || !/^[0-9a-f]{32}$/.test(value.tag || '') ||
          typeof value.data !== 'string') throw new Error('Invalid encrypted live audio checkpoint');
      const decipher = createDecipheriv('aes-256-gcm', key, Buffer.from(value.iv, 'hex'));
      decipher.setAAD(AAD);
      decipher.setAuthTag(Buffer.from(value.tag, 'hex'));
      return validateLiveAudioState(JSON.parse(Buffer.concat([decipher.update(Buffer.from(value.data, 'base64')), decipher.final()]).toString()));
    },
  };
}

/**
 * Durable live-audio lifecycle store: encrypted Pinata checkpoints, locally mirrored by default.
 * restore() resolves only an empty state when no checkpoint exists; any listing, gateway, decryption or schema
 * failure rejects so the service stays closed. Hosted mode instead verifies the latest encrypted readback.
 */
export function createLiveAudioPinataStore({ storageKey, distinctFrom = [], checkpointMirror, pinataJwt,
  hostedVerified = false, ...pinata } = {}) {
  if (!hostedVerified && (!checkpointMirror || typeof checkpointMirror.mirror !== 'function')) {
    throw new Error('Live audio state requires the existing checkpoint mirror');
  }

  const codec = liveAudioStateCodec(storageKey, { distinctFrom });
  const store = createPinataStateStore({ ...pinata, pinataJwt, name: LIVE_AUDIO_STATE_NAME, tags: LIVE_AUDIO_STATE_TAGS,
    // Never fall back to an older room checkpoint: it could reopen a cancelled room or forget checks/arming.
    restoreLatestOnly: true, rejectAmbiguousLatest: true, requireLocalMirror: !hostedVerified, ...codec,
    beforeUpload: hostedVerified ? undefined : (bytes, options) => checkpointMirror.mirror(bytes, options) });
  return {
    async restore() {
      const restored = await store.restore();
      return restored === null ? { version: 1, rooms: [] } : restored;
    },
    async save(value) {
      const uri = await store.save(validateLiveAudioState(value));
      if (!/^ipfs:\/\/\S+$/.test(uri || '')) throw new Error('Live audio checkpoint did not confirm');
      if (hostedVerified) {
        const restored = await store.restore();
        if (store.getLatestSnapshotUri() !== uri || JSON.stringify(restored) !== JSON.stringify(value)) {
          throw new Error('Latest live audio checkpoint was not verified');
        }
      }
      return uri;
    },
    close: () => store.close(),
    getLatestSnapshotUri: () => store.getLatestSnapshotUri(),
  };
}

import { createHash, randomUUID } from 'node:crypto';
import { AccessToken, RoomServiceClient, IngressClient, IngressInput, TrackSource } from 'livekit-server-sdk';
import { LiveAudioError } from './live-audio-errors.js';

export function liveAudioRoomName(bookingId) {
  return `dbusk-audio-${createHash('sha256').update(String(bookingId)).digest('hex').slice(0, 32)}`;
}
export function rehearsalRoomName(id) {
  return `dbusk-rehearsal-${createHash('sha256').update(String(id)).digest('hex').slice(0, 32)}`;
}

export function receivedAudioPackets(stats) {
  // rtc-node can report inbound media on either peer connection's stats list.
  return [...(stats?.subscriberStats || []), ...(stats?.publisherStats || [])].reduce((total, entry) => {
    const rtp = entry.stats?.case === 'inboundRtp' ? entry.stats.value : null;
    return rtp?.stream?.kind === 'audio' ? total + BigInt(rtp.received?.packetsReceived || 0) : total;
  }, 0n);
}

export function createLiveAudioTransport({ url = '', apiKey = '', apiSecret = '', enabled = false,
  ingressEnabled = false, listenerLimit = 10, roomClient, ingressClient, rtcLoader = () => import('@livekit/rtc-node'), now = () => Date.now() } = {}) {
  if (!Number.isInteger(listenerLimit) || listenerLimit < 1 || listenerLimit > 90) throw Error('Live listener limit must be between 1 and 90');
  const ready = enabled && /^wss:\/\/[a-z0-9.-]+\.livekit\.cloud\/?$/i.test(url) && !!apiKey && !!apiSecret;
  const host = url.replace(/^wss:/, 'https:');
  const rooms = roomClient || (ready ? new RoomServiceClient(host, apiKey, apiSecret, { requestTimeout: 5 }) : null);
  const ingress = ingressClient || (ready ? new IngressClient(host, apiKey, apiSecret, { requestTimeout: 5 }) : null);
  const monitors = new Map();
  const suspendedListeners = new Set();

const publisherIdentity = booking => `performer:${booking.wallet.toLowerCase()}`;
const roomName = booking => booking.rehearsal === true ? rehearsalRoomName(booking.id) : liveAudioRoomName(booking.id);
const requireReady = () => { if (!ready) throw new LiveAudioError('Live audio hosting is not configured'); };
async function grant(booking, identity, publish = false, subscribe = !publish) {
  requireReady();
  const remaining = Math.floor(((booking.broadcast?.accessUntil ?? Date.parse(booking.endUtc)) - now()) / 1000);
  if (remaining <= 0) throw new LiveAudioError('This live room has reached its booked end');
  const token = new AccessToken(apiKey, apiSecret, { identity, ttl: Math.min(30, remaining) });
  token.addGrant({ roomJoin: true, room: roomName(booking), canPublish: publish,
    canPublishSources: publish ? [TrackSource.MICROPHONE] : [], canSubscribe: subscribe, canPublishData: false });
  return { url, token: await token.toJwt(), ...(booking.rehearsal === true ? {} : { publisherIdentity: publisherIdentity(booking) }) };
}
async function ensureRoom(booking) {
  requireReady();
  await rooms.createRoom({ name: roomName(booking), emptyTimeout: 60, departureTimeout: 20,
    // Shared rehearsal: up to six people plus the independent delivery receiver.
    maxParticipants: booking.rehearsal === true ? 8 : listenerLimit + 3,
    metadata: JSON.stringify({ purpose: booking.rehearsal === true ? 'DecentBusking private rehearsal' : 'DecentBusking audio pilot',
      bookingId: booking.id }) });
}
async function revokeIngress(booking) {
  const existing = await ingress.listIngress({ roomName: roomName(booking) });
  for (const item of existing) await ingress.deleteIngress(item.ingressId);
}

async function monitor(booking, onFrame, onPcm) {
  requireReady();
  if (monitors.has(booking.id)) return;
  const state = { room: null, closed: false, readers: new Map(), decodedAt: 0, decodedBy: new Map(), statsTimer: null,
    decodedLogged: false, statsLogged: false };
  const isSource = identity => booking.rehearsal === true ? identity.startsWith('rehearsal:') : identity === publisherIdentity(booking);
  monitors.set(booking.id, state);
  try {
    await ensureRoom(booking);
    const { Room, AudioStream, TrackKind } = await rtcLoader();
    if (state.closed) return;
    const room = new Room();
    state.room = room;
    room.on('participantConnected', participant => {
      if (suspendedListeners.has(booking.id) && participant.identity.startsWith('listener:')) {
        void rooms.removeParticipant(roomName(booking), participant.identity).catch(() => {});
      }
    });
    const subscribe = (publication, participant) => {
      if (isSource(participant.identity) && publication.kind === TrackKind.KIND_AUDIO) {
        publication.setSubscribed(true);
      }
    };
    room.on('trackPublished', subscribe);
    room.on('trackSubscribed', (track, publication, participant) => {
      if (state.closed || !isSource(participant.identity) || track.kind !== TrackKind.KIND_AUDIO) return;
      const reader = new AudioStream(track, { sampleRate: 48000, numChannels: 1 }).getReader();
      state.readers.set(publication.sid, reader);
      void (async () => {
        try {
          while (!state.closed) {
            const { value: frame, done } = await reader.read();
            if (done) break;
            // Zero-valued PCM is valid delivered silence, not a disconnection.

        if (frame.samplesPerChannel > 0 && frame.data?.length) {
          state.decodedAt = now(); state.decodedBy.set(participant.identity, state.decodedAt);
          onPcm?.(frame);
          if (!state.decodedLogged) {
            state.decodedLogged = true;
            console.info('[live-audio-receiver] First decoded audio frame');
          }
        }
      }
    } catch (error) {
      if (!state.closed) console.warn('[live-audio-receiver] Audio reader unavailable:', error.code || error.name || 'reader error');
    }
    finally { state.readers.delete(publication.sid); await reader.cancel().catch(() => {}); }
  })();
});
room.on('trackUnsubscribed', (_track, publication) => {
  void state.readers.get(publication.sid)?.cancel().catch(() => {});
});
room.on('disconnected', () => { void stopMonitor(booking.id); });
const auth = await grant(booking, `health:${booking.id}`);
await room.connect(url, auth.token, { autoSubscribe: false, dynacast: false,
  dataStream: { maxPayloadByteLength: 1024 } });
console.info('[live-audio-receiver] Independent receiver connected');
if (state.closed) { await room.disconnect(); return; }
for (const participant of room.remoteParticipants.values()) {
  if (suspendedListeners.has(booking.id) && participant.identity.startsWith('listener:')) {
    await rooms.removeParticipant(roomName(booking), participant.identity);
    continue;
  }
  for (const publication of participant.trackPublications.values()) subscribe(publication, participant);
}
let packets = 0n, checking = false;
state.statsTimer = setInterval(async () => {

      if (checking || state.closed) return;
      checking = true;
      try {
        const stats = await room.getRtcStats();
        const next = receivedAudioPackets(stats);
        if (!state.statsLogged && state.decodedAt) {
          state.statsLogged = true;
          console.info('[live-audio-receiver] Packet evidence:', JSON.stringify({
            receivedPackets: String(next),
            subscriberKinds: (stats.subscriberStats || []).map(entry => entry.stats?.case),
            publisherKinds: (stats.publisherStats || []).map(entry => entry.stats?.case),
          }));
        }
        if (!state.closed && next > packets && now() - state.decodedAt < 2000) {
          onFrame({ samples: 1, sources: [...state.decodedBy].filter(([, at]) => now() - at < 2000).map(([id]) => id) });
        }
        packets = next;
      } catch { /* Transport counters, not amplitude or concealed frames, establish freshness. */ }
      finally { checking = false; }
    }, 1000);
    state.statsTimer.unref?.();
  } catch (error) {
    await stopMonitor(booking.id);
    throw error;
  }
}
async function stopMonitor(bookingId) {
  const state = monitors.get(bookingId);
  if (!state) return;
  monitors.delete(bookingId);
  state.closed = true;
  clearInterval(state.statsTimer);
  for (const reader of state.readers.values()) void reader.cancel().catch(() => {});
  await state.room?.disconnect().catch(() => {});
}
return {
  ready, listenerLimit, ingressEnabled: ready && ingressEnabled, ensureRoom, monitor,
  publisherIdentity,
  async connect(booking, role) {
    await ensureRoom(booking);
    if (role === 'publisher' && ingressEnabled) await revokeIngress(booking);

  return grant(booking, role === 'publisher' ? publisherIdentity(booking) : `owner:${randomUUID()}`, role === 'publisher');
},
async rehearsalConnect(booking, wallet, publish) {
  await ensureRoom(booking);
  const identity = `rehearsal:${wallet.toLowerCase()}`;
  return { ...(await grant(booking, identity, publish, true)), identity };
},
async rehearsalRemove(booking, wallet) {
  requireReady();
  try { await rooms.removeParticipant(roomName(booking), `rehearsal:${wallet.toLowerCase()}`); }
  catch (error) { if (error.code !== 'not_found' && error.status !== 404) throw error; }
},
async listener(booking) {
  requireReady();
  if (suspendedListeners.has(booking.id)) throw new LiveAudioError('This performer is privately recovering; public listening is suspended');
  const participants = await rooms.listParticipants(roomName(booking));
  if (participants.filter(p => p.identity.startsWith('listener:')).length >= listenerLimit) throw new LiveAudioError(`The ${listenerLimit}-listener live room is full`);
  return grant(booking, `listener:${randomUUID()}`);
},
async suspendListeners(booking) {
  requireReady();
  suspendedListeners.add(booking.id);
  const participants = await rooms.listParticipants(roomName(booking));
  await Promise.all(participants.filter(p => p.identity.startsWith('listener:')).map(async p => {
    try { await rooms.removeParticipant(roomName(booking), p.identity); }
    catch (error) { if (error.code !== 'not_found' && error.status !== 404) throw error; }
  }));
},
resumeListeners(booking) { suspendedListeners.delete(booking.id); },
async obs(booking) {
  requireReady();

      if (!ingressEnabled) throw new LiveAudioError('OBS ingress is disabled; hosting quota must be approved first');
      await ensureRoom(booking);
      await revokeIngress(booking);
      const result = await ingress.createIngress(IngressInput.WHIP_INPUT, {
        name: `DecentBusking audio ${booking.id}`, roomName: roomName(booking),
        participantIdentity: publisherIdentity(booking), participantName: 'Live performer',
        enableTranscoding: false,
      });
      return { protocol: 'WHIP', whipEndpoint: `${result.url.replace(/\/$/, '')}/${encodeURIComponent(result.streamKey)}`,
        notice: 'Private OBS WHIP endpoint includes the stream key. Use Opus audio; leave Bearer Token empty. Never publish or log this endpoint.' };
    },
    async close(booking) {
      requireReady();
      await stopMonitor(booking.id);
      let ingressError;
      if (ingressEnabled) {
        try { await revokeIngress(booking); } catch (error) { ingressError = error; }
      }
      try { await rooms.deleteRoom(roomName(booking)); }
      catch (error) { if (error.code !== 'not_found' && error.status !== 404) throw error; }
      if (ingressError) throw ingressError;
    },
    async stop() { await Promise.all([...monitors.keys()].map(stopMonitor)); },
  };
}

