    async restore() {
      try { return JSON.parse(await readFile(path, 'utf8')); }
      catch (error) { if (error.code === 'ENOENT') return { version: 1, rooms: [] }; throw error; }
    },
    async save(value) {
      await writeFile(`${path}.next`, JSON.stringify(value), { mode: 0o600 });
      await rename(`${path}.next`, path);
