    baseUrl: base.origin,
    async put(key, bytes, type) {
      if (!/^[a-f0-9]{32}\/(?:index\.m3u8|state\.json|segment-\d{9}\.ts)$/.test(key)) throw new Error('Invalid broadcast object');
      const deadline = AbortSignal.timeout(8000);
      for (let attempt = 0; attempt < 3; attempt++) {
        try {
