        const result = await send({ automatic: true, payload: built.draft, nonce: built.draft.requestId,
          contentHash: await announcementHash(built.draft), expiresAt: event.startUtc }, dest);
        lastReminder = result.delivery;
        reminderError = null;
        reminderRetryAt = 0;
      });
      queue = operation.catch(() => {});
      await operation;
    }
  })().catch(error => {
    if (now() >= reminderRetryAt) log.error(`[radio-reminder] ${error.message}`);
    reminderError = error.message;
    reminderRetryAt = Math.max(reminderRetryAt, now() + 60_000);
  }).finally(() => { reminderTask = null; });
  return reminderTask;
},
async handle(action, body, origin) {
await ready;
const expires = Date.parse(body.expiresAt);
if (!['options', 'preview', 'send'].includes(action) || !/^0x[\da-f]{40}$/i.test(body.address || '') ||

    !/^[\da-f-]{16,100}$/i.test(body.nonce || '') || !Number.isFinite(expires) || expires <= now() || expires > now() + 300_000 ||
    body.contentHash !== await announcementHash(body.payload)) throw new Error('Invalid or expired announcement authorization');
const message = announcementAuthorization({ ...body, action, origin, occurrenceId: body.payload.occurrenceId, startUtc: body.payload.startUtc });
const recovered = verifyMessage(message, body.signature).toLowerCase();
if (recovered !== body.address.toLowerCase() || recovered !== ownerWallet.toLowerCase()) throw new Error('Announcement authorization is not from the radio owner');
if (restoreError) throw new Error(`Announcements disabled: ${restoreError.message}`);
for (const [nonce, entry] of seen) if (entry.expires < now()) seen.delete(nonce);
const binding = `${action}:${body.contentHash}`;
if (seen.has(body.nonce) && seen.get(body.nonce).binding !== binding) throw new Error('Nonce already used');
seen.set(body.nonce, { binding, expires });
const dest = await destination();
if (action === 'options') {
  const roles = [...dest.channel.guild.roles.cache.values()].filter(role => role.id !== dest.channel.guild.id && role.mentionable && !role.managed)
    .map(role => ({ id: role.id, name: role.name }));
  const defaults = { everyone: defaultMention === 'everyone', roles: defaultMention === 'everyone' || defaultMention === 'none' ? [] : defaultMention.split(',').map(id => id.trim()) };
  announcementMentions(defaults, dest.channel.guild);
  return { channelId, channelName: dest.channel.name, roles, defaultMentions: defaults, deliveries: state.deliveries };
}
if (action === 'preview') {
  const built = await draftFor(body.payload, dest);

      return { ...built, contentHash: await announcementHash(built.draft), channelName: dest.channel.name,
        lastAnnouncement: lastDelivery(built.draft.occurrenceId) };
    }
    if (!body.payload.requestId) throw new Error('Preview and explicitly confirm before sending');
    const result = queue.then(() => send({ ...body, automatic: false, nonce: body.payload.requestId }, dest));
    queue = result.catch(() => {});
    return result;
  } };
}

export function createRadioDeploymentGate({ getSession, getLiveHandoff = () => ({ ready: true }),
  now = () => Date.now(), leaseMs = 120000 } = {}) {
  let deploymentId = null, expiresAt = 0;
  return async ({ action, id }) => {
    if (!/^[a-zA-Z0-9:_-]{1,100}$/.test(id || '') || !['drain', 'cancel'].includes(action)) {
      throw new Error('Invalid radio deployment handoff');
    }
    if (deploymentId && expiresAt > now() && deploymentId !== id) {
      throw new Error('Another deployment holds the radio handoff');
    }
    const session = getSession();
    if (!session) throw new Error('Radio worker is not ready for deployment handoff');
    if (action === 'cancel') {
      expiresAt = 0; deploymentId = null;
      try { await getLiveHandoff({ action, id, expiresAt: 0 }); }
      finally { await session.drainForDeployment(0); }
      return { draining: false, ready: false };
    }
    deploymentId = id;
    expiresAt = now() + leaseMs;
    let status = await session.drainForDeployment(expiresAt);
    const liveHandoff = await getLiveHandoff({ action, id, expiresAt });
    if (!liveHandoff || typeof liveHandoff.ready !== 'boolean') throw new Error('Live recording handoff is not verified');
    status = { ...status, ready: status.ready && liveHandoff.ready,
      ...(liveHandoff.recordingCheckpointVerified === true ? { recordingCheckpointVerified: true } : {}),
      ...(liveHandoff.ready ? {} : { liveRecordingPending: true }) };
    if (status.ready) {
      expiresAt = now() + 15 * 60_000;
      status = await session.drainForDeployment(expiresAt);
      const extended = await getLiveHandoff({ action, id, expiresAt });
      if (!extended || typeof extended.ready !== 'boolean') throw new Error('Live recording handoff extension is not verified');

      status = { ...status, ready: status.ready && extended.ready,
        ...(extended.recordingCheckpointVerified === true ? { recordingCheckpointVerified: true } : {}),
        ...(extended.ready ? {} : { liveRecordingPending: true }) };
    }
    return { ...status, deploymentId };
  };
}

import { mkdtemp, rm } from 'node:fs/promises';
import { createWriteStream } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Readable, Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';

/** Finish the HTTP transfer before a real-time decoder can backpressure the gateway. */
export async function bufferRadioMedia(url, { fetchImpl = fetch, signal,
  maxBytes = 256 * 1024 * 1024, timeoutMs = 90_000 } = {}) {
  const directory = await mkdtemp(join(tmpdir(), 'dbusk-paid-media-'));
  const path = join(directory, 'recording');
  const dispose = () => rm(directory, { recursive: true, force: true });
  try {
    const transferSignal = signal
      ? AbortSignal.any([signal, AbortSignal.timeout(timeoutMs)])
      : AbortSignal.timeout(timeoutMs);
    const response = await fetchImpl(url, { signal: transferSignal });
    if (response.status !== 200 || !response.body) {
      await response.body?.cancel();
      throw new Error(`Paid media download failed (HTTP ${response.status})`);
    }
    const length = response.headers.get('content-length');
    const expected = length === null ? null : Number(length);
    if (expected !== null && (!Number.isSafeInteger(expected) || expected < 1 || expected > maxBytes)) {
      await response.body.cancel();
      throw new Error('Paid media download exceeds the size limit or has an invalid length');
    }
    let bytes = 0;
    const limit = new Transform({
      transform(chunk, encoding, callback) {
        bytes += chunk.length;
        callback(bytes > maxBytes ? new Error('Paid media download exceeds the size limit') : null, chunk);
      },
    });
    await pipeline(Readable.fromWeb(response.body), limit, createWriteStream(path, { flags: 'wx' }),

      { signal: transferSignal });
    if (bytes === 0 || (expected !== null && bytes !== expected)) throw new Error('Paid media download was incomplete');
    return { path, bytes, dispose };
  } catch (error) {
    await dispose();
    throw error;
  }
}

import { randomUUID } from 'node:crypto';
import { pathToFileURL } from 'node:url';

export async function waitForRadioDeployment({ serviceUrl, secret, legacySecret, id = randomUUID(), fetchImpl = fetch,
  now = () => Date.now(), sleep = ms => new Promise(resolve => setTimeout(resolve, ms)),
  timeoutMs = 25 * 60_000, log = console } = {}) {
  // The running worker may predate RADIO_DEPLOY_SECRET, so a refused dedicated secret
  // falls back once to the legacy one; the worker decides which it accepts.
  const secrets = [...new Set([secret, legacySecret])].filter(value => value && value.length >= 32);
  if (!/^https:\/\/[a-z0-9.-]+$/i.test(serviceUrl || '') || !secrets.length) {
    throw new Error('An existing HTTPS radio service and deployment authorization are required');
  }
  const deadline = now() + timeoutMs;
  while (now() < deadline) {
    let response;
    try {
      response = await fetchImpl(`${serviceUrl}/api/radio/deployment`, {
        method: 'POST', headers: { authorization: `Bearer ${secrets[0]}`, 'content-type': 'application/json' },
        body: JSON.stringify({ action: 'drain', id }), signal: AbortSignal.timeout(60000), redirect: 'error' });
    } catch (error) {
      log.info(`[radio-deploy] Radio handoff check did not answer (${error.name || 'network error'}); retrying, no audio was stopped.`);
      await sleep(5000);
      continue;
    }
    // A slow drain can outlast the platform proxy; the gateway error is not the worker refusing.
    if ([502, 503, 504].includes(response.status)) {
      log.info(`[radio-deploy] Radio handoff gateway returned ${response.status}; retrying, no audio was stopped.`);
      await sleep(5000);
      continue;
    }
    if (response.status === 403 && secrets.length > 1) {
      secrets.shift();

      log.info('[radio-deploy] Running worker refused RADIO_DEPLOY_SECRET; retrying with the legacy authorization.');
      continue;
    }
    if (!response.ok) throw new Error(`Radio handoff refused (${response.status}); deployment must not restart paid playback`);
    const status = await response.json();
    if (status.deploymentId !== id || !status.draining || !(status.expiresAt > now())) {
      throw new Error('Radio handoff lease is not verified; refusing deployment');
    }
    if (status.ready === true) {
      log.info('[radio-deploy] Paid playback drained; new purchases remain queued until the replacement worker starts.');
      return status;
    }
    log.info(`[radio-deploy] Waiting for protected paid playback${status.activePlaylistBatchId
      ? ` in playlist ${status.activePlaylistBatchId}` : ''}${status.liveRecordingPending
      ? ' and live performance recording' : ''}; no audio was stopped.`);
    await sleep(2000);
  }
  throw new Error('Radio handoff timed out; leave the current worker playing and retry deployment later');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    await waitForRadioDeployment({ serviceUrl: process.env.RENDER_EXTERNAL_URL || process.env.PUBLIC_WORKER_URL,
      secret: process.env.RADIO_DEPLOY_SECRET, legacySecret: process.env.CHECKPOINT_MIRROR_SECRET, id: process.env.RENDER_GIT_COMMIT || randomUUID() });
  } catch (error) {
    console.error(`[radio-deploy] ${error.message}`);
    process.exitCode = 1;
  }
}

import { monitorEventLoopDelay } from 'node:perf_hooks';
import { readFile } from 'node:fs/promises';
import { Session } from 'node:inspector';

export function summarizeRadioCpuProfile(profile) {
  const nodes = new Map(profile.nodes.map(node => [node.id, node]));
  const parents = new Map();
  for (const node of profile.nodes) for (const child of node.children || []) parents.set(child, node.id);
  const root = new URL('.', import.meta.url).href, totals = new Map();
  for (const [index, id] of (profile.samples || []).entries()) {
    let node = nodes.get(id);
    const runtimeName = ['(idle)', '(garbage collector)', '(program)'].includes(node?.callFrame.functionName)
      ? node.callFrame.functionName : '(runtime)';
    while (node && !node.callFrame.url.startsWith(root)) node = nodes.get(parents.get(node.id));
    const frame = node?.callFrame;
    const file = frame ? frame.url.slice(root.length).slice(0, 200) : '(runtime)';
    const line = frame ? frame.lineNumber + 1 : 0;
    const name = frame ? frame.functionName.slice(0, 100) || '(anonymous)' : runtimeName;
    const key = `${file}:${line}:${name}`;
    const entry = totals.get(key) || { file, line, function: name, sampledMs: 0 };
    entry.sampledMs += (profile.timeDeltas?.[index] || 0) / 1000;
    totals.set(key, entry);
  }
  return [...totals.values()].sort((a, b) => b.sampledMs - a.sampledMs).slice(0, 10);
}

function createRadioCpuDiagnostics(log) {
  const session = new Session();
  const post = (method, params = {}) => new Promise((resolve, reject) =>
    session.post(method, params, (error, result) => error ? reject(error) : resolve(result)));
  let closed = false, windows = 0;
  const close = async () => {
    if (closed) return;
    closed = true;

    try { await post('Profiler.disable'); } finally { session.disconnect(); }
  };
  session.connect();
  const ready = post('Profiler.enable').then(() => post('Profiler.setSamplingInterval', { interval: 10000 }))
    .then(() => post('Profiler.start'));
  const failed = async () => {
    log.error('[radio-resources] CPU_PROFILE_FAILED');
    await close().catch(() => log.error('[radio-resources] CPU_PROFILE_STOP_FAILED'));
  };
  void ready.catch(failed);
  return {
    async sample(maxDelayMs) {
      if (closed) return;
      try {
        await ready;
        const { profile } = await post('Profiler.stop');
        if (maxDelayMs > 500) log.info('[radio-cpu-stall]', JSON.stringify({
          eventLoopMaxMs: maxDelayMs, top: summarizeRadioCpuProfile(profile),
        }));
        if (++windows >= 10) await close();
        else await post('Profiler.start');
      } catch { await failed(); }
    },
    stop: () => { void ready.then(close).catch(failed); },
  };
}

export async function readContainerResources({ platform = process.platform, read = readFile } = {}) {
  if (platform !== 'linux') return { available: false, reason: 'Container quotas are not available on this platform' };
  try {
    const [cpu, quota, memory, limit, stat] = await Promise.all([
      ...['cpu.stat', 'cpu.max', 'memory.current', 'memory.max'].map(name => read(`/sys/fs/cgroup/${name}`, 'utf8')),
      read('/sys/fs/cgroup/memory.stat', 'utf8').catch(error => {
        if (!['ENOENT', 'ENOTDIR'].includes(error.code)) console.warn('[radio-resources] MEMORY_BREAKDOWN_UNREADABLE');
        return null;
      }),
    ]);
    const [allocation, period] = quota.trim().split(/\s+/);
    const usage = cpu.match(/^usage_usec (\d+)$/m);

    if (!usage || !Number.isFinite(Number(memory)) || Number(memory) < 0 ||
        allocation !== 'max' && (!(Number(allocation) > 0) || !(Number(period) > 0)) ||
        limit.trim() !== 'max' && !(Number(limit) > 0)) throw new Error('Invalid container resource counters');
    let memoryBreakdown = { available: false };
    if (stat !== null) {
      const counters = Object.fromEntries([...stat.matchAll(/^([a-z_]+) (\d+)$/gm)].map(([, key, value]) => [key, Number(value)]));
      if (['anon', 'file', 'inactive_file'].every(key => Number.isSafeInteger(counters[key]) && counters[key] >= 0)) {
        memoryBreakdown = { available: true, anonymousBytes: counters.anon, fileBytes: counters.file,
          inactiveFileBytes: counters.inactive_file };
      } else console.warn('[radio-resources] MEMORY_BREAKDOWN_UNREADABLE');
    }
    return { available: true, cpuUsageUs: Number(usage[1]), memoryBreakdown,
      cpuLimitCores: allocation === 'max' ? null : Number(allocation) / Number(period),
      memoryBytes: Number(memory), memoryLimitBytes: limit.trim() === 'max' ? null : Number(limit) };
  } catch (error) {
    if (!['ENOENT', 'ENOTDIR'].includes(error.code)) console.warn('[radio-resources] CONTAINER_COUNTERS_UNREADABLE');
    return { available: false, reason: 'Container counters unavailable; process values do not establish hosting headroom' };
  }
}

export function createRadioResourceMetrics({ now = Date.now, cpuUsage = process.cpuUsage,
  memoryUsage = process.memoryUsage, histogram = monitorEventLoopDelay({ resolution: 20 }),
  readContainer = readContainerResources, profileCpu = false, log = console } = {}) {
  histogram.enable();
  const diagnostics = profileCpu ? createRadioCpuDiagnostics(log) : null;

  let previousAt = now(), previousCpu = cpuUsage(), last = null, previousContainer = null;
  return {
    async sample() {
      const at = now(), cpu = cpuUsage(), memory = memoryUsage(), elapsedMs = at - previousAt;
      if (elapsedMs <= 0) return last;
      const container = await readContainer();
      if (container.available) {
        container.cpuQuotaPercent = previousContainer?.available && container.cpuLimitCores
          ? (container.cpuUsageUs - previousContainer.cpuUsageUs) / (elapsedMs * 10 * container.cpuLimitCores) : null;
        container.memoryQuotaPercent = container.memoryLimitBytes ? container.memoryBytes / container.memoryLimitBytes * 100 : null;
      }
      last = { at, elapsedMs, cpuCorePercent: (cpu.user + cpu.system - previousCpu.user - previousCpu.system) / (elapsedMs * 10),
        rssBytes: memory.rss, heapUsedBytes: memory.heapUsed, eventLoopP99Ms: histogram.percentile(99) / 1e6,
        eventLoopMaxMs: histogram.max / 1e6,
        container };
      await diagnostics?.sample(last.eventLoopMaxMs);
      previousContainer = container;
      previousAt = at; previousCpu = cpu; histogram.reset();
      return last;
    },
    snapshot: () => last,
    stop() { histogram.disable(); diagnostics?.stop(); },
  };
}

// discord-bot/radio.js
// IPFS track-list fetcher and per-guild RadioSession manager.
//
// RadioSession streams audio files from an IPFS directory to a Discord voice
// channel using FFmpeg for transcoding and @discordjs/voice for playback.

import { spawn }  from 'child_process';
import {
  joinVoiceChannel,
  createAudioPlayer,
  createAudioResource,
  AudioPlayerStatus,
  VoiceConnectionStatus,
  entersState,
  StreamType,
} from '@discordjs/voice';

// ── IPFS helpers ──────────────────────────────────────────────────────────────

const AUDIO_EXTENSIONS_RE = /\.(mp3|m4a|wav|ogg|flac|aac|opus)$/i;

/**
 * Fetch an ordered list of audio track URLs from an IPFS directory.
 * The function fetches the HTTP gateway directory listing HTML and parses
 * every href that ends with a recognised audio extension.
 *
 * @param {string} cid     - IPFS CID (with or without ipfs:// prefix)
 * @param {string} gateway - IPFS HTTP gateway base URL (e.g. https://w3s.link)
 * @returns {Promise<string[]>} Sorted array of full HTTP track URLs
 */
export async function fetchTrackList(cid, gateway) {
  const normalizedCid = cid.replace(/^ipfs:\/\//, '').trim();
  const dirUrl = `${gateway.replace(/\/$/, '')}/ipfs/${normalizedCid}/`;

  const response = await fetch(dirUrl);
  if (!response.ok) {
    throw new Error(`HTTP ${response.status} fetching IPFS directory at ${dirUrl}`);
  }

  const html   = await response.text();
  const tracks = [];

  // Parse href attributes from the directory listing HTML.
  // Handles relative paths (track.mp3), root-relative (/ipfs/CID/track.mp3),
  // and absolute URLs.
  const hrefRe = /href="([^"]+)"/g;
  let match;

  while ((match = hrefRe.exec(html)) !== null) {
    const href = match[1];
    // Skip navigation fragments, query-only links, and parent-dir links
    if (href.startsWith('#') || href.startsWith('?') || href === '../') continue;
    if (AUDIO_EXTENSIONS_RE.test(href)) {
      try {
        tracks.push(new URL(href, dirUrl).toString());
      } catch {
        // Ignore malformed hrefs
      }
    }
  }

  return tracks.sort();
}

// ── FFmpeg stream helper ──────────────────────────────────────────────────────

/** Path to the ffmpeg binary — override via the FFMPEG_PATH env var. */
const FFMPEG_BIN = process.env.FFMPEG_PATH || 'ffmpeg';

/**
 * Spawn FFmpeg to pull an HTTP(S) audio URL and output raw 16-bit LE PCM
 * at 48 kHz stereo (the format expected by @discordjs/voice's StreamType.Raw).
 *
 * @param {string} url - Full HTTP URL of the audio file
 * @returns {{ stream: import('stream').Readable, process: import('child_process').ChildProcess }}
 */
function createFFmpegStream(url) {
  const args = [
    '-reconnect',            '1',
    '-reconnect_streamed',   '1',
    '-reconnect_delay_max',  '5',
    '-i',                    url,
    '-analyzeduration',      '0',
    '-loglevel',             '0',
    '-vn',
    '-f',  's16le',
    '-ar', '48000',
    '-ac', '2',
    'pipe:1',
  ];

  const ffmpeg = spawn(FFMPEG_BIN, args, { stdio: ['ignore', 'pipe', 'ignore'] });
  ffmpeg.on('error', (err) => console.error('[radio] FFmpeg spawn error:', err.message));
  return { stream: ffmpeg.stdout, process: ffmpeg };
}

// ── Per-guild session registry ────────────────────────────────────────────────

/** @type {Map<string, RadioSession>} guildId → active session */
const sessions = new Map();

/**
 * Return the active RadioSession for a guild, or null.
 * @param {string} guildId
 * @returns {RadioSession|null}
 */
export function getSession(guildId) {
  return sessions.get(guildId) ?? null;
}

/**
 * Create a new RadioSession for a guild, destroying any existing session first.
 *
 * @param {string} guildId
 * @param {{ voiceChannel: import('discord.js').VoiceBasedChannel, textChannel: import('discord.js').TextBasedChannel }} opts
 * @returns {RadioSession}
 */
export function createSession(guildId, opts) {
  const existing = sessions.get(guildId);
  if (existing) existing.destroy();
  const session = new RadioSession(opts);
  sessions.set(guildId, session);
  return session;
}

// ── RadioSession ──────────────────────────────────────────────────────────────

export class RadioSession {
  /**
   * @param {object} opts
   * @param {import('discord.js').VoiceBasedChannel} opts.voiceChannel
   * @param {import('discord.js').TextBasedChannel}  opts.textChannel
   */
  constructor({ voiceChannel, textChannel }) {
    this.voiceChannel  = voiceChannel;
    this.textChannel   = textChannel;
    this.queue         = [];
    this.trackIndex    = 0;
    this.isPaused      = false;
    this._destroyed    = false;
    this.connection    = null;
    this._ffmpeg       = null; // current FFmpeg child process
    this.player        = createAudioPlayer();

  this.player.on(AudioPlayerStatus.Idle, () => this._playNext());
  this.player.on('error', (err) => {
    console.error('[radio] Audio player error:', err.message);
    this._playNext();
  });
}

// ── Connection ──────────────────────────────────────────────────────────────

/** Join the voice channel and subscribe the audio player to it. */
async connect() {
  this.connection = joinVoiceChannel({
    channelId:      this.voiceChannel.id,
    guildId:        this.voiceChannel.guild.id,
    adapterCreator: this.voiceChannel.guild.voiceAdapterCreator,
  });

  await entersState(this.connection, VoiceConnectionStatus.Ready, 30_000);
  this.connection.subscribe(this.player);

  // Auto-clean-up if the bot is disconnected from outside
  this.connection.on(VoiceConnectionStatus.Disconnected, async () => {
    try {
      await Promise.race([
        entersState(this.connection, VoiceConnectionStatus.Signalling, 5_000),
        entersState(this.connection, VoiceConnectionStatus.Connecting, 5_000),
      ]);
    } catch {
      this.destroy();
    }
  });
}

// ── Playback ────────────────────────────────────────────────────────────────

/**
 * Load a track list into the queue and start playback from the beginning.
 * @param {string[]} tracks - Array of HTTP audio URLs
 */
async start(tracks) {
  this.queue      = tracks;
  this.trackIndex = 0;
  await this._playNext();
}

async _playNext() {

  // Kill any lingering FFmpeg process from the previous track
  if (this._ffmpeg) {
    try { this._ffmpeg.kill(); } catch {}
    this._ffmpeg = null;
  }

  // If the session was explicitly stopped, don't post a "finished" message
  if (this._destroyed) return;

  if (this.trackIndex >= this.queue.length) {
    await this.textChannel
      .send('✅ Radio playlist finished. Disconnecting from voice channel.')
      .catch(() => {});
    this.destroy();
    return;
  }

  const url       = this.queue[this.trackIndex];
  const filename  = url.split('/').pop();
  const trackName = filename ? decodeURIComponent(filename) : `Track ${this.trackIndex + 1}`;
  this.trackIndex++;

  try {
    const { stream, process: ffmpeg } = createFFmpegStream(url);
    this._ffmpeg = ffmpeg;

    const resource = createAudioResource(stream, { inputType: StreamType.Raw });
    this.player.play(resource);

    await this.textChannel
      .send(`🎵 Now Playing (${this.trackIndex}/${this.queue.length}): **${trackName}**`)
      .catch(() => {});
  } catch (err) {
    console.error('[radio] Failed to start track:', err.message);
    await this.textChannel
      .send(`⚠️ Skipping **${trackName}**: ${err.message}`)
      .catch(() => {});
    await this._playNext();
  }
}

// ── Controls ────────────────────────────────────────────────────────────────

/** Skip the current track and move to the next one. */
skip() {
  // Calling stop(true) forces the player into Idle state, which triggers _playNext.
  this.player.stop(true);
}

/**
 * Toggle between paused and playing.

   * @returns {boolean} true if now paused, false if now resumed
   */
  togglePause() {
    if (this.isPaused) {
      this.player.unpause();
      this.isPaused = false;
    } else {
      this.player.pause();
      this.isPaused = true;
    }
    return this.isPaused;
  }

  /** Stop playback, clear the queue, and disconnect from voice. */
  stop() {
    this.queue      = [];
    this.trackIndex = 0;
    this.destroy();
    // stop() after destroy() so the Idle event (if it fires) sees _destroyed=true
    this.player.stop(true);
  }

  /** Tear down the voice connection and remove this session from the registry. */
  destroy() {
    this._destroyed = true;
    sessions.delete(this.voiceChannel.guild.id);
