async function _openModal(event) {
  if (!isAdminWallet()) return;
  _closeModal();
  _resetAdminWallet();
  _radioOpen = event?.detail?.section === 'radio-programming';
  _connectedAddr = document.getElementById(_radioOpen ? 'radio-programming-connected-addr' : 'admin-connected-addr');
  _statusEl = document.getElementById(_radioOpen ? 'radio-programming-status' : 'admin-status');
  _adminOpen = true;

  if (_radioOpen) _radioModal.showModal();
  else _modal?.classList.remove('hidden');
  _setStatus('Verifying your admin wallet...');
  await _connectWallet();
}

function _closeModal() {
  _adminOpen = false;
  _radioOpen = false;
  ++_walletCheckId;
  if (_mintSection) _mintSection.open = false;
  _modal?.classList.add('hidden');
  _radioModal?.close();
  _setStatus('');
}

// ── Connect Wallet ────────────────────────────────────────────────────────────
async function _connectWallet() {
  const wallet = window._wallet;
  if (!isAdminWallet(wallet?.address)) {
    _resetAdminWallet();
    _closeModal();
    return;
  }
  if (!wallet?.signer || !wallet.address) {
    _resetAdminWallet();
    _setStatus('Connect your wallet in the header to use admin tools.');
    return;
  }

  const checkId = ++_walletCheckId;
  try {
    const signer = wallet.signer;
    const address = wallet.address;
    const cfg = window.DecentConfig || {};

    if (wallet.chainId !== (cfg.chainId || 8453)) {
      _resetAdminWallet();
      _setStatus(`⚠️ Switch MetaMask to ${cfg.chainName || 'Base Mainnet'} before using admin tools.`, true);
      return;
    }

    renderWallet(_connectedAddr, address);

    // Check that connected wallet is DEFAULT_ADMIN_ROLE on the contract
    const contract = new ethers.Contract(cfg.contractAddress, ROLE_GRANT_ABI, signer);
    const adminRole = await contract.DEFAULT_ADMIN_ROLE();
    const isAdmin   = await contract.hasRole(adminRole, address);
    if (checkId !== _walletCheckId || !_adminOpen) return;

    if (!isAdmin) {
      _resetAdminWallet();
      _setStatus(

        '⛔ Your wallet does not hold DEFAULT_ADMIN_ROLE on this contract and cannot grant roles.',
        true,
      );
      return;
    }

    _adminSigner = signer;
    _adminAddress = address;
    _setStatus('');
    if (_radioOpen) {
      _radioScheduleSection?.classList.remove('hidden');
      await _loadRadioSchedule();
      return;
    }
    document.getElementById('admin-connected-role')?.removeAttribute('hidden');
    _mintSection?.classList.remove('hidden');
    _roleSection?.classList.remove('hidden');
    document.getElementById('admin-devert-campaigns')?.classList.remove('hidden');
    document.getElementById('admin-promotions')?.classList.remove('hidden');
    await _loadDevertCampaigns();
  } catch (err) {
    if (checkId === _walletCheckId) _setStatus(`❌ ${err.message || 'Wallet verification failed'}`, true);
  }
}

