async function _loadDevertCampaigns() {
  const status = document.getElementById('admin-devert-status');
  const list = document.getElementById('admin-devert-list');
  if (!_adminSigner || !list || !status) return;
  const checkId = _walletCheckId;
  const signer = _adminSigner;
  status.textContent = 'Loading confirmed campaigns...';
  try {
    const service = window.DecentConfig?.ipfsUploadServiceUrl;
    if (!service) throw new Error('Radio service is not configured');
    const response = await fetch(`${service.replace(/\/$/, '')}/api/devert`, { cache: 'no-store' });
    const snapshot = await response.json();
    if (!response.ok) throw new Error(snapshot.error || 'Campaigns could not be loaded');
    if (checkId !== _walletCheckId || !_adminOpen) return;
    list.replaceChildren();
    const campaigns = snapshot.campaigns.filter(campaign => Date.parse(campaign.startedAt) <= Date.now() &&
      Date.now() < Date.parse(campaign.expiresAt));
    for (const campaign of campaigns) {
      const item = document.createElement('li');
      const label = document.createElement('span');
      label.textContent = `${campaign.title} (#${campaign.campaignId}) - ${campaign.advertiser} - ${
        campaign.removed ? 'removed; paid term ends' : 'active until'} ${new Date(campaign.expiresAt).toLocaleString()} `;
      item.append(label);
      if (!campaign.removed) {
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = 'Remove from playback';

        button.addEventListener('click', async () => {
          if (checkId !== _walletCheckId || !window.confirm('Remove this campaign from both radio players? No refund; its paid term remains unchanged.')) return;
          button.disabled = true;
          status.textContent = 'Sign the removal request in your wallet...';
          try {
            await removeDevertCampaign({ service, signer, campaignId: campaign.campaignId });
            await _loadDevertCampaigns();
          } catch (error) {
            status.textContent = `Removal failed: ${error.message}`;
            button.disabled = false;
          }
        });
        item.append(button);
      }
      list.append(item);
    }
    status.textContent = campaigns.length ? `${campaigns.length} campaign(s) within their paid term.` : 'No campaigns within their paid term.';
  } catch (error) {
    if (checkId === _walletCheckId) status.textContent = `Campaigns unavailable: ${error.message}`;
  }
}

function _setMintPendingCount(count) {
  if (!_mintPendingBadge) return;
  const value = Number.isSafeInteger(count) && count > 0 ? count : 0;
  _mintPendingBadge.textContent = value > 0 ? String(value) : '';
  _mintPendingBadge.hidden = value <= 0;
  _mintPendingBadge.classList.toggle('is-pending', value > 0);
}

async function _loadRadioSchedule() {
  if (!_adminSigner || !_adminAddress) return;
  const checkId = _walletCheckId;
  _setRadioScheduleStatus('Loading the shared radio calendar…');
  try {
    const service = window.DecentConfig?.ipfsUploadServiceUrl;
    if (!service) throw new Error('The radio service is not configured');
    const response = await fetch(`${service.replace(/\/$/, '')}/api/radio/schedule`, { cache: 'no-store' });
    const payload = await response.json();

  if (!response.ok) throw new Error(payload.error || `Schedule unavailable (${response.status})`);
  if (checkId !== _walletCheckId) return;
  try {
    const promotionsResponse = await fetch(`${service.replace(/\/$/, '')}/api/promotions`, { cache: 'no-store' });
    const promotions = await promotionsResponse.json();
    payload.promotionEvents = promotionsResponse.ok ? (promotions.campaigns || [])
      .filter(campaign => campaign.template === 'musician-referral' && ['published', 'paused', 'closed'].includes(campaign.status))
      .map(campaign => ({ id: campaign.id, title: campaign.title, status: campaign.status,
        startUtc: campaign.startsAt, endUtc: campaign.endsAt, remainingAwards: campaign.remainingAwards, campaign })) : [];
    if (!promotionsResponse.ok) payload.promotionEventsError = promotions.error || `Promotions unavailable (${promotionsResponse.status})`;
  } catch (error) {
    payload.promotionEvents = [];
    payload.promotionEventsError = error.message;
  }
  if (checkId !== _walletCheckId) return;
  _radioSchedule = payload;
  renderPlaylistShowPreview(payload);
  _populateRadioWeeklyForm(payload.schedule || defaultRadioSchedule(payload.weeklySchedule));
  _renderRadioScheduleEvents();
  _setRadioScheduleStatus(payload.ready ? 'Shared calendar loaded. Times below use America/New_York.' : 'Calendar is read-only until durable Pinata storage is available.', !payload.ready);
  const saveButton = document.getElementById('admin-radio-event-save');
  if (saveButton) saveButton.disabled = payload.ready !== true;
  const weeklyButton = document.getElementById('admin-radio-weekly-save');
  if (weeklyButton) weeklyButton.disabled = payload.ready !== true;
} catch (error) {

    if (checkId === _walletCheckId) _setRadioScheduleStatus(`❌ ${error.message}`, true);
  }
}

function _populateRadioWeeklyForm(schedule) {
  const slots = [
    ['friday-top10-hype', 'admin-radio-top10-start', 'admin-radio-top10-end'],
    ['friday-live-performance', 'admin-radio-live-start', 'admin-radio-live-end'],
  ];
  for (const [id, startId, endId] of slots) {
    const show = schedule.find(item => item.id === id);
    for (const [elementId, selected, last] of [[startId, show?.startHourLocal ?? 20, 23], [endId, show?.endHourLocal ?? 21, 24]]) {
      const select = document.getElementById(elementId);
      if (!select) continue;
      select.replaceChildren();
      for (let hour = 0; hour <= last; hour++) {
        const suffix = hour >= 12 ? 'PM' : 'AM';
        const value = hour % 12 || 12;
        const option = document.createElement('option');
        option.value = String(hour);
        option.textContent = hour === 24 ? '12:00 AM (Saturday)' : `${value}:00 ${suffix}`;
        select.append(option);
      }
      select.value = String(selected);
    }
  }
}

function _renderRadioScheduleEvents() {
  const calendarRoot = document.getElementById('admin-programming-calendar');
  if (calendarRoot && _radioSchedule) {
    if (!_programmingCalendar) _programmingCalendar = mountRadioProgrammingCalendar(calendarRoot, {
      getSchedule: () => _radioSchedule,
      save: _saveRadioSchedule,
      isCurrent: () => !!_adminSigner && !!_adminAddress,
    });
    else _programmingCalendar.refresh();
  }
  if (!_radioScheduleEventsEl) return;
  const signer = _adminSigner;
  const address = _adminAddress;
  const checkId = _walletCheckId;
  if (signer && address && _radioSchedule) renderAdminRadioAnnouncements({

  anchor: _radioScheduleEventsEl, schedule: _radioSchedule,
  isCurrent: () => checkId === _walletCheckId && signer === _adminSigner,
  request: async (action, payload) => {
    if (checkId !== _walletCheckId || signer !== _adminSigner) throw new Error('Wallet changed; reopen the admin calendar');
    const result = await requestRadioAnnouncement({ serviceUrl: window.DecentConfig.ipfsUploadServiceUrl,
      signer, address, action, payload, isCurrent: () => checkId === _walletCheckId && signer === _adminSigner });
    if (checkId !== _walletCheckId || signer !== _adminSigner) throw new Error('Wallet changed; reopen the admin calendar');
    return result;
  },
});
const now = Date.now();
const events = (_radioSchedule?.events || []).filter(event => Date.parse(event.endUtc) > now)
  .sort((first, second) => Date.parse(first.startUtc) - Date.parse(second.startUtc));
if (!events.length) {
  _radioScheduleEventsEl.innerHTML = '<li class="admin-schedule-empty">No active or upcoming events.</li>';
  return;
}
_radioScheduleEventsEl.innerHTML = events.map(event => {
  if (event.status === 'cancelled') return `<li class="admin-schedule-event"><div><strong>${_esc(event.title)} · Canceled</strong><span>${_esc(event.cancellationReason)}</span></div></li>`;
  const active = Date.parse(event.startUtc) <= now && now < Date.parse(event.endUtc);
  const date = value => new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(value));

    return `<li class="admin-schedule-event"><div><strong>${_esc(event.title)}${event.type === 'playlist_show' ? ' · Playlist show' : ''}</strong><span>${date(event.startUtc)} – ${date(event.endUtc)} ET${active ? ' · LIVE NOW' : ''}</span></div><div class="admin-schedule-actions"><button class="admin-btn admin-btn-secondary" type="button" data-radio-event-edit="${_esc(event.id)}" aria-label="Edit ${_esc(event.title)}">Edit</button><button class="admin-btn admin-btn-secondary" type="button" data-radio-event-cancel="${_esc(event.id)}" aria-label="Cancel ${_esc(event.title)}">Cancel</button></div></li>`;
  }).join('');
}

