// ── NFT Mint Queue ───────────────────────────────────────────────────────────
  async function _loadMintQueue({ reset = true } = {}) {

if (!_adminSigner || !_adminAddress || _mintBusy || _mintQueueLoading) return;
const checkId = _walletCheckId;
_mintQueueLoading = true;
const targetOffset = reset ? 0 : (_mintQueueNextOffset ?? _mintQueue.length);
_setMintStatus(reset ? 'Loading private mint queue…' : 'Loading more requests…');
if (_mintMoreBtn) _mintMoreBtn.disabled = true;
try {
  const cfg = window.DecentConfig || {};
  const response = await fetchMintQueue({
    serviceUrl: cfg.ipfsUploadServiceUrl,
    signer: _adminSigner,
    address: _adminAddress,
    origin: window.location.origin,
    offset: targetOffset,
    limit: 20,
  });
  if (checkId !== _walletCheckId) return;

  let newItems = [];
  if (Array.isArray(response)) {
    newItems = response;
    _mintQueueNextOffset = null;
    _mintQueueTotal = response.length;
  } else {
    newItems = response.requests || [];
    _mintQueueNextOffset = response.nextOffset;
    _mintQueueTotal = response.total || (targetOffset + newItems.length);
  }

  if (reset) {
    _mintQueue = newItems;
    _mintQueueOffset = 0;
  } else {
    _mintQueue = _mintQueue.concat(newItems);
    _mintQueueOffset = targetOffset;
  }

  _renderMintQueue();

  if (_mintMoreBtn) {
    if (_mintQueueNextOffset !== null && _mintQueue.length < _mintQueueTotal) {
      _mintMoreBtn.classList.remove('hidden');
      _mintMoreBtn.disabled = false;
    } else {
      _mintMoreBtn.classList.add('hidden');
    }
  }

  const totalDisplay = _mintQueueTotal > _mintQueue.length
    ? `${_mintQueue.length} of ${_mintQueueTotal} pending request(s) loaded.`

      : `${_mintQueue.length} pending request(s).`;
    _setMintStatus(_mintQueue.length ? totalDisplay : 'The mint queue is empty.');
    _setMintPendingCount(_mintQueueTotal || _mintQueue.length);
    document.dispatchEvent(new CustomEvent('mint-queue-count-updated', {
      detail: { count: _mintQueueTotal || _mintQueue.length },
    }));
  } catch (err) {
    if (checkId === _walletCheckId) _setMintStatus(`❌ ${err.message}`, true);
  } finally {
    _mintQueueLoading = false;
    if (_mintMoreBtn) _mintMoreBtn.disabled = false;
  }
}

function _renderMintQueue() {
  const batchMintEnabled = window.DecentConfig?.nftBatchMintEnabled === true;
  ++_artworkPreviewId;
  _artworkPreviewGenerations.clear();
  for (const url of _artworkPreviewUrls.values()) URL.revokeObjectURL(url);
  _artworkPreviewUrls.clear();
  if (!_mintQueueEl) return;
  if (_mintQueue.length === 0) {
    _mintQueueEl.innerHTML = '<div class="admin-mint-empty">No pending NFT requests.</div>';
    if (_mintSelectedBtn) _mintSelectedBtn.disabled = true;
    return;
  }
  _mintQueueEl.innerHTML = _mintQueue.map((track, index) => `
    <div class="admin-mint-request">
      <input class="admin-mint-check" type="checkbox" data-index="${index}" aria-label="Select ${_esc(track.title)}" />
      <div>
        ${track.requestType === 'artwork-update' ? `
          <div class="admin-artwork-compare">
            <img class="admin-artwork-preview" data-index="${index}" ${track.currentArtworkCid ? `src="${_esc(_gatewayUrl(track.currentArtworkCid))}"` : 'hidden'} alt="Current artwork for ${_esc(track.title)}" />
            <span aria-hidden="true">→</span>

        ? `<div class="admin-mint-actions"><button class="admin-btn admin-btn-secondary admin-artwork-approve" type="button" data-index="${index}">Approve</button><button class="admin-btn admin-btn-secondary admin-artwork-reject" type="button" data-index="${index}">Reject</button></div>`
        : track.requestType === 'split-update'
          ? `<div class="admin-mint-actions"><button class="admin-btn admin-btn-secondary admin-split-approve" type="button" data-index="${index}">Apply split</button><button class="admin-btn admin-btn-secondary admin-split-reject" type="button" data-index="${index}">Reject</button></div>`
        : `<button class="admin-btn admin-btn-secondary admin-mint-one" type="button" data-index="${index}">Mint</button>`}
    </div>
  `).join('');
  for (const [index, track] of _mintQueue.entries()) {
    if (track.requestType !== 'split-update') continue;
    renderCreatorSplitPie(
      _mintQueueEl.querySelector(`[data-admin-split-before="${index}"]`),
      track.currentRecipients.map((wallet, item) => ({
        wallet, shareBps: Number(track.currentSharesBps[item]),
      })),
      { label: `Current payout split for ${track.title}`, size: 'compact' },
    );
    renderCreatorSplitPie(
      _mintQueueEl.querySelector(`[data-admin-split-after="${index}"]`),
      track.recipients.map((wallet, item) => ({
        wallet, shareBps: Number(track.sharesBps[item]),
      })),
      { label: `Proposed payout split for ${track.title}`, size: 'compact' },
    );
  }
  if (_mintSelectedBtn) _mintSelectedBtn.disabled = false;
}

function _mintSelected() {
  const selected = [...(_mintQueueEl?.querySelectorAll('.admin-mint-check:checked') || [])]

    .map((checkbox) => Number(checkbox.dataset.index));
  if (selected.length === 0) {
    _setMintStatus('Select at least one request.', true);
    return;
  }
  _processQueue(selected);
}

async function _updateArtworkPreview(index) {
  const track = _mintQueue[index];
  if (!track || _mintBusy) return;
  const generation = ++_artworkPreviewId;
  _artworkPreviewGenerations.set(index, generation);
  const image = _mintQueueEl.querySelector(`.admin-artwork-preview[data-index="${index}"]`);
  const status = _mintQueueEl.querySelector(`.admin-artwork-status[data-index="${index}"]`);
  try {
    const file = _mintQueueEl.querySelector(`.admin-artwork[data-index="${index}"]`)?.files?.[0];
    const cid = _mintQueueEl.querySelector(`.admin-artwork-cid[data-index="${index}"]`)?.value || '';
    const uri = await resolveMintArtwork({ file, cid, defaultCid: track.artworkCid,
      serviceUrl: window.DecentConfig?.ipfsUploadServiceUrl, upload: async value => {
        const prior = _artworkPreviewUrls.get(index); if (prior) URL.revokeObjectURL(prior);
        const url = URL.createObjectURL(value); _artworkPreviewUrls.set(index, url); return url;
      } });
    if (_artworkPreviewGenerations.get(index) !== generation) return;
    image.src = uri.startsWith('ipfs://') ? _gatewayUrl(uri.slice(7)) : uri;
    image.hidden = false;
    status.textContent = file ? 'New upload preview; it will be pinned when you mint.' : cid ? 'IPFS image preview; no new file upload required.' : 'Queued default artwork selected.';
  } catch (error) {
    if (_artworkPreviewGenerations.get(index) !== generation) return;
    status.textContent = error.message;
  }
}

async function _processQueue(indices) {

if (_mintBusy || !_adminSigner) return;
_mintBusy = true;
_setMintControlsDisabled(true);
let completed = false;
let completedBatches = 0;
let completedItems = 0;
let failureMessage = '';
try {
  const selectedTracks = indices.map(index => ({ index, track: _mintQueue[index] })).filter(entry => entry.track);
  const hasSpecialRequests = selectedTracks.some(entry => entry.track.requestType !== 'mint');
  if (!hasSpecialRequests && window.DecentConfig?.nftBatchMintEnabled === true) {
    const batches = splitMintBatches(indices);
    for (let index = 0; index < batches.length; index++) {
      _setMintStatus(`Preparing batch ${index + 1}/${batches.length} (${batches[index].length} songs)…`);
      await _mintQueuedBatch(batches[index]);
      completedBatches++;
      completedItems += batches[index].length;
    }
  } else {
    for (let position = 0; position < selectedTracks.length; position++) {
      const { index, track } = selectedTracks[position];
      _setMintStatus(`Processing ${position + 1}/${selectedTracks.length}: ${track.title}`);
      if (track.requestType === 'artwork-update') await _approveArtworkUpdate(track, index);
      else if (track.requestType === 'split-update') await _approveCreatorSplitUpdate(track);
      else await _mintQueuedTrack(track, index);
      completedItems++;
    }
  }
  completed = true;
} catch (err) {
  failureMessage = `❌ Stopped after ${completedBatches} confirmed batch(es): ${err.message}`;
  _setMintStatus(failureMessage, true);
} finally {
  _mintBusy = false;
  _setMintControlsDisabled(false);
}
if (completed || completedBatches > 0) {
  await _loadMintQueue();

    if (completed) _setMintStatus(`✅ Processed ${completedItems} queue request(s).`);
    else _setMintStatus(failureMessage, true);
  }
}

async function _prepareQueuedTrack(track, index, { batch = false } = {}) {
  const cfg = window.DecentConfig || {};
  const artwork = _mintQueueEl?.querySelector(`.admin-artwork[data-index="${index}"]`)?.files?.[0];
  const upload = createBrowserIpfsUploader({
    provider: cfg.ipfsUploadProvider || 'pinata',
    serviceUrl: cfg.ipfsUploadServiceUrl,
    ipfsApiUrl: cfg.ipfsApiUrl,
    signer: _adminSigner,
    address: _adminAddress,
    origin: window.location.origin,
  });

  let image;
  if (batch) image = resolveBatchMintArtwork(track.artworkCid);
  else {
    const artworkCid = _mintQueueEl?.querySelector(`.admin-artwork-cid[data-index="${index}"]`)?.value || '';
    image = await resolveMintArtwork({ file: artwork, cid: artworkCid, defaultCid: track.artworkCid,
      serviceUrl: cfg.ipfsUploadServiceUrl, upload: async file => {
        _setMintStatus(`Uploading artwork for ${track.title}…`);
        return upload(file);
      } });
  }
  const metadata = {
    name: track.title,
    description: `Shared through DecentJukebox by ${track.uploader}`,
    animation_url: `ipfs://${track.ipfsCid}`,
    audioUrl: `ipfs://${track.ipfsCid}`,
    ...(track.mediaType ? { mediaType: track.mediaType } : {}),
    ...(track.mediaType === 'video/mp4' ? { videoUrl: `ipfs://${track.ipfsCid}` } : {}),
    ...(track.isDevertAd === true ? { isDevertAd: true } : {}),
    ...(track.creatorSplits ? { creatorSplits: track.creatorSplits } : {}),
    ...(image ? { image } : {}),
    artist: track.recipient,
    creator: track.recipient,

    tipWallet: track.tipWallet || track.recipient,
    ...(track.parentTokenId > 0 ? { parentTokenId: track.parentTokenId, royaltyChain: { parentTokenId: track.parentTokenId } } : {}),
    registeredBy: _adminAddress,
    mintedAt: new Date().toISOString(),
  };
  const metadataFile = new File(
    [JSON.stringify(metadata, null, 2)],
    `${_slugify(track.title)}.json`,
    { type: 'application/json' },
  );
  if (batch) return { metadata, metadataFile };
  _setMintStatus(`Uploading metadata for ${track.title}…`);
  const metadataUrl = await upload(metadataFile);
  return { metadata, metadataUrl };
}

async function _mintQueuedTrack(track, index) {
  const cfg = window.DecentConfig || {};
  const { metadata, metadataUrl } = await _prepareQueuedTrack(track, index);
  const contract = new ethers.Contract(cfg.contractAddress, ROLE_GRANT_ABI, _adminSigner);
  _setMintStatus(`Registering ${track.title} — confirm transaction 1/2…`);
  const registration = await contract.registerToken(0, metadataUrl, 0, track.recipient, 500);
  const registrationReceipt = await registration.wait();
  let tokenId = null;
  for (const log of registrationReceipt.logs) {
    try {
      const event = contract.interface.parseLog(log);
      if (event?.name === 'TokenRegistered') {
        tokenId = event.args.tokenId.toString();
        break;
      }
    } catch (_) {}
  }
  if (tokenId === null) throw new Error(`Could not read the token ID for ${track.title}`);

  _setMintStatus(`Minting ${track.title} as token #${tokenId} — confirm transaction 2/2…`);
  const mint = await contract.mintProduct(track.recipient, tokenId, 1);
  const mintReceipt = await mint.wait();
  const txHash = mintReceipt.hash || mint.hash;

  try {
    await reportMintCompletion({
      serviceUrl: cfg.ipfsUploadServiceUrl,
      trackId: track.trackId,
      tokenId,
      txHash,
    });
    addNFTToSpace({ tokenId: Number(tokenId), contractAddress: cfg.contractAddress,
      chainId: cfg.chainId, metadataUri: metadataUrl, ...metadata });
  } catch (err) {
    throw new Error(
      `Token #${tokenId} minted, but Discord sync failed. Use /jukeloop mark-minted with ` +
      `track ${track.trackId}, token ${tokenId}, and tx ${txHash}. ${err.message}`,
    );
  }
}

async function _approveArtworkUpdate(track, index) {
  const cfg = window.DecentConfig || {};
  if (!track || track.requestType !== 'artwork-update') throw new Error('Artwork update request not found');
  const contract = new ethers.Contract(cfg.contractAddress, [
    'function setTokenURI(uint256 tokenId,string uri) external',
    'function multicall(bytes[] data) external returns (bytes[] results)',
  ], _adminSigner);
  _setMintStatus(`Updating artwork for token #${track.tokenId}…`);
  const tx = await contract.setTokenURI(track.tokenId, track.metadataUri);
  const receipt = await tx.wait();
  const txHash = receipt.hash || tx.hash;
  await completeArtworkUpdateRequest({
    serviceUrl: cfg.ipfsUploadServiceUrl,
    signer: _adminSigner,
    address: _adminAddress,
    origin: window.location.origin,
    requestId: track.trackId,
    txHash,
  });
  _setMintStatus(`✅ Artwork updated for ${track.title}.`);
}

async function _approveCreatorSplitUpdate(track) {
  if (!track || track.requestType !== 'split-update' || track.kind !== 'song') {
    throw new Error('DJuke song split update not found');
  }
  const cfg = window.DecentConfig || {};

const contract = new ethers.Contract(cfg.djukeContractAddress, DJUKE_SPLIT_ADMIN_ABI, _adminSigner);
const { request } = await fetchCreatorSplitProposal({ serviceUrl: cfg.ipfsUploadServiceUrl, requestId: track.trackId });
if (request.kind !== 'song' || request.status !== 'pending' || Date.parse(request.expiresAt) <= Date.now() ||
    !Number.isFinite(Date.parse(request.expiresAt)) ||
    request.contractAddress.toLowerCase() !== cfg.djukeContractAddress.toLowerCase() ||
    request.resourceId !== track.resourceId) {
  throw new Error('Split request is stale; refresh the owner queue');
}
const current = await contract.getSong(request.resourceId);
if (!current.enabled || current.audioURI !== request.audioURI ||
    current.recipients.length !== request.currentRecipients.length ||
    current.recipients.some((wallet, index) => wallet.toLowerCase() !== request.currentRecipients[index].toLowerCase() ||
      Number(current.sharesBps[index]) !== Number(request.currentSharesBps[index]))) {
  throw new Error('On-chain song split changed; create a new approval request');
}
_setMintStatus(`Applying approved creator split for ${track.title}…`);
const tx = await contract.configureSong(request.resourceId, request.audioURI, request.recipients, request.sharesBps);
const receipt = await tx.wait();
if (Number(receipt?.status) !== 1) throw new Error('DJuke split update transaction did not confirm');
await completeCreatorSplitProposal({
  serviceUrl: cfg.ipfsUploadServiceUrl,
  signer: _adminSigner,
  address: _adminAddress,
  requestId: track.trackId,
  txHash: receipt.hash || tx.hash,
  origin: window.location.origin,
});

  _setMintStatus(`✅ Creator split updated for ${track.title}.`);
}

async function _rejectCreatorSplitUpdate(index) {
  const track = _mintQueue[index];
  if (!track || track.requestType !== 'split-update') return;
  const cfg = window.DecentConfig || {};
  try {
    await rejectCreatorSplitProposal({
      serviceUrl: cfg.ipfsUploadServiceUrl,
      signer: _adminSigner,
      address: _adminAddress,
      requestId: track.trackId,
