export function initBigNutenPanel({ document = globalThis.document, window = globalThis.window,
  fetchImpl = globalThis.fetch, now = () => new Date(),
  timeZone = () => Intl.DateTimeFormat().resolvedOptions().timeZone,
  monotonicNow = () => performance.now(), schedule = setInterval, clear = clearInterval } = {}) {
  const byId = id => document.getElementById(`bignuten-${id}`);
  const total = byId('water-total');
  if (!total) return;
  const status = byId('water-status');
  const service = String(window.DecentConfig?.ipfsUploadServiceUrl || '').replace(/\/$/, '');
  const wallet = () => String(window._wallet?.address || '').toLowerCase();
  let address = '', signer, revision = 0, busy = false, available = false, state = null, pending = null, selected = '';
  const say = message => { status.textContent = message; };
  const today = () => musicianCareDay(now(), timeZone());
  const lastWater = () => state?.entries.filter(entry => !entry.removedAt && entry.activity === 'water' && entry.date === today()).at(-1);
  const current = check => check === revision && address === wallet() && signer === window._wallet?.signer;
  let method = 'even', practice = null;
  const duration = seconds => `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(Math.floor(seconds % 60)).padStart(2, '0')}`;
  const practiceSay = message => { byId('practice-status').textContent = message; };
  const timer = createPracticeTimer({
    now: monotonicNow, schedule, clear,

  tick(seconds, precise) {
    if (practice) { practice.seconds = seconds; practice.precise = precise; }
    renderPractice();
  },
  complete() { if (practice) { practice.status = 'complete'; renderPractice(); } },
});

function renderPractice() {
  const preset = PRACTICES[method], voice = preset.family === 'throat';
  const seconds = practice?.seconds || 0, precise = practice?.precise || 0;
  const phase = practicePhase(method, precise);
  const running = practice?.status === 'running', complete = practice?.status === 'complete';
  byId('practice-controls').classList.toggle('is-voice', voice);
  byId('practice-controls').dataset.running = String(running);
  byId('practice-title').textContent = preset.title;
  byId('practice-hint').textContent = preset.hint;
  byId('breath-methods').hidden = byId('breath-today').hidden = voice;
  if (voice) byId('breath-icon').setAttribute('hidden', '');
  else byId('breath-icon').removeAttribute('hidden');
  byId('voice-methods').hidden = byId('voice-icon').hidden = byId('voice-today').hidden = !voice;
  byId('practice-symbol').textContent = preset.symbol;
  for (const id of Object.keys(PRACTICES)) {
    byId(`method-${id}`).setAttribute('aria-pressed', String(id === method));
    byId(`method-${id}`).disabled = !!practice;
  }
  const label = complete ? seconds >= 60 ? 'Minute complete' : 'Ready to log'
    : running ? phase.label : practice ? 'Paused' : 'One gentle minute';
  if (byId('practice-phase').textContent !== label) byId('practice-phase').textContent = label;
  byId('practice-elapsed').textContent = duration(seconds);
  byId('practice-countdown').textContent = running ? `${phase.remaining}s` : '';

  byId('practice-ring').setAttribute('aria-valuenow', String(seconds));
  byId('practice-progress').setAttribute('stroke-dashoffset', String(100 * (1 - precise / 60)));
  const scale = !practice || complete ? .8 : phase.key === 'inhale' ? .74 + .26 * phase.progress
    : phase.key === 'exhale' || phase.key === 'sound' ? 1 - .26 * phase.progress : .74;
  byId('practice-orb').style.transform = `scale(${scale})`;
  byId('voice-wave').style.transform = `scaleY(${practice && !complete && phase.key === 'sound' ? .4 + .6 * Math.abs(Math.sin(phase.progress * Math.PI * 4)) : .18})`;
  byId('practice-start').disabled = !!practice || !!pending || !!document.hidden;
  byId('practice-pause').disabled = !practice || complete;
  byId('practice-pause').textContent = practice?.status === 'paused' ? 'Resume' : 'Pause';
  byId('practice-save').disabled = !practice || seconds < 1 || busy || !!pending;
  byId('practice-spark').hidden = !!practice;
  byId('practice-discard').hidden = !practice;
  byId('practice-discard').disabled = !!pending;
}

function pausePractice() {
  if (practice?.status !== 'running') return;
  timer.pause();
  practice.status = 'paused';
  renderPractice();
}

function resetPractice() {
  practice = null;
  timer.cancel();
}

function confirmPractice(id) {
  if (practice?.entry?.id !== id) return;
  const elapsed = duration(practice.seconds);
  resetPractice();
  practiceSay(`Logged ${elapsed}.`);
}

function render() {
  const totals = state && musicianCareTotals(state, today());
  total.textContent = totals ? String(totals.water) : address ? '--' : '0';
  byId('water-fill').setAttribute('stroke-dashoffset', String(100 * (1 - Math.min((totals?.water || 0) / 8, 1))));

  for (const activity of ['breathwork', 'chanting', 'vocal']) {
    byId(`${activity}-total`).textContent = totals ? String(Math.round(totals[activity] / 60 * 10) / 10) : '--';
  }
  const disabled = busy || !available || !signer || !!pending;
  byId('water-add').disabled = disabled;
  byId('water-remove').disabled = disabled || !lastWater();
  byId('retry').hidden = !pending && (available || !address || busy);
  byId('retry').disabled = busy || (!!pending && !signer);
  byId('water-add').title = address ? 'Add one glass' : 'Connect your wallet using the header';
  renderPractice();
}

function select(kind) {
  pausePractice();
  let next = selected === kind ? '' : kind;
  if (next && practice && next !== PRACTICES[method].family) {
    next = PRACTICES[method].family;
    practiceSay('Finish or discard this session before changing practice.');
  }
  selected = next;
  if (selected && !practice && selected !== PRACTICES[method].family) {
    method = selected === 'heart' ? 'even' : 'hum';
    practiceSay('');
  }
  for (const name of ['heart', 'throat']) byId(`${name}-select`).setAttribute('aria-pressed', String(selected === name));
  byId('home').hidden = byId('project').hidden = !!selected;
  byId('practice-controls').hidden = !selected;
  byId('practice-controls').dataset.kind = selected;
  renderPractice();
  if (selected) byId('practice-back').focus();
}

function accept(profile) {
  if (profile?.address?.toLowerCase() !== address) throw new Error('The profile response belongs to a different wallet.');
  const next = normalizeMusicianCareState(profile.musicianCare);
  musicianCareTotals(next);
  state = next;
  available = true;

  document.dispatchEvent(new window.CustomEvent('musician-care-updated', { detail: { address, musicianCare: state } }));
}

async function refresh() {
  if (address !== wallet() || signer !== window._wallet?.signer) return walletChanged();
  render();
  if (busy || !address) return;
  const check = ++revision;
  busy = true;
  say('');
  render();
  try {
    const response = await fetchImpl(`${service}/api/creator/profile?${new URLSearchParams({ address })}`,
      { cache: 'no-store', signal: AbortSignal.timeout(15000) });
    if (!current(check)) return;
    if (!response.ok) throw new Error(`Profile service returned HTTP ${response.status}.`);
    const profile = await response.json();
    if (!current(check)) return;
    accept(profile);
    if (pending) {
      const entry = state.entries.find(item => item.id === pending.entry.id);
      if (entry && (pending.action === 'add-musician-care' || entry.removedAt)) {
        confirmPractice(entry.id);
        pending = null;
      }
    }
    say(pending ? 'Save not confirmed. Retry this entry.' : '');
  } catch (error) {
    if (!current(check)) return;
    available = false;
    say(`Activity unavailable: ${error.message}${state ? ' Showing saved totals.' : ''}`);
  } finally {
    if (current(check)) { busy = false; render(); }
  }
}

async function save(change) {
  if (address !== wallet() || signer !== window._wallet?.signer) { void walletChanged(); return; }
  if (busy) return;
  if (!address || !signer || (!available && !pending)) {
    say(address ? 'Profile tracking is unavailable. Retry loading it.' : 'Connect your wallet using the header.');
    return;
  }
  const check = ++revision;
  pending = pending || change;

  busy = true;
  let submitted = false;
  render();
  try {
    const body = { ...pending, address, origin: window.location.origin, visibility: 'public',
      nonce: window.crypto.randomUUID(), issuedAt: now().toISOString() };
    say('Confirm in your wallet...');
    const signature = await signer.signMessage(buildMusicianCareAuthorizationMessage(body));
    if (!current(check)) return;
    submitted = true;
    say('Saving...');
    const response = await fetchImpl(`${service}/api/creator/musician-care`, { method: 'POST',
      headers: { 'content-type': 'application/json' }, body: JSON.stringify({ ...body, signature }),
      signal: AbortSignal.timeout(30000) });
    if (!current(check)) return;
    if (!response.ok) throw new Error(`Profile save returned HTTP ${response.status}.`);
    const result = await response.json();
    if (!current(check)) return;
    if (result.ok !== true) throw new Error('Profile save did not confirm.');
    accept(result.profile);
    const recorded = state.entries.find(entry => entry.id === pending.entry.id);
    if (!recorded || (pending.action === 'remove-musician-care' && !recorded.removedAt)) throw new Error('Entry is not confirmed in the saved profile.');
    confirmPractice(recorded.id);
    pending = null;
    say('');
  } catch (error) {
    if (!current(check)) return;
    if (!submitted) pending = null;
    say(submitted ? `Save not confirmed: ${error.message} Retry this entry.`
      : `Not saved: ${error.shortMessage || error.message}`);
  } finally {
    if (current(check)) { busy = false; render(); }
  }
}

function add(activity, amount) {
  try {
    const entry = normalizeMusicianCareEntry({ id: window.crypto.randomUUID(), activity, amount,

      unit: activity === 'water' ? 'glasses' : 'seconds', timestamp: now().toISOString(), timeZone: timeZone() });
    return save({ action: 'add-musician-care', entry });
  } catch (error) { say(`Not saved: ${error.message}`); }
}

async function walletChanged() {
  const nextAddress = /^0x[0-9a-f]{40}$/.test(wallet()) ? wallet() : '';
  const nextSigner = window._wallet?.signer;
  const identityChanged = address !== nextAddress;
  if (!identityChanged && signer === nextSigner) return;
  revision++;
  address = nextAddress;
  signer = nextSigner;
  busy = false;
  if (identityChanged) {
    state = null; pending = null; available = false;
    if (practice) { resetPractice(); practiceSay('Wallet changed; unfinished practice cleared.'); }
    say('');
  }
  render();
  if (address && !available) await refresh();
}

for (const kind of ['heart', 'throat']) byId(`${kind}-select`).addEventListener('click', () => select(kind));
byId('practice-back').addEventListener('click', () => {
  const kind = selected;
  select('');
  byId(`${kind}-select`).focus();
});
for (const id of Object.keys(PRACTICES)) byId(`method-${id}`).addEventListener('click', () => {
  if (practice) return;
  method = id;
  practiceSay('');
  renderPractice();
});
byId('practice-start').addEventListener('click', () => {
  if (practice || pending || !selected || document.hidden) return;
  if (address !== wallet() || signer !== window._wallet?.signer) { void walletChanged(); return; }
  practice = { status: 'running', seconds: 0, precise: 0, entry: null };
  practiceSay('');
  timer.start(60);
});
byId('practice-pause').addEventListener('click', () => {
  if (practice?.status === 'running') pausePractice();

  else if (practice?.status === 'paused' && selected && !document.hidden) {
    practice.status = 'running';
    timer.resume();
  }
});
byId('practice-discard').addEventListener('click', () => {
  if (pending) return;
  resetPractice();
  practiceSay('Discarded. Nothing logged.');
  byId('practice-start').focus();
});
byId('water-add').addEventListener('click', () => add('water', 1));
byId('water-remove').addEventListener('click', () => {
  const entry = lastWater();
  if (!entry) { say('No water entries to undo today.'); render(); return; }
  return save({ action: 'remove-musician-care', entry });
});
byId('practice-save').addEventListener('click', () => {
  if (!practice || practice.seconds < 1 || busy || pending) return;
  if (address !== wallet() || signer !== window._wallet?.signer) { void walletChanged(); return; }
  practice.seconds = timer.end();
  practice.precise = practice.seconds;
  practice.status = 'complete';
  renderPractice();
  try {
    practice.entry ||= normalizeMusicianCareEntry({ id: window.crypto.randomUUID(), activity: PRACTICES[method].activity,
      amount: practice.seconds, unit: 'seconds', timestamp: now().toISOString(), timeZone: timeZone() });
    return save({ action: 'add-musician-care', entry: practice.entry });
  } catch (error) {
    say(`Not saved: ${error.message}`);
  }
});
byId('retry').addEventListener('click', () => pending ? save(pending) : refresh());
document.addEventListener('wallet-connected', walletChanged);
document.addEventListener('wallet-disconnected', walletChanged);
window.addEventListener('focus', refresh);
window.addEventListener('pagehide', pausePractice);

  document.addEventListener('visibilitychange', () => { if (document.hidden) pausePractice(); else void refresh(); });
  select('');
  void walletChanged();
  return { refresh, pause: pausePractice };
}

// Adapted from BigNuten_Vanilla at f33c487 (Apache-2.0); see img/BigNuten.NOTICE.txt.
export const PRACTICES = Object.freeze({
  even: { family: 'heart', activity: 'breathwork', title: 'Easy breath', symbol: '',
    hint: 'Follow the circle, gently. No holds.',
    phases: [{ key: 'inhale', label: 'Breathe in', seconds: 4 }, { key: 'exhale', label: 'Breathe out', seconds: 4 }] },
  extended: { family: 'heart', activity: 'breathwork', title: 'Long exhale', symbol: '',
    hint: 'An easy breath in. A soft, longer breath out.',
    phases: [{ key: 'inhale', label: 'Breathe in', seconds: 4 }, { key: 'exhale', label: 'Breathe out', seconds: 6 }] },
  hum: { family: 'throat', activity: 'vocal', title: 'Gentle hum', symbol: 'mmm',
    hint: 'Lips together. Hum softly on a comfortable note.',
    phases: [{ key: 'inhale', label: 'Easy breath in', seconds: 4 }, { key: 'sound', label: 'Mmm...', seconds: 4 }, { key: 'rest', label: 'Breathe naturally', seconds: 4 }] },
  trill: { family: 'throat', activity: 'vocal', title: 'Lip trill', symbol: 'brr',
    hint: 'Relax your lips. Let them flutter with a little air.',
    phases: [{ key: 'inhale', label: 'Easy breath in', seconds: 4 }, { key: 'sound', label: 'Brr...', seconds: 4 }, { key: 'rest', label: 'Breathe naturally', seconds: 4 }] },
  chant: { family: 'throat', activity: 'chanting', title: 'Aum / Om', symbol: 'om',
    hint: 'An easy ah-oh-mmm. Let the sound soften away.',
    phases: [{ key: 'inhale', label: 'Easy breath in', seconds: 4 }, { key: 'sound', label: 'Ah - oh - mmm', seconds: 4 }, { key: 'rest', label: 'Breathe naturally', seconds: 4 }] },
});

export function practicePhase(method, seconds) {
  const practice = PRACTICES[method];

  if (!practice || !Number.isFinite(seconds) || seconds < 0) throw new Error('Invalid practice or elapsed time.');
  const cycle = practice.phases.reduce((sum, phase) => sum + phase.seconds, 0);
  let within = seconds % cycle;
  for (const phase of practice.phases) {
    if (within < phase.seconds) return { ...phase, progress: within / phase.seconds, remaining: Math.ceil(phase.seconds - within) };
    within -= phase.seconds;
  }
}

export function createPracticeTimer({ tick, complete, now = () => performance.now(), schedule = setInterval, clear = clearInterval }) {
  let interval = null, elapsed = 0, started = 0, target = 0, active = false;
  const stop = () => { if (interval !== null) clear(interval); interval = null; };
  const preciseSeconds = () => Math.min(target, (elapsed + (interval !== null ? now() - started : 0)) / 1000);
  const seconds = () => Math.floor(preciseSeconds());
  function update() {
    const precise = preciseSeconds();
    tick(Math.floor(precise), precise);
    if (precise >= target) { stop(); active = false; elapsed = target * 1000; complete(target); }
  }
  return {
    start(targetSeconds) { stop(); elapsed = 0; target = targetSeconds; active = true; started = now(); interval = schedule(update, 200); update(); },
    pause() { if (interval === null) return; elapsed += now() - started; stop(); tick(seconds(), preciseSeconds()); },
    resume() { if (!active || interval !== null) return; started = now(); interval = schedule(update, 200); update(); },
    end() { const value = seconds(); stop(); active = false; elapsed = value * 1000; return value; },
    cancel() { stop(); active = false; elapsed = 0; tick(0, 0); },
  };
}

/**
 * Required booth setup before a performer's microphone starts, shared by the
 * private rehearsal and backstage rooms. Performers monitor locally (interface
 * direct monitor) or not at all. Browser monitoring is delayed, so it is offered
 * only in private practice (SHOW_MODES excludes it). The public radio is never a
 * performance monitor.
 */
export const BOOTH_MODES = Object.freeze({
  direct: 'Headphones in my interface · direct monitor on (recommended)',
  unplugged: 'No headphones · unplugged',
  browser: 'Browser monitor · delayed, practice only',
});
export const SHOW_MODES = Object.freeze(['direct', 'unplugged']);

const GUIDANCE = {
  '': 'Choose how you will hear yourself, then confirm the radio is off everywhere else.',
  direct: 'Plug your headphones into the interface and turn its direct monitor on. Effects belong in your interface or mixer so the radio hears them too. Hear my input stays off so you never hear yourself twice.',
  unplugged: 'No monitor: play to the room with no headphones. Hear my input stays off and no speaker plays the radio near your mic.',
  browser: 'Practice only: browser monitoring arrives late. Turn your interface’s direct monitor off, start your mic, then use Hear my input with headphones. Shows use your interface or unplugged.',
};

export function boothSetupProblem({ mode, radioOff } = {}, modes = Object.keys(BOOTH_MODES)) {
  if (!modes.includes(mode || '')) return 'Booth setup: choose how you will hear yourself first.';
  if (radioOff !== true) return 'Booth setup: confirm the radio is off on every other tab, phone and device first.';
  return '';
}

/**
 * mode is a <select> whose option values are '' and the allowed modes (a subset of

 * the BOOTH_MODES keys; pass SHOW_MODES for live shows); radioOff a checkbox; status an output. monitorToggle is
 * the Hear my input checkbox. onMonitorDisallowed must stop browser monitoring
 * without stopping the microphone. Choices persist for this tab only, so a
 * reload mid-show does not block republishing. Changing them never stops a mic.
 */
export function bindBoothSetup({ mode, radioOff, status, monitorToggle, onMonitorDisallowed, onChange,
  storage, key = 'dbusk-booth-setup', modes = Object.keys(BOOTH_MODES) }) {
  modes = modes.filter(value => Object.hasOwn(BOOTH_MODES, value));
  try {
    const saved = JSON.parse(storage?.getItem(key) || 'null');
    if (saved && modes.includes(saved.mode)) mode.value = saved.mode;
    if (saved?.radioOff === true) radioOff.checked = true;
  } catch { /* Missing or blocked storage only means choosing again. */ }

  const current = () => ({ mode: modes.includes(mode.value || '') ? mode.value : '', radioOff: radioOff.checked === true });
  function render() {
    const choice = current();
    const allowed = choice.mode === 'browser';
    if (!allowed && monitorToggle.checked) void Promise.resolve(onMonitorDisallowed?.()).catch(() => {});
    monitorToggle.disabled = !allowed;
    const problem = boothSetupProblem(choice, modes);
    status.textContent = !problem ? `✓ Booth ready. ${GUIDANCE[choice.mode]}`
      : choice.mode ? `${GUIDANCE[choice.mode]} ${problem}` : GUIDANCE[''];
    if (status.dataset) status.dataset.ready = String(!problem);
  }
  function changed() {
    try { storage?.setItem(key, JSON.stringify(current())); } catch { /* Choices still apply in this page. */ }
    render();
    onChange?.();
  }
  mode.addEventListener('change', changed);
  radioOff.addEventListener('change', changed);
  render();

import { pinCommunityManifest } from './pinner-rewards.mjs';
import { createPinnerRewardsView } from './pinner-rewards-ui.mjs?v=20261126-pinner-onboarding';

export function initCommunityPinning({ fetchImpl = fetch } = {}) {
  const dialog = document.getElementById('community-pin-dialog');
  if (!dialog) return;
  const summary = document.getElementById('community-pin-summary');
  const progress = document.getElementById('community-pin-progress');
  const start = document.getElementById('community-pin-start');
  const key = document.getElementById('community-pin-key');
  const keyLabel = document.getElementById('community-pin-key-label');
  const rewardStatus = document.getElementById('community-pin-rewards-status');
  let manifest = null;
  let busy = false;
  const rewardsRoot = document.getElementById('community-pinner-rewards');
  const rewardsView = rewardsRoot ? createPinnerRewardsView({ root: rewardsRoot, enrollment: true, fetchImpl,
    isBusy: () => busy, setBusy: value => { busy = value; updateProvider(); } }) : null;
  const provider = () => document.querySelector('[name="community-pin-provider"]:checked')?.value || 'local';

  async function loadManifest() {
    manifest = null;
    start.disabled = true;
    summary.textContent = 'Loading the shared content manifest…';
    const service = (window.DecentConfig?.ipfsUploadServiceUrl || '').replace(/\/$/, '');
    if (!service) { summary.textContent = 'Community pin manifest is not configured.'; return; }
    try {
      const response = await fetchImpl(`${service}/api/pinners/manifest`, { cache: 'no-store', signal: AbortSignal.timeout(15000) });
      const value = await response.json();
      if (!response.ok) throw new Error(value.error || `HTTP ${response.status}`);

    if (value.schemaVersion !== 1 || !Array.isArray(value.entries)) throw new Error('Invalid pin manifest');
    manifest = value;
    summary.textContent = `${value.entryCount} unique CIDs · shared playlist, songs and albums`;
    rewardStatus.textContent = value.rewardStatus === 'active'
      ? 'Shared Pinata stays primary. Join the approved pinner program below to earn verified weekly rewards.'
      : `Shared Pinata stays primary. Pinner reward status: ${value.rewardStatus}.`;
    start.disabled = !value.entryCount;
  } catch (error) { summary.textContent = `Manifest unavailable: ${error.message}`; }
}

function updateProvider() {
  const pinata = provider() === 'pinata';
  key.hidden = !pinata;
  keyLabel.hidden = !pinata;
  start.textContent = pinata ? 'Pin to my Pinata' : 'Pin to IPFS Desktop';
  start.disabled = busy || !manifest?.entryCount || (pinata && !key.value.trim());
}

document.querySelectorAll('[name="community-pin-provider"]').forEach(input => input.addEventListener('change', updateProvider));
key.addEventListener('input', updateProvider);
window.addEventListener('open-community-pinning', async () => {
  if (!dialog.open) dialog.showModal();
  await Promise.all([loadManifest(), rewardsView?.load()]);
  updateProvider();
});
document.getElementById('community-pin-cancel').addEventListener('click', () => { key.value = ''; dialog.close(); updateProvider(); });
start.addEventListener('click', async () => {
  if (!manifest || busy) return;
  busy = true;
  updateProvider();
  const selectedProvider = provider();
  const pinataJwt = selectedProvider === 'pinata' ? key.value.trim() : '';
  try {
    const result = await pinCommunityManifest({ manifest, provider: selectedProvider, pinataJwt,

        ipfsApiUrl: window.DecentConfig?.ipfsApiUrl || 'http://127.0.0.1:5001', fetchImpl,
        onProgress: ({ completed, total }) => { progress.textContent = `Pinned ${completed} of ${total} CIDs…`; } });
      progress.textContent = `Pinned ${result.successes.length} of ${manifest.entryCount}. ${result.failures.length ? `${result.failures.length} could not be pinned; try again later.` : 'All selected CIDs are pinned.'}`;
      rewardStatus.textContent = 'Your pins add a community copy. Enroll below; only approved nodes with qualifying independent checks earn weekly awards.';
    } catch (error) { progress.textContent = error.message; }
    finally { key.value = ''; busy = false; updateProvider(); }
    await rewardsView?.load();
  });
  for (const event of ['wallet-connected', 'wallet-disconnected']) document.addEventListener(event, () => {
    if (dialog.open) void rewardsView?.load();
  });
  dialog.addEventListener('close', () => { key.value = ''; });
  updateProvider();
}

if (typeof document !== 'undefined') document.addEventListener('DOMContentLoaded', () => initCommunityPinning(), { once: true });

