// js/components/header-admin-inject.js — DecentBusking
//
// Injects a "🔑 Admin" link into the AppTitle left-ankh dropdown and a small
// pending-mint badge on the left ankh for the owner wallet.

const ADMIN_LINK_STYLE = `
  .admin-nav-item {
    list-style: none;
    padding: 0.45rem 1rem;
    cursor: pointer;
    white-space: nowrap;
    color: #a0e0ff;
    font-size: 0.9rem;
    transition: background 0.15s;
  }
  .admin-nav-item:hover { background: rgba(160, 224, 255, 0.12); }
  .ankh-left { position: relative; }
  .admin-mint-count-badge {
    position: absolute;
    top: -5px;
    right: -5px;
    z-index: 2;
    min-width: 1.15rem;
    height: 1.15rem;
    padding: 0 0.22rem;
    border-radius: 999px;
    color: #fff8ef;
    background: linear-gradient(180deg, rgba(255, 145, 82, .96), rgba(148, 45, 24, .96));
    box-shadow: 0 0 0 1px rgba(255, 213, 176, .22), 0 0 10px rgba(255, 145, 82, .42);
    text-align: center;
    font: 700 0.66rem / 1.15rem system-ui, sans-serif;
    pointer-events: none;
  }
  .admin-mint-count-badge.is-pending { animation: admin-mint-count-pulse 4.2s ease-in-out infinite; }
  @keyframes admin-mint-count-pulse {
    0%, 100% { transform: scale(1); box-shadow: 0 0 0 1px rgba(255, 213, 176, .22), 0 0 10px rgba(255, 145, 82, .38); }
    50% { transform: scale(1.07); box-shadow: 0 0 0 1px rgba(255, 237, 216, .34), 0 0 14px rgba(255, 145, 82, .7); }
  }
  @media (prefers-reduced-motion: reduce) {
    .admin-mint-count-badge.is-pending { animation: none; }
  }
`;

let _badgePollTimer = 0;
let _badgeRoot = null;
let _badge = null;
let _currentCount = 0;

function patchAppTitle() {
  const cls = customElements.get('app-title');
  if (!cls) return;

  const originalRender = cls.prototype.render;
  cls.prototype.render = function () {

    originalRender.call(this);
    _injectAdminLink(this.shadowRoot);
    _ensureMintBadge(this.shadowRoot);
  };

  _findAllAppTitles().forEach(el => {
    _injectAdminLink(el.shadowRoot);
    _ensureMintBadge(el.shadowRoot);
  });
}

function _injectAdminLink(shadowRoot) {
  if (!shadowRoot) return;
  const leftMenu = shadowRoot.querySelector('.ankh-left .dropdown-menu');
  if (!leftMenu) return;

  _injectStyle(shadowRoot);

  if (!leftMenu.querySelector('[data-admin-item]')) {
    const li = document.createElement('li');
    li.className = 'admin-nav-item';
    li.dataset.adminItem = '1';
    li.textContent = '🔑 Admin';
    li.addEventListener('click', e => {
      e.stopPropagation();
      leftMenu.style.display = 'none';
      document.dispatchEvent(new CustomEvent('open-admin'));
    });
    leftMenu.appendChild(li);
  }

  if (!leftMenu.querySelector('[data-radio-programming-item]')) {
    const li = document.createElement('li');
    li.className = 'admin-nav-item';
    li.dataset.radioProgrammingItem = '1';
    li.textContent = '☿ Admin Community Calendar';
    li.addEventListener('click', e => {
      e.stopPropagation();
      leftMenu.style.display = 'none';
      document.dispatchEvent(new CustomEvent('open-radio-programming'));
    });
    leftMenu.appendChild(li);
  }
}

function _injectStyle(shadowRoot) {
  if (!shadowRoot || shadowRoot.querySelector('#admin-nav-style')) return;
  const style = document.createElement('style');
  style.id = 'admin-nav-style';
  style.textContent = ADMIN_LINK_STYLE;
  shadowRoot.appendChild(style);
}

function _ensureMintBadge(shadowRoot) {
  if (!shadowRoot) return;
  _badgeRoot = shadowRoot;

  _injectStyle(shadowRoot);
  const leftAnkh = shadowRoot.querySelector('.ankh-left');
  if (!leftAnkh) return;
  if (!_badge) {
    _badge = document.createElement('span');
    _badge.className = 'admin-mint-count-badge';
    _badge.hidden = true;
    _badge.setAttribute('aria-hidden', 'true');
    leftAnkh.appendChild(_badge);
  } else if (_badge.parentElement !== leftAnkh) {
    leftAnkh.appendChild(_badge);
  }
  _applyCount(_currentCount);
}

function _applyCount(count) {
  _currentCount = Number.isSafeInteger(count) && count > 0 ? count : 0;
  if (!_badge) return;
  _badge.textContent = _currentCount > 0 ? String(_currentCount) : '';
  _badge.hidden = _currentCount <= 0;
  _badge.classList.toggle('is-pending', _currentCount > 0);
}

async function _refreshPendingCount() {
  const config = window.DecentConfig || {};
  const owner = (config.adminWalletAddress || config.mintOwnerWallet || '').toLowerCase();
  const connected = (window._wallet?.address || '').toLowerCase();
  if (!owner || connected !== owner || !config.ipfsUploadServiceUrl) {
    _applyCount(0);
    document.dispatchEvent(new CustomEvent('mint-queue-count-updated', { detail: { count: 0 } }));
    return;
  }
  try {
    const response = await fetch(`${config.ipfsUploadServiceUrl.replace(/\/$/, '')}/api/mint-queue/pending-count`, { cache: 'no-store' });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok || !Number.isSafeInteger(payload.count)) throw new Error(payload.error || 'Pending mint count unavailable');
    _applyCount(payload.count);
    document.dispatchEvent(new CustomEvent('mint-queue-count-updated', { detail: { count: payload.count } }));
  } catch (error) {
    console.warn('[mint-queue-badge]', error.message);
  }
}

function _syncPolling() {

  clearInterval(_badgePollTimer);
  _badgePollTimer = 0;
  if (!window._wallet?.address) {
    _applyCount(0);
    return;
  }
  void _refreshPendingCount();
  const owner = (window.DecentConfig?.adminWalletAddress || window.DecentConfig?.mintOwnerWallet || '').toLowerCase();
  if ((window._wallet.address || '').toLowerCase() === owner && window.DecentConfig?.ipfsUploadServiceUrl) {
    _badgePollTimer = window.setInterval(() => { void _refreshPendingCount(); }, 5 * 60 * 1000);
  } else {
    _applyCount(0);
  }
}

function _findAllAppTitles() {
  const found = [];
  function walk(root) {
    root.querySelectorAll('app-title').forEach(el => found.push(el));
    root.querySelectorAll('*').forEach(el => {
      if (el.shadowRoot) walk(el.shadowRoot);
    });
  }
  walk(document);
  return found;
}

if (customElements.get('app-title')) {
  patchAppTitle();
} else {
  customElements.whenDefined('app-title').then(patchAppTitle);
}

document.addEventListener('wallet-connected', _syncPolling);
document.addEventListener('wallet-disconnected', _syncPolling);
document.addEventListener('mint-queue-count-updated', event => {
  if (_badgeRoot) _ensureMintBadge(_badgeRoot);
  _applyCount(event.detail?.count);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => _syncPolling(), { once: true });
} else {
  _syncPolling();
}

// js/components/header-payroll-inject.js — DecentBusking
//
// Injects a "💸 Payroll" link into AppTitle's left ankh dropdown
// (the ☥ icon on the left side of the shared header component).
//
// Uses the same prototype-patching pattern as about-override.js so the
// injection survives any future re-renders of the AppTitle component.
// The button dispatches a custom "open-payroll" DOM event that payroll.js
// listens for — keeping the shadow-DOM boundary fully decoupled.

// Styles injected into the AppTitle shadow root. Inline styles are avoided
// in favour of a scoped <style> element so rules stay maintainable and
// consistent with the app's CSS custom properties.
import { isAdminWallet } from '../admin-access.mjs';

let queueNotice = '';
const PAYROLL_LINK_STYLE = `
  .payroll-nav-item {
    list-style: none;
    padding: 0.45rem 1rem;
    cursor: pointer;
    white-space: nowrap;
    color: #f0c040;
    font-size: 0.9rem;
    transition: background 0.15s;
  }
  .payroll-nav-item:hover {
    background: rgba(240, 192, 64, 0.12);
  }
  .payroll-nav-item[hidden] { display: none; }
`;

function patchAppTitle() {
  const cls = customElements.get('app-title');
  if (!cls) return;

  // Wrap render() so every future call also injects the Payroll link.
  const originalRender = cls.prototype.render;
  cls.prototype.render = function () {
    originalRender.call(this);
    _injectPayrollLink(this.shadowRoot);
  };

  // Inject into any AppTitle instances already rendered in the DOM.
  _findAllAppTitles().forEach(el => _injectPayrollLink(el.shadowRoot));
}

function _injectPayrollLink(shadowRoot) {
  if (!shadowRoot) return;

  const leftMenu = shadowRoot.querySelector('.ankh-left .dropdown-menu');
  if (!leftMenu) return;

  // Don't inject twice.

if (leftMenu.querySelector('[data-payroll-item]')) return;

// Inject scoped styles if not already present.
if (!shadowRoot.querySelector('#payroll-nav-style')) {
  const style = document.createElement('style');
  style.id = 'payroll-nav-style';
  style.textContent = PAYROLL_LINK_STYLE;
  shadowRoot.appendChild(style);
}

// The CDN AppTitle's left dropdown currently contains only placeholder
// items ("Option1", "Option 2"). We replace those with real navigation
// links so the dropdown has meaningful content. If the CDN component
// is later updated to include real items, this section should be revised
// to append instead of replace.
leftMenu.innerHTML = '';

const historyItem = document.createElement('li');
historyItem.className = 'payroll-nav-item';
historyItem.dataset.playHistoryTotalsItem = '1';
historyItem.textContent = 'Playback Tally';
historyItem.addEventListener('click', (event) => {
  event.stopPropagation();
  leftMenu.style.display = 'none';
  document.dispatchEvent(new CustomEvent('open-radio-history', { detail: { mode: 'totals' } }));
});
leftMenu.appendChild(historyItem);
for (const [label, eventName, datasetKey] of [
  ['Admin Nft Mint', 'open-admin', 'adminItem'], ['Payroll', 'open-payroll', 'payrollItem'],
]) {
  const item = document.createElement('li');
  item.className = 'payroll-nav-item';
  item.dataset[datasetKey] = '1';
  item.dataset.adminOnly = '1';
  item.textContent = label;
  if (eventName === 'open-payroll') {
    const notice = document.createElement('span');
    notice.dataset.payrollNotice = '1';
    notice.setAttribute('role', 'status');
    notice.textContent = queueNotice;
    item.appendChild(notice);
  }
  item.hidden = !isAdminWallet();

    item.addEventListener('click', event => {
      event.stopPropagation();
      if (!isAdminWallet()) return;
      leftMenu.style.display = 'none';
      document.dispatchEvent(new CustomEvent(eventName));
    });
    leftMenu.appendChild(item);
  }
}

// Shadow-DOM aware traversal — same helper pattern as about-override.js.
function _findAllAppTitles() {
  const found = [];
  function walk(root) {
    root.querySelectorAll('app-title').forEach(el => found.push(el));
    root.querySelectorAll('*').forEach(el => {
      if (el.shadowRoot) walk(el.shadowRoot);
    });
  }
  walk(document);
  return found;
}

// Bootstrap — patch immediately if already defined, otherwise wait.
if (customElements.get('app-title')) {
  patchAppTitle();
} else {
  customElements.whenDefined('app-title').then(patchAppTitle);
}

function updateAdminItems() {
  for (const title of _findAllAppTitles()) {
    title.shadowRoot?.querySelectorAll('[data-admin-only]').forEach(item => { item.hidden = !isAdminWallet(); });
  }
}
document.addEventListener('wallet-connected', updateAdminItems);
document.addEventListener('wallet-disconnected', updateAdminItems);

document.addEventListener('payroll-queue-status', event => {
  queueNotice = event.detail.error ? ' - unavailable'
    : event.detail.count ? ` - ${event.detail.count} unpaid` : '';
  for (const title of _findAllAppTitles()) {
    const notice = title.shadowRoot?.querySelector('[data-payroll-notice]');
    if (notice) notice.textContent = queueNotice;
  }
});

// js/components/header-right-ankh-override.js — DecentBusking
//
// Owns the wallet-specific playback menu. header.js imports this module before
// loading DecentHead components, so the legacy token dropdown is never needed.
import { DECENT_HEAD_BASE } from './header-source.mjs';

class CleanRightAnkh extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    // Resolve the DecentHead CDN base path so the shared header.css
    // (which styles .ankh-wrapper, .ankh-coin and .sparkle) is loaded.

    this.shadowRoot.innerHTML = `
      <link rel="stylesheet" href="${DECENT_HEAD_BASE}css/header.css" />
      <style>
        .ankh-container { position: relative; }
        .dropdown-menu.right-ankh-menu {
          position: absolute;
          top: 100%;
          right: 0;
          left: auto;
          transform: none;
          width: max-content;
          max-width: calc(100vw - 24px);
          list-style: none;
          padding: 0;
          margin: 0;
        }
        .wallet-item { list-style: none; }
        .wallet-btn {
          background: none;
          border: none;
          color: inherit;
          cursor: pointer;
          font: inherit;
          padding: 0.4rem 1rem;
          white-space: nowrap;
          width: 100%;
          text-align: left;
        }
        .wallet-btn:hover { opacity: 0.8; }
        .calendar-icon { width: 16px; height: 16px; margin-right: 6px; vertical-align: -3px; filter: invert(1); }
      </style>
      <div class="ankh-wrapper">
        <div class="ankh-container">
          <span class="ankh-coin" role="button" aria-haspopup="true" aria-label="Right menu">☥</span>
          <ul class="dropdown-menu right-ankh-menu"

          style="display:none;">
        <li class="wallet-item"><button class="wallet-btn" id="creator-profile-btn">Profile</button></li>
        <li class="wallet-item">
            <button class="wallet-btn" id="radio-schedule-btn"><img class="calendar-icon" src="https://cdn.jsdelivr.net/npm/lucide-static@0.468.0/icons/calendar-days.svg" alt="" /> Public Schedule</button>
        </li>
        <li class="wallet-item">
          <button class="wallet-btn" id="radio-history-btn" style="display:none;">My Playbacks</button>
        </li>
      </ul>
    </div>
    <span class="sparkle sparkle-top">✨</span>
    <span class="sparkle sparkle-bottom">✨</span>
    <span class="sparkle sparkle-left">✨</span>
    <span class="sparkle sparkle-right">✨</span>
  </div>
`;

const coin = this.shadowRoot.querySelector('.ankh-coin');
const popup = this.shadowRoot.querySelector('.dropdown-menu.right-ankh-menu');
const scheduleBtn = this.shadowRoot.querySelector('#radio-schedule-btn');
const historyBtn = this.shadowRoot.querySelector('#radio-history-btn');
this.shadowRoot.querySelector('#creator-profile-btn')?.addEventListener('click', event => {
  event.stopPropagation();
  popup.style.display = 'none';
  document.dispatchEvent(new CustomEvent('open-creator-profile', { detail: {} }));
});
scheduleBtn?.addEventListener('click', event => {
  event.stopPropagation();
  if (popup) popup.style.display = 'none';
  document.dispatchEvent(new CustomEvent('open-radio-schedule', { detail: {} }));
});
historyBtn?.addEventListener('click', (event) => {
  event.stopPropagation();
  if (popup) popup.style.display = 'none';
  if (window._wallet?.address) {

      document.dispatchEvent(new CustomEvent('open-radio-history', {
        detail: { mode: 'personal', wallet: window._wallet.address },
      }));
    }
  });

  const _onConnected = (ev) => {
    const addr = ev.detail?.address || '';
    if (historyBtn) historyBtn.style.display = addr ? 'block' : 'none';
  };
  const _onDisconnected = () => {
    if (historyBtn) historyBtn.style.display = 'none';
    if (popup) popup.style.display = 'none';
  };

  document.addEventListener('wallet-connected',    _onConnected);
  document.addEventListener('wallet-disconnected', _onDisconnected);

  // Reflect current state in case the wallet was already connected before
  // this element attached (e.g. page reload with auto-connect).
  if (window._wallet?.address) {
    _onConnected({ detail: { address: window._wallet.address } });
  }

  // Store listener references for cleanup.
  this._onConnected    = _onConnected;
  this._onDisconnected = _onDisconnected;

  coin?.addEventListener('click', e => {
    if (!popup) return;
    popup.style.display = popup.style.display === 'block' ? 'none' : 'block';
    e.stopPropagation();
  });

  // Store the listener reference so it can be removed in disconnectedCallback.
  this._closePopup = () => { if (popup) popup.style.display = 'none'; };
  document.addEventListener('click', this._closePopup);
}

disconnectedCallback() {
  if (this._closePopup) {
    document.removeEventListener('click', this._closePopup);
    this._closePopup = null;
  }
  if (this._onConnected) {
    document.removeEventListener('wallet-connected',    this._onConnected);
    this._onConnected = null;
  }
  if (this._onDisconnected) {

      document.removeEventListener('wallet-disconnected', this._onDisconnected);
      this._onDisconnected = null;
    }
  }
}

if (!customElements.get('right-ankh')) customElements.define('right-ankh', CleanRightAnkh);

// js/components/header-title-color-override.js — DecentBusking
//
// Injects DecentBusking's warm neon title and electric end symbols into
// the shared AppTitle shadow root.
//
// The Shadow DOM prevents host-page CSS from reaching .title-main, so the
// only reliable approach is to inject a scoped <style> element directly into
// the shadow root — the same technique used by header-admin-inject.js and
// header-payroll-inject.js.

const TITLE_COLOR_STYLE = `
  #app-title .title-main {
    position: relative;
    z-index: 3;
    margin: 0 -8px;
    color: #fff1d9 !important;
    background: none;
    -webkit-text-fill-color: currentColor;
    text-shadow: 0 0 2px #fffaf0, 0 0 5px #ffe2b5, 0 0 11px #ffb86c, 0 0 22px #ff8b38, 0 0 36px #fa681d88;
    filter: none;
    animation: busking-neon-flicker 30s linear infinite;
    pointer-events: none;
  }
  .title-symbol {
    color: #ffe8d1 !important;
    font-size: 1.15rem;
    margin: 0 .32rem;
    opacity: .85;
    text-shadow: 0 1px 0 #a64b20, 0 2px 2px rgba(0,0,0,.75);
    pointer-events: none;
  }
  .title-symbol .neon-contact {
    display: inline-block;
    color: #986548;
    text-shadow: 0 0 2px #ffae6c44;
    animation: busking-contact-current 3.8s linear infinite;
    animation-delay: var(--contact-delay);
  }
  @keyframes busking-contact-current {
    0%, 65%, 100% { color: #986548; text-shadow: 0 0 2px #ffae6c44; }
    74%, 82% { color: #fff8e8; text-shadow: 0 0 3px #fff, 0 0 8px #ffbd7b, 0 0 16px #ff8438; transform: translateY(-1px); }
  }
  @keyframes busking-neon-flicker {
    0%, 91%, 91.3%, 92%, 92.4%, 94%, 94.5%, 100% { opacity: 1; }
    91.1%, 91.2%, 92.1%, 92.3%, 94.1%, 94.4% { opacity: .4; }
  }
  @media (prefers-reduced-motion: reduce) {

    #app-title .title-main, .title-symbol .neon-contact { animation: none; }
    .title-symbol .neon-contact { color: #ffe8d1; }
  }
  .peacock-icon {
    position: relative;
    z-index: 2;
    display: inline-flex;
    flex: 0 0 auto;
    width: 62px;
    height: 62px;
    margin: 0 -12px;
    align-items: center;
    justify-content: center;
    pointer-events: auto;
  }
  #app-subtitle {
    position: relative;
    z-index: 4;
    pointer-events: none;
  }
  #app-title .peacock-icon img.dbusker-avatar {
    position: absolute;
    top: calc(50% + 9px);
    left: 50%;
    transform: translate(-50%, -50%);
    box-sizing: border-box;
    display: block;
    width: 100px;
    height: 100px;
    border: 2px solid #ffd1a6;
    border-radius: 50%;
    object-fit: cover;
    box-shadow: 0 2px 9px rgba(0,0,0,.65), 0 0 8px rgba(255,143,70,.38);
  }
  @media (max-width: 600px) {
    #app-title-wrapper .title-center { overflow: visible; }
    .title-symbol { font-size: 8px; margin: 0 1px; }
    .peacock-icon { width: 44px; height: 44px; margin: 0 -8px; }
    #app-title .peacock-icon img.dbusker-avatar { width: 112px; height: 112px; top: calc(50% - 10px); border-width: 1px; }
  }
`;

function patchAppTitle() {
  const cls = customElements.get('app-title');
  if (!cls) return;

  // Wrap render() so the style is re-injected after every future re-render.
  const originalRender = cls.prototype.render;
  cls.prototype.render = function () {
    originalRender.call(this);
    _injectTitleColor(this.shadowRoot);
  };

  // Apply to any app-title instances already in the DOM.
  _findAllAppTitles().forEach(el => _injectTitleColor(el.shadowRoot));
}

function _injectTitleColor(shadowRoot) {
  if (!shadowRoot) return;
  if (shadowRoot.querySelector('#busking-title-color')) return;

  const style = document.createElement('style');
  style.id = 'busking-title-color';
  style.textContent = TITLE_COLOR_STYLE;
  shadowRoot.appendChild(style);
  shadowRoot.querySelectorAll('.title-symbol').forEach((symbol, side) => {
    symbol.setAttribute('aria-hidden', 'true');
    const characters = [...symbol.textContent];
    symbol.replaceChildren(...characters.map((character, index) => {
      const contact = document.createElement('span');
      contact.className = 'neon-contact';
      contact.textContent = character;
      contact.style.setProperty('--contact-delay', `${(side ? characters.length - 1 - index : index) * .12}s`);
      return contact;
    }));
  });
}

function _findAllAppTitles() {
  const found = [];
  function walk(root) {
    root.querySelectorAll('app-title').forEach(el => found.push(el));
    root.querySelectorAll('*').forEach(el => {
      if (el.shadowRoot) walk(el.shadowRoot);
    });
  }
  walk(document);
  return found;
}

if (customElements.get('app-title')) {
  patchAppTitle();
} else {
  customElements.whenDefined('app-title').then(patchAppTitle);
}

