  if (!coin || !wrapper) return;
  injectStyle(root, 'decentbusking-coin-hit-area', COIN_HIT_AREA_STYLE);
  coin.setAttribute('role', 'button');
  coin.setAttribute('tabindex', '0');
  coin.setAttribute('aria-haspopup', 'menu');
