    `Wallet: ${address.toLowerCase()}`,
    `Origin: ${origin}`,
    `Album: ${albumId.toLowerCase()}`,
    `Song: ${songId.toLowerCase()}`,
    `Transaction: ${txHash.toLowerCase()}`,
    `Issued At: ${issuedAt}`,
  ].join('\n');
}

export function validateCreatorSplitRows(rows, { maxRecipients = MAX_CREATOR_RECIPIENTS } = {}) {
