import { getPlaylistBatchAbi, quoteNamedPlaylist, supportsDJukePlaylistBatch, supportsDJukePlaylistRadio } from './djuke-playlists.mjs';
import { ensureBaseNetwork, approvalNotice, waitForAllowance } from './base-chain.mjs';
import { formatUsdcUnits } from './usdc-format.mjs';
import { BASE_USDC_ADDRESS } from './djuke-payment.mjs';
import { USDC_BROWSER_ABI } from './usdc-abi.mjs';
import { checkPlaylistSchedule, playlistConflictMessage } from './playlist-schedule-warning.mjs';

export async function checkoutRadioPlaylist({ playlist, signer, config, onStep = () => {}, fetchImpl = fetch,
  ethers: library = globalThis.ethers, signal, ensureChain = ensureBaseNetwork,
  checkSchedule = checkPlaylistSchedule, confirmConflict = message => globalThis.confirm(message) }) {
  signal?.throwIfAborted();
  if (!supportsDJukePlaylistRadio(config)) throw new Error('Radio playlist checkout is unavailable');
  const songIds = playlist.songIds;
  quoteNamedPlaylist(songIds.length, 'radio');
  onStep('Checking your playlist against the public radio calendar…');
  const conflict = await checkSchedule({ songIds, config, fetchImpl, signal });
  signal?.throwIfAborted();
  if (conflict && await confirmConflict(playlistConflictMessage(conflict)) !== true) {
    throw new Error('Play Live checkout cancelled. No approval or purchase was requested; your playlist is unchanged.');
  }
  signal?.throwIfAborted();
  await ensureChain(signer.provider);
  const listener = await signer.getAddress();
  const quoteUrl = new URL(`${String(config.ipfsUploadServiceUrl || '').replace(/\/$/, '')}/api/djuke/playlist-gas-quote`);
  quoteUrl.searchParams.set('listener', listener);
  songIds.forEach(songId => quoteUrl.searchParams.append('songId', songId));

const response = await fetchImpl(quoteUrl, { cache: 'no-store', signal: AbortSignal.timeout(10000) });
const quote = await response.json();
if (!response.ok) throw new Error(quote.error || 'Playlist gas quote is unavailable');
const nowSeconds = Math.floor(Date.now() / 1000);
const maxTotal = BigInt(quote.maxTotal);
const fulfillmentCostWei = BigInt(quote.fulfillmentCostWei);
const contributionWei = BigInt(quote.contributionWei);
if (quote.contractAddress?.toLowerCase() !== config.djukePlaylistBatchAddress?.toLowerCase() ||
    quote.listener?.toLowerCase() !== listener.toLowerCase() || !Number.isInteger(quote.deadline) ||
    quote.deadline < nowSeconds || quote.deadline > nowSeconds + 300 ||
    maxTotal !== quoteNamedPlaylist(songIds.length, 'radio').totalUnits ||
    contributionWei !== fulfillmentCostWei * 2n * BigInt(songIds.length)) throw new Error('Invalid or expired playlist payment quote');
const djuke = new library.Contract(config.djukePlaylistBatchAddress, getPlaylistBatchAbi(), signer);
if (config.djukePlaylistBatchVersion === '0.5') {
  if (contributionWei !== 0n || fulfillmentCostWei !== 0n || await djuke.CONTRACT_VERSION() !== '0.5') {
    throw new Error('DJuke v0.5 requires a verified USDC-only purchase quote');
  }
} else if (contributionWei <= 0n) throw new Error('Legacy playlist checkout requires its disclosed worker gas contribution');
const usdc = new library.Contract(BASE_USDC_ADDRESS, USDC_BROWSER_ABI, signer);
if (Number(await usdc.decimals()) !== 6) throw new Error('Configured token is not native Base USDC');
if (await usdc.balanceOf(listener) < maxTotal) throw new Error(`You need ${formatUsdcUnits(maxTotal)} USDC on Base`);

  if (contributionWei > 0n && await signer.provider.getBalance(listener) < contributionWei) throw new Error('Not enough Base ETH for the legacy playback contribution');
  if (await usdc.allowance(listener, djuke.target) < maxTotal) {
    signal?.throwIfAborted();
    onStep(approvalNotice(formatUsdcUnits(maxTotal), { workerContribution: contributionWei > 0n }));
    if ((await (await usdc.approve(djuke.target, maxTotal)).wait())?.status !== 1) throw new Error('USDC approval did not confirm');
    await waitForAllowance(usdc, listener, djuke.target, maxTotal);
  }
  onStep(`${songIds.length} songs · ${formatUsdcUnits(maxTotal)} USDC · ${contributionWei === 0n
    ? 'standard Base network gas only' : `${library.formatEther(contributionWei)} ETH worker gas`}`);
  await djuke.requestPlaylistWithGas.staticCall(songIds, maxTotal, fulfillmentCostWei, quote.deadline, quote.signature, { value: contributionWei });
  onStep('Confirm radio playlist checkout in your wallet');
  signal?.throwIfAborted();
  const transaction = await djuke.requestPlaylistWithGas(songIds, maxTotal, fulfillmentCostWei, quote.deadline, quote.signature, { value: contributionWei });
  onStep('Waiting for Base confirmation…');
  if ((await transaction.wait())?.status !== 1) throw new Error('Radio playlist request did not confirm');
  return { txHash: transaction.hash, totalUnits: maxTotal, contributionWei };
}

export async function checkoutPrivatePlaylist({ playlist, signer, config, onStep = () => {}, onSubmitted = () => {},
  ethers: library = globalThis.ethers, signal, ensureChain = ensureBaseNetwork }) {
  signal?.throwIfAborted();
  if (!supportsDJukePlaylistBatch(config)) throw new Error('Private named-playlist checkout is unavailable until a compatible DJuke batch contract is configured');

  await ensureChain(signer.provider);
  quoteNamedPlaylist(playlist.songIds.length, 'private');
  const address = await signer.getAddress();
  const djuke = new library.Contract(config.djukePlaylistBatchAddress, getPlaylistBatchAbi(), signer);
  const usdc = new library.Contract(BASE_USDC_ADDRESS, USDC_BROWSER_ABI, signer);
  if (Number(await usdc.decimals()) !== 6) throw new Error('Configured token is not native Base USDC');
  const chainQuote = await djuke.quotePlaylist(playlist.songIds, false);
  const totalUnits = BigInt(chainQuote.total ?? chainQuote[2]);
  if (await usdc.balanceOf(address) < totalUnits) throw new Error(`You need ${formatUsdcUnits(totalUnits)} USDC on Base`);
  if (await usdc.allowance(address, djuke.target) < totalUnits) {
    signal?.throwIfAborted();
    onStep(approvalNotice(formatUsdcUnits(totalUnits), { workerContribution: false }));
    if ((await (await usdc.approve(djuke.target, totalUnits)).wait())?.status !== 1) throw new Error('USDC approval did not confirm');
    await waitForAllowance(usdc, address, djuke.target, totalUnits);
  }
  onStep(`Private playlist · ${playlist.songIds.length} songs at creator listen prices · ${formatUsdcUnits(totalUnits)} USDC total`);
  await djuke.purchasePlaylistPrivate.staticCall(playlist.songIds, totalUnits);
  onStep('Confirm private playlist purchase in your wallet');
  signal?.throwIfAborted();
  const transaction = await djuke.purchasePlaylistPrivate(playlist.songIds, totalUnits);
  await onSubmitted({ payer: address, contract: djuke.target, txHash: transaction.hash });
  onStep('Waiting for Base confirmation…');
  if ((await transaction.wait())?.status !== 1) throw new Error('Private playlist purchase did not confirm');
  return { txHash: transaction.hash, totalUnits };
}

import { approvalNotice, ensureBaseNetwork, retryMissingRevertData, waitForAllowance } from './base-chain.mjs';
import { formatUsdcUnits } from './usdc-format.mjs';
import { DJUKE_SIGNING_DOMAIN_VERSION } from './djuke-version.mjs';

export const BASE_USDC_ADDRESS = '0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913';
export const DJUKE_BROWSER_ABI = [
  'function CONTRACT_VERSION() view returns(string)',
  'function quote() view returns (uint256)',
  'function requestPlay(bytes32 songId, uint256 maxPrice) returns (uint256)',
  'function replaceRequest(uint256 requestId, bytes32 songId)',
  'function gasWorker() view returns(address)',
  'function maxGasContributionWei() view returns(uint256)',
  'function gasQuoteNonces(address) view returns(uint256)',
  'function requestPlayWithGas(bytes32,uint256,uint256,uint256,bytes) payable returns(uint256)',
];

// Both the platform drawer and the standalone widget use this checkout boundary.
export async function purchaseDjukeSong({ signer, djuke, usdc, songId, maxPriceUnits, gasQuote = null,
  ethers: library = globalThis.ethers, onStep = () => {}, signal, ensureChain = ensureBaseNetwork, verifyEligibility = async () => {} }) {
  signal?.throwIfAborted();
  await ensureChain(signer.provider);
  if (usdc.target.toLowerCase() !== BASE_USDC_ADDRESS.toLowerCase() || Number(await usdc.decimals()) !== 6) throw new Error('Configured token is not native Base USDC');
  if (!/^0x[0-9a-fA-F]{64}$/.test(songId || '')) throw new Error('Select a song');
  await verifyEligibility(songId);
  const address = await signer.getAddress();
  const price = await djuke.quote();
  if (price > maxPriceUnits) throw new Error(`Price rose to ${formatUsdcUnits(price)} USDC; refresh and try again`);

if (await usdc.balanceOf(address) < price) throw new Error(`You need ${formatUsdcUnits(price)} USDC on Base`);
if (gasQuote) {
  if (gasQuote.listener.toLowerCase() !== address.toLowerCase() || gasQuote.songId !== songId ||
      gasQuote.contractAddress.toLowerCase() !== djuke.target.toLowerCase() || gasQuote.chainId !== 8453 ||
      Number(gasQuote.deadline) <= Math.floor(Date.now() / 1000) || BigInt(gasQuote.maxPrice) !== maxPriceUnits) throw new Error('Refresh the DJuke payment quote');
  const [worker, cap, nonce] = await Promise.all([djuke.gasWorker(), djuke.maxGasContributionWei(), djuke.gasQuoteNonces(address)]);
  const contribution = BigInt(gasQuote.contributionWei);
  const version = await djuke.CONTRACT_VERSION();
  if (version === '0.5' && (contribution !== 0n || BigInt(gasQuote.fulfillmentCostWei) !== 0n)) throw new Error('DJuke v0.5 requires a verified USDC-only purchase quote');
  const sponsored = contribution === 0n && BigInt(gasQuote.fulfillmentCostWei) === 0n && version === '0.5';
  if ((!sponsored && contribution <= 0n) || contribution !== BigInt(gasQuote.fulfillmentCostWei) * 2n ||
      contribution > cap || String(nonce) !== String(gasQuote.nonce)) throw new Error('Invalid DJuke payment quote');
  const types = { GasQuote: [{ name: 'listener', type: 'address' }, { name: 'songId', type: 'bytes32' },
    { name: 'maxPrice', type: 'uint256' }, { name: 'fulfillmentCostWei', type: 'uint256' }, { name: 'nonce', type: 'uint256' },
    { name: 'deadline', type: 'uint256' }] };
  const recovered = library.verifyTypedData({ name: 'DecentJukeBox', version: DJUKE_SIGNING_DOMAIN_VERSION, chainId: 8453,
    verifyingContract: djuke.target }, types, gasQuote, gasQuote.signature);

    if (recovered.toLowerCase() !== worker.toLowerCase()) throw new Error('Invalid DJuke payment signature');
    if (contribution > 0n && await signer.provider.getBalance(address) < contribution) throw new Error('Insufficient Base ETH for the legacy playback contribution');
  }
  if (await usdc.allowance(address, djuke.target) < price) {
    signal?.throwIfAborted();
    onStep(approvalNotice(formatUsdcUnits(price), { workerContribution: gasQuote !== null && BigInt(gasQuote.contributionWei) > 0n }));
    if ((await (await usdc.approve(djuke.target, price)).wait())?.status !== 1) throw new Error('USDC approval did not confirm');
    onStep('Confirming approval…');
    await waitForAllowance(usdc, address, djuke.target, price);
  }
  const args = gasQuote ? [songId, maxPriceUnits, BigInt(gasQuote.fulfillmentCostWei), gasQuote.deadline, gasQuote.signature,
    { value: BigInt(gasQuote.contributionWei) }] : [songId, maxPriceUnits];
  const request = gasQuote ? djuke.requestPlayWithGas : djuke.requestPlay;
  onStep('Creating request…');
  await retryMissingRevertData(() => request.staticCall(...args), async () => {
    onStep('Confirming approval…');
    await waitForAllowance(usdc, address, djuke.target, price);
  });
  onStep('Confirm your DJuke request');
  await verifyEligibility(songId);
  signal?.throwIfAborted();
  const transaction = await request(...args);
  onStep('Waiting for Base confirmation…');
  if ((await transaction.wait())?.status !== 1) throw new Error('DJuke request did not confirm');
  return { txHash: transaction.hash, priceUnits: price };
}

export async function replaceDjukeSong({ signer, djuke, chainRequestId, songId, signal, verifyEligibility = async () => {} }) {
  signal?.throwIfAborted();

  if (Number((await signer.provider.getNetwork()).chainId) !== 8453) throw new Error('Switch your wallet to Base');
  await djuke.replaceRequest.staticCall(BigInt(chainRequestId), songId);
  await verifyEligibility(songId);
  signal?.throwIfAborted();
  const transaction = await djuke.replaceRequest(BigInt(chainRequestId), songId);
  if ((await transaction.wait())?.status !== 1) throw new Error('Replacement did not confirm');
  return transaction.hash;
}

// Shared by the DJuke drawer and the standalone DJuke widget; keep it free of radio/player imports.
// On-chain `delivered` events trail settlement, so the live `playing` lane and heard `played` lanes drive the count.
export function playlistBatchProgress(batch) {
  const songs = Array.isArray(batch?.songs) ? batch.songs : [];
  const count = status => songs.filter(song => song.status === status).length;
  const total = songs.length;
  const delivered = count('delivered');
  const played = count('played');
  const remaining = count('pending');
  const playing = songs.findIndex(song => song.status === 'playing');
  const name = batch?.name || 'Playlist';
  return {
    total, delivered, played, remaining, position: playing >= 0 ? playing + 1 : null,
    heading: playing >= 0
      ? `${name} · Song ${playing + 1} of ${total} · ${remaining} remaining`
      : `${name} · ${remaining} of ${total} songs remaining`,
    progress: `${delivered} / ${total} songs delivered${played ? ` · ${played} played, settling` : ''}${
      playing >= 0 ? ` · now playing song ${playing + 1}` : ''}`,
  };
}

