      const result = await contribute({ signer, router, token, slug: leg.slug,
        asset, amount: contributionAmount(leg.amountUnits, asset), onStep, planLeg: true, onConfirmed: txHash => {
          Object.assign(leg, { status: 'confirmed', txHash });
