  const rawAddress = /^0x[0-9a-fA-F]{40}$/.test(String(address || '')) && (label === address || label === shortAddress(address) || !label);
  const labelHtml = rawAddress ? renderWalletAddress(address) : `${avatar}${escapeHtml(label)}`;
