const FALLBACK_GATEWAYS = [
  'https://gateway.pinata.cloud/ipfs/',
  'https://peach-fast-pike-16.mypinata.cloud/ipfs/',
];

function gatewayUrl(gateway, cid) {
  const base = gateway.replace(/\/$/, '');
  return `${base}${base.endsWith('/ipfs') ? '' : '/ipfs'}/${cid}`;
}

export function buildIpfsGatewayUrls(uri, primaryGateway) {
  if (!uri?.startsWith('ipfs://')) return uri ? [uri] : [];
  const cid = uri.slice('ipfs://'.length);
  return [...new Set([primaryGateway, ...FALLBACK_GATEWAYS].filter(Boolean).map((gateway) => gatewayUrl(gateway, cid)))];
}

export async function fetchIpfsJson(uri, { primaryGateway, fetchImpl = globalThis.fetch, timeoutMs = 8000 } = {}) {
  const urls = buildIpfsGatewayUrls(uri, primaryGateway);
  for (const url of urls) {
    try {
      const response = await fetchImpl(url, { signal: AbortSignal.timeout(timeoutMs) });
      if (!response.ok) continue;
      return await response.json();
    } catch (_) {}
  }
  return null;
}

export function buildUploadAuthorizationMessage({ address, origin, name, size, type, issuedAt, purpose }) {
  return [
    purpose === 'submission' ? 'DecentBusking artist media upload authorization' : 'DecentBusking IPFS upload authorization',
    `Wallet: ${address.toLowerCase()}`,
    `Origin: ${origin}`,
    `File: ${name}`,
    `Size: ${size}`,
    `Type: ${type}`,
    `Issued At: ${issuedAt}`,
  ].join('\n');
}

export function buildUploadBatchAuthorizationMessage({ address, origin, issuedAt, files }) {
  return [
    'DecentBusking IPFS metadata batch upload authorization',
    `Wallet: ${address.toLowerCase()}`,
    `Origin: ${origin}`,
    `Issued At: ${issuedAt}`,
    `Files: ${JSON.stringify(files)}`,
  ].join('\n');
}

function extractCid(result) {
  return result.data?.cid || result.cid || result.IpfsHash || result.Hash;
}

function readResponseError(response, fallbackMessage) {
  return response.text().then(async text => {
    const result = text ? JSON.parse(text) : {};
    const detail = typeof result.error === 'string' ? result.error
      : result.error?.message || result.error?.reason || result.message || result.Message;
    const error = new Error(detail || fallbackMessage);
    error.status = response.status;
    error.retryable = response.status >= 500 || response.status === 429 || response.status === 408;
    return error;
  }).catch(() => {
    const error = new Error(fallbackMessage);
    error.status = response.status;
    error.retryable = response.status >= 500 || response.status === 429 || response.status === 408;
    return error;
  });
}

function uploadWithProgress(endpoint, file, fetchImpl, includeNetwork, onProgress) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    const form = new FormData();

    form.append('file', file, file.name);
    if (includeNetwork) form.append('network', 'public');
    xhr.open('POST', endpoint, true);
    xhr.responseType = 'text';
    xhr.upload.onprogress = event => {
      if (event.lengthComputable && typeof onProgress === 'function') {
        onProgress({ loaded: event.loaded, total: event.total, progress: event.total ? event.loaded / event.total : 0 });
      }
    };
    xhr.onload = async () => {
      if (xhr.status < 200 || xhr.status >= 300) {
        reject(await readResponseError({ status: xhr.status, text: async () => xhr.responseText }, `IPFS upload failed (${xhr.status}) for ${file.name}`));
        return;
      }
      try {
        const cid = extractCid(JSON.parse(xhr.responseText || '{}'));
        if (!cid) throw new Error('IPFS upload response did not include a CID');
        resolve(`ipfs://${cid}`);
      } catch (error) {
        reject(error);
      }
    };
    xhr.onerror = () => reject(new Error(`Network error uploading ${file.name}`));
    xhr.onabort = () => reject(new Error(`Upload aborted for ${file.name}`));
    xhr.timeout = 0;
    xhr.send(form);
  });
}

async function uploadForm(endpoint, file, fetchImpl, includeNetwork = false, { onProgress } = {}) {
  if (typeof XMLHttpRequest !== 'undefined' && typeof onProgress === 'function') {
    return uploadWithProgress(endpoint, file, fetchImpl, includeNetwork, onProgress);
  }
  const form = new FormData();
  form.append('file', file, file.name);
  if (includeNetwork) form.append('network', 'public');
  const response = await fetchImpl(endpoint, { method: 'POST', body: form });
  if (!response.ok) {
    throw await readResponseError(response, `IPFS upload failed (${response.status}) for ${file.name}`);
  }

  const cid = extractCid(await response.json());
  if (!cid) throw new Error('IPFS upload response did not include a CID');
  return `ipfs://${cid}`;
}

function isRetryableError(error) {
  return Boolean(error?.retryable || /Failed to fetch|NetworkError|network|load failed|fetch failed|aborted|AbortError/i.test(error?.message || ''));
}

function stepError(prefix, step, detail, suggestion) {
  const message = `${prefix} (${step}) — ${detail || suggestion}`;
  const error = new Error(message);
  error.step = step;
  return error;
}

async function withRetries(step, action, {
  retries = 2,
  prefix,
  retrySuggestion,
  logPrefix = '[ipfs-upload]',
}) {
  let lastError;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await action(attempt);
    } catch (error) {
      lastError = error;
      const retryable = attempt < retries && isRetryableError(error);
      console.warn(logPrefix, step, { attempt: attempt + 1, retryable, error });
      if (!retryable) break;
      await new Promise(resolve => setTimeout(resolve, 250 * (2 ** attempt)));
    }
  }
  throw stepError(prefix, step, lastError?.message, retrySuggestion);
}

const IMAGE_SIGNATURES = [
  { type: 'image/jpeg', ext: 'jpg', test: b => b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff },
  { type: 'image/png', ext: 'png', test: b => b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47 },
  { type: 'image/gif', ext: 'gif', test: b => b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x38 },
  { type: 'image/webp', ext: 'webp', test: b => b[0] === 0x52 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x46 && b[8] === 0x57 && b[9] === 0x45 && b[10] === 0x42 && b[11] === 0x50 },
];

// Pinata checks the real file contents against the signed MIME type, so an image whose
// extension doesn't match its bytes (e.g. a JPEG saved as .png) must be relabelled first.
export async function normalizeImageFileType(file) {
  if (!file || typeof file.slice !== 'function' || !String(file.type || '').startsWith('image/')) return file;
  const bytes = new Uint8Array(await file.slice(0, 12).arrayBuffer());
  const detected = IMAGE_SIGNATURES.find(signature => signature.test(bytes));
  if (!detected || detected.type === file.type || typeof File === 'undefined') return file;
  const base = String(file.name || 'artwork').replace(/\.[^.]*$/, '');
  return new File([file], `${base}.${detected.ext}`, { type: detected.type, lastModified: file.lastModified });
}

export function createBrowserIpfsUploader({
  provider = 'pinata',
  serviceUrl,
  ipfsApiUrl = 'http://127.0.0.1:5001',
  signer,
  address,
  origin,
  purpose,
  fetchImpl = globalThis.fetch,
  retries = 2,
}) {
  const upload = async function upload(file, options = {}) {
    const { onProgress } = options || {};
    if (provider === 'local') {
      const endpoint = `${ipfsApiUrl.replace(/\/$/, '')}/api/v0/add?cid-version=1&pin=true`;
      return withRetries('step 1/2', () => uploadForm(endpoint, file, fetchImpl, false, { onProgress }), {
        retries,
        prefix: 'Upload to IPFS failed',
        retrySuggestion: 'retry, or try a smaller file',
      });
    }
    if (provider !== 'pinata') throw new Error(`Unsupported IPFS upload provider: ${provider}`);
    if (!serviceUrl) throw new Error('The Render IPFS worker URL is not configured');
    if (!signer || !address) throw new Error('Connect your wallet before uploading');
    file = await normalizeImageFileType(file);

const endpoint = purpose === 'submission' ? 'submission-upload-url' : 'upload-url';
let lastUploadError;
for (let attempt = 0; attempt <= retries; attempt++) {
  let url;
  try {
    const issuedAt = new Date().toISOString();
    const authorization = {
      address,
      origin,
      name: file.name,
      size: file.size,
      type: file.type || 'application/octet-stream',
      issuedAt,
      ...(purpose === 'submission' ? { purpose } : {}),
    };
    const signature = await signer.signMessage(buildUploadAuthorizationMessage(authorization));
    const signingResponse = await fetchImpl(`${serviceUrl.replace(/\/$/, '')}/api/ipfs/${endpoint}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ ...authorization, signature }),
    });
    if (!signingResponse.ok) {
      throw await readResponseError(signingResponse, `Pinata signing failed (${signingResponse.status})`);
    }
    const signingResult = await signingResponse.json();
    url = signingResult.url;
    if (!url) throw new Error('Pinata signing response did not include a URL');
  } catch (error) {
    const retryable = attempt < retries && isRetryableError(error);
    console.warn('[ipfs-upload]', 'step 1/2', { attempt: attempt + 1, retryable, error });
    if (!retryable) throw stepError('Couldn’t reach the upload service', 'step 1/2', error.message, 'please retry');
    await new Promise(resolve => setTimeout(resolve, 250 * (2 ** attempt)));
    continue;
  }
  try {
    return await uploadForm(url, file, fetchImpl, true, { onProgress });
  } catch (error) {
    lastUploadError = error;

      const retryable = attempt < retries && isRetryableError(error);
      console.warn('[ipfs-upload]', 'step 2/2', { attempt: attempt + 1, retryable, error });
      if (!retryable) break;
      await new Promise(resolve => setTimeout(resolve, 250 * (2 ** attempt)));
    }
  }
  throw stepError('Upload to IPFS failed', 'step 2/2', lastUploadError?.message, 'retry, or try a smaller file');
};

upload.batch = async files => {
  if (!Array.isArray(files) || files.length < 1 || files.length > 20) {
    throw new Error('Metadata upload batches must contain 1 to 20 files');
  }
  if (provider === 'local') return Promise.all(files.map(file => uploadForm(
    `${ipfsApiUrl.replace(/\/$/, '')}/api/v0/add?cid-version=1&pin=true`, file, fetchImpl)));
  if (provider !== 'pinata') throw new Error(`Unsupported IPFS upload provider: ${provider}`);
  if (!serviceUrl) throw new Error('The Render IPFS worker URL is not configured');
  if (!signer || !address) throw new Error('Connect your wallet before uploading');
  const issuedAt = new Date().toISOString();
  const descriptors = files.map(file => ({ name: file.name, size: file.size,
    type: file.type || 'application/octet-stream' }));
  const authorization = { address, origin, issuedAt, files: descriptors };
  const signature = await signer.signMessage(buildUploadBatchAuthorizationMessage(authorization));
  const response = await fetchImpl(`${serviceUrl.replace(/\/$/, '')}/api/ipfs/upload-batch-urls`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ ...authorization, signature }),
  });
  if (!response.ok) {
    throw await readResponseError(response, `Pinata batch signing failed (${response.status})`);
  }

    const result = await response.json();
    if (!Array.isArray(result.urls) || result.urls.length !== files.length || result.urls.some(url => typeof url !== 'string' || !url)) {
      throw new Error('Pinata batch signing response did not include one URL per metadata file');
    }
    return Promise.all(files.map((file, index) => withRetries(`batch ${index + 1}/${files.length}`, () =>
      uploadForm(result.urls[index], file, fetchImpl, true, {}), {
        retries,
        prefix: 'Upload to IPFS failed',
        retrySuggestion: 'retry, or try a smaller file',
      })));
  };

  return upload;
}

export function uploadFileToIPFS(file) {
  const config = window.DecentConfig || {};
  const params = new URLSearchParams(window.location.search);
  return createBrowserIpfsUploader({
    provider: config.ipfsUploadProvider || 'pinata',
    serviceUrl: params.get('worker') || config.ipfsUploadServiceUrl,
    ipfsApiUrl: config.ipfsApiUrl,
    signer: window._wallet?.signer,
    address: window._wallet?.address,
    origin: window.location.origin,
  })(file);
}

// Adapted from BigNuten_Vanilla/js/issueHelper.js (Apache-2.0).
// Local text only: no wallet, chat, logs, storage, model or posting credentials.
export const ISSUE_DESTINATION = 'https://github.com/TheJollyLaMa/DecentBusking/issues/new';
export const ISSUE_LIMITS = Object.freeze({ field: 1500, title: 120, body: 5000, url: 7500 });
const CREDENTIAL = String.raw`\b[a-z0-9_-]{0,64}(?:authorization|bearer|password|passwd|secret|seed(?:\s+phrase)?|mnemonic|private[\s_-]*key|api[\s_-]*key|client[\s_-]*secret|(?:access|refresh|session)[\s_-]*(?:key|token)|token|credential|jwt)\b`;
const ADDRESS = /0x[a-f0-9]{40}\b|\b(?:bc1|tb1)[a-z0-9]{25,87}\b|\b[13][a-km-zA-HJ-NP-Z1-9]{25,34}\b|[\p{L}\p{N}.!#$%&'*+/=?^_`{|}~-]+@[\p{L}\p{N}.-]+\.[\p{L}]{2,}|\b(?:\d{1,3}\.){3}\d{1,3}\b|\b(?:[a-f0-9]{1,4}:){2,}[a-f0-9:]{1,4}\b|::[a-f0-9]{1,4}\b|\b\d{1,6}\s+(?:[\p{L}\d.'-]+\s+){0,5}(?:street|st|road|rd|avenue|ave|lane|ln|drive|dr|court|ct|boulevard|blvd)\b/giu;

export function sanitizeIssueText(value, limit = ISSUE_LIMITS.field) {
  if (typeof value !== 'string') throw new Error('Report fields must be text.');
  if (value.length > limit) throw new Error(`Text is too long (maximum ${limit} characters). Shorten it and review again.`);
  let text = value.normalize('NFKC').replace(/\p{Cf}/gu, '');
  for (let i = 0; i < 4 && /%[a-f0-9]{2}/i.test(text); i++) {
    try { text = decodeURIComponent(text); }
    catch { throw new Error('Malformed URL encoding. Remove it before continuing.'); }
  }
  text = text.normalize('NFKC').replace(/\p{Cf}/gu, '').trim();
  if (/%[a-f0-9]{2}/i.test(text) || /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f\uD800-\uDFFF]/u.test(text)) {
    throw new Error('Unsupported or excessively encoded text. Remove it before continuing.');
  }
  return text

    .replace(/-----BEGIN [^-]*(?:PRIVATE KEY|SECRET)[^-]*-----[\s\S]*?(?:-----END [^-]+-----|$)/gi, '[redacted]')
    .replace(new RegExp(CREDENTIAL + `[ \\t:="'-]*\\r?\\n[\\s\\S]*`, 'gi'), '[redacted]')
    .replace(new RegExp(CREDENTIAL + '[^\\n]*', 'gi'), '[redacted]')
    .replace(/\b(?:gh[pousr]_[a-z0-9_]+|github_pat_[a-z0-9_]+|sk-[a-z0-9_-]+|(?:AKIA|ASIA)[A-Z0-9]{16}|xox[baprs]-[a-z0-9-]+)\b/gi, '[redacted]')
    .replace(/\b[a-z0-9_-]{20,}\.[a-z0-9_-]{6,}\.[a-z0-9_-]{20,}\b/gi, '[redacted]')
    .replace(/[a-z][a-z0-9+.-]*:\/\/[^\s<>]+/gi, '[removed URL]')
    .replace(/(?:0x)?[a-f0-9]{48,}/gi, '[removed key-like data]')
    .replace(/\b[a-z0-9_+/=-]{32,}\b/gi, '[removed key-like data]')
    .replace(ADDRESS, '[removed address]')
    .replace(/<@(?:!|&)?\d+>|\b\d{16,22}\b/g, '[removed identifier]');
}

export function reviewIssueDraft({ title, body }) {
  const cleanTitle = sanitizeIssueText(title, ISSUE_LIMITS.title).replace(/\s+/g, ' ');
  const cleanBody = sanitizeIssueText(body, ISSUE_LIMITS.body);
  if (!cleanTitle || !cleanBody) throw new Error('A title and report body are required.');
  const url = new URL(ISSUE_DESTINATION);
  url.search = new URLSearchParams({ title: cleanTitle, body: cleanBody, labels: 'bug,bug-catcher-pending' }).toString();
  if (url.href.length > ISSUE_LIMITS.url) throw new Error('The GitHub link is too long. Shorten your report and review again.');
  const search = new URL('https://github.com/TheJollyLaMa/DecentBusking/issues');
  search.searchParams.set('q', `is:issue ${cleanTitle.replace(/[^\p{L}\p{N}\s]/gu, ' ').trim()}`);
  return { title: cleanTitle, body: cleanBody, url: url.href, searchUrl: search.href,
    redacted: cleanTitle !== title.trim() || cleanBody !== body.trim() };
}

export function buildIssueDraft(input) {

  const headings = {
    actual: 'What happened?', expected: 'What did you expect?',
    steps: 'Steps to reproduce', impact: 'Impact',
    environment: 'Browser, device and page or control',
  };
  const parts = Object.entries(headings).map(([field, heading]) => {
    const text = sanitizeIssueText(input[field]);
    if (!text) throw new Error(`Please answer: ${heading}`);
    return `### ${heading}\n${text}`;
  });
  return reviewIssueDraft({ title: input.title, body: `## Bug report\n\n${parts.join('\n\n')}` });
}

import { ISSUE_LIMITS, buildIssueDraft, reviewIssueDraft } from './issue-draft.mjs';

export function openIssueHelper({ document = globalThis.document } = {}) {
  if (document.getElementById('issue-helper')) return;
  let previous = document.activeElement;
  while (previous?.shadowRoot?.activeElement) previous = previous.shadowRoot.activeElement;
  previous = previous?.closest('.ankh-left')?.querySelector('.ankh-coin') || previous;
  const dialog = document.createElement('dialog');
  dialog.id = 'issue-helper';
  dialog.setAttribute('aria-labelledby', 'issue-helper-heading');
  dialog.innerHTML = `
    <header><img src="img/D_Busker.jpeg" alt="" width="56" height="56"><div><h2 id="issue-helper-heading">Found a problem? Let's write it up.</h2><p>One problem, one GitHub issue. You are the reporter.</p></div></header>
    <p>This helper is local and needs no wallet or AI sign-in. Nothing is saved, uploaded or submitted here. If you ask DBusker for wording, paste only the text you want to share into the draft below.</p>
    <p>GitHub issues are public. Credentials, URLs, wallet addresses and other address-like text are stripped conservatively. This is not a complete privacy detector: inspect every word. Add only reviewed public screenshots or evidence on GitHub yourself.</p>
    <form autocomplete="off">
      <label>Short title<input name="title" maxlength="${ISSUE_LIMITS.title}" required></label>
      <label>What happened?<textarea name="actual" maxlength="${ISSUE_LIMITS.field}" required></textarea></label>
      <label>What should have happened?<textarea name="expected" maxlength="${ISSUE_LIMITS.field}" required></textarea></label>
      <label>Steps to reproduce<textarea name="steps" maxlength="${ISSUE_LIMITS.field}" required></textarea></label>

    review(() => buildIssueDraft(fields));
  });
  find('[data-review]').addEventListener('click', () => review(() => reviewIssueDraft({ title: title.value, body: body.value })));
  dialog.addEventListener('input', event => {
    if (event.target.matches('[data-confirm], [data-duplicates]')) sync();
    else if (event.target.matches('input, textarea')) invalidate();
  });
  find('[data-copy]').addEventListener('click', async () => {
    if (!reviewed || find('[data-copy]').disabled) return;
    try {
      await document.defaultView.navigator.clipboard.writeText(`${reviewed.title}\n\n${reviewed.body}`);
      status.textContent = 'Reviewed report copied. Paste it on GitHub if needed, review it there, and submit.';
    } catch (error) { status.textContent = `Copy unavailable: ${error.message}. Select the reviewed text above and copy it manually.`; }
  });
  const close = () => { dialog.close(); dialog.remove(); previous?.focus(); };
  find('[data-close]').addEventListener('click', close);
  dialog.addEventListener('keydown', event => {
    if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(); }
  });
  dialog.addEventListener('cancel', event => { event.preventDefault(); close(); });
  document.body.append(dialog);
  dialog.showModal();
  find('[name="title"]').focus();
}

if (typeof document !== 'undefined') {
  document.addEventListener('open-issue-helper', () => openIssueHelper());
}

