export const LIVE_RECORDING_SAMPLE_RATE = 48_000;
export const LIVE_RECORDING_MIN_RELEASE_SAMPLES = LIVE_RECORDING_SAMPLE_RATE / 2;
export const LIVE_RECORDING_MAX_SONG_SAMPLES = LIVE_RECORDING_SAMPLE_RATE * 30 * 60;
export const LIVE_RECORDING_MAX_SONGS = 50;

const draftPrefix = (wallet, id) => `decentbusking:recording-draft:v1:${wallet.toLowerCase()}:${id}:`;
export const recordingDraftKey = (wallet, id, cid) => `${draftPrefix(wallet, id)}${cid}`;

export function hasLocalRecordingDraft(storage, wallet, bookingId) {
  const prefix = draftPrefix(wallet, bookingId);
  for (let i = 0; i < (storage?.length ?? 0); i++) {
    const key = storage.key(i);
    if (!key?.startsWith(prefix) || !/^[a-z0-9]+$/i.test(key.slice(prefix.length))) continue;
    try {
      const saved = JSON.parse(storage.getItem(key));
      if (saved?.schema === 1 && saved.draft?.songs?.length > 0) return true;
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      console.warn('Could not read the saved recording draft.', error.name);
    }
  }
  return false;
}

const validTitle = (value, limit) => typeof value === 'string' &&
  value.trim().length > 0 && value.trim().length <= limit && !/[\u0000-\u001f\u007f]/.test(value);

export function canEditCatalogRecording(nft = {}, walletAddress = '') {
  const wallet = String(walletAddress || '').toLowerCase();
  const artist = /^0x[0-9a-f]{40}$/i.test(nft.artist || '')
    ? String(nft.artist).toLowerCase() : String(nft.creator || '').toLowerCase();
  const source = String(nft.audioUrl || nft.animation_url || '');
  const cid = source.match(/^ipfs:\/\/([^/?#]+)$/i)?.[1] ||
    source.match(/^https:\/\/[^/]+\/ipfs\/([^/?#]+)$/i)?.[1] || '';
  return /^0x[0-9a-f]{40}$/.test(wallet) && artist === wallet &&

    (nft.chainId ?? 8453) === 8453 &&
    /^0x[0-9a-f]{40}$/i.test(nft.contractAddress || '') &&
    nft.tokenId !== undefined && nft.tokenId !== null && nft.tokenId !== '' &&
    Number.isSafeInteger(Number(nft.tokenId)) && Number(nft.tokenId) >= 0 &&
    /^[a-zA-Z0-9]{20,120}$/.test(cid) &&
    String(nft.mediaType || 'audio/mpeg').startsWith('audio/');
}

export function recordingBoundaryRange(draft, totalSamples, index, key) {
  const song = draft?.songs?.[index];
  if (!song || !Number.isSafeInteger(index) || index < 0 || !['startSample', 'endSample'].includes(key) ||
      !Number.isSafeInteger(totalSamples) || totalSamples <= 0 ||
      !draft.songs.every(track => Number.isSafeInteger(track.startSample) && Number.isSafeInteger(track.endSample) &&
        track.startSample >= 0 && track.endSample >= track.startSample && track.endSample <= totalSamples)) {
    throw Error('Recording boundaries are unavailable');
  }
  const previous = draft.songs[index - 1], next = draft.songs[index + 1];
  const paired = key === 'endSample' && next?.startSample === song.endSample;
  const min = key === 'startSample'
    ? Math.max(previous?.endSample || 0, song.endSample - LIVE_RECORDING_MAX_SONG_SAMPLES)
    : Math.max(song.startSample + LIVE_RECORDING_MIN_RELEASE_SAMPLES,
      paired ? next.endSample - LIVE_RECORDING_MAX_SONG_SAMPLES : 0);
  const max = key === 'startSample'
    ? song.endSample - LIVE_RECORDING_MIN_RELEASE_SAMPLES
    : Math.min(paired ? next.endSample - LIVE_RECORDING_MIN_RELEASE_SAMPLES : next?.startSample ?? totalSamples,
      song.startSample + LIVE_RECORDING_MAX_SONG_SAMPLES, totalSamples);
  if (min > max) throw Error('Correct the surrounding song boundaries before moving this cut');
  return { min, max, paired };
}

export function moveRecordingBoundary(draft, totalSamples, index, key, sample) {
  if (!Number.isFinite(sample)) throw Error('Invalid recording cut position');
  const range = recordingBoundaryRange(draft, totalSamples, index, key);
  const next = structuredClone(draft);
  const value = Math.max(range.min, Math.min(range.max, Math.round(sample)));
  next.songs[index][key] = value;
  if (range.paired) next.songs[index + 1].startSample = value;
  return next;
}

export function recordingSourceSamples(segments) {
  if (!Array.isArray(segments) || !segments.length) throw Error('Recording source is unavailable');
  const bytes = segments.reduce((total, segment) => {
    if (!Number.isSafeInteger(segment?.bytes) || segment.bytes <= 0 || segment.bytes % 2 !== 0) {
      throw Error('Recording source duration is invalid');
    }
    return total + segment.bytes;
  }, 0);
  const samples = bytes / 2;
  if (!Number.isSafeInteger(samples) || samples <= 0) throw Error('Recording source duration is invalid');
  return samples;
}

export function validateRecordingDraft(draft, totalSamples) {
  if (!Number.isSafeInteger(totalSamples) || totalSamples <= 0 ||
      !draft || typeof draft !== 'object' || Array.isArray(draft) ||
      Object.keys(draft).some(key => !['revision', 'albumTitle', 'songs'].includes(key)) ||
      !Number.isSafeInteger(draft.revision) || draft.revision < 0 ||
      !validTitle(draft.albumTitle, 120) ||
      !Array.isArray(draft.songs) || draft.songs.length < 1 || draft.songs.length > LIVE_RECORDING_MAX_SONGS) {
    throw Error('Invalid recording edit');
  }
  let previousEnd = 0;
  const titles = new Set();
  const songs = draft.songs.map((song, index) => {
    if (!song || typeof song !== 'object' || Array.isArray(song) ||

        Object.keys(song).some(key => !['title', 'startSample', 'endSample'].includes(key)) ||
        !validTitle(song.title, 100) ||
        !Number.isSafeInteger(song.startSample) || !Number.isSafeInteger(song.endSample) ||
        song.startSample < previousEnd || song.endSample > totalSamples ||
        song.endSample - song.startSample < LIVE_RECORDING_MIN_RELEASE_SAMPLES ||
        song.endSample - song.startSample > LIVE_RECORDING_MAX_SONG_SAMPLES) {
      throw Error(`Invalid song boundary or title at track ${index + 1}`);
    }
    const title = song.title.trim();
    const key = title.toLocaleLowerCase('en');
    if (titles.has(key)) throw Error('Song titles must be unique within the release');
    titles.add(key);
    previousEnd = song.endSample;
    return { title, startSample: song.startSample, endSample: song.endSample };
  });
  return { revision: draft.revision, albumTitle: draft.albumTitle.trim(), songs };
}

export function validateCatalogRecordingDraft(draft, totalSamples) {
  const normalized = validateRecordingDraft(draft, totalSamples);
  if (normalized.songs.length > 4) throw Error('A catalog recording can have at most four cuts');
  return normalized;
}

function validCatalogIdentity(nftId) {
  return typeof nftId === 'string' && /^8453:0x[0-9a-f]{40}:\d{1,20}$/i.test(nftId);
