async function openHistory(event) {
  const currentRequest = ++requestId;
  mode = event?.detail?.mode === 'personal' ? 'personal' : 'totals';
  wallet = mode === 'personal' ? String(window._wallet?.address || '') : '';
  reports = [];
  fundingState = null;
  openSections.clear();
  weekSelect.replaceChildren();
  searchInput.value = '';

if (viewSelect) {
  viewSelect.value = '';
  viewSelect.querySelector?.('option[value="funding"]')?.toggleAttribute?.('hidden', mode !== 'personal');
}
artistSelect.value = '';
fromInput.value = '';
toInput.value = '';
if (!dialog.open) dialog.showModal();
content.textContent = 'Loading playback tally…';
if (titleEl) titleEl.textContent = mode === 'personal' ? 'My Playback Tally' : 'Playback Tally';
if (rewardsEl) {
  rewardsEl.hidden = mode !== 'personal' || !/^0x[0-9a-fA-F]{40}$/.test(wallet);
  rewardsEl.replaceChildren();
}
if (noteEl) noteEl.textContent = mode === 'personal'
  ? `Playback tally for connected wallet ${wallet.slice(0, 6)}…${wallet.slice(-4)}`
  : 'Community playback tally';
try {
  const service = (window.DecentConfig?.ipfsUploadServiceUrl || '').replace(/\/$/, '');
  if (!service) throw new Error('Playback tally service is not configured');
  if (mode === 'personal' && !/^0x[0-9a-fA-F]{40}$/.test(wallet)) throw new Error('Connect your wallet to view My Playback Tally.');
  const query = new URLSearchParams({ weeks: '12', includeAllTime: '1' });
  query.set('calendar', 'new-york');
  if (wallet) query.set('wallet', wallet);
  const response = await fetch(`${service}/api/radio/history?${query}`, { cache: 'no-store' });
  const result = await response.json();
  if (currentRequest !== requestId) return;
  if (!response.ok) throw new Error(result.error || `History unavailable (${response.status})`);
  reports = Array.isArray(result.weeks) ? result.weeks : [];
  weekSelect.replaceChildren(...reports.slice().reverse().map((report) => {
    const option = document.createElement('option');
    option.value = report.week;

      option.textContent = report.week === 'all-time' ? 'All Time' : `${report.week}${report.current ? ' · current' : ''}`;
      return option;
    }));
    if (!reports.length) {
      content.textContent = 'No playback tally has been recorded yet.';
      return;
    }
    weekSelect.value = (reports.find(report => report.week === 'all-time') || reports.at(-1)).week;
    renderWeek();
    if (mode === 'personal') await loadArtistFunding(service, currentRequest, wallet);
  } catch (error) {
    if (currentRequest === requestId) content.textContent = error.message;
  }
}

function init() {
  dialog = document.getElementById('radio-history-dialog');
  weekSelect = document.getElementById('radio-history-week');
  content = document.getElementById('radio-history-content');
  titleEl = document.getElementById('radio-history-title');
  noteEl = dialog?.querySelector('.radio-history-note');
  searchInput = document.getElementById('radio-history-search');
  artistSelect = document.getElementById('radio-history-artist');
  fromInput = document.getElementById('radio-history-from');
  toInput = document.getElementById('radio-history-to');
  rewardsEl = document.getElementById('radio-history-rewards');
  viewSelect = document.getElementById('radio-history-view');
  if (!dialog || !weekSelect || !content) return;
  setInterval(() => {
    if (!dialog.open || mode !== 'personal' || !wallet) return;
    const service = (window.DecentConfig?.ipfsUploadServiceUrl || '').replace(/\/$/, '');
    if (service) loadArtistFunding(service, requestId, wallet, false);
  }, 15000);
  document.addEventListener('open-radio-history', openHistory);
  document.addEventListener('wallet-connected', () => {
    if (dialog.open && mode === 'personal') openHistory({ detail: { mode: 'personal' } });

  });
  document.addEventListener('wallet-disconnected', () => {
    if (mode !== 'personal') return;
    ++requestId;
    reports = [];
    wallet = '';
    fundingState = null;
    content.replaceChildren();
    weekSelect.replaceChildren();
    if (rewardsEl) rewardsEl.hidden = true;
    if (dialog.open) dialog.close();
  });
  document.getElementById('radio-history-close')?.addEventListener('click', () => dialog.close());
  weekSelect.addEventListener('change', renderWeek);
  searchInput?.addEventListener('input', refresh);
  viewSelect?.addEventListener('change', refresh);
  artistSelect?.addEventListener('change', renderWeek);
  fromInput?.addEventListener('change', renderWeek);
  toInput?.addEventListener('change', renderWeek);
  dialog.addEventListener('click', (event) => {
    const bounds = dialog.getBoundingClientRect();
    if (event.target === dialog && (event.clientX < bounds.left || event.clientX > bounds.right ||
        event.clientY < bounds.top || event.clientY > bounds.bottom)) dialog.close();
  });
}

document.addEventListener('DOMContentLoaded', init, { once: true });

import { BASE_USDC_ADDRESS } from './settlement-funds.mjs?v=20261017-mercury-release';
import { announcePaymentCelebration } from './payment-celebration.mjs';
import { previewTopTenSongPayroll, songPayoutSplits } from './top-ten-prizes.mjs';
import { formatUsdcUnits as formatUsdc } from './usdc-format.mjs?v=20261017-mercury-release';
import { payrollPeriodFromKey, PAYROLL_TIME_ZONE, overlappingUtcWeeks } from './payroll-week.mjs';

const WALLET = /^0x[0-9a-fA-F]{40}$/;

function hasPayoutWallet(wallet) {
  return WALLET.test(wallet || '') && !/^0x0{40}$/i.test(wallet);
}

export function playbackArtistKey(track) {
  if (hasPayoutWallet(track?.wallet)) return track.wallet.toLowerCase();
  const artist = String(track?.artist || '').trim().toLowerCase();
  return `unlinked:${artist ? `artist:${artist}` : `track:${String(track?.trackId || '').toLowerCase()}`}`;
}

// Each payee earns plays weighted by its song share (basis points); single-wallet songs weigh 10000 per play.
function eligibleArtists(tracks, splitSongs = false) {
  const artists = new Map();
  for (const track of tracks) {
    if (!Number.isSafeInteger(track.plays) || track.plays <= 0) continue;
    const splits = splitSongs ? songPayoutSplits(track) : null;
    const payees = splits || (hasPayoutWallet(track.wallet) ? [{ wallet: track.wallet, shareBps: 10000 }] : []);
    for (const payee of payees) {
      const key = payee.wallet.toLowerCase();
      const artist = artists.get(key) || { wallet: payee.wallet, artist: track.artist, plays: 0, tracks: 0, weightBps: 0n };
      artist.plays += track.plays;
      artist.weightBps += BigInt(track.plays) * BigInt(payee.shareBps);
      if (!Number.isSafeInteger(artist.plays)) throw new Error('Playback total exceeds safe accounting precision');

      artist.tracks++;
      artists.set(key, artist);
    }
  }
  return [...artists.values()].sort((first, second) => (second.weightBps > first.weightBps ? 1 : second.weightBps < first.weightBps ? -1 : 0) ||
    second.plays - first.plays || first.wallet.localeCompare(second.wallet));
}

function checkBudget(budgetUnits, minimumUnits) {
  if (typeof budgetUnits !== 'bigint' || budgetUnits < 0n || typeof minimumUnits !== 'bigint' || minimumUnits < 0n) {
    throw new Error('Budgets must be nonnegative token-unit amounts');
  }
}

export function previewPlaybackPayroll({ tracks, budgetUnits, minimumUnits = 0n, splitSongs = false }) {
  checkBudget(budgetUnits, minimumUnits);
  const artists = eligibleArtists(tracks, splitSongs);
  const unlinkedArtists = new Map();
  for (const track of tracks) {
    if (hasPayoutWallet(track.wallet) || (splitSongs && songPayoutSplits(track)) || !Number.isSafeInteger(track.plays) || track.plays <= 0) continue;
    const artist = String(track.artist || '');
    const key = playbackArtistKey(track);
    const entry = unlinkedArtists.get(key) || { wallet: '', artist, plays: 0, tracks: 0, shareKey: key };
    entry.plays += track.plays;
    if (!Number.isSafeInteger(entry.plays)) throw new Error('Playback total exceeds safe accounting precision');
    entry.tracks++;
    unlinkedArtists.set(key, entry);
  }
  const totalPlays = tracks.reduce((total, track) =>
    total + (Number.isSafeInteger(track.plays) && track.plays > 0 ? BigInt(track.plays) : 0n), 0n);
  let allocated = 0n;
  const entries = artists.map(({ weightBps, ...artist }) => {
    const amountUnits = totalPlays ? budgetUnits * weightBps / (totalPlays * 10000n) : 0n;
    const payable = amountUnits > 0n && amountUnits >= minimumUnits;
    if (payable) allocated += amountUnits;

    return { ...artist, amountUnits, payable };
  });
  const forfeitedEntries = [...unlinkedArtists.values()].map(artist => ({
    ...artist,
    amountUnits: totalPlays ? budgetUnits * BigInt(artist.plays) / totalPlays : 0n,
    payable: false,
  }));
  const forfeitedUnits = forfeitedEntries.reduce((total, artist) => total + artist.amountUnits, 0n);
  entries.push(...forfeitedEntries);
  return { entries, totalPlays, forfeitedUnits, allocatedUnits: allocated, remainderUnits: budgetUnits - allocated };
}

function voteRankedArtists(tracks) {
  const artists = new Map();
  for (const track of tracks) {
    if (!WALLET.test(track.wallet || '') || /^0x0{40}$/i.test(track.wallet) || !Number.isSafeInteger(track.votes)) continue;
    const key = track.wallet.toLowerCase();
    const artist = artists.get(key) || { wallet: track.wallet, artist: track.artist, plays: 0, votes: 0, tracks: 0 };
    artist.votes += track.votes;
    artist.plays += Number.isSafeInteger(track.plays) && track.plays >= 0 ? track.plays : 0;
    if (!Number.isSafeInteger(artist.votes) || !Number.isSafeInteger(artist.plays)) throw new Error('Vote total exceeds safe accounting precision');
    artist.tracks++;
    artists.set(key, artist);
  }
  return [...artists.values()].filter(artist => artist.votes > 0)
    .sort((first, second) => second.votes - first.votes || first.wallet.toLowerCase().localeCompare(second.wallet.toLowerCase()));
}

function normalizeTopTenRanking(ranking) {
  const value = String(ranking || 'votes').replace(/-halving$/, '');
  return value === 'plays' ? 'plays' : 'votes';
}

function previewLegacyTopTenPayroll({ tracks, budgetUnits, minimumUnits = 0n, ranking = 'votes' }) {

  const artists = (normalizeTopTenRanking(ranking) === 'votes' ? voteRankedArtists(tracks) : eligibleArtists(tracks)).slice(0, 10);
  const amountUnits = artists.length ? budgetUnits / BigInt(artists.length) : 0n;
  const entries = artists.map((artist, index) => ({ ...artist, rank: index + 1, amountUnits,
    payable: amountUnits > 0n && amountUnits >= minimumUnits }));
  const allocated = entries.reduce((total, entry) => total + (entry.payable ? entry.amountUnits : 0n), 0n);
  return { entries, allocatedUnits: allocated, remainderUnits: budgetUnits - allocated };
}

function previewHalvingTopTenPayroll({ tracks, budgetUnits, minimumUnits = 0n, ranking = 'votes' }) {
  const artists = (normalizeTopTenRanking(ranking) === 'votes' ? voteRankedArtists(tracks) : eligibleArtists(tracks)).slice(0, 10);
  if (!artists.length || budgetUnits === 0n) return { entries: [], allocatedUnits: 0n, remainderUnits: budgetUnits };
  const theoretical = [];
  let remaining = budgetUnits;
  for (let index = 0; index < artists.length; index++) {
    const amount = index === artists.length - 1 ? remaining : budgetUnits / (2n ** BigInt(index + 1));
    theoretical.push(amount);
    remaining -= amount;
  }
  let payableCount = artists.length;
  for (let index = 0; index < theoretical.length - 1; index++) {
    if (theoretical[index] < minimumUnits) { payableCount = index === 0 ? 1 : index; break; }
  }
  const entries = artists.slice(0, payableCount).map((artist, index) => {
    const amountUnits = index < payableCount - 1
      ? theoretical[index]
      : budgetUnits - theoretical.slice(0, index).reduce((sum, amount) => sum + amount, 0n);
    return { ...artist, rank: index + 1, amountUnits, payable: amountUnits > 0n && amountUnits >= minimumUnits };
  });

  const allocated = entries.reduce((sum, entry) => sum + entry.amountUnits, 0n);
  return { entries, allocatedUnits: allocated, remainderUnits: budgetUnits - allocated };
}

export function previewTopTenPayroll({ tracks, budgetUnits, minimumUnits = 0n, ranking = 'votes' }) {
  checkBudget(budgetUnits, minimumUnits);
  const normalized = normalizeTopTenRanking(ranking);
  if (!['votes', 'plays'].includes(normalized)) throw new Error('Invalid Top 10 ranking');
  return previewHalvingTopTenPayroll({ tracks, budgetUnits, minimumUnits, ranking: normalized });
}

export function radioWorkReferenceText({ week, category, wallet, trackId }) {
  const ny = String(week || '').startsWith('NY-');
  if (ny) payrollPeriodFromKey(week);
  if ((!ny && !/^\d{4}-W(?:0[1-9]|[1-4]\d|5[0-3])$/.test(week || '')) || !['playback', 'top10'].includes(category) || !WALLET.test(wallet || '')) {
    throw new Error('Invalid radio payout identity');
  }
  if (trackId !== undefined) {
    if (category !== 'top10' || typeof trackId !== 'string' || !trackId.trim() || trackId.length > 512) throw new Error('Invalid song payout identity');
    return `decentbusking:radio:v4:8453:${week}:${category}:${wallet.toLowerCase()}:${encodeURIComponent(trackId)}`;
  }
  return `decentbusking:radio:${ny ? 'v3' : 'v1'}:8453:${week}:${category}:${wallet.toLowerCase()}`;
}

function isSongPrizeAllocation(allocation) {
  return allocation?.category === 'top10' && allocation.schemaVersion >= 5;
}

// Schema 6 receipts freeze each song's split, so later split changes cannot alter a closed week.
function withFrozenSplits(tracks, allocation) {
  if (!(allocation.schemaVersion >= 6)) return tracks;

  const frozen = new Map((Array.isArray(allocation.songSplits) ? allocation.songSplits : []).map(song => [song.trackId, song.splits]));
  return tracks.map(track => {
    const { splits, ...rest } = track;
    return frozen.has(track.trackId) ? { ...rest, splits: frozen.get(track.trackId) } : rest;
  });
}

// Rebuild one chart row per song from a frozen receipt whose split prizes have one entry per payee.
export function tracksFromAllocationEntries(allocation) {
  if (allocation.schemaVersion < 6 || allocation.category !== 'top10') return allocation.entries;
  const songs = new Map();
  for (const entry of allocation.entries || []) if (!songs.has(entry.trackId)) songs.set(entry.trackId, entry);
  return withFrozenSplits([...songs.values()], allocation);
}

function frozenReport(report, allocation) {
  return report || { week: allocation.week, current: false, tracks: tracksFromAllocationEntries(allocation) };
}

export function radioAllocationMatchesReport(report, allocation) {
  try {
    if (!report || !allocation || report.current || report.week !== allocation.week || !Array.isArray(report.tracks)) return false;
    const budgetUnits = BigInt(allocation.budgetUnits);
    const minimumUnits = BigInt(allocation.minimumUnits);
    const ranking = allocation.schemaVersion === 1 ? 'plays' : normalizeTopTenRanking(allocation.ranking);
    const splitSongs = allocation.schemaVersion >= 6;
    const tracks = withFrozenSplits(report.tracks, allocation);
    const plan = allocation.category === 'playback'
      ? previewPlaybackPayroll({ tracks, budgetUnits, minimumUnits, splitSongs })
      : (allocation.schemaVersion >= 5
        ? previewTopTenSongPayroll({ tracks, budgetUnits, minimumUnits, splitSongs })
        : allocation.schemaVersion < 4

        ? previewLegacyTopTenPayroll({ tracks: report.tracks, budgetUnits, minimumUnits, ranking })
        : previewTopTenPayroll({ tracks: report.tracks, budgetUnits, minimumUnits, ranking }));
    const expectedEntries = plan.entries.filter(entry => entry.payable);
    if (BigInt(allocation.allocatedUnits) !== plan.allocatedUnits || BigInt(allocation.remainderUnits) !== plan.remainderUnits ||
        expectedEntries.length !== allocation.entries?.length) return false;
    return expectedEntries.every((expected, index) => {
      const actual = allocation.entries[index];
      return actual.wallet?.toLowerCase() === expected.wallet.toLowerCase() && actual.plays === expected.plays &&
        (expected.votes === undefined || actual.votes === expected.votes) &&
        (expected.rank === undefined || actual.rank === expected.rank) &&
        (!isSongPrizeAllocation(allocation) || actual.trackId === expected.trackId) &&
        BigInt(actual.amountUnits) === expected.amountUnits &&
        actual.workReferenceText === radioWorkReferenceText({ week: report.week, category: allocation.category, wallet: expected.wallet,
