const plan = category === 'playback' ? previewPlaybackPayroll({ tracks: report.tracks, budgetUnits, minimumUnits, splitSongs })
  : (topTenScheduleVersion >= 3
    ? previewTopTenSongPayroll({ tracks: report.tracks, budgetUnits, minimumUnits, splitSongs })
    : topTenScheduleVersion === 1
    ? previewLegacyTopTenPayroll({ tracks: report.tracks, budgetUnits, minimumUnits, ranking })
    : previewTopTenPayroll({ tracks: report.tracks, budgetUnits, minimumUnits, ranking }));
const entries = plan.entries.filter(entry => entry.payable);
if (!entries.length) throw new Error('No payouts meet the minimum threshold');
const songPrizes = category === 'top10' && topTenScheduleVersion >= 3;

  if (songPrizes && entries.some(entry => !hasPayoutWallet(entry.wallet))) throw new Error('Link the artist wallet for every winning song before finalizing Top 10');
  return { schemaVersion: splitSongs ? 6 : songPrizes ? 5 : category === 'top10' ? 4 : period ? 3 : 2, ...(period ? { timeZone: PAYROLL_TIME_ZONE, startAt: period.startAt, endAt: period.endAt, partial: Boolean(report.partial) } : {}),
    ranking: category === 'playback' ? 'qualified-plays' : songPrizes ? 'song-votes-halving' : `${normalizeTopTenRanking(ranking)}-halving`, station: 'decentbusking', chainId: 8453, category, week: report.week,
    routerAddress, assetAddress, fundSlug, budgetUnits: budgetUnits.toString(), minimumUnits: minimumUnits.toString(),
    allocatedUnits: plan.allocatedUnits.toString(), remainderUnits: plan.remainderUnits.toString(),
    finalizedAt: new Date(now).toISOString(),
    ...(splitSongs ? { songSplits: report.tracks.map(track => ({ trackId: track.trackId, splits: songPayoutSplits(track) }))
      .filter(song => song.splits) } : {}),
    entries: entries.map(entry => ({ wallet: entry.wallet, artist: entry.artist || '', plays: entry.plays,
      ...(songPrizes ? { trackId: entry.trackId, title: entry.title || '' } : {}),
      ...(entry.splitShareBps ? { splitShareBps: entry.splitShareBps, songAmountUnits: entry.songAmountUnits.toString() } : {}),
      ...(category === 'top10' ? { votes: entry.votes, rank: entry.rank } : {}),
      amountUnits: entry.amountUnits.toString(), workReferenceText: radioWorkReferenceText({ week: report.week, category, wallet: entry.wallet,
        ...(songPrizes ? { trackId: entry.trackId } : {}) }) })) };
}

export async function settleRadioAllocation(options) {

const { allocation, metadataUri, metadataHash, report, router, hashReference } = options;
if (!allocation || allocation.chainId !== 8453 || allocation.routerAddress?.toLowerCase() !== router.target.toLowerCase()) throw new Error('Finalized allocation does not match this Base router');
if (!/^ipfs:\/\/[^/\s]+$/.test(metadataUri || '') || !/^0x[0-9a-fA-F]{64}$/.test(metadataHash || '')) throw new Error('An immutable IPFS allocation receipt is required');
if (allocation.assetAddress?.toLowerCase() !== BASE_USDC_ADDRESS.toLowerCase()) throw new Error('Radio settlement supports native Base USDC only');
const validated = finalizeRadioAllocation({ report: { week: allocation.week, current: false,
  tracks: tracksFromAllocationEntries(allocation) }, splitSongs: allocation.schemaVersion >= 6,
  category: allocation.category, budgetUnits: BigInt(allocation.budgetUnits), minimumUnits: BigInt(allocation.minimumUnits),
  ranking: allocation.schemaVersion === 1 ? 'plays' : allocation.ranking,
  topTenScheduleVersion: allocation.schemaVersion >= 5 ? 3 : allocation.schemaVersion < 4 ? 1 : 2,
  fundSlug: allocation.fundSlug, routerAddress: allocation.routerAddress, assetAddress: allocation.assetAddress });
if (validated.week !== allocation.week) throw new Error('Invalid completed week');
if (isSongPrizeAllocation(allocation) && !radioAllocationMatchesReport(frozenReport(report, allocation), allocation)) throw new Error('Song prizes do not match the frozen chart allocation; load the full closed-week report including forfeited positions');
return settleReviewedFundAllocation({ ...options, identityPrefix: 'radio-artist',
  paymentLabel: allocation.category === 'playback' ? 'Playback' : 'Top 10', entryLabel: 'song prizes',

    workReferenceFor: entry => radioWorkReferenceText({ week: allocation.week, category: allocation.category, wallet: entry.wallet,
      ...(isSongPrizeAllocation(allocation) ? { trackId: entry.trackId } : {}) }),
    checkUnpaid: async entry => {
      if (isSongPrizeAllocation(allocation) && await router.completedWorkReferences(hashReference(radioWorkReferenceText({ week: allocation.week, category: allocation.category, wallet: entry.wallet })))) throw new Error('An artist-based prize was already paid for this week; manual reconciliation required');
      if (allocation.schemaVersion >= 3 && String(allocation.week).startsWith('NY-')) {
        for (const legacyWeek of overlappingUtcWeeks(payrollPeriodFromKey(allocation.week))) {
          const legacy = radioWorkReferenceText({ week: legacyWeek, category: allocation.category, wallet: entry.wallet });
          if (await router.completedWorkReferences(hashReference(legacy))) throw new Error('A paid legacy UTC receipt overlaps this New York period; manual reconciliation required');
        }
      }
    } });
}

export async function settleReviewedFundAllocation({ allocation, metadataUri, metadataHash, router, signer, owner,
  hashReference, workReferenceFor, identityPrefix, paymentLabel, entryLabel = 'entries',
  checkUnpaid = async () => {}, onStep = () => {}, onConfirmed = async () => {}, onTransaction }) {
  if (allocation.chainId !== 8453 || allocation.routerAddress?.toLowerCase() !== router.target.toLowerCase() ||
    allocation.assetAddress?.toLowerCase() !== BASE_USDC_ADDRESS.toLowerCase()) throw new Error('Allocation does not match this Base USDC router');

if (!/^ipfs:\/\/[^/\s]+$/.test(metadataUri || '') || !/^0x[0-9a-fA-F]{64}$/.test(metadataHash || '')) throw new Error('An immutable IPFS allocation receipt is required');
if (Number((await signer.provider.getNetwork()).chainId) !== 8453 || (await signer.getAddress()).toLowerCase() !== owner?.toLowerCase()) throw new Error('Connect the Base owner wallet');
const waitForTransaction = async (transaction, detail) => {
  let receipt;
  try {
    receipt = await transaction.wait();
  } catch (error) {
    if (error.receipt?.status === 0) await onTransaction?.({ ...detail, kind: 'failed', txHash: transaction.hash, receipt: error.receipt });
    throw error;
  }
  if (receipt?.status === 1 || receipt?.status === 0) {
    await onTransaction?.({ ...detail, kind: receipt.status === 1 ? detail.kind : 'failed', txHash: transaction.hash, receipt });
  }
  return receipt;
};
if (await router.paused()) throw new Error('Settlement router is paused');
if (!await router.hasRole(await router.PAYROLL_ROLE(), owner)) throw new Error('PAYROLL_ROLE is required');
if (!await router.approvedAssets(allocation.assetAddress)) throw new Error('USDC is not approved');
const fundId = hashReference(allocation.fundSlug);
const fund = await router.funds(fundId);
if (!(fund.exists ?? fund[2]) || !(fund.active ?? fund[1])) throw new Error('Create and activate this fund first');
const unpaid = [];
const recipientsToApprove = new Map();
let reviewedTotal = 0n;
const identities = new Set();
for (const entry of allocation.entries) {
  const identity = workReferenceFor(entry);
  if (identity !== entry.workReferenceText || identities.has(identity) || BigInt(entry.amountUnits) <= 0n) throw new Error('Invalid or duplicate allocation entry');

  identities.add(identity);
  reviewedTotal += BigInt(entry.amountUnits);
  const workReference = hashReference(identity);
  if (await router.completedWorkReferences(workReference)) continue;
  await checkUnpaid(entry);
  const recipient = await router.contributors(entry.wallet);
  if (!(recipient.approved ?? recipient[1])) recipientsToApprove.set(entry.wallet.toLowerCase(), entry.wallet);
  unpaid.push({ ...entry, workReference });
}
const total = unpaid.reduce((sum, entry) => sum + BigInt(entry.amountUnits), 0n);
if (reviewedTotal !== BigInt(allocation.allocatedUnits) || total > reviewedTotal || reviewedTotal > BigInt(allocation.budgetUnits)) throw new Error('Allocation exceeds its reviewed budget or totals do not match');
if (await router.fundBalances(fundId, allocation.assetAddress) < total) throw new Error('Fund has insufficient USDC for unpaid allocations');
if (recipientsToApprove.size) {
  if (!await router.hasRole(await router.CONTRIBUTOR_ADMIN_ROLE(), owner)) throw new Error('CONTRIBUTOR_ADMIN_ROLE is required to enable payroll recipient wallets');
  for (const wallet of recipientsToApprove.values()) {
    const recipient = await router.contributors(wallet);
    if (recipient.approved ?? recipient[1]) continue;
    const existingHash = recipient.githubIdHash ?? recipient[0];
    const identityHash = existingHash && !/^0x0{64}$/i.test(existingHash)
      ? existingHash : hashReference(`${identityPrefix}:${wallet.toLowerCase()}`);
    onStep(`Confirm one-time payroll wallet approval for ${wallet}. This enables payment; it does not transfer USDC.`);
    const transaction = await router.setContributorApproved(wallet, identityHash, true);

    const receipt = await waitForTransaction(transaction, { kind: 'approval', wallet, amountUnits: '0', entries: 0 });
    if (receipt?.status !== 1) throw new Error(`Payroll wallet approval did not confirm for ${wallet}`);
    const updated = await router.contributors(wallet);
    if (!(updated.approved ?? updated[1])) throw new Error(`Payroll wallet approval is not active for ${wallet}`);
  }
}
const confirmed = [];
const walletBatches = new Map();
for (const entry of unpaid) {
  const key = entry.wallet.toLowerCase();
  if (!walletBatches.has(key)) walletBatches.set(key, []);
  walletBatches.get(key).push(entry);
}
for (const batch of walletBatches.values()) {
  const remaining = [];
  for (const entry of batch) {
    if (!await router.completedWorkReferences(entry.workReference)) remaining.push(entry);
  }
  if (!remaining.length) continue;
  const wallet = remaining[0].wallet;
  const amount = remaining.reduce((sum, entry) => sum + BigInt(entry.amountUnits), 0n);
  const repositoryHash = hashReference('TheJollyLaMa/DecentBusking');
  const contributorHash = hashReference(`${identityPrefix}:${wallet.toLowerCase()}`);
  const multiple = remaining.length > 1;
  const args = multiple
    ? [fundId, allocation.assetAddress, wallet, remaining.map(entry => BigInt(entry.amountUnits)),
      remaining.map(entry => entry.workReference), remaining.map(() => repositoryHash),
      remaining.map(() => contributorHash), remaining.map(() => metadataUri), remaining.map(() => metadataHash)]
    : [fundId, allocation.assetAddress, wallet, amount, remaining[0].workReference,
      repositoryHash, contributorHash, metadataUri, metadataHash];
  const payout = multiple ? router.payoutBatch : router.payout;

    await payout.staticCall(...args);
    onStep(`Confirm ${formatUsdc(amount)} USDC to ${wallet}${multiple ? ` for ${remaining.length} ${entryLabel} in one payment` : ''}`);
    const transaction = await payout(...args);
    const receipt = await waitForTransaction(transaction, { kind: 'payout', wallet, amountUnits: amount.toString(), entries: remaining.length });
    if (receipt?.status !== 1) throw new Error(`${paymentLabel} payout did not confirm; refresh before retrying`);
    if (!onTransaction) announcePaymentCelebration({
      chainId: 8453,
      txHash: transaction.hash,
      amountText: formatUsdc(amount),
      assetText: 'USDC',
      summary: `${paymentLabel} payout confirmed`,
      txLabel: `Paid ${wallet.slice(0, 6)}…`,
    });
    for (const entry of remaining) {
      confirmed.push({ wallet: entry.wallet, txHash: transaction.hash });
      await onConfirmed({ ...entry, txHash: transaction.hash });
    }
  }
  return { confirmed, skipped: allocation.entries.length - confirmed.length };
}

export function validateRadioReceipt(allocation, { routerAddress, assetAddress, funds, report }) {
  if (!allocation || ![1, 2, 3, 4, 5, 6].includes(allocation.schemaVersion) || allocation.chainId !== 8453 ||
      !['playback', 'top10'].includes(allocation.category) || allocation.station !== 'decentbusking' ||
      allocation.routerAddress?.toLowerCase() !== routerAddress.toLowerCase() || allocation.assetAddress?.toLowerCase() !== assetAddress.toLowerCase() ||
      allocation.fundSlug !== (allocation.category === 'playback' ? funds.playback : funds.topTen)) throw new Error('Receipt does not match this station, fund, asset, and router');

if (!Array.isArray(allocation.entries) || !allocation.entries.length || allocation.entries.length > 1000) throw new Error('Invalid receipt entries');
if (String(allocation.week).startsWith('NY-')) {
  const period = payrollPeriodFromKey(allocation.week);
  if (allocation.schemaVersion < 3 || allocation.timeZone !== PAYROLL_TIME_ZONE || allocation.startAt !== period.startAt || allocation.endAt !== period.endAt) throw new Error('Receipt payroll timezone or boundaries do not match');
} else if (allocation.schemaVersion >= 3 && allocation.timeZone) throw new Error('New York receipts require the new payroll schema');
finalizeRadioAllocation({ report: { week: allocation.week, current: false,
  tracks: tracksFromAllocationEntries(allocation) }, splitSongs: allocation.schemaVersion >= 6,
  category: allocation.category, budgetUnits: BigInt(allocation.budgetUnits), minimumUnits: BigInt(allocation.minimumUnits),
  ranking: allocation.schemaVersion === 1 ? 'plays' : allocation.ranking,
  topTenScheduleVersion: allocation.schemaVersion >= 5 ? 3 : allocation.schemaVersion < 4 ? 1 : 2,
  fundSlug: allocation.fundSlug, routerAddress, assetAddress });
if (isSongPrizeAllocation(allocation) && !radioAllocationMatchesReport(frozenReport(report, allocation), allocation)) throw new Error('Song prizes do not match the frozen chart allocation; load the full closed-week report including forfeited positions');
const identities = new Set();
let total = 0n;
for (const entry of allocation.entries) {
  const identity = radioWorkReferenceText({ week: allocation.week, category: allocation.category, wallet: entry.wallet,
    ...(isSongPrizeAllocation(allocation) ? { trackId: entry.trackId } : {}) });

    const validCount = allocation.category === 'top10' && normalizeTopTenRanking(allocation.ranking) === 'votes'
      ? Number.isSafeInteger(entry.votes) && entry.votes > 0 && Number.isSafeInteger(entry.plays) && entry.plays >= 0
      : Number.isSafeInteger(entry.plays) && entry.plays > 0;
    if (identity !== entry.workReferenceText || identities.has(identity) || !validCount || BigInt(entry.amountUnits) <= 0n) throw new Error('Receipt has invalid or duplicate payout entries');
    identities.add(identity); total += BigInt(entry.amountUnits);
  }
  if (total !== BigInt(allocation.allocatedUnits) || total > BigInt(allocation.budgetUnits)) throw new Error('Receipt totals exceed budget or do not match');
  return allocation;
}

export function playlistTakeover(state) {
  const playlist = state?.nowPlaying?.djukePlaylist;
  if (!playlist || typeof playlist.name !== 'string' || !playlist.name.trim() || playlist.name.length > 60 ||
      !Number.isSafeInteger(playlist.songCount) || playlist.songCount < 1 || playlist.songCount > 24 ||
      !Number.isSafeInteger(playlist.remaining) || playlist.remaining < 1 || playlist.remaining > playlist.songCount) return null;
  // Older servers sent only a reservation-time remaining count; position is the live lane's place in the batch.
  const hasPosition = Number.isSafeInteger(playlist.position) && playlist.position >= 1 && playlist.position <= playlist.songCount;
  return { ...playlist, label: hasPosition
    ? `${playlist.name} · Play Live · Song ${playlist.position} of ${playlist.songCount}`
    : `${playlist.name} · Play Live · ${playlist.remaining} of ${playlist.songCount} songs remaining` };
}

export function createRadioPlaylistEffects({ scene, camera, readSpectrum, root = document, three = THREE }) {
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  const spectrum = new Uint8Array(128);
  const particles = [];
  const textures = ['♪', '♫', '🎈', '🧞'].map(symbol => {
    const canvas = root.createElement('canvas');
    canvas.width = canvas.height = 128;
    const ctx = canvas.getContext('2d');
    ctx.font = '80px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#94e6ff';
    ctx.fillText(symbol, 64, 64);
    return new three.CanvasTexture(canvas);
  });
  const badge = root.getElementById('radio-playlist-takeover');
  let active = null;
  let mode = 'radio';
  let lastSpawn = 0;
  let lastEnergy = 0;
  const clear = () => {

  for (const particle of particles) { scene.remove(particle.sprite); particle.sprite.material.dispose(); }
  particles.length = 0;
};
const stateChanged = event => {
  active = playlistTakeover(event.detail);
  if (badge) { badge.hidden = !active || mode !== 'radio'; badge.textContent = active?.label || ''; }
  if (!active) clear();
};
const modeChanged = event => {
  mode = event.detail;
  if (badge) badge.hidden = !active || mode !== 'radio';
  if (mode !== 'radio') clear();
};
root.addEventListener('dbusk-radio-state', stateChanged);
root.addEventListener('radio-source-mode-change', modeChanged);
function update(now) {
  if (!active || mode !== 'radio' || root.hidden || reduced.matches) { clear(); return; }
  const live = readSpectrum(spectrum) === true;
  const energy = live ? spectrum.subarray(0, 16).reduce((sum, n) => sum + n, 0) / (16 * 255) : 0;
  const beat = energy > .16 && energy > lastEnergy * 1.08;
  lastEnergy = energy * .2 + lastEnergy * .8;
  if (beat && now - lastSpawn > 1800 && particles.length < 8) {
    const footer = root.querySelector('footer');
    const rect = footer?.getBoundingClientRect();
    if (rect) {
      const origin = new three.Vector3((rect.x + rect.width / 2) / innerWidth * 2 - 1,
        -(rect.y + 12) / innerHeight * 2 + 1, .8).unproject(camera);
      const sprite = new three.Sprite(new three.SpriteMaterial({
        map: textures[Math.floor(Math.random() * textures.length)], transparent: true, opacity: .35, depthWrite: false,
      }));
      sprite.position.copy(origin);
      sprite.scale.setScalar(.045);
      scene.add(sprite);
      particles.push({ sprite, origin, born: now, drift: (Math.random() - .5) * .09 });
      lastSpawn = now;
    }
  }

    for (let i = particles.length - 1; i >= 0; i--) {
      const particle = particles[i], age = (now - particle.born) / 1000;
      if (age > 14) {
        scene.remove(particle.sprite); particle.sprite.material.dispose(); particles.splice(i, 1);
      } else {
        particle.sprite.position.copy(particle.origin);
        particle.sprite.position.y += age * .025;
        particle.sprite.position.x += Math.sin(age * .5) * particle.drift;
        particle.sprite.position.z -= age * .012;
        particle.sprite.material.opacity = Math.min(age, 1) * (1 - age / 14) * .35;
      }
    }
  }
  return { update, dispose() {
    clear();
    textures.forEach(texture => texture.dispose());
    root.removeEventListener('dbusk-radio-state', stateChanged);
    root.removeEventListener('radio-source-mode-change', modeChanged);
  } };
}

    !['shuffle', 'weekly-score', 'weekly-growth'].includes(value.ranking) ||
    !Number.isInteger(value.limit) || value.limit < 0 || value.limit > 100 ||
    !Number.isInteger(value.revision) || value.revision < 1) throw new Error('Invalid radio preset');
  return { id: value.id, title: value.title.trim(), revision: value.revision, selector: value.selector,
