    const fromCdn = !!_publicBroadcastStateUrl;
    const state = await readRadioState({ radioUrl: _publicBroadcastStateUrl || _radioUrl() });
    const broadcast = state.publicBroadcast;
    _publicBroadcastStateUrl = null;
