    _fadeLevel = initial * (1 - progress) ** 2;
    _applyRadioVolume();
    if (progress < 1) {
      const timer = setTimeout(step, 30);
      timer.unref?.();
    }
    else _pauseAudio();
  };

  step();
}

function _stopAudio() {
