// Earned referral Supporter tokens, listed in the dev payroll queue and sent directly from the admin wallet.
import { SUPPORTER_REWARD, SUPPORTER_REWARD_ABI, supporterRewardQueue, supporterRewardKey } from './promotions.mjs?v=20261123-supporter-queue';
import { fetchPromotionsState, signedPromotionCommand, promotionWallet } from './promotions-ui.mjs?v=20261126-eth-gifts';
import { isAdminWallet } from './admin-access.mjs';

const rewardKey = item => item.tokenKey || supporterRewardKey(item.token);
const journalKey = item => `decentbusking:supporter-delivery:${item.campaignId}:${item.wallet}${rewardKey(item) === supporterRewardKey() ? '' : `:${rewardKey(item)}`}`;
const short = wallet => `${wallet.slice(0, 6)}…${wallet.slice(-4)}`;
const delivered = (state, item) => supporterRewardQueue(state.campaigns || [])
  .find(entry => entry.campaignId === item.campaignId && entry.wallet === item.wallet && rewardKey(entry) === rewardKey(item))?.status === 'delivered';

export function createSupporterPayroll({ root, fetchState = fetchPromotionsState, sign = signedPromotionCommand,
  getWallet = promotionWallet, storage = globalThis.localStorage, ask = globalThis.prompt, confirmAction = globalThis.confirm,
  isBusy = () => false, setBusy = () => {} } = {}) {
  let state = null;
  let busy = false;
  let line = null;
  const status = (text, error = false) => {
    if (line) { line.textContent = text; line.classList.toggle('is-error', error); }
  };
  const command = async c => {
    state = await sign({ revision: state.revision, ...c });
    return state;
  };
  const journal = item => {
    try { return JSON.parse(storage.getItem(journalKey(item)) || 'null'); }
    catch { throw new Error('Supporter transfer journal is invalid; inspect wallet history before proceeding'); }
  };

async function send(item) {
  const w = await getWallet();
  if (!isAdminWallet(w.address)) throw new Error('Connect the admin wallet');
  if (storage.getItem(journalKey(item))) throw new Error('A transfer is unresolved. Check its receipt before retrying.');
  const reward = item.token || SUPPORTER_REWARD;
  const token = new w.ethers.Contract(reward.contract, SUPPORTER_REWARD_ABI, w.signer);
  const tokenId = BigInt(reward.tokenId), quantity = BigInt(reward.quantity);
  if (await token.balanceOf(w.address, tokenId) < quantity) throw new Error(`Admin wallet holds no Supporter #${tokenId}`);
  const args = [w.address, item.wallet, tokenId, quantity, '0x'];
  await token.safeTransferFrom.staticCall(...args);
  state = await fetchState();
  await command({ action: 'prepare-supporter', campaignId: item.campaignId, wallet: item.wallet, tokenKey: rewardKey(item) });
  await w.check();
  storage.setItem(journalKey(item), JSON.stringify({ status: 'awaiting-wallet' }));
  let tx;
  try { tx = await token.safeTransferFrom(...args); } catch (error) {
    if (error.code === 'ACTION_REJECTED' || error.code === 4001) storage.removeItem(journalKey(item));
    throw error;
  }
  try { storage.setItem(journalKey(item), JSON.stringify({ hash: tx.hash })); }
  catch (error) { throw new Error(`Sent as ${tx.hash}, but the browser journal failed: ${error.message}. Check this hash; do not send again.`); }
  status(`🎖 Sending… ${tx.hash.slice(0, 10)}… Do not send again.`);
  const firstCheck = await command({ action: 'reconcile-supporter', campaignId: item.campaignId, wallet: item.wallet, tokenKey: rewardKey(item), txHash: tx.hash });
  if (delivered(firstCheck, item)) {
    storage.removeItem(journalKey(item));
    return;
  }

  await tx.wait(2, 120000);
  await w.check();
  if (delivered(await command({ action: 'reconcile-supporter', campaignId: item.campaignId,
    wallet: item.wallet, tokenKey: rewardKey(item), txHash: tx.hash }), item)) storage.removeItem(journalKey(item));
  else return 'transfer-pending';
}

async function check(item) {
  const savedHash = item.txHash || journal(item)?.hash || '';
  const hash = String(ask?.('Transaction hash for this Supporter transfer (update it if replaced)', savedHash) || '').trim();
  if (!hash) throw new Error('Enter the transaction hash, or release if wallet history shows nothing was sent');
  state = await fetchState();
  const next = await command({ action: 'reconcile-supporter', campaignId: item.campaignId, wallet: item.wallet, tokenKey: rewardKey(item), txHash: hash });
  const entry = supporterRewardQueue(next.campaigns || []).find(e => e.campaignId === item.campaignId && e.wallet === item.wallet && rewardKey(e) === rewardKey(item));
  if (!entry) throw new Error('Supporter transfer is missing from the queue; check wallet history and do not send again');
  if (entry.status !== 'transfer-pending') storage.removeItem(journalKey(item));
  else {
    if (!entry.txHash) throw new Error('Pending transfer has no recorded hash; check wallet history and do not send again');
    storage.setItem(journalKey(item), JSON.stringify({ hash: entry.txHash }));
    return 'transfer-pending';
  }
}

async function release(item) {
  if (!confirmAction?.('Only release if wallet history shows no Supporter transfer was broadcast. Continue?')) return;
  const reason = String(ask?.('What did wallet history show?') || '').trim();
  if (!reason) throw new Error('Record why wallet history confirms nothing was sent');

  state = await fetchState();
  await command({ action: 'release-supporter-preparation', campaignId: item.campaignId, wallet: item.wallet,
    tokenKey: rewardKey(item), confirmNoBroadcast: true, reason });
  storage.removeItem(journalKey(item));
}

function render() {
  const doc = root.ownerDocument;
  const items = supporterRewardQueue(state?.campaigns || []);
  const open = items.filter(item => item.status !== 'delivered');
  const done = items.length - open.length;
  const admin = isAdminWallet();
  root.replaceChildren();
  const el = (tag, className, text = '') => {
    const node = doc.createElement(tag);
    node.className = className;
    node.textContent = text;
    return node;
  };
  const head = el('header', 'supporter-payroll-head');
  const info = el('span', 'supporter-payroll-info', 'ⓘ');
  info.title = 'Earned in referral campaigns. One of each selected Base Supporter DNFT per eligible wallet, from the admin wallet. Delivered after 2 confirmations.';
  head.append(el('h4', '', '🎖 Supporter tokens owed'),
    el('span', 'supporter-payroll-count', `${open.length} owed${done ? ` · ${done} ✅` : ''}`), info);
  const list = el('ul', 'supporter-payroll-list');
  for (const item of open) {
    const row = el('li', `supporter-payroll-row is-${item.status}`);
    const who = el('span', 'supporter-payroll-who', `👽 ${item.name || short(item.wallet)}`);
    who.title = item.wallet;
    const what = el('span', 'supporter-payroll-what', `🎖 ${item.token?.name || `Supporter #${item.token?.tokenId || '75'}`} ×1 · ${item.title || 'Referral Campaign'}`);
    const actions = el('span', 'supporter-payroll-actions');
    const button = (label, title, fn) => {

      const b = el('button', 'payroll-btn payroll-btn-secondary supporter-payroll-btn', label);
      b.type = 'button';
      b.title = title;
      b.disabled = !admin || busy || isBusy();
      b.addEventListener('click', () => run(fn, item));
      actions.append(b);
    };
    if (item.status === 'owed') button('🎖 Send', 'Send 1 Supporter from the admin wallet', send);
    else {
      button('🔎 Check', 'Check the transfer receipt', check);
      let journaled = true;
      try { journaled = Boolean(journal(item)?.hash); } catch {}
      if (!item.txHash && !journaled) button('↩', 'Release an unsent transfer after checking wallet history', release);
    }
    row.append(who, what, actions);
    list.append(row);
  }
  line = el('p', 'payroll-status supporter-payroll-status');
  root.append(head, ...(open.length ? [list] : []), line);
  if (!open.length) status(items.length ? '✅ All earned Supporters delivered' : 'No Supporter tokens owed yet');
}

async function run(fn, item) {
  if (busy || isBusy()) { status('Another Payroll action is in progress; wait before sending a Supporter.', true); return; }
  busy = true;
  setBusy(true);
  render();
  status('⏳ Working…');
  let outcome;
  try {
    outcome = await fn(item);
    root.classList.add('is-celebrating');
    setTimeout(() => root.classList.remove('is-celebrating'), 1200);
  } catch (error) {
    busy = false;
    setBusy(false);
    try { state = await fetchState(); } catch {}
    render();
    status(`⚠️ ${error.shortMessage || error.message}`, true);
    return;
  }
  busy = false;
  setBusy(false);
  render();
  status(outcome === 'transfer-pending' ? '⏳ Transfer still confirming' : '✨ Updated');

  }

  return {
    async load() {
      if (busy) return;
      try { state = await fetchState(); render(); }
      catch (error) { state = null; render(); status(`⚠️ Supporter queue unavailable: ${error.message}`, true); }
    },
  };
}

let mounted = null;
export async function loadSupporterPayroll(doc = globalThis.document, options = {}) {
  const root = doc?.getElementById('payroll-supporter-queue');
  if (!root) return;
  try {
    if (mounted?.root !== root) mounted = { root, view: createSupporterPayroll({ root, ...options }) };
    await mounted.view.load();
  } catch (error) {
    root.textContent = `⚠️ Supporter queue unavailable: ${error.message}`;
  }
}

const ADDRESS = /^0x[0-9a-fA-F]{40}$/;
const HASH = /^0x[0-9a-fA-F]{64}$/;
const WEI = /^(0|[1-9][0-9]{0,99})$/;
const UNITS = /^[1-9][0-9]{0,77}$/;
const TOKEN_ID = /^(0|[1-9][0-9]{0,77})$/;
const SOURCES = ['Live performance', 'Radio recording', 'Archive recording'];
const KNOWN_TOKENS = { '0x833589fcd6edb6e08f4c7c32d4f71b54bda02913': { symbol: 'USDC', decimals: 6 } };

function validAsset(entry, assets) {
  if (!entry.kind) return typeof entry.amountWei === 'string' && WEI.test(entry.amountWei);
  if (!assets) return false;
  if (entry.kind === 'token') return ADDRESS.test(entry.token || '') && UNITS.test(entry.amountUnits || '');
  return entry.kind === 'nft' && ADDRESS.test(entry.collection || '') && [0, 1].includes(entry.standard) &&
    TOKEN_ID.test(entry.tokenId || '') && UNITS.test(entry.amount || '');
}

function tokenAmount(ethers, token, units) {
  const known = KNOWN_TOKENS[String(token).toLowerCase()];
  return known ? `${ethers.formatUnits(units, known.decimals)} ${known.symbol}` : `${units} units of ${token}`;
}

export async function fetchTipLedger({ serviceUrl, routerAddress, address, offset = 0, fetchImpl = fetch }) {
  if (!serviceUrl || !ADDRESS.test(routerAddress || '') || !ADDRESS.test(address || '')) throw new Error('Tip ledger configuration is unavailable');
  const response = await fetchImpl(`${String(serviceUrl).replace(/\/$/, '')}/api/tips/ledger?${new URLSearchParams({
    wallet: address, router: routerAddress, offset, limit: 25,
  })}`, { cache: 'no-store', signal: AbortSignal.timeout(15000) });
  const state = await response.json();
  if (!response.ok || state.ready !== true) throw new Error(state.error || state.lastError || `Tip ledger unavailable (${response.status})`);

  if (state.chainId !== 8453 || state.routerAddress?.toLowerCase() !== routerAddress.toLowerCase() ||
      !Array.isArray(state.entries) || state.entries.length > 25 ||
      typeof state.attributedWei !== 'string' || typeof state.unattributedWei !== 'string' ||
      !WEI.test(state.attributedWei) || !WEI.test(state.unattributedWei) ||
      !Number.isSafeInteger(state.total) || state.total < state.entries.length ||
      (state.nextOffset !== null && (!Number.isSafeInteger(state.nextOffset) || state.nextOffset <= offset)) ||
      (state.assets === true && (!state.tokenTotals || typeof state.tokenTotals !== 'object' ||
        Object.entries(state.tokenTotals).some(([token, total]) => !ADDRESS.test(token) ||
          !WEI.test(total?.attributedUnits || '') || !WEI.test(total?.unattributedUnits || '')) ||
        !Number.isSafeInteger(state.nftGifts?.attributed) || !Number.isSafeInteger(state.nftGifts?.unattributed)))) {
    throw new Error('Invalid tip ledger response');
  }
  for (const entry of state.entries) {
    if (entry.chainId !== 8453 || entry.routerAddress?.toLowerCase() !== routerAddress.toLowerCase() ||
        entry.recipient?.toLowerCase() !== address.toLowerCase() || !ADDRESS.test(entry.sender || '') ||
        !HASH.test(entry.txHash || '') || !Number.isSafeInteger(entry.logIndex) || entry.logIndex < 0 ||
        !validAsset(entry, state.assets === true) ||
        ![0, 1, 2].includes(entry.sourceKind) || typeof entry.contextRef !== 'string' || entry.contextRef.length > 256 ||
        typeof entry.chainVerified !== 'boolean' ||
        !['verified', 'unavailable', 'mismatch'].includes(entry.sourceVerification?.status)) {
      throw new Error('Invalid tip ledger event');
    }
  }
  return state;
}

export function renderTipLedger({ container, config, address, ethers, isCurrent = () => true }) {
  const sections = [renderRouterLedger({ container, config, address, ethers, isCurrent,
    routerAddress: config.tipRouterAddress, heading: 'Native ETH tips' })];
  if (config.tipRouterAddress && ADDRESS.test(config.tipSplitRouterAddress || '')) {
    sections.push(renderRouterLedger({ container, config, address, ethers, isCurrent,
      routerAddress: config.tipSplitRouterAddress, heading: '👥 Shared · $ USDC · 🎁 NFT tips' }));
  }
  container.replaceChildren(...sections);
}

function renderRouterLedger({ container, config, address, ethers, isCurrent, routerAddress, heading }) {
  const document = container.ownerDocument;
  const details = document.createElement('details'), summary = document.createElement('summary');
  const status = document.createElement('p'), list = document.createElement('ol'), more = document.createElement('button');
  const body = document.createElement('div');
  const title = document.createElement('span');
  title.className = 'creator-dropdown-title';
  details.className = 'creator-dropdown';
  body.className = 'creator-dropdown-body';
  title.textContent = heading;
  summary.append(title);
  details.style.overflowWrap = 'anywhere';
  status.setAttribute('role', 'status');
  more.type = 'button';
  more.textContent = 'More tip receipts';
  more.hidden = true;
  body.append(status, list, more);
  details.append(summary, body);
  if (routerAddress === '' || routerAddress === undefined) {
    status.textContent = 'Contract attribution is not enabled. Earlier direct wallet transfers are not included in this ledger.';
    return details;
  }
  let nextOffset = 0, loading = false, loaded = false;
  const seen = new Set();

const load = async () => {
  if (loading || !isCurrent()) return;
  loading = true;
  more.disabled = true;
  status.textContent = 'Reading the separate native ETH tip ledger...';
  try {
    const state = await fetchTipLedger({ serviceUrl: config.ipfsUploadServiceUrl,
      routerAddress, address, offset: nextOffset });
    if (!isCurrent()) return;
    const totals = [`${ethers.formatEther(state.attributedWei)} ETH`,
      ...Object.entries(state.tokenTotals || {}).map(([token, total]) => tokenAmount(ethers, token, total.attributedUnits)),
      ...(state.nftGifts?.attributed ? [`${state.nftGifts.attributed} 🎁`] : [])];
    title.textContent = `${heading} - ${totals.join(' · ')} attributed`;
    status.textContent = `${state.total} tip receipt(s). ${ethers.formatEther(state.unattributedWei)} ETH has unverified source context. ` +
      `${!state.caughtUp || state.restoringCount ? 'Index recovery is in progress; totals are incomplete. ' : ''}` +
      `Checked ${state.lastCheckedAt || 'time unavailable'}. Not combined with USDC payroll or supporter gifts.`;
    for (const entry of state.entries) {
      const key = `${entry.txHash.toLowerCase()}:${entry.logIndex}`;
      if (seen.has(key)) continue;
      seen.add(key);
      const item = document.createElement('li'), label = document.createElement('p'), context = document.createElement('small');
      const proof = document.createElement('a');
      const verification = !entry.chainVerified ? 'chain comparison pending'
        : entry.sender === entry.recipient ? 'self-transfer, not earnings'
        : entry.sourceVerification.status === 'verified' ? 'recording/booking identity verified'

          : `source unverified: ${entry.sourceVerification.error || entry.sourceVerification.status}`;
        const what = entry.kind === 'token' ? tokenAmount(ethers, entry.token, entry.amountUnits)
          : entry.kind === 'nft' ? `🎁 NFT #${entry.tokenId}${entry.standard === 1 ? ` ×${entry.amount}` : ''} from ${entry.collection}`
          : `${ethers.formatEther(entry.amountWei)} ETH`;
        label.textContent = `${what} - ${SOURCES[entry.sourceKind] || 'Unknown source'} - ${entry.sourceVerification.label || ''} (${verification})`;
        context.textContent = entry.contextRef;
        context.style.overflowWrap = 'anywhere';
        proof.href = `https://basescan.org/tx/${entry.txHash}#eventlog`;
        proof.textContent = `On-chain proof, log ${entry.logIndex}`;
        proof.target = '_blank';
        proof.rel = 'noopener noreferrer';
        item.append(label, context, document.createElement('br'), proof);
        list.append(item);
      }
      nextOffset = state.nextOffset;
      more.hidden = nextOffset === null;
      loaded = true;
    } catch (error) {
      if (isCurrent()) {
        status.textContent = `Tip ledger unavailable: ${error.message}`;
        more.textContent = 'Retry tip ledger';
        more.hidden = false;
      }
    } finally {
      loading = false;
      more.disabled = false;
    }
  };
  details.addEventListener('toggle', () => { if (details.open && !loaded) void load(); });
  more.addEventListener('click', () => { more.textContent = 'More tip receipts'; void load(); });
  return details;
}

export const TIP_SOURCE_KINDS = Object.freeze({ live: 0, radio: 1, archive: 2 });
export const TIP_ABI = Object.freeze([
  'function tip(address recipient,uint8 sourceKind,string contextRef) payable',
  'event TipSent(address indexed sender,address indexed recipient,bytes32 indexed contextId,uint8 sourceKind,uint256 amount,string contextRef)',
]);
export const TIP_SPLIT_ABI = Object.freeze([
  ...TIP_ABI,
  'function tipSplit(address[] recipients,uint16[] sharesBps,uint8 sourceKind,string contextRef) payable',
]);
export const TIP_ASSET_ABI = Object.freeze([
  ...TIP_SPLIT_ABI,
  'function allowedTokens(address token) view returns (bool)',
  'function tipToken(address token,address recipient,uint256 amount,uint8 sourceKind,string contextRef)',
  'function tipTokenSplit(address token,address[] recipients,uint16[] sharesBps,uint256 amount,uint8 sourceKind,string contextRef)',
  'function giftNfts((address collection,uint8 standard,uint256 tokenId,uint256 amount,address recipient)[] gifts,uint8 sourceKind,string contextRef)',
  'event TokenTipSent(address indexed sender,address indexed recipient,bytes32 indexed contextId,address token,uint8 sourceKind,uint256 amount,string contextRef)',
  'event NftGiftSent(address indexed sender,address indexed recipient,bytes32 indexed contextId,address collection,uint8 standard,uint256 tokenId,uint256 amount,uint8 sourceKind,string contextRef)',
]);
export const NFT_STANDARDS = Object.freeze({ erc721: 0, erc1155: 1 });
export const MAX_NFT_GIFTS = 32;
const ADDRESS = /^0x[0-9a-fA-F]{40}$/;
const HASH = /^0x[0-9a-fA-F]{64}$/;
const UINT256_MAX = (1n << 256n) - 1n;

export function createTipContext({ source, bookingId, nftId }) {
  if (!Object.hasOwn(TIP_SOURCE_KINDS, source)) throw new Error('Unsupported tip source');
  let reference;

  if (source === 'live') {
    if (typeof bookingId !== 'string' || !/^[a-zA-Z0-9:_-]{1,200}$/.test(bookingId)) {
      throw new Error('A verified live booking is required for tip attribution');
    }
    reference = bookingId;
  } else {
    const match = typeof nftId === 'string' && nftId.match(/^([1-9][0-9]*):(0x[0-9a-fA-F]{40}):(0|[1-9][0-9]*)$/);
    if (!match || /^0x0{40}$/i.test(match[2]) || match[1].length > 78 || match[3].length > 78 ||
        BigInt(match[1]) > UINT256_MAX || BigInt(match[3]) > UINT256_MAX) {
      throw new Error('A verified recording NFT identity is required for tip attribution');
    }
    reference = `${match[1]}:${match[2].toLowerCase()}:${match[3]}`;
  }
  const contextRef = `decentbusking:${source}:${reference}`;
  if (contextRef.length > 256) throw new Error('Tip context is too long');
  return Object.freeze({ sourceKind: TIP_SOURCE_KINDS[source], contextRef });
}

export function parseTipContext({ sourceKind, contextRef }) {
  const source = Object.keys(TIP_SOURCE_KINDS).find(key => TIP_SOURCE_KINDS[key] === sourceKind);
  if (!source || typeof contextRef !== 'string' || contextRef.length > 256 ||
      !contextRef.startsWith(`decentbusking:${source}:`)) throw new Error('Tip source context is not recognized');
  const reference = contextRef.slice(`decentbusking:${source}:`.length);
  const context = source === 'live' ? { source, bookingId: reference } : { source, nftId: reference };
  if (createTipContext(context).contextRef !== contextRef) throw new Error('Tip source context is not canonical');
  return Object.freeze(context);
}

export function decodeTipReceipt({ receipt, routerAddress, ethers }) {
  if (!ADDRESS.test(routerAddress || '') || /^0x0{40}$/i.test(routerAddress)) throw new Error('Invalid tip contract');

  if (receipt?.status !== 1 || !Array.isArray(receipt.logs)) throw new Error('Tip transaction is not confirmed successfully');
  const txHash = receipt.hash || receipt.transactionHash;
  if (!HASH.test(txHash || '')) throw new Error('Tip transaction hash is unavailable');
  const iface = new ethers.Interface(TIP_ABI);
  const topic = iface.getEvent('TipSent').topicHash.toLowerCase();
  return receipt.logs.filter(log => log.address?.toLowerCase() === routerAddress.toLowerCase() &&
    log.topics?.[0]?.toLowerCase() === topic).map(log => {
    const event = iface.parseLog(log), args = event.args;
    const logIndex = log.index ?? log.logIndex;
    if (!Number.isSafeInteger(logIndex) || logIndex < 0 || args.amount <= 0n ||
        args.contextId !== ethers.id(args.contextRef)) throw new Error('Invalid on-chain tip event');
    const sourceKind = Number(args.sourceKind);
    let context = null, contextError = '';
    try { context = parseTipContext({ sourceKind, contextRef: args.contextRef }); }
    catch (error) { contextError = error.message; }
    return {
      txHash, logIndex, routerAddress: routerAddress.toLowerCase(),
      sender: args.sender.toLowerCase(), recipient: args.recipient.toLowerCase(),
      amountWei: args.amount.toString(), sourceKind, contextId: args.contextId,
      contextRef: args.contextRef, context, contextError,
    };
  });
}

export function verifyAttributedTipReceipt({ receipt, routerAddress, intent, ethers }) {
  const context = createTipContext(intent);
  const matches = decodeTipReceipt({ receipt, routerAddress, ethers }).filter(event =>
    event.sender === intent.payer.toLowerCase() && event.recipient === intent.recipient.toLowerCase() &&
    event.amountWei === String(intent.amountWei) && event.sourceKind === context.sourceKind &&

    event.contextRef === context.contextRef);
  if (matches.length !== 1) throw new Error('No single exact DecentBusking tip event matches this payment');
  return matches[0];
}

export function normalizeTipSplit(recipients, sharesBps) {
  if (!Array.isArray(recipients) || !Array.isArray(sharesBps) || recipients.length < 2 ||
      recipients.length > 16 || recipients.length !== sharesBps.length) throw new Error('This song split cannot receive a shared tip');
  const seen = new Set();
  let total = 0;
  const parts = recipients.map((recipient, index) => {
    const wallet = String(recipient || '');
    const shareBps = Number(sharesBps[index]);
    if (!ADDRESS.test(wallet) || /^0x0{40}$/i.test(wallet) || seen.has(wallet.toLowerCase()) ||
        !Number.isSafeInteger(shareBps) || shareBps <= 0 || shareBps > 10000) throw new Error('This song split cannot receive a shared tip');
    seen.add(wallet.toLowerCase());
    total += shareBps;
    return Object.freeze({ recipient: wallet, shareBps });
  });
  if (total !== 10000) throw new Error('This song split cannot receive a shared tip');
  return Object.freeze(parts);
}

// Mirrors DecentBuskingTipRouter v0.2: each part rounds down and the last payee receives the remainder.
export function splitTipAmounts(amountWei, splits) {
  const total = BigInt(amountWei);
  let remaining = total;
  return splits.map((part, index) => {
    const amount = index === splits.length - 1 ? remaining : total * BigInt(part.shareBps) / 10000n;
    if (amount <= 0n) throw new Error('Tip is too small to split between every owner');
    remaining -= amount;
    return amount;
  });
}

export function verifySplitTipReceipt({ receipt, routerAddress, intent, ethers }) {
  const context = createTipContext(intent);

  const amounts = splitTipAmounts(intent.amountWei, intent.splits);
  const events = decodeTipReceipt({ receipt, routerAddress, ethers }).filter(event =>
    event.sender === intent.payer.toLowerCase() && event.sourceKind === context.sourceKind &&
    event.contextRef === context.contextRef);
  if (events.length !== intent.splits.length) throw new Error('The shared tip receipt does not match every song owner');
  return intent.splits.map((part, index) => {
    const matches = events.filter(event => event.recipient === part.recipient.toLowerCase() &&
      event.amountWei === amounts[index].toString());
    if (matches.length !== 1) throw new Error('The shared tip receipt does not match every song owner');
    return matches[0];
  });
}

function eventContext(sourceKind, contextRef) {
  try { return { context: parseTipContext({ sourceKind, contextRef }), contextError: '' }; }
  catch (error) { return { context: null, contextError: error.message }; }
}

// Decodes v0.2 TokenTipSent (kind 'token') and NftGiftSent (kind 'nft') events from one router.
export function decodeAssetTipReceipt({ receipt, routerAddress, ethers }) {
  if (!ADDRESS.test(routerAddress || '') || /^0x0{40}$/i.test(routerAddress)) throw new Error('Invalid tip contract');
  if (receipt?.status !== 1 || !Array.isArray(receipt.logs)) throw new Error('Tip transaction is not confirmed successfully');
  const txHash = receipt.hash || receipt.transactionHash;
  if (!HASH.test(txHash || '')) throw new Error('Tip transaction hash is unavailable');
  const iface = new ethers.Interface(TIP_ASSET_ABI);
  const topics = { [iface.getEvent('TokenTipSent').topicHash.toLowerCase()]: 'token', [iface.getEvent('NftGiftSent').topicHash.toLowerCase()]: 'nft' };

  return receipt.logs.filter(log => log.address?.toLowerCase() === routerAddress.toLowerCase() && topics[log.topics?.[0]?.toLowerCase()])
    .map(log => {
      const kind = topics[log.topics[0].toLowerCase()];
      const args = iface.parseLog(log).args;
      const logIndex = log.index ?? log.logIndex;
      if (!Number.isSafeInteger(logIndex) || logIndex < 0 || args.amount <= 0n ||
          args.contextId !== ethers.id(args.contextRef)) throw new Error('Invalid on-chain tip event');
      const sourceKind = Number(args.sourceKind);
      const base = {
        kind, txHash, logIndex, routerAddress: routerAddress.toLowerCase(),
        sender: args.sender.toLowerCase(), recipient: args.recipient.toLowerCase(), sourceKind,
        contextId: args.contextId, contextRef: args.contextRef, ...eventContext(sourceKind, args.contextRef),
      };
      if (kind === 'token') return { ...base, token: args.token.toLowerCase(), amountUnits: args.amount.toString() };
      const standard = Number(args.standard);
      if (standard !== NFT_STANDARDS.erc721 && standard !== NFT_STANDARDS.erc1155) throw new Error('Invalid on-chain NFT gift event');
      return { ...base, collection: args.collection.toLowerCase(), standard, tokenId: args.tokenId.toString(), amount: args.amount.toString() };
    });
}

// `intent.splits` (shared song) or `intent.recipient` (one owner); `intent.amountUnits` in token base units.
export function verifyTokenTipReceipt({ receipt, routerAddress, intent, ethers }) {
  const context = createTipContext(intent);
  const parts = intent.splits
    ? splitTipAmounts(intent.amountUnits, intent.splits).map((amount, index) => ({ recipient: intent.splits[index].recipient, amount }))
    : [{ recipient: intent.recipient, amount: BigInt(intent.amountUnits) }];

  const events = decodeAssetTipReceipt({ receipt, routerAddress, ethers }).filter(event => event.kind === 'token' &&
    event.sender === intent.payer.toLowerCase() && event.token === intent.token.toLowerCase() &&
    event.sourceKind === context.sourceKind && event.contextRef === context.contextRef);
  if (events.length !== parts.length) throw new Error('The token tip receipt does not match every song owner');
  return parts.map(part => {
    const matches = events.filter(event => event.recipient === part.recipient.toLowerCase() && event.amountUnits === part.amount.toString());
    if (matches.length !== 1) throw new Error('The token tip receipt does not match every song owner');
    return matches[0];
  });
}

const giftKey = gift => [gift.recipient, gift.collection, gift.standard, gift.tokenId, gift.amount].map(v => String(v).toLowerCase()).join('|');

// Validates a gift batch against the song's owners. Returns contract-ready gifts.
export function normalizeNftGifts(gifts, owners) {
  const allowed = new Set((owners || []).map(owner => String(owner).toLowerCase()));
  if (!Array.isArray(gifts) || !gifts.length || gifts.length > MAX_NFT_GIFTS) throw new Error(`Choose 1 to ${MAX_NFT_GIFTS} NFT gifts`);
  const seen721 = new Set();
  return Object.freeze(gifts.map(gift => {
    const collection = String(gift?.collection || '');
    const standard = Number(gift?.standard);
    let tokenId, amount;
    try { tokenId = BigInt(gift.tokenId); amount = BigInt(gift.amount); } catch { throw new Error('Enter a whole-number token ID and amount'); }
    if (!ADDRESS.test(collection) || /^0x0{40}$/i.test(collection)) throw new Error('Enter a valid NFT collection address');

    if (standard !== NFT_STANDARDS.erc721 && standard !== NFT_STANDARDS.erc1155) throw new Error('Unsupported NFT standard');
    if (tokenId < 0n || tokenId > UINT256_MAX || amount <= 0n || amount > UINT256_MAX) throw new Error('Enter a valid token ID and amount');
    if (standard === NFT_STANDARDS.erc721) {
      if (amount !== 1n) throw new Error('An ERC-721 NFT can only be gifted once');
      const key = `${collection.toLowerCase()}:${tokenId}`;
      if (seen721.has(key)) throw new Error('The same ERC-721 NFT cannot be gifted twice');
      seen721.add(key);
    }
    if (!allowed.has(String(gift.recipient || '').toLowerCase())) throw new Error('Each NFT must go to one of this song\'s owners');
    return Object.freeze({ collection, standard, tokenId: tokenId.toString(), amount: amount.toString(), recipient: String(gift.recipient) });
  }));
}

export function verifyNftGiftReceipt({ receipt, routerAddress, intent, ethers }) {
  const context = createTipContext(intent);
  const events = decodeAssetTipReceipt({ receipt, routerAddress, ethers }).filter(event => event.kind === 'nft' &&
    event.sender === intent.payer.toLowerCase() && event.sourceKind === context.sourceKind && event.contextRef === context.contextRef);
  const expected = intent.gifts.map(giftKey).sort();
  const actual = events.map(giftKey).sort();
  if (expected.length !== actual.length || expected.some((key, index) => key !== actual[index])) {
    throw new Error('The NFT gift receipt does not match the gifts you sent');
  }
  return events;
}

