export const USDC_BROWSER_ABI = [
  'function decimals() view returns (uint8)',
  'function balanceOf(address) view returns (uint256)',
  'function allowance(address, address) view returns (uint256)',
  'function approve(address, uint256) returns (bool)',
];

export function formatUsdcUnits(units) {
  const value = typeof units === 'bigint' ? units : BigInt(units || 0);
  const magnitude = value < 0n ? -value : value;
  const cents = (magnitude + 5000n) / 10000n;
  return `${value < 0n && cents > 0n ? '-' : ''}${cents / 100n}.${String(cents % 100n).padStart(2, '0')}`;
}

// One free signature tags a listener's radio votes with their wallet for 7 days.
// The signed message itself is the pass, so the worker needs no secret and passes survive restarts.
export const VOTE_PASS_TTL_MS = 7 * 24 * 60 * 60 * 1000;
const TITLE = 'DecentBusking listener sign-in';
const NOTE = 'Tags my radio votes with this wallet for 7 days. Free: no transaction, no payment.';
const FIELDS = ['Wallet', 'Listener', 'Origin', 'Issued', 'Expires'];

export function votePassMessage({ wallet, listener, origin, issuedAt, expiresAt }) {
  return [TITLE, NOTE, `Wallet: ${String(wallet).toLowerCase()}`, `Listener: ${listener}`, `Origin: ${origin}`,
    `Issued: ${issuedAt}`, `Expires: ${expiresAt}`].join('\n');
}

export function parseVotePass(message) {
  const lines = String(message || '').split('\n');
  if (lines.length !== 7 || lines[0] !== TITLE || lines[1] !== NOTE) return null;
  const values = {};
  for (const [index, field] of FIELDS.entries()) {
    const line = lines[index + 2];
    if (!line.startsWith(`${field}: `)) return null;
    values[field] = line.slice(field.length + 2);
  }
  const pass = { wallet: values.Wallet, listener: values.Listener, origin: values.Origin,
    issuedAt: values.Issued, expiresAt: values.Expires };
  return votePassMessage(pass) === message ? pass : null;
}

const storageKey = wallet => `dbusk-vote-pass:${String(wallet).toLowerCase()}`;
const declinedKey = wallet => `dbusk-vote-pass-declined:${String(wallet).toLowerCase()}`;

export function storedVotePass({ wallet, listener, origin, storage, now = Date.now() }) {
  try {
    const pass = JSON.parse(storage?.getItem(storageKey(wallet)) || 'null');
    const fields = parseVotePass(pass?.message);

    if (fields && fields.wallet === String(wallet).toLowerCase() && fields.listener === listener &&
        fields.origin === origin && Date.parse(fields.expiresAt) - now > 60_000 && /^0x[0-9a-fA-F]+$/.test(pass.signature)) {
      return { message: pass.message, signature: pass.signature };
    }
  } catch {}
  return null;
}

export function forgetVotePass(wallet, storage) {
  try { storage?.removeItem(storageKey(wallet)); } catch {}
}

/**
 * Returns a valid pass for the connected wallet, asking for one signature when none is stored.
 * Returns null without a wallet, or when the listener declines (asked again next browser session).
 */
export async function ensureVotePass({ wallet, signer, listener, origin, storage, session, now = Date.now(), onSign = () => {} }) {
  if (!/^0x[0-9a-fA-F]{40}$/.test(wallet || '') || !signer) return null;
  const stored = storedVotePass({ wallet, listener, origin, storage, now });
  if (stored) return stored;
  try { if (session?.getItem(declinedKey(wallet))) return null; } catch {}
  const message = votePassMessage({ wallet, listener, origin, issuedAt: new Date(now).toISOString(),
    expiresAt: new Date(now + VOTE_PASS_TTL_MS).toISOString() });
  try {
    onSign();
    const signature = await signer.signMessage(message);
    try { storage?.setItem(storageKey(wallet), JSON.stringify({ message, signature })); } catch {}
    return { message, signature };
  } catch {
    try { session?.setItem(declinedKey(wallet), '1'); } catch {}
    return null;
  }
}

export function renderWallet(element, address) {
  if (!element) return;
  element.replaceChildren();
  element.title = address || '';
  element.removeAttribute('aria-label');
  if (!address) return;
  const part = text => Object.assign(document.createElement('code'), { textContent: text });
  const icons = document.createElement('span');
  icons.className = 'creator-profile-wallet-icons';
  icons.setAttribute('aria-hidden', 'true');
  for (let i = 0; i < 4; i++) {
    const icon = Object.assign(document.createElement('img'), { src: 'img/Ens_Eth_Breathe.png', alt: '', loading: 'lazy' });
    icon.style.animationDelay = `${i * 0.25}s`;
    icons.append(icon);
  }
  element.setAttribute('aria-label', `Wallet ${address}`);
  element.append(part(address.slice(0, 6)), icons, part(address.slice(-4)));
}

// js/wallet.js — DecentBusking
//
// Single global wallet state, shared across all modules.
// All MetaMask interaction is centralised here; other modules read
// window._wallet.signer / window._wallet.address instead of calling
// eth_requestAccounts themselves.
//
// Usage:
//   import { initWallet, connectWallet } from './wallet.js';
//   initWallet();  // called once from main.js on DOMContentLoaded
//
// Modules that need the signer:
//   const signer = window._wallet?.signer;
//   if (!signer) { /* prompt user to connect via header */ }
//
// Listen for wallet changes:
//   document.addEventListener('wallet-connected',    e => console.log(e.detail.address));
//   document.addEventListener('wallet-disconnected', () => { … });

// ─── Global wallet state object ───────────────────────────────────────────────

window._wallet = {
  address:  null,   // checksummed address of the connected account (or null)
  signer:   null,   // ethers.Signer  (or null when disconnected)
  provider: null,   // ethers.BrowserProvider (or null)
  chainId:  null,   // chain ID as a Number (or null)
};

// ─── Helpers ──────────────────────────────────────────────────────────────────

function _dispatch(eventName) {
  document.dispatchEvent(new CustomEvent(eventName, {
    bubbles: true,
    detail: {
      address:  window._wallet.address,
      chainId:  window._wallet.chainId,
    },
  }));
}

async function _applyAccounts(accounts) {
  if (!accounts || accounts.length === 0) {
    window._wallet.address  = null;

    window._wallet.signer   = null;
    window._wallet.provider = null;
    window._wallet.chainId  = null;
    _dispatch('wallet-disconnected');
    return;
  }

  try {
    const provider = new ethers.BrowserProvider(window.ethereum);
    const signer   = await provider.getSigner();
    const network  = await provider.getNetwork();

    window._wallet.address  = accounts[0];
    window._wallet.signer   = signer;
    window._wallet.provider = provider;
    window._wallet.chainId  = Number(network.chainId);

    _dispatch('wallet-connected');
  } catch (err) {
    console.warn('[wallet] failed to build provider/signer:', err.message);
  }
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Request the user to connect MetaMask (triggers the popup).
 * Called by the "🦊 Connect Wallet" button in the right-ankh dropdown.
 */
export async function connectWallet() {
  if (!window.ethereum) {
    console.warn('[wallet] MetaMask not available');
    return;
  }
  try {
    const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
    await _applyAccounts(accounts);
  } catch (err) {
    console.warn('[wallet] connect cancelled or failed:', err.message);
  }
}

/**
 * Initialise the global wallet module.
 * - Attaches MetaMask accountsChanged / chainChanged listeners.
 * - Auto-connects silently if the site is already authorised.
 * - Exposes window._wallet.connect for callers without a module import.
 *
 * Call once from main.js inside DOMContentLoaded.
 */
export function initWallet() {
  // Expose connect() on the global object so shadow-DOM components can call it

  // without needing a direct module import.
  window._wallet.connect = connectWallet;

  if (!window.ethereum) {
    console.info('[wallet] MetaMask not detected — wallet features disabled.');
    return;
  }

  // React to the user switching accounts in MetaMask.
  window.ethereum.on('accountsChanged', async (accounts) => {
    await _applyAccounts(accounts);
  });

  // React to chain/network changes.
  window.ethereum.on('chainChanged', async () => {
    // Re-fetch accounts to rebuild provider state after a chain switch.
    try {
      const accounts = await window.ethereum.request({ method: 'eth_accounts' });
      await _applyAccounts(accounts);
    } catch (_) {}
  });

  // Auto-connect silently if already authorised (no browser popup).
  window.ethereum.request({ method: 'eth_accounts' })
    .then(accounts => {
      if (accounts && accounts.length > 0) {
        _applyAccounts(accounts);
      }
    })
    .catch(err => {
      console.warn('[wallet] auto-connect check failed:', err.message);
    });
}

import { buildCreatorWatchlistAuthorizationMessage, normalizeCreatorWatchlistEntry } from './creator-profile-data.mjs?v=20261030-ad-cutoff';
import { nftIdentity } from './nft-loader.js';

const WATCHLIST_EVENT = 'creator-watchlist-changed';

let _state = {
  address: '',
  watchlist: [],
  loading: false,
  error: '',
};

let _revision = 0;

function _serviceUrl() {
  return String(window.DecentConfig?.ipfsUploadServiceUrl || '').replace(/\/$/, '');
}

function _profileUrl(address) {
  return `${_serviceUrl()}/api/creator/profile?${new URLSearchParams({ address })}`;
}

function _watchlistUrl() {
  return `${_serviceUrl()}/api/creator/watchlist`;
}

function _clone(entry) {
  return entry ? { ...entry } : entry;
}

function _cloneState() {
  return { ..._state, watchlist: _state.watchlist.map(_clone) };
}

function _dispatch(detail = {}) {
  if (typeof document === 'undefined' || !document?.dispatchEvent) return;
  const CustomEventCtor = globalThis.CustomEvent || document.defaultView?.CustomEvent;
  if (!CustomEventCtor) return;
  document.dispatchEvent(new CustomEventCtor(WATCHLIST_EVENT, { detail: { ..._cloneState(), ...detail } }));
}

function _setState(next) {
  _state = {
    address: next.address || '',
    watchlist: Array.isArray(next.watchlist) ? next.watchlist.map(_clone) : [],
    loading: Boolean(next.loading),
    error: next.error || '',
  };
  _dispatch();
}

function _currentAddress() {
  return window._wallet?.address || '';
}

function _normalizeEntry(entry = {}) {

  const normalized = normalizeCreatorWatchlistEntry(entry);
  return { ...normalized, nftId: nftIdentity(normalized) };
}

function _sameIdentity(a, b) {
  return a && b && a.nftId === b.nftId;
}

function _findEntry(nft) {
  if (!nft) return null;
  const normalized = _normalizeEntry(nft);
  return _state.watchlist.find(entry => _sameIdentity(entry, normalized)) || null;
}

export function getCreatorWatchlistState() {
  return _cloneState();
}

export function creatorWatchlistIdentity(nft) {
  return nftIdentity(_normalizeEntry(nft));
}

export function creatorWatchlistEntrySnapshot(nft = {}) {
  const normalized = _normalizeEntry(nft);
  return {
    ...normalized,
    title: String(nft.name || nft.title || normalized.title || `Track #${normalized.tokenId}`).trim(),
    artist: String(nft.artist || nft.creator || normalized.artist || '').trim(),
    artworkURI: String(nft.artworkURI || nft.image || normalized.artworkURI || '').trim(),
    metadataUri: String(nft.metadataUri || normalized.metadataUri || '').trim(),
    audioUrl: String(nft.audioUrl || nft.videoUrl || nft.animation_url || normalized.audioUrl || '').trim(),
  };
}

export function isCreatorWatchlisted(nft) {
  return Boolean(_findEntry(nft));
}

export function creatorWatchlistButtonState(nft, { loading = false, resolving = false, saving = false, unavailable = false } = {}) {
  if (unavailable) return { label: '👀 Unavailable', title: 'Could not verify the NFT for this playback', pressed: false, disabled: true, mode: 'unavailable' };
  const address = _currentAddress();
  if (!address) return { label: '👀 Connect', title: 'Connect your wallet to save this NFT', pressed: false, disabled: false, mode: 'connect' };

  if (loading) return { label: '👀 Loading', title: 'Loading your watchlist…', pressed: false, disabled: true, mode: 'loading' };
  if (resolving) return { label: '👀 Pending', title: 'Verifying the exact NFT…', pressed: false, disabled: true, mode: 'pending' };
  const entry = _findEntry(nft);
  if (entry) return { label: '👀 Saved', title: 'Remove from your watchlist', pressed: true, disabled: saving, mode: 'saved', entry };
  return { label: '👀 Save', title: 'Save this NFT to your watchlist', pressed: false, disabled: saving, mode: 'save' };
}

export function applyCreatorWatchlistButton(button, nft, options = {}) {
  if (!button) return null;
  const state = creatorWatchlistButtonState(nft, options);
  button.textContent = state.label;
  button.title = state.title;
  button.setAttribute('aria-label', state.title);
  button.setAttribute('aria-pressed', String(state.pressed));
  button.disabled = state.disabled;
  return state;
}

export async function syncCreatorWatchlist(address = _currentAddress(), { fetchImpl = globalThis.fetch } = {}) {
  const nextAddress = String(address || '').toLowerCase();
  if (!/^0x[0-9a-fA-F]{40}$/.test(nextAddress)) {
    _setState({ address: '', watchlist: [], loading: false, error: '' });
    return _cloneState();
  }
  const revision = ++_revision;
  const priorWatchlist = _state.address === nextAddress ? _state.watchlist : [];
  _setState({ address: nextAddress, watchlist: priorWatchlist, loading: true, error: '' });
  try {
    const response = await fetchImpl(_profileUrl(nextAddress), { signal: AbortSignal.timeout(15000), cache: 'no-store' });
    const profile = await response.json();
    if (revision !== _revision) return _cloneState();
    if (!response.ok) throw new Error(profile.error || 'Profile unavailable');

    const watchlist = Array.isArray(profile.watchlist) ? profile.watchlist.map(_clone) : [];
    _setState({ address: nextAddress, watchlist, loading: false, error: '' });
  } catch (error) {
    if (revision !== _revision) return _cloneState();
    _setState({ address: nextAddress, watchlist: priorWatchlist, loading: false, error: error.message });
  }
  return _cloneState();
}

export function clearCreatorWatchlist() {
  ++_revision;
  _setState({ address: '', watchlist: [], loading: false, error: '' });
}

export async function toggleCreatorWatchlist(nft, { fetchImpl = globalThis.fetch } = {}) {
  const entry = _findEntry(nft);
  return entry ? removeCreatorWatchlist(nft, { fetchImpl }) : saveCreatorWatchlist(nft, { fetchImpl });
}

export async function saveCreatorWatchlist(nft, { fetchImpl = globalThis.fetch } = {}) {
  return _mutateCreatorWatchlist('save-watchlist', nft, { fetchImpl });
}

export async function removeCreatorWatchlist(nft, { fetchImpl = globalThis.fetch } = {}) {
  return _mutateCreatorWatchlist('remove-watchlist', nft, { fetchImpl });
}

async function _mutateCreatorWatchlist(action, nft, { fetchImpl = globalThis.fetch } = {}) {
  const address = _currentAddress();
  const signer = window._wallet?.signer;
  if (!address || !signer) throw new Error('Connect your wallet in the page header');
  const snapshot = creatorWatchlistEntrySnapshot(nft);
  const body = {
    address,
    origin: window.location.origin,
    action,
    entry: snapshot,
    nonce: crypto.randomUUID(),
    issuedAt: new Date().toISOString(),
  };
  const capturedSigner = signer;
  const capturedAddress = address;
  const signature = await capturedSigner.signMessage(buildCreatorWatchlistAuthorizationMessage(body));

  if (capturedAddress !== window._wallet?.address || capturedSigner !== window._wallet?.signer) {
    throw new Error('Wallet changed; sign again');
  }
  const response = await fetchImpl(_watchlistUrl(), {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ ...body, signature }),
    signal: AbortSignal.timeout(30000),
  });
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'Watchlist request failed');
  if (capturedAddress !== window._wallet?.address || capturedSigner !== window._wallet?.signer) {
    throw new Error('Wallet changed; refresh your watchlist');
  }
  const watchlist = Array.isArray(result.profile?.watchlist) ? result.profile.watchlist.map(_clone) : [];
  _setState({ address: capturedAddress.toLowerCase(), watchlist, loading: false, error: '' });
  return result;
}

if (typeof document !== 'undefined' && document?.addEventListener) {
  document.addEventListener('wallet-connected', (event) => {
    void syncCreatorWatchlist(event.detail?.address || _currentAddress()).catch(() => {});
  });
  document.addEventListener('wallet-disconnected', () => {
    clearCreatorWatchlist();
  });
}

import { BASE_CHAIN_ID, ensureBaseNetwork, getBaseReadProvider } from './base-chain.mjs?v=20261018-shared-provider';
import { isAdminWallet } from './admin-access.mjs';
const DEFAULT_ESTIMATED_DAILY_BURN_WEI = 86_000_000_000_000n;
// 0.00002 ETH: roughly ten music-play reports or fifty impressions at October 2026 Base fees.
export const DEFAULT_WORKER_MIN_BALANCE_WEI = 20_000_000_000_000n;
export const SPONSORED_WORKER_WARNING_WEI = 2_000_000_000_000_000n;
export const SPONSORED_WORKER_MIN_BALANCE_WEI = 1_000_000_000_000_000n;
export const SPONSORED_WORKER_TARGET_WEI = 3_000_000_000_000_000n;

// Typo guard: a single top-up can add at most 0.1 ETH (about 33 tanks).
export const MAX_WORKER_TOP_UP_WEI = 100_000_000_000_000_000n;
const WEI_PER_ETH = 1_000_000_000_000_000_000n;

function formatEth(wei) {
  if (typeof wei !== 'bigint' || wei < 0n) return '0 ETH';
  const whole = wei / 1_000_000_000_000_000_000n;
  const fraction = String(wei % 1_000_000_000_000_000_000n).padStart(18, '0').replace(/0+$/, '').slice(0, 6);
  return `${whole}${fraction ? `.${fraction}` : ''} ETH`;
}

function safeBigInt(value, fallback = 0n) {
  if (value == null) return fallback;
  try {
    return typeof value === 'bigint' ? value : BigInt(value);
  } catch {
    return fallback;
  }
}

export async function readWorkerGasState({ provider, workerAddress, minBalanceWei = 0n,
  estimatedDailyBurnWei = DEFAULT_ESTIMATED_DAILY_BURN_WEI }) {
  if (!/^0x[0-9a-fA-F]{40}$/.test(workerAddress || '')) throw new Error('Invalid worker wallet');
  if (Number((await provider.getNetwork()).chainId) !== 8453) throw new Error('Worker balance must be checked on Base');
  const balance = await provider.getBalance(workerAddress);

  if (typeof balance !== 'bigint' || balance < 0n) throw new Error('Invalid worker ETH balance');
  const thresholdWei = safeBigInt(minBalanceWei, 0n);
  const dailyBurnWei = safeBigInt(estimatedDailyBurnWei, DEFAULT_ESTIMATED_DAILY_BURN_WEI);
  return {
    workerAddress,
    balanceWei: balance,
    thresholdWei,
    empty: balance === 0n,
    lowBalance: balance < thresholdWei,
    runwayDays: dailyBurnWei > 0n ? Number(balance / dailyBurnWei) : null,
  };
}


const ETH_STEP_WEI = 1_000_000_000_000n;
const GAUGE_ARC = 'M10 50 A40 40 0 0 1 90 50';
const BASESCAN = 'https://basescan.org';

function ethDigits(wei, digits = 6) {
  const whole = wei / WEI_PER_ETH;
  const fraction = String(wei % WEI_PER_ETH).padStart(18, '0').slice(0, digits).replace(/0+$/, '');
  return `${whole}${fraction ? `.${fraction}` : ''}`;
}

function shortAddress(address) {
  return `${address.slice(0, 6)}…${address.slice(-4)}`;
}

export function workerTankWei(state) {
  const threshold = safeBigInt(state?.thresholdWei, 0n);
  return threshold > SPONSORED_WORKER_TARGET_WEI ? threshold : SPONSORED_WORKER_TARGET_WEI;
}

export function workerGauge(state, targetWei = workerTankWei(state)) {
  if (typeof state?.balanceWei !== 'bigint' || targetWei <= 0n) return { level: 'unknown', fill: 0, multiplier: 0 };
  const balance = state.balanceWei;
  const tanks = balance / targetWei;
  return {
    level: state.lowBalance ? 'low' : balance < targetWei ? 'reserve' : 'full',
    fill: tanks >= 1n ? 1 : Number(balance * 10_000n / targetWei) / 10_000,
    multiplier: tanks >= 2n ? Number(tanks) : 0,
  };
}

// Amount that lifts the balance to `tanks` full tanks, rounded up to the next 0.000001 ETH.
export function topUpToTanksWei(state, tanks = 1) {
  if (typeof state?.balanceWei !== 'bigint') return 0n;

  const missing = workerTankWei(state) * BigInt(tanks) - state.balanceWei;
  return missing > 0n ? (missing + ETH_STEP_WEI - 1n) / ETH_STEP_WEI * ETH_STEP_WEI : 0n;
}

export function parseTopUpWei(text, maxWei = MAX_WORKER_TOP_UP_WEI) {
  const match = /^(\d*)(?:\.(\d*))?$/.exec(String(text ?? '').trim());
  if (!match || (!match[1] && !match[2])) throw new Error('Enter an ETH amount');
  const fraction = match[2] || '';
  if (fraction.length > 18) throw new Error('Use at most 18 decimals');
  const wei = BigInt(match[1] || '0') * WEI_PER_ETH + BigInt(fraction.padEnd(18, '0'));
  if (wei <= 0n) throw new Error('Enter more than 0 ETH');
  if (wei > maxWei) throw new Error(`One top-up is capped at ${formatEth(maxWei)}`);
  return wei;
}

export async function sendWorkerTopUp({ signer, workerAddress, amountWei, onStep = () => {} }) {
  if (!/^0x[0-9a-fA-F]{40}$/.test(workerAddress || '')) throw new Error('Worker wallet is not verified yet');
  if (typeof amountWei !== 'bigint' || amountWei <= 0n || amountWei > MAX_WORKER_TOP_UP_WEI) {
    throw new Error('Choose a valid top-up amount');
  }
  onStep('confirm');
  const tx = await signer.sendTransaction({ to: workerAddress, value: amountWei, chainId: BASE_CHAIN_ID });
  onStep('pending', tx.hash);
  let receipt;
  try {
    receipt = await tx.wait();
  } catch (error) {
    if (error?.code !== 'TRANSACTION_REPLACED' || error.receipt?.status !== 1) throw error;
    if (error.cancelled) throw new Error('The wallet cancelled or replaced this top-up. Check your wallet before trying again');
    receipt = error.receipt;
  }
  if (receipt?.status !== 1) throw new Error('Top-up was not confirmed');
  return { hash: receipt.hash || tx.hash };
}

export function workerGaugeMarkup({ preview = false } = {}) {

  return `<svg class="wg-svg" viewBox="0 0 100 66" aria-hidden="true" focusable="false">`
    + `<path class="wg-track" d="${GAUGE_ARC}" pathLength="100"/>`
    + (preview ? `<path class="wg-after" d="${GAUGE_ARC}" pathLength="100"/>` : '')
    + `<path class="wg-fill" d="${GAUGE_ARC}" pathLength="100"/>`
    + '<text class="wg-mark" x="10" y="62" text-anchor="middle">E</text>'
    + '<text class="wg-mark" x="90" y="62" text-anchor="middle">F</text>'
    + '<text class="wg-pump" x="50" y="38" text-anchor="middle">⛽</text>'
    + '<line class="wg-needle" x1="50" y1="50" x2="50" y2="18"/>'
    + '<circle class="wg-pivot" cx="50" cy="50" r="4"/>'
    + '<text class="wg-times" x="50" y="65" text-anchor="middle"></text></svg>';
}

// The preview draws the current level solid, the post-top-up level as a ghost arc, and points the needle at the result.
function paintGauge(root, gauge, after = null) {
  const shown = after || gauge;
  root.dataset.level = gauge.level;
  if (after) root.dataset.afterLevel = after.level;
  else delete root.dataset.afterLevel;
  const fill = root.querySelector('.wg-fill');
  if (fill) fill.style.strokeDasharray = `${(gauge.fill * 100).toFixed(2)} 100`;
  const ghost = root.querySelector('.wg-after');
  if (ghost) ghost.style.strokeDasharray = `${((after?.fill || 0) * 100).toFixed(2)} 100`;
  const needle = root.querySelector('.wg-needle');
  if (needle) needle.style.transform = `rotate(${(-90 + 180 * shown.fill).toFixed(1)}deg)`;
  const times = root.querySelector('.wg-times');
  if (times) times.textContent = shown.multiplier ? `${shown.multiplier}×` : '';
}

function readingText(state, gauge, error) {
  if (!state) return error ? `unavailable (${error})` : 'checking…';

  const runway = Number.isInteger(state.runwayDays) ? ` · ~${state.runwayDays} day${state.runwayDays === 1 ? '' : 's'}` : '';
  const level = gauge.multiplier ? `${gauge.multiplier} tanks` : `${Math.round(gauge.fill * 100)}% of a ${formatEth(workerTankWei(state))} tank`;
  return `${formatEth(state.balanceWei)}${runway} · ${level}${gauge.level === 'low' ? ' · low' : ''}`;
}

function workerGasConfig() {
  const cfg = globalThis.window?.DecentConfig || {};
  const configured = safeBigInt(cfg.workerMinBalanceWei, DEFAULT_WORKER_MIN_BALANCE_WEI);
  return {
    contract: cfg.djukeContractAddress,
    thresholdWei: cfg.djukeContractVersion === '0.5' && configured < SPONSORED_WORKER_WARNING_WEI
      ? SPONSORED_WORKER_WARNING_WEI : configured,
    dailyBurnWei: safeBigInt(cfg.workerEstimatedDailyBurnWei, DEFAULT_ESTIMATED_DAILY_BURN_WEI),
  };
}

export function initWorkerGasGauge() {
  const button = document.getElementById('worker-gas-gauge');
  if (!button) return;
  const dialog = document.getElementById('worker-gas-dialog');
  const calendar = document.getElementById('radio-programming-modal');
  const part = name => dialog?.querySelector(`[data-worker-gas-${name}]`);
  const preview = part('preview'), reading = part('reading'), form = part('form'), amount = part('amount'),
    slider = part('slider'), explorer = part('explorer'), status = part('status'), send = part('send');
  const presets = [...(dialog?.querySelectorAll('[data-worker-gas-preset]') || [])];
  button.innerHTML = workerGaugeMarkup();
  if (preview) preview.innerHTML = workerGaugeMarkup({ preview: true });

  let state = null, error = '', pending = null, checkedAt = 0, generation = 0, busy = false, touched = false;
  const config = workerGasConfig();

const say = (text = '', tone = '', hash = '') => {
  if (!status) return;
  status.textContent = text;
  status.dataset.tone = tone;
  if (hash) {
    const link = document.createElement('a');
    link.href = `${BASESCAN}/tx/${hash}`;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.textContent = ' View on Basescan ↗';
    status.append(link);
  }
};

function amountWei() {
  try { return parseTopUpWei(amount?.value); } catch { return null; }
}

function renderDialog() {
  if (!dialog) return;
  if (!touched && !busy && amount) amount.value = ethDigits(topUpToTanksWei(state, 1) || SPONSORED_WORKER_TARGET_WEI);
  const gauge = workerGauge(state);
  const wei = amountWei();
  const after = state && wei ? workerGauge({ ...state, balanceWei: state.balanceWei + wei,
    lowBalance: state.balanceWei + wei < state.thresholdWei }) : null;
  if (preview) paintGauge(preview, gauge, after);
  if (reading) {
    const afterRunway = after && config.dailyBurnWei > 0n ? ` · ~${(state.balanceWei + wei) / config.dailyBurnWei} days` : '';
    reading.textContent = `Now ${readingText(state, gauge, error)}${after ? `\nAfter ${formatEth(state.balanceWei + wei)}${afterRunway}` : ''}`;
  }
  if (explorer) {
    explorer.hidden = !state;
    if (state) {
      explorer.href = `${BASESCAN}/address/${state.workerAddress}`;
      explorer.textContent = `${shortAddress(state.workerAddress)} ↗`;
      explorer.title = state.workerAddress;
    }
  }
  presets.forEach(preset => {
    const wei = topUpToTanksWei(state, Number(preset.dataset.workerGasPreset));
    preset.disabled = busy || !wei || wei > MAX_WORKER_TOP_UP_WEI;

    preset.title = !state ? 'Checking the balance…' : wei ? `Add ${formatEth(wei)}` : 'Already there';
  });
  if (slider && wei) slider.value = ethDigits(wei);
  if (amount) amount.disabled = busy;
  if (slider) slider.disabled = busy;
  if (send) {
    send.disabled = busy || !state || !wei;
    send.textContent = wei ? `Send ${formatEth(wei)}` : 'Send';
  }
}

function render() {
  const admin = isAdminWallet();
  button.hidden = !admin;
  const gauge = workerGauge(state);
  paintGauge(button, gauge);
  const label = `Worker gas ${readingText(state, gauge, error)} — open top-up`;
  button.setAttribute('aria-label', label);
  button.title = label;
  if (!admin && dialog?.open) dialog.close();
  renderDialog();
}

async function check() {
  const revision = generation;
  let timeout, provider;
  try {
    provider = getBaseReadProvider({ ethers });
    const read = async () => {
      if (!config.contract) throw new Error('DJuke contract is not configured');
      const contract = new ethers.Contract(config.contract, ['function gasWorker() view returns(address)'], provider);
      return readWorkerGasState({ provider, workerAddress: await contract.gasWorker(),
        minBalanceWei: config.thresholdWei, estimatedDailyBurnWei: config.dailyBurnWei });
    };
    const result = await Promise.race([read(), new Promise((_, reject) => {
      timeout = setTimeout(() => reject(new Error('Worker balance check timed out')), 15000);
    })]);
    if (revision !== generation || !isAdminWallet()) return null;
    state = result;
    error = '';
    checkedAt = Date.now();
    return result;
  } catch (failure) {
    if (revision !== generation) return null;

    console.warn('[worker-gas]', failure.message);
    state = null;
    error = String(failure?.error?.message || failure?.shortMessage || failure?.message || 'balance check failed').slice(0, 80);
    return null;
  } finally {
    clearTimeout(timeout);
    provider?.destroy();
    if (revision === generation) render();
  }
}

function refresh({ force = false } = {}) {
  if (!isAdminWallet()) return Promise.resolve(null);
  if (pending) return force ? pending.then(() => refresh({ force })) : pending;
