const CLOSING_ISSUE_RE = /(?:closes?|fixes?|resolves?)\s+(?:[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+)?#(\d+)/gi;
const TITLE_ISSUE_RE = /#(\d+)/g;
const AMOUNT_RE = /^\d+(?:\.\d+)?$/;
const LEGACY_CURRENCIES = PAYROLL_ASSET_CONFIG.legacy || {};
const DBUSK_REPO_FUND = PAYROLL_ASSET_CONFIG.fundSlug;

const CONTRIBUTOR_ALIASES = {
  'copilot-swe-agent': 'copilot',
  'copilot-swe-agent[bot]': 'copilot',
};

function normalizeLogin(login) {
  const value = String(login || '').trim();
  return CONTRIBUTOR_ALIASES[value.toLowerCase()] || value;
}

function normalizeCurrency(entryOrCurrency) {
  const value = typeof entryOrCurrency === 'object'
    ? entryOrCurrency && entryOrCurrency.currency
    : entryOrCurrency;
  return String(value || 'ETH').trim().toUpperCase();
}

function labelNames(issue) {
  return (issue.labels || []).map(label => typeof label === 'string' ? label : label.name);
}

function currencyDecimals(currency = 'ART', assetRegistry = PAYROLL_ASSET_CONFIG.assets) {
  const symbol = String(currency || 'ART').toUpperCase();
  const decimals = assetRegistry?.[symbol]?.ledgerDecimals ?? LEGACY_CURRENCIES[symbol]?.ledgerDecimals;
  if (!Number.isInteger(decimals) || decimals < 0 || decimals > 18) {

    throw new Error(`Unsupported payroll currency: ${currency}`);
  }
  return decimals;
}

function normalizeAmount(value, currency = 'ART', assetRegistry = PAYROLL_ASSET_CONFIG.assets) {
  const input = String(value).trim();
  if (!AMOUNT_RE.test(input)) throw new Error(`Invalid payout amount: ${value}`);

  let [whole, fraction = ''] = input.split('.');
  whole = whole.replace(/^0+(?=\d)/, '');
  fraction = fraction.replace(/0+$/, '');
  const decimals = currencyDecimals(currency, assetRegistry);
  if (fraction.length > decimals) {
    throw new Error(`${String(currency).toUpperCase()} payouts support at most ${decimals} decimal places: ${value}`);
  }
  if (BigInt(`${whole}${fraction}` || '0') <= 0n) throw new Error(`Invalid payout amount: ${value}`);
  return fraction ? `${whole}.${fraction}` : whole;
}

function parseAmountLabel(issue, pattern = BOUNTY_LABEL_RE, assetRegistry = PAYROLL_ASSET_CONFIG.assets) {
  for (const label of labelNames(issue)) {
    const match = String(label || '').match(pattern);
    if (match) {
      const currency = String(match[2] || 'ART').toUpperCase();
      if (!assetRegistry?.[currency]) continue;
      return { label, amount: normalizeAmount(match[1], currency, assetRegistry), currency };
    }
  }
  return null;
}

function parseAmountLabels(issue, pattern = BOUNTY_LABEL_RE, assetRegistry = PAYROLL_ASSET_CONFIG.assets) {
  const bounties = new Map();
  for (const label of labelNames(issue)) {
    const match = String(label || '').match(pattern);
    if (!match) continue;
    const currency = String(match[2] || 'ART').toUpperCase();
    if (!assetRegistry?.[currency]) continue;
    if (bounties.has(currency)) throw new Error(`Issue has more than one ${currency} bounty label`);

    bounties.set(currency, { label, amount: normalizeAmount(match[1], currency, assetRegistry), currency });
  }
  return [...bounties.values()];
}

function parseIdeaCredit(issue) {
  for (const label of labelNames(issue)) {
    const match = String(label || '').match(IDEA_CREDIT_LABEL_RE);
    if (match) return normalizeLogin(match[1]);
  }
  return null;
}

function parseBugCatcherCredit(issue) {
  const labels = labelNames(issue).map(label => String(label || '').trim());
  if (!labels.some(label => label.toLowerCase() === BUG_CATCHER_APPROVED_LABEL)) return null;
  if (labels.some(label => label.toLowerCase() === 'bug-catcher-pending')) {
    throw new Error('Approved bug-catcher credit cannot keep the pending-review label');
  }
  if (labels.some(label => /^bug-catcher-(?:duplicate|rejected|spam|self-reported|maintainer-discovered)$/i.test(label))) {
    throw new Error('Excluded reports cannot receive bug-catcher approval');
  }
  if (!labels.some(label => label.toLowerCase() === 'bug-catcher')) {
    throw new Error('Approved bug-catcher credit requires the bug-catcher label');
  }
  const logins = labels
    .map(label => label.match(BUG_CATCHER_LABEL_RE)?.[1])
    .filter(Boolean)
    .map(normalizeLogin);
  if (logins.length !== 1) {
    throw new Error('Approved bug-catcher credit requires exactly one bug-catcher: @username label');
  }
  return logins[0];
}

function extractIssueNumbers({ body = '', title = '', linked = [], override = [] } = {}) {
  const numbers = new Set();
  for (const value of override) {
    const number = Number(value);
    if (Number.isInteger(number) && number > 0) numbers.add(number);
  }
  for (const match of String(body).matchAll(CLOSING_ISSUE_RE)) numbers.add(Number(match[1]));

  for (const match of String(title).matchAll(TITLE_ISSUE_RE)) numbers.add(Number(match[1]));
  for (const value of linked) {
    const number = Number(value);
    if (Number.isInteger(number) && number > 0) numbers.add(number);
  }
  return [...numbers];
}

function amountToUnits(value, currency = 'ART', assetRegistry = PAYROLL_ASSET_CONFIG.assets) {
  if (/^0(?:\.0+)?$/.test(String(value).trim())) return 0n;
  const normalized = normalizeAmount(value, currency, assetRegistry);
  const [whole, fraction = ''] = normalized.split('.');
  const decimals = currencyDecimals(currency, assetRegistry);
  const scale = 10n ** BigInt(decimals);
  return BigInt(whole) * scale + BigInt(fraction.padEnd(decimals, '0') || '0');
}

function unitsToAmount(units, currency = 'ART', assetRegistry = PAYROLL_ASSET_CONFIG.assets) {
  const decimals = currencyDecimals(currency, assetRegistry);
  const scale = 10n ** BigInt(decimals);
  const whole = units / scale;
  const fraction = (units % scale).toString().padStart(decimals, '0').replace(/0+$/, '');
  return fraction ? `${whole}.${fraction}` : String(whole);
}

function splitIdeaCredit(amount, currency = 'ART', assetRegistry = PAYROLL_ASSET_CONFIG.assets) {
  const units = amountToUnits(amount, currency, assetRegistry);
  const decimals = currencyDecimals(currency, assetRegistry);
  if (units % 5n !== 0n) {
    throw new Error(`Payout amount cannot be split exactly at ${decimals} decimal places: ${amount}`);
  }
  const originatorUnits = units / 5n;
  return {
    implementer: unitsToAmount(units - originatorUnits, currency, assetRegistry),
    originator: unitsToAmount(originatorUnits, currency, assetRegistry),
  };
}

function splitBugCatcherCredit(amount, currency = 'ART', { hasIdea = false } = {}, assetRegistry = PAYROLL_ASSET_CONFIG.assets) {
  const units = amountToUnits(amount, currency, assetRegistry);
  const decimals = currencyDecimals(currency, assetRegistry);
  const divisor = hasIdea ? 10n : 2n;
  if (units % divisor !== 0n) {
    throw new Error(`Payout amount cannot be split exactly at ${decimals} decimal places: ${amount}`);
  }
  const bugCatcherUnits = units / 2n;
  const ideaUnits = hasIdea ? units / 5n : 0n;
  return {
    implementer: unitsToAmount(units - bugCatcherUnits - ideaUnits, currency, assetRegistry),
    bugCatcher: unitsToAmount(bugCatcherUnits, currency, assetRegistry),
    ...(hasIdea ? { originator: unitsToAmount(ideaUnits, currency, assetRegistry) } : {}),
  };
}

function findAccount(accounts, login) {
  const normalized = normalizeLogin(login).toLowerCase();
  return (accounts.contributors || []).find(
    account => String(account.github || '').trim().toLowerCase() === normalized
  );
}

// Accounts whose bounties are never paid out; the amount stays in the repo-dev fund.
function isRetainInFund(account) {
  return String(account?.payoutMode || '').trim().toLowerCase() === 'retain-in-fund';
}

function blockedPayoutReason(address, config = PAYROLL_ASSET_CONFIG) {
  const normalized = String(address || '').trim().toLowerCase();
  if (!normalized) return null;
  const match = (config.blockedPayoutAddresses || [])
    .find(item => String(item.address || '').trim().toLowerCase() === normalized);
  return match ? (match.reason || 'blocked payout address') : null;
}

function requireWhitelistedAccount(accounts, candidates, description) {
  for (const login of candidates) {
    const account = findAccount(accounts, login);

    if (account && (String(account.walletAddress || '').trim() || isRetainInFund(account))) return account;
  }
  throw new Error(`No whitelisted wallet found for ${description}: ${candidates.filter(Boolean).join(', ') || 'none'}`);
}

function entryRole(entry) {
  return String(entry.role || 'contributor').toLowerCase();
}

function isDuplicate(queue, candidate) {
  const candidateIssueRef = String(candidate.issueRef || '').trim();
  const candidateGithub = String(candidate.contributorGithub || '').trim().toLowerCase();
  const candidateRole = entryRole(candidate);
  const candidateCurrency = normalizeCurrency(candidate);

  return [...(queue.pending || []), ...(queue.settled || []), ...(queue.retained || [])].some(entry => {
    if (String(entry.issueRef || '').trim() !== candidateIssueRef) return false;
    if (normalizeCurrency(entry) !== candidateCurrency) return false;

    const entryGithub = String(entry.contributorGithub || '').trim().toLowerCase();
    const entryRoleName = entryRole(entry);
    if (entryRoleName === 'bug-catcher' && candidateRole !== 'tester') return true;
    if ((candidateRole === 'bug-catcher' && entryRoleName === 'tester') ||
        (candidateRole === 'tester' && entryRoleName === 'bug-catcher')) return false;
    if (entryGithub === candidateGithub) return true;
    if (candidateRole === 'contributor') return false;
    return (entryRoleName === 'implementer' || entryRoleName === 'idea-originator') &&
      (candidateRole === 'implementer' || candidateRole === 'idea-originator');
  });
}

function pickWhitelistedTester({ assigneeLogins = [], accounts, commenter = '' } = {}) {
  const eligible = assigneeLogins
    .map(login => normalizeLogin(login))
    .filter(Boolean)
    .map(login => findAccount(accounts, login))

    .filter(account => account && String(account.walletAddress || '').trim());

  if (eligible.length === 0) throw new Error('No assigned tester on this issue has a whitelisted wallet.');

  const commenterKey = normalizeLogin(commenter).toLowerCase();
  const commenterMatch = eligible.find(
    account => String(account.github || '').trim().toLowerCase() === commenterKey
  );
  if (commenterMatch) return commenterMatch;
  if (eligible.length > 1) {
    throw new Error(`Multiple assigned testers have whitelisted wallets: ${eligible.map(account => account.github).join(', ')}`);
  }
  return eligible[0];
}

function createBountyEntries({ issue, pr, accounts, queue, repoSlug, queuedAt, queuedBy, assetRegistry = PAYROLL_ASSET_CONFIG.assets }) {
  const bounties = parseAmountLabels(issue, BOUNTY_LABEL_RE, assetRegistry);
  if (!bounties.length) return { entries: [], reason: 'missing-bounty-label' };
  const bugCatcherLogin = parseBugCatcherCredit(issue);
  const labels = labelNames(issue).map(label => String(label).toLowerCase());
  const reviewed = labels.some(label => /^bug-catcher-(?:approved|duplicate|rejected|spam|self-reported|maintainer-discovered)$/.test(label));
  const report = labels.includes('bug') || /^## Bug report\b/m.test(issue.body || '') ||
    ['What happened?', 'What did you expect?', 'Steps to reproduce'].every(heading => (issue.body || '').includes(`### ${heading}`));
  if (labels.includes('bug-catcher-pending') || (report && !reviewed)) {
    return { entries: [], retained: [], reason: 'bug-report-pending-review' };
  }
  if (labels.some(label => /^bug-catcher-(?:duplicate|rejected|spam)$/.test(label))) {
    return { entries: [], retained: [], reason: 'bug-report-ineligible' };
  }

  const prAuthor = normalizeLogin(pr.user && pr.user.login);

const assignees = (issue.assignees || []).map(assignee => normalizeLogin(assignee.login));
const implementer = requireWhitelistedAccount(
  accounts,
  [...new Set([prAuthor, ...assignees].filter(Boolean))],
  'PR author or issue assignee'
);
const ideaOriginatorLogin = parseIdeaCredit(issue);
const issueRef = `${repoSlug}#${issue.number}`;
const originator = ideaOriginatorLogin
  ? requireWhitelistedAccount(accounts, [ideaOriginatorLogin], 'idea originator')
  : null;
const bugCatcher = bugCatcherLogin
  ? requireWhitelistedAccount(accounts, [bugCatcherLogin], 'bug catcher')
  : null;
if (bugCatcher) {
  if (normalizeLogin(bugCatcher.github).toLowerCase() === normalizeLogin(implementer.github).toLowerCase()) {
    throw new Error('Self-reported fixes cannot receive bug-catcher rewards; record a self-reported review');
  }
  if (!issue.user?.login || normalizeLogin(issue.user.login).toLowerCase() !== normalizeLogin(bugCatcher.github).toLowerCase()) {
    throw new Error('Bug-catcher attribution must match the authenticated issue author');
  }
  if (issue.user.login.toLowerCase() === repoSlug.split('/')[0].toLowerCase()) {
    throw new Error('Maintainer-discovered reports cannot receive bug-catcher rewards');
  }
  if ((issue.user?.type === 'Bot' || /bot\]$|^(?:copilot|dbusker)$/i.test(bugCatcher.github)) && !isRetainInFund(bugCatcher)) {
    throw new Error('AI/bot bug-catcher credit must retain-in-fund');
  }
  if (!isRetainInFund(bugCatcher) && !/^0x[0-9a-f]{40}$/i.test(bugCatcher.walletAddress || '')) {
    throw new Error('Bug catcher has no valid registered payout wallet');
  }
}
const entries = [];
for (const bounty of bounties) {
  if (bugCatcher) {

  const previous = [...(queue.pending || []), ...(queue.settled || []), ...(queue.retained || [])]
    .filter(entry => entry.issueRef === issueRef && normalizeCurrency(entry) === bounty.currency && entryRole(entry) !== 'tester');
  if (previous.length && !previous.some(entry => entryRole(entry) === 'bug-catcher')) {
    throw new Error('Bounty already allocated without bug-catcher credit; refusing to add a second allocation');
  }
}
const common = {
  issueRef,
  currency: bounty.currency,
  fund: PAYROLL_ASSET_CONFIG.fundSlug,
  queuedAt,
  queuedBy,
  prNumber: pr.number,
};
const forAccount = (account, fields) => {
  if (isRetainInFund(account)) return { ...common, contributorGithub: account.github, ...fields, retainedInFund: true };
  const blocked = blockedPayoutReason(account.walletAddress);
  if (blocked) throw new Error(`Refusing to queue a payout for @${account.github}: ${blocked}`);
  return { ...common, contributor: account.walletAddress, contributorGithub: account.github, ...fields };
};
if (bugCatcher) {
  const split = splitBugCatcherCredit(
    bounty.amount,
    bounty.currency,
    { hasIdea: Boolean(originator) },
    assetRegistry,
  );
  entries.push(
    forAccount(implementer, { amount: split.implementer, role: 'implementer' }),
    forAccount(bugCatcher, { amount: split.bugCatcher, role: 'bug-catcher' }),
  );
  if (originator) {
    entries.push(forAccount(originator, { amount: split.originator, role: 'idea-originator' }));
  }
} else if (originator) {
  const split = splitIdeaCredit(bounty.amount, bounty.currency, assetRegistry);
  entries.push(

        forAccount(implementer, { amount: split.implementer, role: 'implementer' }),
        forAccount(originator, { amount: split.originator, role: 'idea-originator' }),
      );
    } else {
      entries.push(forAccount(implementer, { amount: bounty.amount }));
    }
  }

  const fresh = entries.filter(entry => !isDuplicate(queue, entry));
  const newEntries = fresh.filter(entry => !entry.retainedInFund);
  const retained = fresh.filter(entry => entry.retainedInFund);
  return {
    entries: newEntries,
    retained,
    skippedDuplicates: entries.length - fresh.length,
    bountyLabel: bounties.map(bounty => bounty.label).join(', '),
  };
}

function accountField(currency, suffix) {
  return `${currency.toLowerCase()}${suffix}`;
}

function updateAccountTotal(account, field, amount, currency, subtract = false) {
  const current = Number(account[field]) || 0;
  const decimals = currencyDecimals(currency);
  const currentUnits = amountToUnits(Math.max(0, current).toFixed(decimals), currency);
  const deltaUnits = amountToUnits(amount, currency);
  const nextUnits = subtract
    ? (currentUnits > deltaUnits ? currentUnits - deltaUnits : 0n)
    : currentUnits + deltaUnits;
  if (nextUnits < 0n) throw new Error(`Payroll balance cannot be negative: ${field}`);
  account[field] = Number(unitsToAmount(nextUnits, currency));
}

function applyAccountAccrual(accounts, entries) {
  for (const entry of entries) {
    const account = findAccount(accounts, entry.contributorGithub);
    if (!account) continue;
    const currency = normalizeCurrency(entry);
    updateAccountTotal(account, accountField(currency, 'Pending'), entry.amount, currency);
    if (!Array.isArray(account.issuesClosed)) account.issuesClosed = [];

    if (!account.issuesClosed.includes(entry.issueRef)) account.issuesClosed.push(entry.issueRef);
    if (entry.role === 'idea-originator') {
      if (!Array.isArray(account.ideasCredited)) account.ideasCredited = [];
      if (!account.ideasCredited.includes(entry.issueRef)) account.ideasCredited.push(entry.issueRef);
    }
    if (entry.role === 'bug-catcher') {
      if (!Array.isArray(account.bugsCaught)) account.bugsCaught = [];
      if (!account.bugsCaught.includes(entry.issueRef)) account.bugsCaught.push(entry.issueRef);
    }
  }
}

function applyRetainedAccrual(accounts, entries) {
  for (const entry of entries) {
    const account = findAccount(accounts, entry.contributorGithub);
    if (!account) continue;
    const currency = normalizeCurrency(entry);
    updateAccountTotal(account, accountField(currency, 'RetainedInFund'), entry.amount, currency);
    if (!Array.isArray(account.issuesClosed)) account.issuesClosed = [];
    if (!account.issuesClosed.includes(entry.issueRef)) account.issuesClosed.push(entry.issueRef);
    if (entry.role === 'bug-catcher') {
      if (!Array.isArray(account.bugsCaught)) account.bugsCaught = [];
      if (!account.bugsCaught.includes(entry.issueRef)) account.bugsCaught.push(entry.issueRef);
    }
  }
}

function settleEntries({
  queue,
  accounts,
  contributorGithub = '',
  issueRef = '',
  role = '',
  currency = '',
  txHash = '',
  settledAt,
  settledBy,
}) {
  const contributorFilter = String(contributorGithub).trim().toLowerCase();
  const issueFilter = String(issueRef).trim();
  const roleFilter = String(role).trim().toLowerCase();
  const currencyFilter = String(currency).trim().toUpperCase();
  const matches = entry =>

    (!contributorFilter || String(entry.contributorGithub || '').trim().toLowerCase() === contributorFilter) &&
    (!issueFilter || String(entry.issueRef || '').trim() === issueFilter) &&
    (!roleFilter || entryRole(entry) === roleFilter) &&
    (!currencyFilter || normalizeCurrency(entry) === currencyFilter);
  const selected = (queue.pending || []).filter(matches);
  queue.pending = (queue.pending || []).filter(entry => !matches(entry));

  const settled = selected.map(entry => ({
    ...entry,
    settledAt,
    settledBy,
    ...(txHash ? { txHash } : {}),
  }));
  if (!Array.isArray(queue.settled)) queue.settled = [];
  queue.settled.push(...settled);

  for (const entry of settled) {
    const account = findAccount(accounts, entry.contributorGithub);
    if (!account) continue;
    const entryCurrency = normalizeCurrency(entry);
    updateAccountTotal(account, accountField(entryCurrency, 'Pending'), entry.amount, entryCurrency, true);
    updateAccountTotal(account, accountField(entryCurrency, 'Earned'), entry.amount, entryCurrency);
  }
  return settled;
}

module.exports = {
  BOUNTY_LABEL_RE,
  BUG_CATCHER_APPROVED_LABEL,
  BUG_CATCHER_LABEL_RE,
  DBUSK_REPO_FUND,
  PAYROLL_ASSET_CONFIG,
  SUPPORTED_CURRENCIES,
  TEST_BOUNTY_LABEL_RE,
  applyAccountAccrual,
  applyRetainedAccrual,
  amountToUnits,
  blockedPayoutReason,
  createBountyEntries,
  isRetainInFund,
  extractIssueNumbers,
  findAccount,
  isDuplicate,
  normalizeAmount,
  parseAmountLabels,
  normalizeCurrency,
  normalizeLogin,
  parseAmountLabel,
  parseBugCatcherCredit,
  parseIdeaCredit,
  pickWhitelistedTester,
  settleEntries,
  splitBugCatcherCredit,
  splitIdeaCredit,
  unitsToAmount,
};

const fs = require('fs');
const path = require('path');

const { applyAccountAccrual, applyRetainedAccrual, createBountyEntries, extractIssueNumbers } = require('./payroll');
const { renderArtFiComment } = require('./commentArt');
const { githubRequest, postIssueComment, repositoryCoordinates } = require('./githubApi');

const ROOT = path.resolve(__dirname, '..');
const QUEUE_PATH = path.join(ROOT, 'payroll-queue.json');
const ACCOUNTS_PATH = path.join(ROOT, 'contributor-accounts.json');

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function writeJson(filePath, value) {
  fs.writeFileSync(filePath, `${JSON.stringify(value, null, 2)}\n`);
}

function buildMergedPayrollComment({ entries, retained = [], isManual, prNumber, issueNumber }) {
  const lines = entries.map(entry =>
    `- **${entry.amount} ${entry.currency || 'ART'}** from ${entry.fund || 'dbusk-repo-dev'} to @${entry.contributorGithub}${entry.role ? ` (${entry.role})` : ''}`
  );
  const retainedLines = retained.map(entry =>
    `- **${entry.amount} ${entry.currency || 'ART'}** credited to @${entry.contributorGithub}${entry.role ? ` (${entry.role})` : ''} stays in ${entry.fund || 'dbusk-repo-dev'}`
  );
  return renderArtFiComment([
    `✅ Payroll ${entries.length ? 'queued' : 'recorded'} from ${isManual ? 'manual recovery for' : 'merged'} PR #${prNumber}:`,
    '',
    ...lines,
    ...(retainedLines.length ? [...(lines.length ? [''] : []), ...retainedLines] : []),
    '',
    ...(lines.length ? ['The entries are queued for settlement from the dbusk-repo-dev fund on the shared Base Settlement Router.'] : []),
    ...(retainedLines.length ? ['Retained credit is not paid out; it remains in the repo-dev fund for future contributor payroll.'] : []),

  ].join('\n'), issueNumber, 'merged-payroll');
}

function canQueueMergedPullRequest(pr) {
  return pr?.merged === true;
}

async function linkedIssueNumbers(owner, repo, prNumber) {
  const data = await githubRequest('/graphql', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      query: `query($owner: String!, $repo: String!, $pr: Int!) {
        repository(owner: $owner, name: $repo) {
          pullRequest(number: $pr) {
            closingIssuesReferences(first: 50) { nodes { number } }
          }
        }
      }`,
      variables: { owner, repo, pr: prNumber },
    }),
  });
  if (data.errors) throw new Error(`GitHub GraphQL failed: ${JSON.stringify(data.errors)}`);
  return data.data.repository.pullRequest.closingIssuesReferences.nodes.map(node => node.number);
}

async function main() {
  const { owner, repo } = repositoryCoordinates();
  const event = readJson(process.env.GITHUB_EVENT_PATH);
  const manualPrNumber = Number(process.env.INPUT_PR_NUMBER || 0);
  const manualIssueNumbers = String(process.env.INPUT_ISSUE_NUMBER || '')
    .split(',')
    .map(value => value.trim())
    .filter(Boolean);
  const isManual = process.env.GITHUB_EVENT_NAME === 'workflow_dispatch';
  const pr = event.pull_request || (manualPrNumber
    ? await githubRequest(`/repos/${owner}/${repo}/pulls/${manualPrNumber}`)
    : null);

  if (!pr) throw new Error('A pull request payload or pr_number input is required');
  if (!canQueueMergedPullRequest(pr)) {
    if (isManual) {
      throw new Error(`PR #${pr.number} has not been merged; refusing manual payroll recovery.`);
    }
    console.log(`PR #${pr.number} was closed without merge; no payout was queued.`);
    return;
  }

  let linked = [];
  try {

  linked = await linkedIssueNumbers(owner, repo, pr.number);
} catch (error) {
  console.warn(`Could not load GitHub-linked closing issues: ${error.message}`);
}
const issueNumbers = extractIssueNumbers({
  body: pr.body || '',
  title: pr.title || '',
  linked,
  override: manualIssueNumbers,
});
if (issueNumbers.length === 0) {
  console.log(`PR #${pr.number} has no issue references in its body, title, or GitHub closing links.`);
  return;
}

const queue = readJson(QUEUE_PATH);
const accounts = readJson(ACCOUNTS_PATH);
if (!Array.isArray(queue.pending)) queue.pending = [];
if (!Array.isArray(queue.settled)) queue.settled = [];
if (!Array.isArray(queue.retained)) queue.retained = [];
if (!Array.isArray(accounts.contributors)) accounts.contributors = [];

const planned = [];
const plannedRetained = [];
const results = [];
let blockedReports = 0;
for (const issueNumber of issueNumbers) {
  const issue = await githubRequest(`/repos/${owner}/${repo}/issues/${issueNumber}`);
  if (issue.pull_request) continue;
  const result = createBountyEntries({
    issue,
    pr,
    accounts,
    queue: { pending: [...queue.pending, ...planned], settled: queue.settled, retained: [...queue.retained, ...plannedRetained] },
    repoSlug: `${owner}/${repo}`,
    queuedAt: new Date().toISOString(),
    queuedBy: process.env.GITHUB_ACTOR || 'github-actions[bot]',
  });
  if (result.reason === 'missing-bounty-label') {
    console.log(`Skipping issue #${issueNumber}: no supported "bounty: <amount> SYMBOL" label.`);
    continue;
  }
  if (result.reason === 'bug-report-pending-review' || result.reason === 'bug-report-ineligible') {
    blockedReports++;

    const message = result.reason === 'bug-report-pending-review'
      ? `Issue #${issueNumber}: owner bug-report review is pending. No bounty allocated. Review, then recover merged PR #${pr.number}.`
      : `Issue #${issueNumber}: duplicate/rejected/spam report; no bounty allocated.`;
    console.warn(`::warning::${message}`);
    if (process.env.GITHUB_STEP_SUMMARY) fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, `- ${message}\n`);
    continue;
  }
  if (isManual) [...result.entries, ...result.retained].forEach(entry => { entry.retroactive = true; });
  result.retained.forEach(entry => { entry.retainedAt = entry.queuedAt; entry.retainedBy = entry.queuedBy; });
  planned.push(...result.entries);
  plannedRetained.push(...result.retained);
  results.push({ issueNumber, result });
}

if (planned.length === 0 && plannedRetained.length === 0) {
  console.log(blockedReports ? `No payroll entries queued; ${blockedReports} report(s) blocked above.` : 'No new payroll entries were needed.');
  return;
}
queue.pending.push(...planned);
queue.retained.push(...plannedRetained);
applyAccountAccrual(accounts, planned);
applyRetainedAccrual(accounts, plannedRetained);
writeJson(QUEUE_PATH, queue);
writeJson(ACCOUNTS_PATH, accounts);

for (const { issueNumber, result } of results) {
  if (result.entries.length === 0 && result.retained.length === 0) continue;
  await postIssueComment(owner, repo, issueNumber, buildMergedPayrollComment({
    entries: result.entries,
    retained: result.retained,
    isManual,
    prNumber: pr.number,
    issueNumber,
  }));
}
if (process.env.GITHUB_STEP_SUMMARY) {

    fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, `## Payroll queue updated\n\nQueued ${planned.length} token payout entries (${plannedRetained.length} retained in fund) from PR #${pr.number}.\n`);
  }
