const fs = require('fs');

const { postIssueComment, repositoryCoordinates } = require('./githubApi');

function parseIssueForm(body) {
  const fields = {};
  const pattern = /(?:^|\r?\n)### ([^\r\n]+)\r?\n+([\s\S]*?)(?=\r?\n### |$)/g;
  for (const match of String(body || '').matchAll(pattern)) fields[match[1].trim()] = match[2].trim();
  return fields;
}

async function main() {
  const event = JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH, 'utf8'));
  const issue = event.issue;
  if (!issue) throw new Error('GitHub issue event payload is required');
  const { owner, repo } = repositoryCoordinates();
  const fields = parseIssueForm(issue.body);
  const github = fields['GitHub username'] || issue.user.login;
  const body = [
    `@${owner}, a contributor request from @${github} is ready for wallet and technical fit review.`,
    '',
    'This GitHub mention is the administrative notification; no email or external notification service is used.',
  ].join('\n');
  await postIssueComment(owner, repo, issue.number, body);

  const summary = [
    '## Contributor request received',
    '',
    `- Issue: #${issue.number}`,
    `- GitHub: @${github}`,
    `- Wallet: ${fields['Wallet address'] || 'not provided'}`,
    `- Area: ${fields['What you want to help with'] || 'not provided'}`,
    `- URL: ${issue.html_url}`,
    '',
  ].join('\n');
  if (process.env.GITHUB_STEP_SUMMARY) fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, summary);
  console.log(`GitHub-native contributor request alert posted for issue #${issue.number}`);
}

if (require.main === module) {
  main().catch(error => {
    console.error(error.stack || error.message);
    process.exitCode = 1;
  });
}

module.exports = { parseIssueForm };

const fs = require('fs');
const path = require('path');

const { renderArtFiComment } = require('./commentArt');
const { postIssueComment, repositoryCoordinates } = require('./githubApi');
const { settleEntries, SUPPORTED_CURRENCIES } = require('./payroll');

const ROOT = path.resolve(__dirname, '..');
const QUEUE_PATH = path.join(ROOT, 'payroll-queue.json');
const ACCOUNTS_PATH = path.join(ROOT, 'contributor-accounts.json');

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function writeJson(filePath, value) {
  fs.writeFileSync(filePath, `${JSON.stringify(value, null, 2)}\n`);
}

function buildSettlementComment({ settledCount, actor, txHash, issueNumber, currency, role }) {
  const body = [
    `✅ Settled ${settledCount} ${currency || 'ART'} ${role ? `${role} ` : ''}payroll entr${settledCount === 1 ? 'y' : 'ies'} by @${actor}.`,
    txHash ? `🔗 Tx: ${txHash}` : '',
  ].filter(Boolean).join('\n');
  return renderArtFiComment(body, issueNumber, 'settlement');
}

function selectSettlementCandidates(queue, { contributorGithub = '', issueRef = '', role = '', currency = '' } = {}) {
  return (queue.pending || []).filter(entry => {
    const entryCurrency = String(entry.currency || 'ETH').trim().toUpperCase();
    return entryCurrency !== 'ETH' &&
      (!contributorGithub || String(entry.contributorGithub || '').trim().toLowerCase() === contributorGithub.toLowerCase()) &&
      (!issueRef || String(entry.issueRef || '').trim() === issueRef) &&
      (!role || String(entry.role || 'contributor').trim().toLowerCase() === role) &&
      (!currency || entryCurrency === currency);
  });
}

function groupByIssue(entries) {
  const groups = new Map();
  for (const entry of entries) {

    const key = `${entry.issueRef}|${entry.currency}|${entry.role || 'contributor'}`;
    if (!groups.has(key)) groups.set(key, { issueRef: String(entry.issueRef || ''), currency: entry.currency, role: entry.role || 'contributor', entries: [] });
    groups.get(key).entries.push(entry);
  }
  return [...groups.values()];
}

async function main() {
  const { owner, repo } = repositoryCoordinates();
  const contributorGithub = String(process.env.INPUT_CONTRIBUTOR_GITHUB || '').trim();
  const issueRef = String(process.env.INPUT_ISSUE_REF || '').trim();
  const role = String(process.env.INPUT_ROLE || '').trim().toLowerCase().replace(/^any$/, '');
  const currency = String(process.env.INPUT_CURRENCY || '').trim().toUpperCase();
  const txHash = String(process.env.INPUT_TX_HASH || '').trim();
  if (!/^0x[a-fA-F0-9]{64}$/.test(txHash)) throw new Error('tx_hash must be a 32-byte transaction hash');
  if (issueRef && !/^[^/]+\/[^/]+#\d+$/.test(issueRef)) throw new Error('issue_ref must look like owner/repo#123');
  if (role && !['contributor', 'implementer', 'idea-originator', 'bug-catcher', 'tester'].includes(role)) throw new Error(`unsupported payroll role: ${role}`);
  if (currency === 'ETH') throw new Error('Legacy ETH cannot be settled by the active Base workflow');
  if (currency && !SUPPORTED_CURRENCIES.includes(currency)) throw new Error(`unsupported payroll asset: ${currency}`);

  const queue = readJson(QUEUE_PATH);
  const accounts = readJson(ACCOUNTS_PATH);
  const candidates = selectSettlementCandidates(queue, { contributorGithub, issueRef, role, currency });
  if (!candidates.length) { console.log('No matching pending Base entries found.'); return; }
  const config = readJson(path.join(ROOT, 'payroll-assets.json'));

const { verifyRepositoryPayment } = await import('../discord-bot/payment-ledger.js');
const { createFailoverProvider } = await import('../discord-bot/rpc-failover.js');
const provider = createFailoverProvider(config);
// With only a tx hash, settle every pending entry that the transaction exactly proves (batch payouts).
const exact = Boolean(contributorGithub && issueRef && role && currency);
const proven = [];
for (const entry of candidates) {
  try {
    await verifyRepositoryPayment({ entry, config, txHash, provider });
    proven.push(entry);
  } catch (error) {
    if (exact || !/No exact router payment proof/.test(error.message)) throw error;
  }
}
if (!proven.length) throw new Error('This transaction does not prove payment for any pending payroll entry');

const settledAt = new Date().toISOString();
const settledBy = process.env.GITHUB_ACTOR || 'github-actions[bot]';
const settled = proven.flatMap(entry => settleEntries({
  queue,
  accounts,
  contributorGithub: entry.contributorGithub,
  issueRef: entry.issueRef,
  role: String(entry.role || 'contributor').toLowerCase(),
  currency: String(entry.currency || '').toUpperCase(),
  txHash,
  settledAt,
  settledBy,
}));
if (settled.length === 0) {
  console.log('No matching pending entries found.');
  return;
}

writeJson(QUEUE_PATH, queue);
writeJson(ACCOUNTS_PATH, accounts);
for (const group of groupByIssue(settled)) {
  const issueMatch = group.issueRef.match(/#(\d+)$/);
  if (!issueMatch || !group.issueRef.startsWith(`${owner}/${repo}#`)) continue;
  const issueNumber = Number(issueMatch[1]);
  await postIssueComment(owner, repo, issueNumber, buildSettlementComment({
    settledCount: group.entries.length,
    actor: settledBy,

      txHash,
      issueNumber,
      currency: group.currency,
      role: group.role,
    }));
  }
  console.log(`Settled ${settled.length} payroll entr${settled.length === 1 ? 'y' : 'ies'} from ${txHash}.`);
}

if (require.main === module) {
  main().catch(error => {
    console.error(error.stack || error.message);
    process.exitCode = 1;
  });
}

module.exports = { buildSettlementComment, selectSettlementCandidates, groupByIssue };

const fs = require('fs');
const path = require('path');
const { DBUSK_REPO_FUND, blockedPayoutReason, isRetainInFund, normalizeAmount, normalizeCurrency, PAYROLL_ASSET_CONFIG, SUPPORTED_CURRENCIES } = require('./payroll');

const QUEUE_PATH = path.join(__dirname, '..', 'payroll-queue.json');
const ACCOUNTS_PATH = path.join(__dirname, '..', 'contributor-accounts.json');
const ADDRESS_RE = /^0x[a-fA-F0-9]{40}$/;
const ISSUE_REF_RE = /^[^/]+\/[^/]+#\d+$/;
const VALID_CURRENCIES = new Set([...SUPPORTED_CURRENCIES, 'ETH']);
const SUPPORTED_ROLES = new Set(['contributor', 'implementer', 'idea-originator', 'bug-catcher', 'tester']);
const LEGACY_CUTOFF = Date.parse('2026-09-16T00:00:00.000Z');

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function fail(message) {
  console.error(`❌ ${message}`);
  process.exit(1);
}

if (!fs.existsSync(QUEUE_PATH)) fail('payroll-queue.json is missing');
if (!fs.existsSync(ACCOUNTS_PATH)) fail('contributor-accounts.json is missing');

let queue;
let accounts;
try { queue = readJson(QUEUE_PATH); } catch (error) { fail(`payroll-queue.json is not valid JSON: ${error.message}`); }
try { accounts = readJson(ACCOUNTS_PATH); } catch (error) { fail(`contributor-accounts.json is not valid JSON: ${error.message}`); }

if (!queue || typeof queue !== 'object' || Array.isArray(queue)) fail('payroll-queue.json must be a JSON object');
if (!Array.isArray(queue.pending)) fail('payroll-queue.json.pending must be an array');
if (!Array.isArray(queue.settled)) fail('payroll-queue.json.settled must be an array');
if (queue.retained !== undefined && !Array.isArray(queue.retained)) fail('payroll-queue.json.retained must be an array');
if (!Array.isArray(queue.retained)) queue.retained = [];

if (!accounts || typeof accounts !== 'object' || Array.isArray(accounts)) fail('contributor-accounts.json must be a JSON object');
if (!Array.isArray(accounts.contributors)) fail('contributor-accounts.json.contributors must be an array');

if (!Number.isInteger(PAYROLL_ASSET_CONFIG.chainId) || PAYROLL_ASSET_CONFIG.chainId <= 0) fail('payroll-assets.json.chainId must be a positive integer');
if (!/^0x[a-fA-F0-9]{40}$/.test(String(PAYROLL_ASSET_CONFIG.routerAddress || ''))) fail('payroll-assets.json.routerAddress must be a valid contract address');
if (!/^[a-z0-9][a-z0-9-]*$/.test(String(PAYROLL_ASSET_CONFIG.fundSlug || ''))) fail('payroll-assets.json.fundSlug must be a lowercase slug');
if (!PAYROLL_ASSET_CONFIG.assets || typeof PAYROLL_ASSET_CONFIG.assets !== 'object' || Array.isArray(PAYROLL_ASSET_CONFIG.assets) || Object.keys(PAYROLL_ASSET_CONFIG.assets).length === 0) {
  fail('payroll-assets.json.assets must contain at least one configured token');
}
if (PAYROLL_ASSET_CONFIG.blockedPayoutAddresses !== undefined && !Array.isArray(PAYROLL_ASSET_CONFIG.blockedPayoutAddresses)) {
  fail('payroll-assets.json.blockedPayoutAddresses must be an array');
}
for (const [index, item] of (PAYROLL_ASSET_CONFIG.blockedPayoutAddresses || []).entries()) {
  if (!ADDRESS_RE.test(String(item?.address || ''))) fail(`payroll-assets.json.blockedPayoutAddresses[${index}].address must be a valid address`);
  if (!String(item?.reason || '').trim()) fail(`payroll-assets.json.blockedPayoutAddresses[${index}].reason is required`);
}
if (PAYROLL_ASSET_CONFIG.assets?.ETH) fail('ETH is reserved for historical Optimism payouts and cannot be configured as a Base token');
for (const [symbol, asset] of Object.entries(PAYROLL_ASSET_CONFIG.assets || {})) {

  if (!/^[A-Z][A-Z0-9]{1,9}$/.test(symbol)) fail(`payroll-assets.json asset symbol is invalid: ${symbol}`);
  if (!ADDRESS_RE.test(String(asset.address || ''))) fail(`payroll-assets.json ${symbol}.address must be a valid contract address`);
  if (!Number.isInteger(asset.decimals) || asset.decimals < 0 || asset.decimals > 36) fail(`payroll-assets.json ${symbol}.decimals must be between 0 and 36`);
  if (!Number.isInteger(asset.ledgerDecimals) || asset.ledgerDecimals < 0 || asset.ledgerDecimals > 18 || asset.ledgerDecimals > asset.decimals) {
    fail(`payroll-assets.json ${symbol}.ledgerDecimals must be between 0 and min(18, token decimals)`);
  }
}

const contributors = new Map();
for (const [index, contributor] of accounts.contributors.entries()) {
  if (!contributor || typeof contributor !== 'object' || Array.isArray(contributor)) {
    fail(`contributor-accounts.json.contributors[${index}] must be an object`);
  }
  const github = String(contributor.github || '').trim();
  const wallet = String(contributor.walletAddress || '').trim();
  if (!github) fail(`contributor-accounts.json.contributors[${index}].github is required`);
  const retain = isRetainInFund(contributor);
  if (contributor.payoutMode !== undefined && !retain) fail(`contributor-accounts.json.contributors[${index}].payoutMode must be "retain-in-fund" when set`);
  if (retain && wallet) fail(`contributor-accounts.json.contributors[${index}] retains credit in the fund and must not have a walletAddress`);
  if (!retain && !ADDRESS_RE.test(wallet)) fail(`contributor-accounts.json.contributors[${index}].walletAddress must be a valid Ethereum address`);

  if (!retain && blockedPayoutReason(wallet)) fail(`contributor-accounts.json.contributors[${index}].walletAddress is blocked: ${blockedPayoutReason(wallet)}`);
  const key = github.toLowerCase();
  if (contributors.has(key)) fail(`duplicate contributor GitHub handle: ${github}`);
  contributors.set(key, retain ? null : wallet.toLowerCase());
}

const seen = new Set();
const bugCatcherCredits = new Set();
function validateEntry(entry, section, index) {
  if (!entry || typeof entry !== 'object' || Array.isArray(entry)) fail(`${section}[${index}] must be an object`);
  const issueRef = String(entry.issueRef || '').trim();
  const github = String(entry.contributorGithub || '').trim();
  const wallet = String(entry.contributor || '').trim();
  const amount = String(entry.amount || '').trim();
  const currency = normalizeCurrency(entry);
  const role = String(entry.role || 'contributor').trim().toLowerCase();
  const queuedAt = String(entry.queuedAt || '').trim();

  if (!ISSUE_REF_RE.test(issueRef)) fail(`${section}[${index}].issueRef must look like owner/repo#123`);
  if (!github) fail(`${section}[${index}].contributorGithub is required`);
  if (section === 'retained') {
    if (wallet) fail(`${section}[${index}].contributor must be omitted for retained credit`);
    if (entry.retainedInFund !== true) fail(`${section}[${index}].retainedInFund must be true`);
  } else if (!ADDRESS_RE.test(wallet)) fail(`${section}[${index}].contributor must be a valid Ethereum address`);
  if (section === 'pending' && blockedPayoutReason(wallet)) fail(`${section}[${index}].contributor is blocked: ${blockedPayoutReason(wallet)}`);
  if (!amount || !Number.isFinite(Number(amount)) || Number(amount) <= 0) fail(`${section}[${index}].amount must be positive`);

if (!VALID_CURRENCIES.has(currency)) fail(`${section}[${index}].currency must be configured in payroll-assets.json or be legacy ETH`);
if (SUPPORTED_CURRENCIES.includes(currency)) {
  try { normalizeAmount(amount, currency); } catch (error) { fail(`${section}[${index}].amount is invalid for ${currency}: ${error.message}`); }
  if (entry.fund !== DBUSK_REPO_FUND) fail(`${section}[${index}].fund must be ${DBUSK_REPO_FUND}`);
}
if (!entry.currency && Date.parse(queuedAt) >= LEGACY_CUTOFF) fail(`${section}[${index}].currency is required for new entries`);
if (!SUPPORTED_ROLES.has(role)) fail(`${section}[${index}].role is not supported: ${role}`);

const key = `${issueRef}:${github.toLowerCase()}:${role}:${currency}`;
if (seen.has(key)) fail(`duplicate payroll entry detected for ${issueRef} / ${github} / ${currency}`);
seen.add(key);
if (role === 'bug-catcher') {
  const creditKey = `${issueRef}:${currency}`;
  if (bugCatcherCredits.has(creditKey)) fail(`duplicate bug-catcher credit detected for ${issueRef} / ${currency}`);
  bugCatcherCredits.add(creditKey);
}
if (!contributors.has(github.toLowerCase())) fail(`${section}[${index}].contributorGithub is not registered in contributor-accounts.json`);
const registeredWallet = contributors.get(github.toLowerCase());
if (section !== 'retained' && registeredWallet === null) fail(`${section}[${index}] cannot be paid: ${github} retains credit in the fund`);
if (section !== 'retained' && registeredWallet !== wallet.toLowerCase()) fail(`${section}[${index}].contributor does not match the registered wallet for ${github}`);
if (section === 'retained' && registeredWallet !== null) fail(`${section}[${index}].contributorGithub must use payoutMode "retain-in-fund"`);

  if (!queuedAt) fail(`${section}[${index}].queuedAt is required`);
  if (!String(entry.queuedBy || '').trim()) fail(`${section}[${index}].queuedBy is required`);
  if (section === 'settled') {
    if (!String(entry.settledAt || '').trim()) fail(`${section}[${index}].settledAt is required`);
    if (!String(entry.settledBy || '').trim()) fail(`${section}[${index}].settledBy is required`);
  }
  if (section === 'retained') {
    if (!String(entry.retainedAt || '').trim()) fail(`${section}[${index}].retainedAt is required`);
    if (!String(entry.retainedBy || '').trim()) fail(`${section}[${index}].retainedBy is required`);
  }
}

queue.pending.forEach((entry, index) => validateEntry(entry, 'pending', index));
queue.settled.forEach((entry, index) => validateEntry(entry, 'settled', index));
queue.retained.forEach((entry, index) => validateEntry(entry, 'retained', index));
console.log(`✅ payroll-queue.json and contributor-accounts.json validated (${queue.pending.length} pending, ${queue.settled.length} settled, ${queue.retained.length} retained in fund; currency-less entries treated as legacy ETH)`);

#!/usr/bin/env node
// Publishes Sourcify exact-match sources to Basescan (Etherscan V2 API).
// Usage: ETHERSCAN_API_KEY=... node scripts/verify-basescan.mjs [--dry-run]
// The key may also be read from discord-bot/.env or ../DecentMarket/.env (BASESCAN_API_KEY or ETHERSCAN_API_KEY).
// No private key is needed; verification only publishes source code.
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const CHAIN_ID = 8453;
const SOURCIFY = "https://sourcify.dev/server/v2/contract";
const ETHERSCAN = `https://api.etherscan.io/v2/api?chainid=${CHAIN_ID}`;

export const BASE_CONTRACTS = [
  { label: "ArtFi settlement router", address: "0x8ecca903e2a6Daa8CCbB933700e4F2C58C44A4B5" },
  { label: "DJuke v0.5 (live)", address: "0xf51D2F7892cF9D49e14DF4afDf227a59ee170A51" },
  { label: "DJuke sponsored playlist module", address: "0x093d2dbCcBA612d2B2aD9B620cA4d0A03D98fE11" },
  { label: "DJuke v0.4 (retired)", address: "0xBBCb7F7369978cbdc32C6719B1d24B07f3d55619" },
  { label: "DJuke v0.3 (retired)", address: "0x5d07489163feBCdB39C9F579CCC36dff5A067FF9" },
  { label: "DJuke v0.2", address: "0x333Aa353d6fc70aE79Cf91CE090645CD740FEf59" },
  { label: "DeVert v0.1", address: "0x135Cbc573F87637158eb3186C87c584fb0B34CD9" },
  { label: "DeVert v0.2", address: "0xc73c9623C6E8E9c43872b1883ae4A290F2BAdD6F" },
  { label: "DVert paid queue v0.2 (sponsored campaigns)", address: "0x3A771295af7F15B68c53251683916b65440eD8d3" },
  { label: "DecentEscrow v0.1", address: "0x31b07b83e99A9bdF379bf40225b8A80d3804C89d" },
  { label: "LivePerformanceEscrow", address: "0x20C08F2e877389D68cFbcF49664211E8CE9554Ec" },
  { label: "DecentNFT v0.2", address: "0xe63EC9f8228720bAAC2fD528C0A6d06B3Dc5439B" },

  { label: "DecentNFT v0.3", address: "0x64D5aDc50E5513975EfF7e9ba366B7eE58586fa3" },
  { label: "BNUT", address: "0x25ACb773159Af5a5c672DEfe31C7Fff6a9A93736" },
];

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function loadKey() {
  const fromEnv = process.env.ETHERSCAN_API_KEY || process.env.BASESCAN_API_KEY;
  if (fromEnv) return fromEnv.trim();
  const here = path.dirname(fileURLToPath(import.meta.url));
  for (const file of ["../discord-bot/.env", "../../DecentMarket/.env"]) {
    try {
      const env = await readFile(path.resolve(here, file), "utf8");
      const m = env.match(/^\s*(?:ETHERSCAN|BASESCAN)_API_KEY\s*=\s*["']?([^"'\s#]+)/m);
      if (m) return m[1];
    } catch {}
  }
  return "";
}

async function etherscan(params, key, method = "GET") {
  await sleep(400); // free tier allows 3 calls/sec
  const body = new URLSearchParams({ ...params, apikey: key });
  const res = method === "GET"
    ? await fetch(`${ETHERSCAN}&${body}`)
    : await fetch(ETHERSCAN, { method: "POST", body });
  return res.json();
}

async function basescanVerified(address, key) {
  const r = await etherscan({ module: "contract", action: "getsourcecode", address }, key);
  return Boolean(r?.result?.[0]?.SourceCode);
}

async function sourcify(address) {
  const fields = "compilation,stdJsonInput,creationBytecode.transformationValues";
  const res = await fetch(`${SOURCIFY}/${CHAIN_ID}/${address}?fields=${fields}`);
  if (!res.ok) return null;
  const d = await res.json();
  return d.match ? d : null;
}

async function main() {
  const dryRun = process.argv.includes("--dry-run");
  const key = await loadKey();
  if (!key && !dryRun) {
    console.error("Missing ETHERSCAN_API_KEY (Etherscan V2 key, free at etherscan.io/myapikey). Use --dry-run to preview.");

    process.exit(1);
  }
  let failures = 0;
  for (const c of BASE_CONTRACTS) {
    const tag = `${c.label.padEnd(24)} ${c.address}`;
    if (key && (await basescanVerified(c.address, key))) {
      console.log(`✔ ${tag} already verified on Basescan`);
      continue;
    }
    const s = await sourcify(c.address);
    if (!s) {
      console.log(`✖ ${tag} not verified on Sourcify; cannot source it`);
      failures++;
      continue;
    }
    const args = (s.creationBytecode?.transformationValues?.constructorArguments || "").replace(/^0x/, "");
    if (dryRun) {
      console.log(`• ${tag} would submit ${s.compilation.fullyQualifiedName} (${s.compilation.compilerVersion}, ${args.length / 64} ctor words)`);
      continue;
    }
    const sub = await etherscan({
      module: "contract",
      action: "verifysourcecode",
      contractaddress: c.address,
      sourceCode: JSON.stringify(s.stdJsonInput),
      codeformat: "solidity-standard-json-input",
      contractname: s.compilation.fullyQualifiedName,
      compilerversion: `v${s.compilation.compilerVersion}`,
      constructorArguements: args,
    }, key, "POST");
    if (sub.status !== "1") {
      console.log(`✖ ${tag} submit failed: ${sub.result}`);
      failures++;
      continue;
    }
    let result = "Pending";
    for (let i = 0; i < 20 && /pending/i.test(result); i++) {
      await sleep(5000);
      result = (await etherscan({ module: "contract", action: "checkverifystatus", guid: sub.result }, key)).result;
    }
    const ok = /pass|already verified/i.test(result);
    if (!ok) failures++;
    console.log(`${ok ? "✔" : "✖"} ${tag} ${result}`);
  }
  process.exit(failures ? 1 : 0);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();

