    container, wallet, serviceUrl: 'https://fixture.invalid',
    bookingState: { bookings: [booking], escrowAddress },
    ethers: { BrowserProvider() { throw new Error('Fixture forbids wallet operations'); } },
    fetchImpl: async (url, options) => {
      requests.push({ url, cache: options?.cache });
      if (scenario === 'offline') throw new Error('Fixture offline');
      if (url.endsWith('/api/live-bookings')) return { ok: true, json: async () => ({ bookings: [booking], escrowAddress }) };
      if (url !== `https://fixture.invalid/api/live-audio/state?bookingId=${encodeURIComponent(booking.id)}`) {
