window.runProfileReentryFixtures = async () => {
  const results = [];
  for (const scenario of ['waiting', 'live', 'approved', 'paid', 'stale', 'offline', 'expired', 'wrong-booking', 'ended']) {
    const fixture = await renderCase(scenario);
    const link = container.querySelector('[data-live-room="performer"]');
