  let downloaded = false;
  const result = await backfillIpfsPins({ client: {}, store, maxBytes: 10 * 1024 * 1024, delayMs: 0,
    log: { log() {}, warn() {} },
    fetchAttachment: async () => ({ size: 10 * 1024 * 1024 + 1, url: 'https://cdn.example/large.mp4' }),
