function createTimerHarness() {
  let nextId = 1;
  const timers = [];
  return {
    timers,
    setTimeout(callback, delay) {
      const timer = { id: nextId++, callback, delay, cancelled: false };
      timers.push(timer);
      return timer.id;
    },
    clearTimeout(id) {
      const timer = timers.find(entry => entry.id === id);
      if (timer) timer.cancelled = true;
    },
    runNext() {
      while (timers.length) {
        const timer = timers.shift();
        if (!timer.cancelled) {
          timer.callback();
          return timer;
        }
      }
      return null;
    },
    runAll() {
      while (this.runNext());
    },
    lastDelay() {
      const timer = [...timers].reverse().find(entry => !entry.cancelled);
      return timer?.delay;
    },
  };
}

function createCelebrationFixture({ reducedMotion = false, panelSource, panelOpen = true, modalOpen = false } = {}) {
  const timers = createTimerHarness();
  const listeners = new Map();
  const stage = {
    hidden: false,
