  vm.runInContext("_renderVoteNetValue(20, 'play-2')", context);
  assert.equal(animations.length, 2, 'track changes are not vote gains');
  reduced = true;

  vm.runInContext("_renderVoteNetValue(21, 'play-2')", context);
