const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');
const { createRequire } = require('node:module');
const ethers = createRequire(path.join(__dirname, '../discord-bot/package.json'))('ethers');

const config = { chainId: 8453, routerAddress: 'router', assets: { ART: {}, USDC: {} } };
const entry = { issueRef: 'owner/repo#1', contributorGithub: 'reporter', role: 'bug-catcher', currency: 'USDC', amount: '1' };
const provider = { getNetwork: async () => ({ chainId: 8453 }), getBlockNumber: async () => 101, getCode: async () => '0x60' };

test('verified backlog excludes completed, retained and historical records with unchanged payment references', async () => {
  const { getRepositoryPayrollStatus, repositoryWorkReferenceText } = await import('../js/repository-payroll-status.mjs');
  const paid = { ...entry }, unpaid = { ...entry, issueRef: 'owner/repo#2', currency: 'ART' };
  const queue = { pending: [paid, unpaid, { ...entry, currency: 'ETH' }, { ...entry, retainedInFund: true }] };
  const calls = [];
  const api = { ...ethers, Contract: class {
    async completedWorkReferences(reference, options) {
      calls.push({ reference, options });
      return reference === ethers.id('owner/repo#1:reporter:bug-catcher:USDC');
    }
  } };
  const result = await getRepositoryPayrollStatus({ queue, config, provider, ethers: api });
  assert.deepEqual(result.pending, [unpaid]);
  assert.deepEqual(result.completed, [paid]);
  assert.equal(result.blockNumber, 100);
  assert.equal(queue.pending.length, 4);
  assert.deepEqual(calls, [
    { reference: ethers.id('owner/repo#1:reporter:bug-catcher:USDC'), options: { blockTag: 100 } },

    { reference: ethers.id('owner/repo#2:reporter:bug-catcher'), options: { blockTag: 100 } },
  ]);
  assert.equal(repositoryWorkReferenceText({ ...entry, currency: 'ART', role: undefined }), 'owner/repo#1:reporter:contributor');
});

test('all-paid rows mean zero unpaid, but missing proof or RPC failure cannot become a zero count', async () => {
  const { getRepositoryPayrollStatus } = await import('../js/repository-payroll-status.mjs');
  const queue = { pending: [entry] };
  const api = { ...ethers, Contract: class { async completedWorkReferences() { return true; } } };
  const result = await getRepositoryPayrollStatus({ queue, config, provider, ethers: api });
  assert.equal(result.pending.length, 0);
  assert.equal(result.completed.length, 1);
  for (const bad of [
    { ...provider, getNetwork: async () => ({ chainId: 10 }) },
    { ...provider, getCode: async () => '0x' },
    { ...provider, getBlockNumber: async () => { throw new Error('RPC offline'); } },
  ]) await assert.rejects(getRepositoryPayrollStatus({ queue, config, provider: bad, ethers: api }), /Base|unavailable|offline/);
  await assert.rejects(getRepositoryPayrollStatus({ queue, config, provider, ethers: {
    ...api, Contract: class { async completedWorkReferences() { throw new Error('RPC offline'); } },
  } }), /offline/);
});

const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');
const { pathToFileURL } = require('node:url');

const modulePath = pathToFileURL(path.join(__dirname, '..', 'discord-bot', 'rpc-failover.js')).href;

test('failover provider retries refused RPCs but not deterministic errors', async t => {
  const { FailoverJsonRpcProvider, rpcUrlsFromConfig } = await import(modulePath);
  assert.deepEqual(
    rpcUrlsFromConfig({ rpcUrl: 'https://a', rpcFallbackUrls: ['https://b', 'https://a', ''] }),
    ['https://a', 'https://b']
  );

  const provider = new FailoverJsonRpcProvider(['https://a', 'https://b', 'https://c']);
  const calls = [];
  const primary = async () => { calls.push('a'); throw new Error('server response 403 Forbidden'); };
  const base = Object.getPrototypeOf(FailoverJsonRpcProvider.prototype);
  const originalSend = base._send;
  base._send = function (payload) { return this === provider ? primary(payload) : originalSend.call(this, payload); };
  t.after(() => { base._send = originalSend; provider.destroy(); });
  provider.backups[0]._send = async payload => { calls.push('b'); return [{ id: payload.id, error: { code: -32602, message: 'Archive requests require a personal token' } }]; };
  provider.backups[1]._send = async payload => { calls.push('c'); return [{ id: payload.id, result: '0x1' }]; };
  assert.deepEqual(await provider._send({ id: 1, method: 'eth_blockNumber' }), [{ id: 1, result: '0x1' }]);
  assert.deepEqual(calls, ['a', 'b', 'c']);

  calls.length = 0;
  provider.backups[0]._send = async payload => { calls.push('b'); return [{ id: payload.id, error: { code: 3, message: 'execution reverted' } }]; };
  const reverted = await provider._send({ id: 2, method: 'eth_call' });

  assert.equal(reverted[0].error.message, 'execution reverted');
  assert.deepEqual(calls, ['a', 'b']);
});

const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');
const { pathToFileURL } = require('node:url');

const url = pathToFileURL(path.join(__dirname, '../discord-bot/rpc-proxy.js')).href;
const USDC = '0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913';
const call = (method, params = [], id = 1) => ({ jsonrpc: '2.0', id, method, params });

async function proxy(options = {}) {
  const { createRpcProxy } = await import(url);
  const seen = [];
  const handler = createRpcProxy({
    request: async (method, params) => { seen.push([method, params]); return { result: '0x1' }; },
    allowedContracts: [USDC],
    ...options,
  });
  return { handler, seen };
}

test('rpc proxy forwards allow-listed reads and rejects everything else without touching the paid RPC', async () => {
  const { handler, seen } = await proxy();
  const ok = await handler.handle([
    call('eth_blockNumber', [], 1),
    call('eth_call', [{ to: USDC.toLowerCase(), data: '0x70a08231' }, 'latest'], 2),
    call('eth_getTransactionReceipt', ['0x' + 'a'.repeat(64)], 3),
    call('eth_getBlockByNumber', ['latest', false], 4),
  ], '1.1.1.1');
  assert.equal(ok.status, 200);
  assert.deepEqual(ok.body.map(item => item.result), ['0x1', '0x1', '0x1', '0x1']);
  const rejected = await handler.handle([
    call('eth_sendRawTransaction', ['0x00'], 1),
    call('eth_getLogs', [{}], 2),
    call('eth_call', [{ to: '0x' + '1'.repeat(40), data: '0x' }], 3),
    call('eth_getBlockByNumber', ['latest', true], 4),
    call('eth_call', [{ to: USDC, data: '0x' + '0'.repeat(9000) }], 5),
  ], '1.1.1.1');
  assert.ok(rejected.body.every(item => item.error && item.result === undefined));
  assert.equal(seen.length, 4);
});

test('rpc proxy limits batch size and per-IP request rate', async () => {
  let clock = 0;
  const { handler } = await proxy({ perIpPerMinute: 3, now: () => clock });
  assert.equal((await handler.handle([], 'a')).status, 400);
  assert.equal((await handler.handle(Array.from({ length: 11 }, (_, index) => call('eth_blockNumber', [], index)), 'a')).status, 400);
  assert.equal((await handler.handle([call('eth_blockNumber'), call('eth_chainId')], 'a')).status, 200);
  const limited = await handler.handle([call('eth_blockNumber'), call('eth_chainId')], 'a');
  assert.equal(limited.status, 429);
  assert.equal(limited.body.error.code, -32005);
  assert.equal((await handler.handle(call('eth_blockNumber'), 'b')).status, 200, 'other visitors are unaffected');
  clock = 60_000;
  assert.equal((await handler.handle(call('eth_blockNumber'), 'a')).status, 200, 'limits reset each minute');
});

test('rpc proxy enforces a global ceiling across all visitors', async () => {
  const { handler } = await proxy({ globalPerMinute: 2, now: () => 0 });
  assert.equal((await handler.handle(call('eth_blockNumber'), 'a')).status, 200);
  assert.equal((await handler.handle(call('eth_blockNumber'), 'b')).status, 200);
  assert.equal((await handler.handle(call('eth_blockNumber'), 'c')).status, 429);
});

test('rpc proxy passes upstream reverts through and hides upstream failures behind a generic error', async () => {
  const { createRpcProxy } = await import(url);
  const handler = createRpcProxy({
    request: async method => {
      if (method === 'eth_call') return { error: { code: 3, message: 'execution reverted', data: '0x08c379a0' } };
      throw new Error('all endpoints down');
    },
    allowedContracts: [USDC],
  });

  const result = await handler.handle([call('eth_call', [{ to: USDC, data: '0x' }], 1), call('eth_blockNumber', [], 2)], 'a');
  assert.equal(result.body[0].error.code, 3);
  assert.equal(result.body[0].error.data, '0x08c379a0');
  assert.equal(result.body[1].error.code, -32603);
});

test('worker /api/rpc serves allowed site origins only and uses the forwarded client IP for rate limits', async () => {
  const http = require('node:http');
  const { createRpcProxy } = await import(url);
  const { createWorkerRequestHandler } = await import(pathToFileURL(path.join(__dirname, '../discord-bot/ipfs-worker.js')).href);
  const ips = [];
  const rpcProxy = createRpcProxy({ request: async () => ({ result: '0x2a' }), allowedContracts: [USDC] });
  const handler = createWorkerRequestHandler({
    allowedOrigins: ['https://site.example'],
    ownerWallet: '0x807061DF657A7697c04045dA7d16D941861cAABc',
    rpcProxy: { handle: (body, ip) => { ips.push(ip); return rpcProxy.handle(body, ip); } },
  });
  const server = http.createServer(handler);
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const base = `http://127.0.0.1:${server.address().port}`;
  try {
    const post = (origin, body) => fetch(`${base}/api/rpc`, {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'x-forwarded-for': '9.9.9.9, 10.0.0.1', ...(origin ? { origin } : {}) },
      body: JSON.stringify(body),
    });
    const ok = await post('https://site.example', call('eth_blockNumber'));
    assert.equal(ok.status, 200);
    assert.equal(ok.headers.get('access-control-allow-origin'), 'https://site.example');
    assert.equal((await ok.json()).result, '0x2a');
    assert.deepEqual(ips, ['9.9.9.9']);

    assert.ok((await post('https://evil.example', call('eth_blockNumber'))).status >= 400);
    assert.ok((await post('', call('eth_blockNumber'))).status >= 400);
    assert.equal(ips.length, 1);
  } finally {
    server.closeAllConnections();
    await new Promise(resolve => server.close(resolve));
  }
});

const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');
const { pathToFileURL } = require('node:url');

const moduleUrl = pathToFileURL(path.join(__dirname, '..', 'discord-bot', 'rpc-router.js')).href;
const PAID = 'https://base-mainnet.g.alchemy.com/v2/SECRETKEY';
const PUBLIC = 'https://mainnet.base.org';

function mockFetch(handlers) {
  const calls = [];
  const fetchImpl = async (url, init) => {
    const body = JSON.parse(init.body);
    calls.push({ url, method: body.method, params: body.params });
    const reply = await handlers[url](body);
    if (reply.status) return { ok: false, status: reply.status, json: async () => ({}) };
    return { ok: true, status: 200, json: async () => ({ jsonrpc: '2.0', id: body.id, ...reply }) };
  };
  return { fetchImpl, calls };
}

test('env endpoints: Alchemy overrides become the paid tier and public URLs stay as fallback', async () => {
  const { baseRpcEndpointsFromEnv } = await import(moduleUrl);
  const assets = { rpcUrl: 'https://base-rpc.publicnode.com', rpcFallbackUrls: ['https://mainnet.base.org'] };
  const { publicUrls, paidUrls } = baseRpcEndpointsFromEnv({ BASE_RPC_URL: PAID, BASE_LOGS_RPC_URL: PAID, PAYROLL_ARCHIVE_RPC_URL: PUBLIC }, assets);
  assert.deepEqual(paidUrls, [PAID]);
  assert.deepEqual(publicUrls, ['https://base-rpc.publicnode.com', 'https://mainnet.base.org', 'https://base.gateway.tenderly.co',
    'https://base-mainnet.public.blastapi.io', 'https://base.drpc.org']);
  assert.deepEqual(baseRpcEndpointsFromEnv({ BASE_PUBLIC_RPC_URLS: 'https://a.example, https://b.example' }).publicUrls,
    ['https://a.example', 'https://b.example']);
});

test('reads go public-first, fail over to paid on rate limits, and trip the breaker', async () => {

  const { createRpcRouter } = await import(moduleUrl);
  let time = 1_000_000;
  const { fetchImpl, calls } = mockFetch({
    [PUBLIC]: () => ({ error: { code: -32011, message: 'request limit reached' } }),
    [PAID]: () => ({ result: '0x2a' }),
  });
  const router = createRpcRouter({ publicUrls: [PUBLIC], paidUrls: [PAID], fetchImpl, now: () => time });
  assert.deepEqual(await router.request('read', 'eth_call', [{ to: '0x1' }, 'latest']), { result: '0x2a' });
  assert.deepEqual(calls.map(call => call.url), [PUBLIC, PAID]);
  calls.length = 0;
  await router.request('read', 'eth_call', [{ to: '0x2' }, 'latest']);
  assert.deepEqual(calls.map(call => call.url), [PAID, PUBLIC].slice(0, 1), 'open breaker skips the rate-limited public endpoint');
  time += 31_000;
  calls.length = 0;
  await router.request('read', 'eth_call', [{ to: '0x3' }, 'latest']);
  assert.equal(calls[0].url, PUBLIC, 'breaker closes after the cooldown');
  const health = router.health();
  assert.equal(JSON.stringify(health).includes('SECRETKEY'), false);
  assert.equal(health.endpoints.find(endpoint => endpoint.tier === 'public').rateLimited, 2);
});

test('logs and critical calls go paid-first; paid outages fall back to public', async () => {
