      return { number: blockNumber, timestamp: blockNumber };
    },
  };
  assert.equal(await findBlockAtOrBefore(provider, 90, { requestDelayMs: 75, wait: async delay => delays.push(delay) }), 89);
  assert.ok(requested[0] < 80);
