      BrowserProvider: function (ethereum, network) { this.network = network; this.getSigner = async () => signer; } },
    Date: { now: () => env.now },
    setTimeout, clearTimeout, setInterval: (fn, ms) => timers.push({ fn, ms }), console: { warn() {} },
  });
